export default [{"id":654,"title":"فتح المسلمين جبال طبرستان والديلم .","date":["العام الهجري :201","العام الميلادي :816"],"text":"افتتح عبدُ الله بن خرداذبة والي طبرستان البلاذرَ، والشيزرَ، من بلاد الديلم، وافتتح جبالَ طبرستان، فأنزل شهريار بن شروين عنها، وأشخَصَ مازيار بن قارن إلى المأمون، وأسَرَ أبا ليلى ملكَ الديلم."},{"id":655,"title":"فتنة العباسيين ضد الخليفة المأمون .","date":["العام الهجري :201","الشهر القمري : رمضان","العام الميلادي :817"],"text":"كان سبَبُ ذلك أن المأمونَ جعل عليَّ بنَ موسى الرضا بن جعفر بن محمد بن علي بن الحسين بن علي بن أبي طالب، وليَّ عهدِ المسلمين والخليفةَ من بعده، ولقَبَّه الرضا من آل محمد، وأمَرَ جُندَه بطرح السَّواد ولُبس الثياب الخُضر، وكتب بذلك إلى الآفاقِ، وكتب الحسَنُ بن سهل إلى عيسى بن محمد بن أبي خالد بعد عودِه إلى بغداد يُعلِمُه أنَّ المأمون قد جعل عليَّ بن موسى وليَّ عَهدِه من بعده. وذلك أنه نظرَ في بني العباس وبني علي، فلم يجِدْ أحدًا أفضَلَ ولا أورعَ ولا أعلَمَ منه، وأمر عيسى بنَ محمد أن يأمُرَ مَن عنده من أصحابه، والجندَ، والقُوَّادَ، وبني هاشم بالبيعة له، ولُبسِ الخُضرة، ويأخذ أهلَ بغداد جميعًا بذلك، فثار العباسيُّون وقالوا: إنما يريد أن يأخُذَ الخلافةَ مِن ولَدِ العبَّاس، وإنمَّا هذا من الفَضلِ بنِ سهلٍ، فمكثوا كذلك أيامًا وتكلَّم بعضُهم وقالوا: نولِّي بعضَنا ونخلع المأمونَ، فكان أشَدَّهم فيه منصورٌ وإبراهيمُ ابنا المهديِّ."},{"id":656,"title":"فتنة مبايعة أهل بغداد لإبراهيم بن المهدي .","date":["العام الهجري :201","الشهر القمري : ذي الحجة","العام الميلادي :817"],"text":"لَمَّا جاء الخبَرُ أن المأمونَ بايع لعليِّ الرضا بن موسى الكاظم بن جعفر الصادق بن محمد بن الحسين بالولايةِ مِن بعده؛ وذلك أن المأمون رأى أنَّ عليًّا الرضا خيرُ أهل البيت، وليس في بني العباس مثلُه في عِلمِه ودينِه، فجعله وليَّ عهده من بعده- اختلفوا فيما بينهم، فمِن مجيبٍ مبايعٍ، ومِن آبٍ ممانعٍ، وجمهورُ العباسيِّين على الامتناعِ من ذلك، وقام في ذلك ابنا المهديِّ إبراهيم ومنصور، فلما كان يوم الثلاثاءِ لخَمسٍ بَقِينَ مِن ذي الحجة فأظهر العباسيونَ البيعةَ لإبراهيم بن المهدي، ولقبوه بالمُبارك- وكان أسودَ اللون- ومِن بعده لابنِ أخيه إسحاق بن موسى بن المهدي، وخَلَعوا المأمون. فلمَّا كان يومُ الجمعة لليلتين بقيتا من ذي الحِجَّة أرادوا أن يَدعُوا للمأمونِ ثم من بعده لإبراهيمَ فقالت العامة: لا تدعُوا إلَّا إلى إبراهيم فقط، واختلفوا واضطربوا فيما بينهم، ولم يُصَلُّوا الجمعةَ، وصلَّى الناسُ فرادى أربعَ ركعاتٍ."},{"id":657,"title":"وفاة أبي العباس عبد الله بن إبراهيم بن الأغلب .","date":["العام الهجري :201","الشهر القمري : ذي الحجة","العام الميلادي :817"],"text":"أبو العبَّاسِ عبد الله الأول بن إبراهيم أحدُ حكَّام الأغالبة، تولَّى بعد وفاة والده إبراهيمَ بنِ الأغلب سنة 196هـ. وكان أبو العباس يلي طرابلُس لأبيه، فأخذ أخوه زيادةُ الله البيعةَ له من رؤساء الجند، ثم دخل القيروان سنة 197هـ, وأقَرَّه الخليفةُ المأمون على ما بيده من إفريقيَّة. عامَلَ أبو العباس سكَّانَ البلاد معاملةً تنطوي على الكثيرِ مِن العنَتِ والجَور، ولم يُصغِ إلى نصائحِ أهل الرأي فيها. وعدَّل نظامَ الضرائبِ فجعل العُشرَ ضريبةً ماليةً ثابتة، حتى لا يتأثَّرَ الدخلُ السَّنويُّ بالخِصب والجَدب، فسَخِطَ الناس عليه، وطالبوا بإلغائِها والعودة إلى نظامِ العُشرِ الذي اعتادوه، كما عاملَ أخاه زيادةَ الله وليَّ عهدِه معاملةً سيئة، وكذلك فعَلَ مع أهلِ بيته. وكان أبو العباسِ أفصحَ أهلِ بيته لسانًا وأكثَرَهم أدبًا، وكان يقولُ الشعر، ويرعى الشعراء. وكانت إمارتُه خمس سنين ونحو شهرين."},{"id":658,"title":"ولاية زيادة الله بن إبراهيم بن الأغلب إفريقية .","date":["العام الهجري :201","الشهر القمري : ذي الحجة","العام الميلادي :817"],"text":"لَمَّا توفِّيَ أبو العباس عبد الله بن إبراهيم بن الأغلب، أميرُ إفريقيَّة، ولِيَ بعده أخوه محمَّد زيادةُ الله بن إبراهيم، وبقي أميرًا رخِيَّ البالِ وادعًا والدنيا عنده آمِنة. ثم جهَّزَ جيشًا في أسطولِ البحرِ إلى مدينة سردانية، وهي للروم، فعطب بعضُها بعد أن غَنِموا من الروم، وقتلوا كثيرًا، فلمَّا عاد مَن سلِمَ منهم أحسَنَ إليهم زيادةُ الله ووصَلَهم."},{"id":659,"title":"مبايعة أهل بغداد لإبراهيم بن المهدي .","date":["العام الهجري :202","الشهر القمري : محرم","العام الميلادي :817"],"text":"بايع أهلُ بغداد إبراهيمَ بن المهدي بالخلافة، ولقَّبوه المبارك، وخلعوا المأمون، وبايعه سائِرُ بني هاشم، فكان المتولِّي لأخذ البيعةِ المطَّلِب بن عبدالله بن مالك، فكان الذي سعى في هذا الأمر السِّندي، وصالحًا صاحِبَ المصلَّى، ونَصيرًا الوصيفَ، وغيرَهم؛ غضبًا على المأمونِ حين أراد إخراجَ الخلافة من ولَدِ العباس، ولِتَركِه لباسَ آبائِه من السَّواد. فلما فرغَ مِن البيعةِ وعد الجُندِ رِزقُ سِتَّة أشهر، ودافَعَهم بها فشَغَّبوا عليه، فأعطاهم لكلِّ رجلٍ مائتي درهم، وكتب لبعضِهم إلى السَّوادِ بقيَّة مالهم حنطةً وشعيرًا فخرجوا في قبضها فانتهبوا الجميعَ، وأخذوا نصيبَ السُّلطانِ وأهلِ السواد، واستولى إبراهيمُ على الكوفة والسوادِ جميعِه، وعسكَرَ بالمدائن، واستعمل على الجانبِ الغربيِّ مِن بغداد العباسَ بنَ موسى الهادي، وعلى الجانب الشرقيِّ منها إسحاقَ بن موسى الهادي."},{"id":660,"title":"فتنة خلع الحكم بن هشام في الأندلس .","date":["العام الهجري :202","الشهر القمري : شعبان","العام الميلادي :818"],"text":"عزَّ على علماء الأندلس انتهاكُ الحكَمِ بنِ هشام للحُرُمات، وأْتَمَروا ليخلعوه، ثم جيَّشوا لقتاله، وجَرَت بالأندلس فتنةٌ عظيمة على الإسلام وأهلِه- فلا قوة إلا بالله- فلمَّا هَمَّ العُلَماءُ بخلعِ الحَكَمِ، قالوا: إنَّه غيرُ عدلٍ، ونكَثُوه في نفوس العوامِّ، وزعموا أنَّه لا يحِلُّ المُكثُ ولا الصبرُ على هذه السيرةِ الذَّميمةِ، وكان ممن تقدَّمَ العلماءَ في الدعوةِ لخلعِ الحكَمِ بن هشام يحيى بن يحيى الليثي، وطالوتُ المعافري, وعوَّلَ أهلُ العلم على تقديمِ أحدِ أهل الشورى بقرطبة، وهو أبو الشماس أحمد بن المنذر بن عبدالرحمن الداخل ابن عمِّ الحكم بن هشام؛ لِما عرفوا من صلاحِه وعَقلِه، ودينِه، فقصدوه، وعرَّفوه بالأمر، فأبدى الميلَ إليهم والبُشرى بهم، وقال لهم: أنتم أضيافي الليلةَ؛ فإنَّ الليلَ أستَرُ. وناموا، وقام هو إلى ابنِ عَمِّه الحكَمِ، فأخبَرَه بشأنهم، فاغتاظ لذلك، وقال: جئتَ لسَفكِ دمي أو دمائِهم، وهم أعلامٌ، فمن أين نتوصَّلُ إلى ما ذكرت? فقال: أرسِلْ معي من تثِقُ به ليتحقَّقَ. فوجَّه من أحبَّ، فأدخلهم أحمدُ في بيته تحت سِترٍ، ودخل الليلُ، وجاء القَومُ، فقال: خبِّروني مَن معكم? فقالوا: فلانٌ الفقيهُ، وفلانٌ الوزير. وعَدُّوا كبارًا، والكاتِبُ يكتب حتى امتلأ الرَّقُّ، فمَدَّ أحدُهم يدَه وراء السترِ، فرأى القومَ، فقام وقاموا، وقالوا: فعلْتَها يا عدوَّ الله. فمَن فَرَّ لحينِه نجا، ومن لا، قُبِضَ عليه، فكان ممَّن فَرَّ: عيسى بن دينار الفقيه، ويحيى بن يحيى الفقيه صاحِبُ مالك، وقرعوس بن العباس الثَّقفي, وقبض على ناس كمالك بن يزيد القاضي، وموسى بن سالم الخولاني، ويحيى بن مُضَر الفقيه، وأمثالهم من أهل العلمِ والدين، في سَبعةٍ وسبعين رجلًا، فضُرِبَت أعناقُهم وصُلِبوا, وأضاف إليهم الحكَمُ عَمَّيه؛ كُليبًا وأميَّة، فصُلِبا، وأحرق القلوبَ عليهم، وسار بأمرِهم الرِّفاقُ، وعَلِمَ الحكمُ أنَّه محقودٌ من الناس كلهم، فأخذ في جمعِ الجُنود والحشَمِ، وتهيَّأ، وأخذت العامَّةُ في الهياجِ، واستأسد النَّاسُ، وتنَمَّروا، وتأهَّبوا. واستفحل الشَّرُّ."},{"id":661,"title":"مسير المأمون للعراق وقتل ذي الرياستين الفضل بن سهل .","date":["العام الهجري :202","الشهر القمري : رمضان","العام الميلادي :818"],"text":"أقبل المأمونُ من خراسان قاصدًا العراق، وذلك أنَّ علي بن موسى الرضا أخبر المأمونَ بما النَّاسُ فيه من الفِتَن والاختلافِ بأرض العراق، وبأنَّ الهاشميِّينَ قد أنهَوا إلى الناس بأنَّ المأمونَ مَسحورٌ ومَسجونٌ، وأنَّهم قد نَقَموا عليك ببيعتِك لعليِّ بن موسى، وأنَّ الحرب قائمة بين الحسَنِ بنِ سَهلٍ وبين إبراهيم بن المهدي. فاستدعى المأمونُ جماعةً مِن أمرائه وأقربائه فسألهم عن ذلك فصدَّقوا عليًّا فيما قال، بعد أخذِهم الأمانَ منه، وقالوا له: إنَّ الفضلَ بنَ سَهلٍ حسَّنَ لك قتلَ هَرثَمة بن أعين، وقد كان ناصحًا لك. فعاجله بقَتلِه، وإنَّ طاهِرَ بن الحسين مهَّدَ لك الأمورَ حتى قاد إليك الخلافةَ بزِمامِها فطَرَدتَه إلى الرقَّة، فقعد لا عملَ له ولا تستنهِضُه في أمرٍ، وإنَّ الأرض تفتَّقَت بالشرور والفِتَن من أقطارها، فلما تحقَّقَ ذلك المأمونُ أمر بالرحيلِ إلى بغداد، وقد فطِنَ الفضلُ بن سهل بما تمالأَ عليه أولئك الناصحون، فضرب قومًا ونتَفَ لحى بعضِهم. وسار المأمونُ فلمَّا كان بسرخس عدا قومٌ على الفضلِ بنِ سَهلٍ وزير المأمون (ذو الرياستين ) وهو في الحمَّام، فقتلوه بالسيوف، وله ستون سنةً، فبعث المأمونُ في آثارهم فجيءَ بهم وهم أربعةٌ من المماليك فقتَلَهم وكتب إلى أخيه الحسَنِ بنِ سهل يعزِّيه فيه، وولَّاه الوَزارةَ مكانَه، وارتحل المأمونُ من سرخس يومَ عيد الفطر نحو العراق، وإبراهيم بن المهدي بالمدائن، وفي مقابلتِه جيشٌ يقاتلونه من جهةِ المأمون."},{"id":662,"title":"موقعة أهل الربض بقرطبة .","date":["العام الهجري :202","الشهر القمري : رمضان","العام الميلادي :818"],"text":"من أشهَرِ الثَّوراتِ التي قمَعها الحكَمُ بن هشام ثورة ُالربض، وهم قومٌ كانوا يعيشونَ في إحدى ضواحي قُرطُبة، وقد ثار أهلُها ثورةً كبيرة جدًّا عليه؛ بسبب ما عُرِفَ عنه من معاقرةِ الخَمرِ، وتشاغُلِه باللهوِ والصَّيد، وقد زاد من نقمةِ الشَّعبِ عليه قتلَه لجماعةٍ مِن أعيان قُرطبة، فكرهه الناسُ, وصاروا يتعرَّضون لجُندِه بالأذى والسَّبِّ، فشرعَ في تحصينِ قُرطبةَ وعِمارةِ أسوارِها وحَفْرِ خَنادِقِها، وارتبط الخيلَ على بابِه، واستكثَرَ المماليكَ، ورتَّب جمعًا لا يفارِقونَ بابَ قَصرِه بالسلاحِ، فزاد ذلك في حقدِ أهل قُرطبةَ، وتيقَّنوا أنه يفعلُ ذلك للانتقام منهم. ثم وضَعَ عليهم عُشرَ الأطعمةِ كُلَّ سنةٍ، مِن غيرِ خَرصٍ، فكرهوا ذلك، ثم عمدَ إلى عشرةٍ مِن رؤساء سفهائِهم، فقتَلَهم، وصَلَبهم، فهاج لذلك أهلُ الربض، وتداعى أهلُ قُرطبةَ من أرباضِهم وتألَّبوا بالسلاحِ وقصدوا القصرَ، فكان أوَّلَ مَن شهرَ السلاحَ أهلُ الربض، واجتمع أهلُ الربض جميعُهم بالسلاح، واجتمعَ الجندُ والأمويُّون والعبيدُ بالقصر، وفرَّقَ الحكمُ الخيلَ والأسلحة، وجعل أصحابَه كتائبَ، ووقع القتالُ بين الطائفتينِ، فغَلَبهم أهلُ الربض، وأحاطوا بقَصرِه، فنزل الحكَمُ من أعلى القصر، ولَبِسَ سلاحَه، ورَكِبَ وحَرَّضَ الناس، فقاتلوا بين يديه قتالًا شديدًا. ثم أمَرَ ابنَ عَمِّه عُبيد الله، فثلَمَ في السُّورِ ثُلمةً، وخرج منها ومعه قطعةٌ من الجيش، وأتى أهلَ الربض من وراء ظهورِهم، ولم يعلَموا بهم، فأضرموا النَّارَ في الربض، وانهزم أهلُه، وقُتلوا مقتلةً عظيمةً، وأخرجوا من وجَدوا في المنازلِ والدُّور، فأسروهم، فانتقى من الأسرى ثلاثَمائة من وجوهِهم، فقتَلَهم، وصَلَبَهم منكَّسِينَ، وأقام النَّهبَ والقتلَ والحريقَ والخرابَ في أرباض قرطبةَ ثلاثةَ أيام. ثم استشار الحكَمُ عبدَ الكريم بن عبد الواحد بن عبد المغيث، فأشار عليه بالصَّفحِ عنهم والعفوِ، وأشار غيرُه بالقتل، فقَبِلَ قَولَه، وأمر فنودي بالأمانِ، على أنَّه من بقي من أهلِ الربض بعد ثلاثةِ أيَّامٍ قَتَلْناه وصَلَبْناه؛ فخرج من بقي بعد ذلك منهم مستخفيًا، وتحمَّلوا على الصَّعبِ والذَّلولِ خارجين من حضرةِ قُرطبة بنِسائِهم وأولادِهم، وما خَفَّ من أموالهم، وقعد لهم الجندُ والفَسَقةُ بالمراصِدِ يَنهبونَ، ومن امتنَعَ عليهم قتلوه. فلما انقَضَت الأيامُ الثلاثة أمر الحكَمُ بكَفِّ الأيدي عن حَرَمِ النَّاسِ، وجمعَهنَّ إلى مكان، وأمر بهدمِ الربضِ القبلي. فكانت وقعةً هائلة شنيعةً، قُتِل فيها عددٌ كثيرٌ زُهاءَ أربعين ألفًا من أهل الربض، وعاينوا البلاءَ وهُدِّمَت ديارُهم ومساجِدُهم، ونزل منهم ألوفٌ بطُليطِلة وخَلقٌ في الثغورِ، وجاز آخرون البحرَ ونزلوا بلادَ البربر، ومنهم من نزل بالإسكندرية في مصر. وكان بزيعُ مولى أميَّة ابن الأمير عبد الرحمن بن معاوية بن هشامٍ محبوسًا في حبسِ الدم بقرطبة، في رجليه قيدٌ ثقيلٌ، فلما رأى أهلَ قُرطبة قد غلَبوا الجندَ سأل الحرسَ أن يُفرِجوا له، فأخذوا عليه العهودَ إن سَلِمَ أن يعودَ إليهم، وأطلقوه، فخرج فقاتلَ قتالًا شديدًا لم يكُنْ في الجيشِ مِثلُه، فلما انهزم أهلُ الربض عاد إلى السِّجنِ، فانتهى خبَرُه إلى الحكم، فأطلقه وأحسَنَ إليه."},{"id":663,"title":"استقلال دولة بني زياد وامتلاكها اليمن وحضرموت .","date":["العام الهجري :203","العام الميلادي :818"],"text":"دولةُ بَني زيادٍ هي أوَّلُ الدُّولِ اليَمنيةِ استقلالًا في القرنِ الثالثِ الهِجريِّ، ففي زمَنِ المأمونِ الخَليفةِ العباسيِّ بدأ النُّفوذُ الشِّيعيُّ يزدادُ بشدةٍ؛ ما جعَله يُولِّي محمدَ بنَ إبراهيمَ الزِّياديَّ اليَمنَ سنةَ 203هـ، وبعد عامٍ مِن هذا التاريخ بدأ الزِّياديُّ في بناءِ مَدينةٍ جَديدةٍ لها، وهي مَدينةُ زُبَيدٍ، وقد نجَح في بَسطِ نُفوذِه على جميعِ أرجاءِ اليَمنِ حتى استَقلَّ بمُلكها، فمَلَكَ إقليمَ اليَمنِ بأسْرِه، وحَضْرَمَوْتَ بأسْرِها، والشِّحْرَ وَمِرْباطَ وأَبْيَنَ وعَدَنَ والتهائِمَ إلى حَلْيِ يَعقوبَ، وكذلك مِن جبالِ الجَنَدِ وأعمالِه ومِخلافِ جَعفرَ ومِخلافِ المعافِرِ وصَنعاءَ وأعمالِها ونَجرانَ وبَيْحانَ والحِجازِ بأسْرِه. وبعدَ أنْ جَعَل الزِّياديُّ المُلكَ في ذُرِّيتِه ودانت له اليَمنُ، حَكم مِن بعده ابنُه إبراهيمُ سنةَ 245هـ، ثم تولى مِن بعدِه زيادٌ، ثم مِن بعدِه ابنُه أبو الجَيْشِ إسحاقُ الذي عمَّرَ طويلًا وبدأ في عَهدِه ضَعفُ الدولةِ الزِّياديةِ، فثارَ في صَنعاءَ ابنُ يَعفُرَ، وثارَ في صَعْدةَ يحيى بنُ القاسِمِ الرَّسِّيُّ المُلقَّبُ بالهادي سنةَ 288هـ، وأصبحت اليَمنُ كُلُّها في مهَبِّ الريحِ، وبدأت الدولةُ الزِّياديةُ بالتفكُّكِ. وانتزع اليَعفُريُّونَ مِن بَني زيادٍ بعضَ المناطقِ، وأصبحت اليَمنُ ثلاثَ دولٍ: دولةَ ابنِ يَعفُرَ في صَنعاءَ، والدولةَ الشِّيعيةَ الزَّيديةَ لِلرَّسِّيينَ في صَعدةَ، ودولةَ الزِّياديِّينَ في زُبَيدٍ. فلم يَدُمِ المُلكُ طَويلًا لِأحدٍ، وشهدَ اليَمنُ اضطراباتٍ مذهبيةً خِلالَ العَصرِ العباسيِّ الثاني. وفي آخِرِ الأمرِ تمكَّنَ نجاحٌ وهو مملوكٌ حبشيٌّ لِمُرجانَ مِن تأسيسِ دولةِ بَني نجاحٍ في زُبَيدٍ، وبهذا انقرضت دولةُ بَني زيادٍ."},{"id":664,"title":"وفاة علي بن موسى الرضي (ولي عهد المأمون) .","date":["العام الهجري :203","الشهر القمري : صفر","العام الميلادي :818"],"text":"تُوفِّيَ علي بن موسى الرضا- الذي كان المأمونُ قد جعله وليًّا للعهدِ- وكان سببُ موته أنَّه أكل عنبًا فأكثَرَ منه، فمات فجأةً، وكان موتُه بمدينة طوس، فصلى المأمونُ عليه، ودفنه عند قبرِ أبيه الرشيد, وقيل: إنَّ المأمون سمَّه في عنب، وكان عليٌّ يحِبُّ العنب. فلما توفِّيَ كتب المأمونُ إلى الحسن بن سهل يُعلِمُه موتَ عليٍّ، وما دخل عليه من المُصيبة بموته، وكتب إلى أهلِ بغداد، وبني العبَّاس والموالي يُعلِمُهم موتَه، وأنهم إنما نَقَموا ببيعتِه، وقد مات، ويسألُهم الدخولَ في طاعته، فكَتَبوا إليه أغلظَ جوابٍ."},{"id":665,"title":"خلع أهل بغداد لإبراهيم بن المهدي .","date":["العام الهجري :203","الشهر القمري : شوال","العام الميلادي :819"],"text":"كان سبَبُ ذلك أنَّ إبراهيمَ قَبَضَ على عيسى بن محمد بن أبي خالد وحبسَه، وأخذ عِدَّةً من قوَّاده وأهلَه، فحبَسَهم ونجا بعضُهم، وفيمن نجا أخو عيسى العباس بن محمد، ومشى بعضُ أهله إلى بعض، وحرَّضوا الناسَ على إبراهيم، وكان أشَدَّهم العباسُ بن محمد، وكان هو رأسَهم، فاجتمعوا وطردوا عاملَ إبراهيمَ على الجسر، والكرخ وغيره، وظهر الفُسَّاق والشُّطَّار، وكتب العباسُ إلى حميد بن عبد الحميد يسألُه أن يَقدَمَ عليهم حتى يُسَلِّموا إليه بغداد، فقَدِمَ عليهم، وسار حتى أتى نهر صرصر فنزل عنده. وخرج إليه العباسُ وقوَّادُ أهل بغداد، فلَقُوه، ووعدهم أن يصنعَ لهم العطاءَ يوم السبت في الياسرية على أن يدْعوَا للمأمونِ بالخلافة يوم الجمعة، ويخلعوا إبراهيمَ، فأجابوه إلى ذلك. ولَمَّا بلغ إبراهيمَ الخبَرُ أخرج عيسى ومن معه من إخوتِه من الحبسِ، وسأله أن يرجِعَ إلى منزله، ويكفيَه أمرَ هذا الجانب، فأبى عليه. ثم بعد ذلك رضِيَ فخَلَّى سبيله، وأخذ منه كُفَلاء، وكلَّم عيسى الجندَ، ووعدَهم أن يعطيَهم مثلَ ما أعطاهم حميدُ بن عبد الحميد، فأبوا ذلك، وشَتَموه وأصحابه، وقالوا: لا نريدُ إبراهيم، فقاتلهم ساعةً، ثم ألقى نفسَه في وسطهم، حتى أخذوه شِبهَ الأسيرِ، فأخذه بعضُ قُوَّاده، فأتى به منزِلَه، ورجع الباقونَ إلى إبراهيم، فأخبروه الخبَرَ، فاغتمَّ لذلك. ثم اختفى إبراهيمُ بنُ المهدي؛ وكان سببُ ذلك أنَّ أصحابَ إبراهيم وقوَّادَه تسلَّلوا إلى حميد بن عبد الحميد فصار عامَّتُهم عنده، وأخذوا له المدائِنَ. فلما رأى إبراهيمُ فعلهم أخرج جميعَ مَن بقيَ عنده حتى يقاتلوا فالتَقَوا على جسر نهر ديالى، فاقتتلوا فهَزمَهم حميدٌ وتَبِعَهم أصحابه، حتى دخلوا بغداد، وذلك نهايةَ ذي القعدة. فلما كان الأضحى اختفى الفَضلُ بن الربيع، ثم تحوَّلَ إلى حميد بن عبد الحميد، وجعل الهاشميُّون والقوَّاد يأتون حميدًا واحدًا بعد واحدٍ، فلمَّا رأى ذلك إبراهيمُ سُقِطَ في يديه، وشقَّ عليه، اختفى ليلة الأربعاء لثلاث عشرة بقيت من ذي الحجة. وكانت أيامُ إبراهيم سنة وأحد عشر شهرًا واثني عشر يومًا."},{"id":666,"title":"اليمن يستقل عن الخلافة العباسية بقيام الدولة الزيادية  .","date":["العام الهجري :204","العام الميلادي :819"],"text":"كان شَخصٌ مِن بني زيادِ بن أبيه، اسمُه محمد بن إبراهيم بن عبيد الله بن زياد، مع جماعةٍ من بني أمية، قد سَلَّمهم المأمونُ إِلى الفضل بن سهل ذي الرياستين، وقيل إِلى أخيه الحسَن، وبلغ المأمونُ اختلالَ أمر اليمن، فأثنى ابنُ سهلٍ على محمَّد بن زياد الأموي، وأشار بإِرساله أميرًا على اليمن، فأرسل المأمونُ محمَّدَ بن زياد، ومعه جماعةٌ، فحَجَّ ابنُ زياد في سنة ثلاث ومائتين، وسار إِلى اليمَنِ، وفتح تِهامةَ بعد حروب جرت بينه وبين العرَبِ، واستقَرَّت قَدَمُ ابنِ زياد باليمن، وبنى مدينةَ زَبيد، واختَطَّها في سنة أربع ومائتين، وأرسلَ ابن زياد مولاه جعفرًا بهدايا جليلةٍ إِلى المأمون، فسار جعفرٌ بها إِلى العراق، وقَدَّمها إِلى المأمون في سنة خمس ومائتين، وعاد جعفرٌ إِلى اليمن في سنة ست ومائتين، ومعه عسكَرٌ مِن جهة المأمون، بمقدار ألفَي فارس، فعَظُمَ أمرُ ابن زياد، وملَكَ إِقليمَ اليمَنِ بأسرِه وتقَلَّد جعفرٌ الجبال، واختَطَّ بها مدينة يقال لها المديحرة، والبلادُ التي كانت لجعفر تسمَّى إِلى اليوم مخلافَ جَعفرٍ، والمخلاف عبارةٌ عن قُطرٍ واسع، وكان جعفرٌ هذا من الكُفاة الدُّهاة، وبه تمَّت دولةُ بني زياد، حتى قُتِلَ ابنُ زياد بجعفرة، وبقِيَ محمَّد بن زياد كذلك حتى توفِّي. فكان ذلك أوَّلَ قيامِ الدولة الزياديَّة باليمن."},{"id":667,"title":"قدوم الخليفة المأمون من جرجان إلى بغداد .","date":["العام الهجري :204","الشهر القمري : صفر","العام الميلادي :819"],"text":"لَمَّا خُلِعَ إبراهيمُ بن المهدي واختفى وانقطعت الفِتَن، قَدِمَ المأمونُ بغداد، وكان قد أقام بجرجان شَهرًا وجعل يقيمُ بالمنزل اليومَ واليومينِ والثلاثةَ، وأقام بالنهروان ثمانيةَ أيام، فخرج إليه أهلُ بيته والقوَّاد، ووجوهُ الناس، وسَلَّموا عليه. وكان قد كتب إلى طاهرِ بنِ الحُسين، وهو بالرقَّة، ليوافيَه بالنهروان، فأتاه بها ودخل بغدادَ مُنتصَفَ صفر، ولباسُه ولباسُ أصحابِه الخُضرة، فلمَّا قَدِمَ بغدادَ نزل الرصافةَ، ثمَّ تحوَّل ونزل قصرَه على شاطئِ دِجلةَ، وأمر القوادَ أن يقيموا في مُعسكَرِهم. وكان الناسُ يدخلونَ عليه في الثياب الخُضر، وكانوا يَخرقونَ كلَّ ملبوسٍ يرونه من السَّوادِ على إنسان، فمكثوا بذلك ثمانية أيام، فتكلَّم بنو العباس وقوَّاد أهل خراسان، وقيل: إنَّه أمر طاهر بن الحسين أن يسألَه حوائِجَه، فكان أوَّلَ حاجةٍ سأله أن يلبَسَ السوادَ، فأجابه إلى ذلك، وجلس للنَّاسِ، وأحضر سوادًا فلَبِسَه، ودعا بخِلعةٍ سوداءَ فألبسَها طاهِرًا، وخلع على قوَّادِه السَّوادَ، فعاد الناسُ إليه."},{"id":668,"title":"وفاة الإمام الشافعي .","date":["العام الهجري :204","الشهر القمري : رجب","العام الميلادي :820"],"text":"هو أبو عبدالله محمَّد بن إدريس بن العبَّاس بن عثمان بن شافع بن السائب بن عبيد بن عبد يزيد بن هشام بن المطلب بن عبد مناف بن قصي بن كلاب بن مرة بن كعب بن لؤي بن غالب، الإمامُ عالِمُ العَصرِ ناصِرُ الحديثِ، فقيه المِلَّة، ثم المطَّلبيُّ الشافعيُّ، المكِّي، الغزي القرَشِيُّ، أحَدُ الأئمَّة الأربعة المشهورينَ في الفقه، ولِدَ في غزَّة عام 150هـ فعادت به أمُّه إلى مكة، وهو ابن سنتين، فنشأ بها، وأقبل على الأدبِ والعربيَّة والشعر، فبرع في ذلك. وحُبِّبَ إليه الرميُ حتى فاق الأقرانَ، وصار يصيبُ من العِشرةِ تِسعةً. ثم كتَبَ العِلمَ. قال الشافعي: \"أقمتُ في بطونِ العَرَب عشرينَ سنةً آخُذُ أشعارَها ولغاتِها، وحَفِظتُ القرآنَ، فما علِمتُ أنَّه مَرَّ بي حرفٌ إلَّا وقد عَلِمتُ المعنى فيه، ما خلا حرفينِ، إحداهما: دسَّاها\" وكان من أفصَحِ النَّاسِ وأحفَظِهم، رحل إلى المدينةِ وسَمِعَ من الإمام مالك, قال الشافعي: \"أتيتُ مالِكًا وأنا ابنُ ثلاث عشرة سنة، وكان ابنُ عمٍّ لي واليَ المدينة، فكلَّمَ لي مالكًا فأتيته. فقال: اطلُبْ من يقرأُ لك، فقلت: أنا أقرأُ، فقرأت عليه. فكان ربَّما قال لي لشيء: أعِدْه, فأُعيدُه حِفظًا, وكأنَّه أعجَبَه\". ثم رحل لليمَنِ، ثمَّ سُيِّرَ إلى العراق إلى الرشيدِ وبَقِيَ فيها وتفَقَّه، وتكررت رحلتُه إلى العراق أكثَرَ مِن مرَّة، ثم إلى مصرَ، وله مِن المؤلَّفات: الرِّسالة، والأم، واختلاف الحديث، وله ديوان شعر، انتشر مذهبُه بسبب كثرة ترحُّلِه وجَمْعِه بين طريقةِ المحَدِّثين وطريقة الفقهاء، وكان أحمدُ بن حنبل يدعو له في صلاتِه نحوًا من أربعينَ سنةً، قال يونس الصدفي: \"ما رأيتُ أعقَلَ من الشافعيِّ؛ ناظرتُه يومًا في مسألةٍ ثمَّ افتَرَقنا ولَقِيَني، فأخذ بيدي ثم قال: يا أبا موسى ألا يستقيمُ أن نكونَ إخوانًا وإن لم نتَّفِقْ في مسألةٍ؟ قلت: هذا يدُلُّ على كمالِ عَقلِ هذا الإمامِ وفِقهِ نفسِه، فما زال النُّظَراءُ يَختَلِفونَ\". توفِّيَ في مصر ودُفِنَ بالقرافة الصغرى، وله أربعٌ وخمسون سَنةً."},{"id":669,"title":"وفاة الحكم بن هشام صاحب الأندلس .","date":["العام الهجري :206","الشهر القمري : ذي الحجة","العام الميلادي :822"],"text":"هو الحكَمُ بنُ هشامٍ ابنُ الداخل عبد الرحمن بن معاوية بن هشام بن عبد الملك بن مروان ابن الحَكَم الأُموي، المرواني، أبو العاصِ، أميرُ الأندلس، وابنُ أميرِها، وحفيدُ أميرها. ويلقَّب: بالمرتضَى، ويعرف: بالربضي؛ لِما فعلَ بأهلِ الربض. بويعَ بالمُلك عند موت أبيه- في صفر سنة ثمانين ومائة- وكان من جبابرةِ الملوك وفُسَّاقهم ومتَمَرِّديهم، وكان فارسًا شجاعًا فاتِكًا، ذا دهاءٍ وحَزمٍ، وعُتُوٍّ وظُلمٍ، تملَّكَ سبعًا وعشرين سنة. وكان في أوَّلِ أمْرِه على سيرةٍ حميدةٍ، تلا فيها أباه، ثم تغيَّرَ وتجاهر بالمعاصي. كان يأخذُ أولادَ النَّاسِ المِلاح، فيُخصيهم ويُمسِكُهم لنَفسِه. وله شِعرٌ جَيِّد. وكان يقرِّبُ الفُقَهاء وأهلَ العلمِ. وكَثُرت العلماء بالأندلُسِ في دولته، حتى قيل: إنَّه كان بقُرطبة أربعةُ آلاف متقَلِّس- أي: مُتزَيِّينَ بزيِّ العلماء- فلما أراد اللهُ فناءهم، عَزَّ عليهم انتهاكُ الحكَمِ بن هشام للحُرُمات، وأْتَمَروا ليخلَعوه، ثم جيَّشوا لقتاله، وجرت بالأندلسِ فِتنةٌ عظيمةٌ على الإسلام وأهله- فلا قوَّةَ إلا باللهِ- على يدِ الحَكَمِ بن هشام، قُتل فيها عشراتُ الآلافِ مِن العُلَماء والعامَّة خاصةً في وقعة الربض بقُرطبة، ثم توفِّيَ الحَكَمُ بن هشام. وهو أوَّلُ من جَنَّد بالأندلُسِ الأجنادَ المُرتَزِقة، وجمع الأسلحةَ والعُدَد، واستكثَرَ من الحشَمِ والحواشي، وارتبَطَ الخيولَ على بابه، وشابَهَ الجبابرةَ في أحوالِه، واتَّخذ المماليكَ، وجعَلَهم في المرتَزِقة، فبلغت عِدَّتُهم خمسةَ آلاف مملوك، وكانوا يُسَمَّون الخُرسَ؛ لعُجمةِ ألسنتِهم، وكانوا يوميًّا على باب قَصرِه. وكان يطَّلِعُ على الأمور بنفسه، ما قَرُب منها وبَعُد، وكان له نفَرٌ مِن ثقاتِ أصحابِه يُطالِعونَه بأحوالِ النَّاس، فيرُدُّ عنهم المظالِمَ، ويُنصِفُ المظلومَ، وهو الذي وطَّأَ لعَقِبه المُلْكَ بالأندلس، وولِيَ بعده ابنُه عبدالرحمن بن الحكَم."},{"id":670,"title":"عبدالرحمن الأوسط يحكم الأندلس .","date":["العام الهجري :206","الشهر القمري : ذي الحجة","العام الميلادي :822"],"text":"لَمَّا مات الحكَمُ بنُ هشام بن عبدالرحمن، قام بالمُلْك بعده ابنُه عبد الرحمن ويكنَّى أبا المطرف، واسمُ أمِّه حلاوة، ولد بطليطِلة، أيَّامَ كان أبوه الحكَمُ يتولَّاها لأبيه هشام، فلمَّا وَلِيَ عبدالرحمن خرج عليه عمُّ أبيه عبد الله البلنسي؛ طمعًا في الحُكمِ بعد موتِ الحَكَمِ."},{"id":671,"title":"خروج عبدالله البلنسي على عبدالرحمن الثاني في الأندلس .","date":["العام الهجري :207","العام الميلادي :822"],"text":"قبل أن يتسَلَّمَ عبدُالرحمن بن الحكَم مقاليدَ الحُكمِ، فوجئ بخروجِ عَمِّ أبيه عبد الله بن عبدالرحمن البلنسي عليه؛ لينتزع المُلكَ منه، خرج من بلنسية يريد قُرطبة، فتجهَّزَ له عبد الرحمن واستعَدَّ لمواجهتِه، وعندما بلغ ذلك عبد الله خاف وضَعُفَت عزيمتُه، وانسحب إلى بلنسية، ثم ما لبث أن مات في أثناء ذلك سريعًا، ووقى الله ذلك الطَّرفَ شَرًّا. فلما مات نقلَ عبدُ الرحمن أولادَه وأهلَه إليه بقُرطبة، فخَلَصت الإمارةُ لولد هشام بن عبد الرحمن."},{"id":672,"title":"خروج عبدالرحمن بن أحمد بن عبدالله باليمن .","date":["العام الهجري :207","العام الميلادي :822"],"text":"خرج عبدُ الرحمن بن أحمد بن عبد الله بن محمد بن عمر بن علي بن أبي طالب ببلادِ عَكٍّ من اليمن، يدعو إلى الرضا من آل محمد, وكان خروجُه من سوءِ سيرةِ عاملِ اليمَنِ، فبايعه خلقٌ، فوجه إليه المأمونُ لحَربِه دينارَ بن عبد الله، وكتب معه بأمانِه، فحَجَّ دينار ثم سار إلى اليمَنِ حتى قرُبَ من عبد الرحمن، وبعث إليه بأمانِه فقَبِلَه وعاد مع دينارٍ إلى المأمون."},{"id":673,"title":"طاهر بن الحسين يعلن قيام الدولة الطاهرية بخراسان .","date":["العام الهجري :207","العام الميلادي :822"],"text":"تُنسبُ الدَّولةُ الطاهريَّةُ إلى طاهر بن الحُسين بن مصعب بن رُزَيق، وكان أبوه أحدَ وُجَهاءِ خراسان ومِن سادتِها في عصر الخليفة العباسيِّ هارون الرشيد، وقد ولَّاه الرشيد بوشنج- إحدى مدن خراسان- والتي تقعُ بين هراة وسرخس. وبعد وفاة هارونَ الرشيد سنة 194هـ حدث نزاعٌ حول الخلافة بين ابنيه: الأمينِ والمأمون، وتصاعد الخِلافُ إلى حدِّ الحرب والاقتتال، وفي ظلِّ تلك الأجواء المشحونةِ بالقتال والصِّراع، وجد طاهِرُ بن الحسين طريقَه إلى الاستقلالِ بخراسان حينما استطاع إلحاقَ الهزيمة بجيش الأمينِ الذي أرسلَ عدَّةَ مرَّات ليقضي عليه، وكل ذلك لا يستطيعُ، وأدَّت تلك الانتصاراتُ المتتالية التي حَقَّقَها طاهِرٌ إلى خروج عمَّالِ الأمين عن طاعتِه، والمسارعةِ إلى خلْعِه وإعلان الطاعةِ لأخيه، واتَّجه طاهِرٌ بجُيوشه إلى بغداد فحاصرها مدَّةً طويلة حتى ضاق الناسُ واشتَدَّ الجوعُ، فلمَّا تمكَّنَ من دخولِها قبض على الأمينِ ثمَّ أمرَ بقَتلِه، واستقَرَّ الأمر للمأمونِ بالخلافة سنة 198هـ فأسند إلى طاهرٍ ولاية خراسانَ وبقية ولاياتِ المَشرِق، فلمَّا توفي طاهر سنة 207هـ عهِدَ المأمونُ إلى عبد الله بن طاهر بولاية خراسانَ خلفًا لأبيه، ثم أخذَ الطاهريُّونَ يَفقِدونَ السيطرةَ على مناطِقِهم لصالحِ الصفاريِّين الذين استطاعوا أخيرا سنة 259ه أن يُنهوا حكمَ الطاهريِّين."},{"id":674,"title":"بداية فتنة المضرية واليمانية بالأندلس .","date":["العام الهجري :207","العام الميلادي :822"],"text":"ثارت بمدينةِ تدميرٍ فتنةٌ بين المُضَرية واليمانية، فاقتتلوا بلورقة، وكان بينهم وقعةٌ تعرَفُ بيوم المُضارة، قُتِل منهم ثلاثةُ آلاف رجل، ودامت الحربُ بينهم سبعَ سنين، فوكَلَ عبدُالرحمن بن الحكم بكَفِّهم، ومَنْعِهم، يحيى بنَ عبدِ الله بن خالد، وسيَّرَه في جميع الجيش، فكانوا إذا أحسُّوا بقرب يحيى تفَرَّقوا وتركوا القتال، وإذا عاد عنهم رجعوا إلى الفتنةِ والقتالِ، حتى عَيِيَ أمرُهم."},{"id":675,"title":"وقعة بالس في الأندلس .","date":["العام الهجري :207","العام الميلادي :822"],"text":"وقعَ عبدُ الرحمن بن الحَكَم، صاحِبُ الأندلس، بجُندِ إلبيرة وأهلِها، وهي الوقعةُ المعروفة بوقعة بالس، كان سببُها أنَّ الحكَمَ كان قد بلغه عن عاملٍ اسمُه ربيع أنَّه ظلم أبناءَ أهلِ الذمَّة، فقبض عليه وصَلَبه قبْلَ وفاته، فلمَّا توفِّيَ الحكَمُ ووَلِيَ ابنُه عبدُ الرحمن سَمِعَ النَّاسُ بصَلبِ الربيع، فأقبلوا إلى قرطبةَ مِن النواحي يطلُبونَ الأموال التي كان ظلَمَهم بها ربيعٌ؛ ظنًّا منهم أنَّها تُرَدُّ إليهم، وكان أهلُ إلبيرة أكثَرَهم طلبًا وإلحاحًا فيه، وتألَّبوا، فبعث إليهم عبدُ الرحمن من يفَرِّقُهم ويُسكِتُهم، فلم يقبَلوا، ودفعوا من أتاهم، فخرج إليهم جمعٌ من الجندِ وأصحابِ عبد الرحمن، فقاتلوهم، فانهزم جندُ إلبيرة ومن معهم، وقُتِلوا قتلًا ذَريعًا، ونجا الباقونَ مُنهَزِمينَ، ثم طلبوا بعد ذلك، فقَتَلوا كثيرًا منهم."},{"id":676,"title":"خلاف قادة الجند مع زيادة الله الأغلب .","date":["العام الهجري :207","العام الميلادي :822"],"text":"وقعَت بين زيادةِ الله وبين الجُند الحُروبُ وهاجت الفِتَن. واستولى كلُّ رئيس بناحية فملكوها عليه كُلَّها، وزحفوا إلى القيروان فحَصَروه، وكان فاتحةَ الخلافِ أنَّ زيادَ بنَ سَهلِ بن الصقليَّة حاصر مدينةَ باجة فسَرَّحَ إليه زيادةُ الله العساكِرَ فهزموه وقتلوا أصحابَه. ثمَّ انتقض منصورُ الترمذي بطبنة، وسار إلى تونُس فملَكَها, فسرَّحَ زيادةُ الله العساكِرَ من القيروان مع غلبون ابنِ عَمِّه، ووزيره اسمُه الأغلب بن عبد الله بن الأغلب، وتهددهم بالقتل إن انهَزَموا، فهزمهم منصور الترمذي، وخَشُوا على أنفسهم ففارقوا غلبون، وافترقوا على إفريقيَّة، واستولوا على باجة والجزيرة وصطفورة والأربس وغيرها. واضطربت إفريقيَّة، ثم اجتمعوا إلى منصورٍ الترمذي، وسار بهم إلى القيروان فملَكَها، ثم خرج إليه زيادةُ الله فقاتله فهزَمه، ولحِقَ قوَّاد الجند بالبلاد التي تغلَّبوا عليها، ولم يبقَ على طاعةِ زيادة الله من إفريقيَّة إلا تونس والساحل وطرابلس ونفزاوة. وبعث الجندُ إلى زيادة الله بالأمانِ وأن يرتحِلَ عن إفريقيَّة، وبلغه أنَّ عامِرَ بنَ نافع الأزرق يريدُ نفزاوة وأنَّ برابرتَها دعَوه، فسرَحَّ إليهم مائتي مقاتلٍ لِمَنع عامر بن نافع، فرجع عامرٌ عنها، وهزَمَه إلى قسطيلة ورجع. ثم هرب عنها واستولَّى سفيانُ على قسطيلة وضبَطَها. وذلك سنةَ تسعٍ ومائتين، واسترجع زيادةُ الله قسطيلةَ والزاب وطرابلس واستقام أمرُه."},{"id":677,"title":"وفاة طاهر بن الحسين أمير خراسان .","date":["العام الهجري :207","الشهر القمري : ربيع الأول","العام الميلادي :822"],"text":"هو طاهِرُ بنُ الحسينِ بنِ مُصعَبِ بن رُزَيق الأمير، مُقَدَّمُ الجُيوشِ، ذو اليمينَينِ، أبو طلحة الخزاعي، ولد طاهِرٌ في بوشنج سنة 159هـ القائم بنصرِ خلافة المأمون؛ فإنه ندبه لحربِ أخيه الأمين فسار في جيشٍ لَجِب، وحاصر الأمينَ فظَفِرَ به وقتله صبرًا، فمُقِت لتسَرُّعِه في قتله. وكان شهمًا مَهِيبًا داهيةً، جوادًا مُمَدَّحًا. كان مع فَرطِ شجاعته عالِمًا خطيبًا مفَوَّهًا بليغًا شاعرًا، بلغ أعلى الرُّتَب. استعمل المأمونُ طاهر بن الحسينِ على المشرق سنة 205هـ، من مدينة السلام ِإلى أقصى عمل المشرِق من خراسان، وكان قبل ذلك يتولَّى الشُّرَط بجانبي بغداد ومعاون السَّواد، مات طاهر بن الحسين من حُمَّى أصابته، ووُجِدَ في فراشه ميتًا."},{"id":678,"title":"وفاة الفضل بن الربيع .","date":["العام الهجري :208","العام الميلادي :823"],"text":"هو الفضلُ بنُ الربيعِ بنِ يونُسَ، الحاجِبُ الأميرُ أبو الفضل، مولِدُه سنة أربعين ومائة، وكان حاجبًا للرشيد ووزيرًا له، ولَمَّا مات الرشيدُ استولى على الخزائِنِ وقَدِمَ بها إلى الأمينِ محمَّد ببغداد ومعه البُردة والقَضيبُ والخاتَم، فأكرمه الأمينُ وفَوَّض إليه أمورَه، فصار إليه الأمرُ والنهي، ولَمَّا خلعَ الأمينُ أخاه المأمونَ مِن ولاية عهدِ الخلافة، استخفى ثم ظهرَ في أيامِ المأمونِ، فأعاده المأمونُ إلى رتبتِه إلى أن مات."},{"id":679,"title":"هزيمة نصارى الأندلس على يد عبد الكريم بن مغيث .","date":["العام الهجري :208","العام الميلادي :823"],"text":"وكان عبدُ الرحمن شديدَ الاهتمامِ بتأمين حدودِ البلاد الشماليَّة، بعد أن تزايدَ عُدوانُ الفِرنجةِ عليها، فأرسل حملةً عسكريةً كبيرةً بقيادةِ عبد الكريم بن عبد الواحد بن مغيث, وقد نجَحَت تلك الحملةُ في إلحاقِ الهزيمةِ بالنَّصارى المتربِّصين، وألحقَت بهم خسائِرَ كبيرةً بعد أن أحرَقَت حُصونَهم، وقتَلت منهم عددًا كبيرًا، وعادت الحملةُ إلى قرطبة محمَّلةً بالغنائم، وهي تسوقُ الأسرى والأسلابَ، وكان لهذه الحملةِ أثَرُها الكبيرُ في ردعِ الفرنج، واستشعارِهم قوَّةَ المسلمين، ووقوعِ هيبتِهم في قلوبِ ملوكِ الفِرنج."},{"id":680,"title":"القضاء على فتنة نصر بن شبث .","date":["العام الهجري :209","العام الميلادي :824"],"text":"أظهرَ نَصرُ بنُ سيَّار بن شبث العقيلي الخِلافَ على المأمون سنة 198ه، وكان يسكن كيسوم، ناحية شماليَّ حَلَب، وكان في عنُقِه بيعةٌ للأمين، وله فيه هوًى، فلمَّا قُتِلَ الأمينُ أظهر نصرٌ الغضَبَ لذلك، وتغلَّبَ على ما جاوره من البلاد، وملك سميساط، واجتمع عليه خلقٌ كثيرٌ مِن الأعراب، وأهلِ الطمع، وقَوِيَت نفسُه، وعبَرَ الفُرات إلى الجانب الشرقي، وحدَّثَته نفسُه بالتغلُّب عليه، فلما رأى الناسُ ذلك منه كثُرَت جموعه وزادت عما كانت، فقَوِيَ أمرُه كثيرًا، فحاصره عبد الله بن طاهر بكيسوم، وضيَّقَ عليه، حتى طلب الأمانَ، فكتب ابنُ طاهر إلى المأمون يُعلِمُه بذلك، فأرسل إليه أن يكتُبَ له أمانًا عن أمير المؤمنين، فكتب له كتابَ أمانٍ فنزل فأمر عبدُ الله بتخريبِ المدينة التي كان متحصِّنًا بها، وذهبَ شَرُّه."},{"id":681,"title":"استعادة عبدالله بن طاهر الإسكندرية للعباسيين .","date":["العام الهجري :210","العام الميلادي :825"],"text":"أخرج عبدُ الله من كان تغلَّبَ على الإسكندريةِ مِن أهل الربض الأندلسيِّينَ بأمانٍ، وكانوا قد جاؤوا في مراكِبَ مِن الأندلس في فتنةِ ابنِ السري وغيره، فأرسَوا بالإسكندرية، ورئيسُهم يدعى أبا حفص، فلم يزالوا بها حتى قَدِمَ ابنُ طاهر، فأرسل يؤذِنُهم بالحَربِ إن هم لم يدخُلوا في الطاعة، فأجابوه، وسألوه الأمانَ على أن يرتَحِلوا عنها إلى بعضِ أطراف الروم التي ليسَت من بلاد الإسلامِ، فأعطاهم الأمانَ على ذلك، فرَحَلوا ونزلوا بجزيرة إقريطش، واستوطنوها وأقاموا بها فأعقَبوا وتناسَلوا. قال يونس بن عبد الأعلى: \"أقبل إلينا فتًى حَدَثٌ من المشرق، يعني ابن طاهرٍ، والدُّنيا عندنا مفتونةٌ قد غلب على كُلِّ ناحيةٍ مِن بلادنا غالِبٌ، والنَّاسُ في بلاءٍ، فأصلح الدُّنيا وأمَّنَ البريءَ، وأخاف السَّقيمَ، واستوسَقَت له الرعيَّةُ بالطاعةِ\"."},{"id":682,"title":"خلع أهل قم للخليفة العباسي المأمون .","date":["العام الهجري :210","العام الميلادي :825"],"text":"خلعَ أهلُ قُم المأمونَ، ومنعوا الخراجَ، وكان سببُه أنَّ المأمونَ لَمَّا سار من خراسانَ إلى العراق أقام بالريِّ عِدَّةَ أيَّامٍ، وأسقط عنهم شيئًا من خراجِهم، فطَمِعَ أهلُ قُم أن يصنع بهم كذلك، فكتَبوا إليه يسألونُه الحطيطةَ، وكان خراجُهم ألفي ألف درهم، فلم يُجِبْهم المأمونُ إلى ما سألوا، فامتنعوا من أدائِه، فوجَّه المأمونُ إليهم عليَّ بن هشام، وعجيف بن عنبسة، فحارباهم فظَفِرا بهم، وقتَلَ يحيى بن عمران، وهدَمَ سُورَ المدينة، وجباها على سبعةِ آلافِ ألف درهم، وكانوا يتظَلَّمونَ مِن ألفَي ألف."},{"id":683,"title":"هزيمة الفرنج بالأندلس أمام جيوش عبدالرحمن بن الحكم .","date":["العام الهجري :210","الشهر القمري : ربيع الأول","العام الميلادي :825"],"text":"سيَّرَ عبدالرحمن بن الحكَم سريَّةً كبيرةً إلى بلاد الفرنج، واستعمل عليها عبيدَ الله المعروف بابن البلنسي، فسار ودخل بلادَ العدُوِّ، وتردَّدَ فيها بالغارات والسبيِ، والقتل والأسْر، ولقِيَ عبيد الله الأعداءَ، فاقتتلوا فانهزم المشركونَ، وكثُرَ القتلُ فيهم، وكان فتحًا عظيمًا."},{"id":684,"title":"المأمون يعفو عن عمه إبراهيم بن المهدي .","date":["العام الهجري :210","الشهر القمري : ربيع الآخر","العام الميلادي :825"],"text":"كان إبراهيمُ المهديُّ قد خرج على المأمونِ وبايعه أهلُ بغداد إلَّا أنَّ الأمرَ لم يدُمْ في يدِه طويلًا، حتى انفَضَّ عنه الناسُ وتركوه، فاختفى مدةَ سِتِّ سنين وشهور، ثم ظَفِرَ به المأمون, فاستعطفه إبراهيمُ فعفا عنه وترَكَه."},{"id":685,"title":"هزيمة الفرنج بالأندلس أمام عبد الرحمن بن الحكم .","date":["العام الهجري :210","الشهر القمري : رمضان","العام الميلادي :826"],"text":"افتتح عسكرٌ سَيَّرَه عبدُ الرحمن حِصنَ القَلعةِ مِن أرضِ العَدُوِّ، وتردَّدَ فيها بالغارات."},{"id":686,"title":"وفاة عبدالرزاق الصنعاني صاحب المصنف .","date":["العام الهجري :211","العام الميلادي :826"],"text":"هو أبو بكر عبدُالرَّزاق بن همام بن نافع الحِمْيري ولاءً الصَّنعاني، الحافِظُ المحَدِّث الثِّقة، عالمُ اليمَنِ الكبيرُ، ولد بصنعاء سنة 126هـ, روى عنه خلقٌ كثيرٌ، منهم الإمام أحمدُ وابنُ عُيَينة، قال الذهبي: هو خزانةُ العِلمِ، له كتابٌ في التفسير، وأشهرُ كتُبِه هو (المصنَّف) المعروفُ، جمعَ فيه الكثيرَ من الأحاديثِ والآثارِ الموقوفةِ عن الصحابة وعن التابعين. كان فيه تشيُّعٌ لعليٍّ، قال أحمد العجلي: عبد الرزَّاق ثقةٌ، كان يتشَيَّع. قال عبدالرزاق: ما انشرح صدري قطُّ أن أفضِّلَ عليًّا على أبي بكرٍ وعُمَرَ، فرحمهما الله, ورَحِمَ عُثمانَ وعَلِيًّا، مَن لم يحِبَّهم فما هو بمؤمنٍ، أوثَقُ عَمَلي حبِّي إياهم. وقال أيضًا: أفضِّلُ الشيخينِ بتفضيلِ عليٍّ إيَّاهما على نفسِه، كفى بي إزراءً أن أخالِفَ عليًّا.   قال أبو صالح محمَّد بن إسماعيل الصراري: بلَغَنا ونحن بصنعاء عند عبد الرزَّاق أنَّ أصحابَنا- يحيى بن مَعِين، وأحمدَ بن حنبل، وغيرَهما- تركوا حديثَ عبد الرزاق وكَرِهوه، فدخَلَنا من ذلك غَمٌّ شديد، وقلنا: قد أنفَقْنا ورَحَلْنا وتَعِبْنا، فلم أزَلْ في غَمٍّ مِن ذلك إلى وقتِ الحَجِّ، فخرجتُ إلى مكَّةَ، فلقيتُ بها يحيى بنَ مَعِينٍ، فقلتُ له: يا أبا زكريَّا، ما نزل بنا من شيءٍ بلَغَنا عنكم في عبدِ الرزاق؟ قال: وما هو؟ قلنا: بلَغَنا أنَّكم تركتُم حديثَه، ورَغِبتُم عنه، قال: يا أبا صالحِ، لو ارتَدَّ عبد الرزَّاق عن الإسلامِ، ما تركْنا حديثَه."},{"id":687,"title":"فتنة عبيدالله بن السري بمصر .","date":["العام الهجري :211","الشهر القمري : صفر","العام الميلادي :826"],"text":"لَمَّا توفِّيَ السري أميرُ مصرَ للمأمونِ، وليَ بعدَه ابنُه عُبيدالله، ولَّاه الجُندُ وبايعوه، ثم حدَّثَته نفسُه الخروجَ عن طاعة المأمونِ وجَمَع وحَشَد، فبلغ المأمونَ ذلك وطلب عبدَ الله بنَ طاهرٍ لقتالِه وقتالِ الخوارج بمصرَ، فسار إليه ابنُ طاهر فتهَّيأ عُبيد الله بن السري لحَربِه وعبَّأ جيوشَه وحفَرَ خندقًا عليه، ثم تقدَّم بعساكِرِه إلى خارج مصرَ والتقى مع عبد اللهِ بنِ طاهر وتقاتلا قتالًا شديدًا، وثبت كلٌّ من الفريقينِ ساعةً كبيرةً حتى كانت الهزيمةُ على عُبيد الله بن السري أميرِ مصر، وانهزم إلى جهةِ مِصرَ، وتَبِعَه عبد الله بن طاهر بعساكِرِه فحاصره عبدُ الله بن طاهر وضيَّقَ عليه حتى أباده وأشرف على الهلاكِ، فطلب عُبيد الله بن السري الأمانَ مِن عبد الله بن طاهر بشُروطِه، فأمَّنَه عبدُ الله بن طاهر بعد أمورٍ صَدَرت، فخرج إليه عُبيد الله بن السري بالأمانِ، وبذل إليه أموالًا كثيرةً، وأذعن له وسلَّمَ إليه الأمرَ."},{"id":688,"title":"المأمون يدعو بأفضلية علي بن أبي طالب رضي الله عنه .","date":["العام الهجري :211","الشهر القمري : ربيع الأول","العام الميلادي :826"],"text":"في هذه السَّنةِ أظهر المأمونُ أوَّلَ بِدَعِه الشنيعةِ، فأمر مناديًا ينادي: بَرِئَت الذمَّةُ ممَّن ذكر معاويةَ بنَ أبي سفيان بخيرٍ أو فضَّلَه على أحدٍ مِن الصَّحابة، وينادي: إنَّ أفضَلَ الخَلقِ بعد رَسولِ الله صلَّى الله عليه وسلَّم عليُّ بنُ أبي طالب. وقيل: كان المأمون يبالِغُ في التشيُّعِ، لكنَّه لم يتكلَّمْ في الشَّيخينِ بسُوءٍ، بل كان يترضَّى عنهما ويعتقِدَ إمامتَهما."},{"id":689,"title":"وفاة أبي العتاهية الشاعر .","date":["العام الهجري :211","الشهر القمري : جمادى الآخرة","العام الميلادي :826"],"text":"هو أبو إسحاقَ، إسماعيلُ بنُ القاسم بن سويد العنزيُّ ولاءً، المشهورُ بأبي العتاهية، لقَّبَه بذلك الخليفةُ المهديُّ، ولِدَ في عين التمر سنة 130هـ، نشأ بالكوفة، قال الشِّعرَ سَجِيَّةً مِن نفسه، قَدِمَ بغداد على المهديِّ وقَرَّبه الرشيدُ، كان شاعرًا مُكثِرًا، وكان أوَّلَ أمرِه في الغَزلِ، ثم أخذ في شِعرِ الزُّهد والتقشُّف والوَرَع، توفِّي عن عمر يناهز الثمانين."},{"id":690,"title":"المأمون يوجه محمد الطوسي لمحاربة بابك الخُرَّمي .","date":["العام الهجري :212","العام الميلادي :827"],"text":"بدأت فِتنةُ بابك الخرمي صاحِبُ البذ عام مائتان وواحد، وهم أصحابُ جاويدان بن سهل، وادَّعى بابك أنَّ روحَ جاويدان دخَلَت فيه، فأخذ في العَيثِ والفساد، فكان يُخشى من أمْرِه؛ لأنَّه في أطرافِ الرُّومِ، ويُمكِنُ أن يتحالَفَ معهم ضِدَّ المسلمين، وكان قبل ذلك حصَلَت عِدَّةُ محاولاتٍ لإخماد فتنتِه؛ لكِنَّها لم تنجَحْ، فوَجَّه المأمونُ محمَّدَ بن حميد الطوسي إلى بابك الخرمي لمحاربتِه، وأمَرَه أن يجعَلَ طريقَه على الموصِلِ ليُصلِحَ أمْرَها ويحارِبَ زريقَ ابنَ علي، وكان المأمونُ ولَّى عليَّ بنَ صدقة المعروف بزُريق، على أرمينية، وأذربيجان، وأمره بمحاربةِ بابك، وأقام بأمْرِه أحمدَ بنَ الجنيد الإسكافي، فأسَرَه بابك، فولَّى إبراهيمَ بنَ اللَّيثِ بن الفضل أذربيجان، فسار محمَّدٌ إلى الموصل، ومعه جيشُه، وجمع ما فيها من الرجالِ مِن اليمن وربيعة، وسار لحَربِ زُريق، ومعه محمَّدُ بن السيد بن أنس الأزدي، فبلغ الخبَرُ إلى زريق، فسار نحوَهم، فالتقَوا في الزاب، فراسَله محمَّدُ بن حميد يدعوه إلى الطاعةِ فامتنع، فناجزه محمَّد واقتتلوا واشتَدَّ قتال الأزدي، فانهزم زريقٌ وأصحابه، ثم أرسل يطلبُ الأمان، فأمَّنه محمَّد، فنزل إليه، فسَيَّرَه إلى المأمون. ثم سارَ إلى أذربيجان، واستخلف على الموصلِ محمَّدَ بن السيد، وقصد المخالفينَ المتغَلِّبينَ على أذربيجان فأخَذَهم، منهم يعلى بنُ مُرَّة ونظراؤه، وسيَّرَهم إلى المأمون وسار نحو بابك الخرمي لمحاربتِه."},{"id":691,"title":"المأمون يعتنق مذهب المعتزلة ويعلنه مذهبا رسميا للدولة .","date":["العام الهجري :212","العام الميلادي :827"],"text":"أظهرَ المأمونُ بِدعتَه الثانيةَ الشَّنيعةَ، ولم يأت هذا الإظهارُ دون سوابِقَ، بل إنَّ المأمونَ عُرِفَ عنه تقريبُه لأئمَّة المعتَزِلة وتودُّده إليهم وإكرامُه لهم، فتأثر بهم وبمذهبِهم، حتى قال بقَولِهم، ولم يقف الأمرُ عند هذا الحَدِّ، بل ألبوه على عُلَماءِ السنَّة الذين يخالفونَهم في الرأي، وكان من أشدِّ الأمور التي ظهر الخلافُ فيها هي مسألةُ خلقِ القرآنِ، فأهلُ السنَّة والجماعة يقولون: إنَّه كلامُ اللهِ غيرُ مخلوقٍ، بل هو صِفةٌ مِن صفاتِه عَزَّ وجَلَّ، وصفاتُه غيرُ مخلوقةٍ، وأمَّا هؤلاء المعتزلةُ ومَن وافقَهم من الجهميَّة وغيرِهم فيقولون بل إنَّ كلامَه مخلوقٌ، فأظهَرَ هذه البدعةَ المأمونُ، وامتحَنَ العُلَماءَ عليها بعد ذلك وعذَّبَ فيها من عذَّبَ، وقَتَلَ فيها من قَتَل، واللهُ المُستعان."},{"id":692,"title":"فتح المسلمين جزيرة كريت وتأسيس قاعدة بحرية فيها .","date":["العام الهجري :212","العام الميلادي :827"],"text":"استولى أهلُ الربض الهاربين من الأندلُسِ على الإسكندرية، فقام عبدُالله بن طاهر أميرُ مِصرَ بمحاصَرتِهم فأعطاهم الأمانَ بشَرطِ الرحيلِ إلى جزيرة كريت، فذهبوا واستولَوا على جزيرةِ كريت التي كانت في أيدي البيزنطيِّينَ وجعلوا عليهم واليًا هو أبو حفصٍ عمَرُ البلوطي، وأسَّسوا قاعدةً لهم بالجزيرةِ وأحاطوها بخندقٍ كبيرٍ، فأصبحت تُعرَفُ باسم الخندق، والتي تُعرَفُ كذلك بهراقليون، وبقيت هذه الجزيرةُ بأيدي المسلمين إلى سنة 350هـ"},{"id":693,"title":"المسلمون يحتلون جزيرة صقلية .","date":["العام الهجري :212","العام الميلادي :827"],"text":"استولى على جزيرةِ صقليَّة فيمي الروميُّ الذي غلَبَ عامِلَ قُسطنطينَ عليها، وكان فيمي طلبَ مِن زيادةِ الله النَّجدةَ، فجهز زيادةُ الله جيشًا كبيرًا بإمرة أسَدِ بنِ الفُرات قاضي القيروان، الذي سار إليهم فانتصرَ المسلمون بالبداية، ثم جاءت نجداتُ الروم إلى نصارى صقلية وانقلبَ فيمي اللعينُ على المسلمينَ، ومات أسدُ بنُ الفرات، فلم يتوغَّلوا داخِلَ الجزيرةِ، لكِنَّ النجدة جاءت من القيروان كما وصلَت سفُنٌ مِن الأندلس ساعدت المسلمينَ، فحاصر المسلمونَ بلرم عام 215هـ وفتحوها في العام التالي."},{"id":694,"title":"وفاة إدريس الثاني حاكم دولة الأدارسة .","date":["العام الهجري :213","العام الميلادي :828"],"text":"كان إدريسُ الثاني قد بُويِعَ وهو رضيعٌ، ولَمَّا بلغ الحاديةَ عشرة من عمره بويع مرةً أخرى، وكان جوادًا أحبَّه الرعيَّةُ، واستمال أهلَ تونُسَ وطرابلس الغرب التي كان يحكُمُها الأغالبة، وانتظم له البربر وبنى مدينةَ فاس، وأخضع الخوارِجَ الصفرية في تلمسان، فلما مات عن عمر 36 عامًا خَلَفَه ابنُه محمَّدٌ، فاختلف الأدارسة؛ إذ نازعه أخوه عيسى بن إدريسَ الذي كان واليًا على أزمور، فأراد محمد أن يستعينَ عليه بأخيه القاسمِ والي طنجةَ، لكن القاسِمَ رفضَ، فاستنجد بأخيه عُمَر والي مكناس، فساعده وسار أولًا إلى عيسى، فلما أوقع عمَرُ بعيسى وغلبَ على ما في يده استنابَه إلى أعمالِه بإذن أخيه محمَّد، ثم أمَرَه أخوه محمَّد بالنهوض إلى حربِ القاسم لقعوده عن إجابتِه في محاربة عيسى، فزحف إليه وأوقع به واستناب عليه إلى ما في يَدِه، فصار الريفُ البحري كلُّه من عمَلِ عُمَرَ مِن تيكيشاش وبلاد غمارة إلى سبتة ثم إلى طنجة."},{"id":695,"title":"ثورة أهل ماردة في الأندلس .","date":["العام الهجري :213","العام الميلادي :828"],"text":"قتلَ أهلُ ماردةَ مِن الأندلس عامِلَهم، فثارت الفتنةُ عندهم، فسيَّرَ إليهم عبدُ الرحمن جيشًا فحصرهم، وأفسَدَ زَرعَهم وأشجارَهم، فعاودوا الطاعةَ، وأُخِذَت رهائنُهم، وعاد الجيشُ بعد أن خَرَّبوا سور المدينة. ثم أرسل عبد الرحمن إليهم بنقلِ حِجارةِ السُّورِ إلى النهرِ؛ لئلَّا يطمَعَ أهلُها في عمارتِه، فلمَّا رأوا ذلك عادوا إلى العِصيانِ، وأسَرُوا العامِلَ عليهم، وجدَّدوا بناء السور وأتقَنوه، ثم تتابعَ القِتالُ بينهم عدَّةَ مَرَّاتٍ خلال عدَّةِ سَنواتٍ إلى سنة 225هـ"},{"id":696,"title":"مقتل محمد الطوسي على يد بابك الخُرَّمي .","date":["العام الهجري :214","العام الميلادي :829"],"text":"لَمَّا فرغ محمَّدُ بن حميد الطوسي مِن أمْرِ المتغَلِّبينَ على طريقِه إلى بابك الخُرمي سار نحوه وقد جمع العساكر، والآلاتِ والميرة، فاجتمع معه عالمٌ كثير من المتطوِّعةِ مِن سائر الأمصار، فسلك المضايقَ إلى بابك، وكان كلَّما جاوز مضيقًا أو عقبةً ترك عليه من يحفَظُه من أصحابِه إلى أن نزل بهشتادسر (جبل في إيران)، وحفَر خندقًا وشاور في دخولِ بلد بابك، فأشاروا عليه بدخولِه مِن وجهٍ ذكروه له، فقَبِلَ رأيهم، وعبَّأ أصحابه، فكان بابك يُشرِفُ عليهم من الجبل، وقد كمَنَ لهم الرجالُ تحت كلِّ صخرةٍ، فلما تقدَّمَ أصحابُ محمد، وصَعِدوا في الجبل خرج عليهم الكُمَناء وانحدر بابك إليهم فيمن معه، وانهزم الناسُ، وصبَرَ محمَّد بن حميد مكانَه، وفرَّ من كان معه غيرَ رجلٍ واحد، وسارا يطلبانِ الخلاص، فرأى جماعةً وقِتالًا فقَصَدهم، فرأى الخرميَّة يقاتلونَ طائفةً مِن أصحابه، فحين رآه الخرميَّة قصدوه؛ لِما رأَوا من حسن هيئتِه، فقاتَلَهم، وقاتلوه، وضربوا فَرَسه بزراق، فسقط إلى الأرضِ، وأكبُّوا على محمد بن حميد فقتلوه."},{"id":697,"title":"خروج هاشم الضراب بطليطلة .","date":["العام الهجري :214","العام الميلادي :829"],"text":"خرج هاشم الضرَّابُ بمدينة طليطلة، من الأندلس، على صاحِبِها عبد الرحمن، وكان هاشِمٌ قد خرج من طليطِلة لَمَّا أوقع الحكَمُ بأهلِها، فسار إلى قُرطُبةَ، ثم سار إلى طليطِلة، فاجتمع إليه أهلُ الشرِّ وغَيرُهم، فسار بهم إلى وادي نحوييه وأغار على البربر وغيرهم، فطار اسمُه واشتَدَّت شَوكتُه، واجتمع له جمعٌ عظيم، وأوقع بأهلِ شنت برية. وكان بينه وبين البربرِ وقعاتٌ كثيرة، فسيَّرَ إليه عبد الرحمن جيشًا فقاتلوه، فلم تستظهِرْ إحدى الطائفتينِ على الأخرى، وبقِيَ هاشِمٌ كذلك، وغلَبَ على عدَّةِ مواضِعَ، فسيَّرَ إليه عبد الرحمن جيشًا كثيفًا سنةَ سِتَّ عشرة ومائتين، فلَقِيَهم هاشم بالقُربِ مِن حِصنِ سمسطا بمجاورة رورية، فاشتدَّت الحربُ بينهم، ودامت عدَّةَ أيَّامٍ، ثم انهزم هاشِمٌ، وقُتِلَ هو وكثيرٌ ممَّن معه من أهل الطَّمَعِ والشَّرِّ وطالبي الفِتَن، وكفى الله النَّاسَ شَرَّهم."},{"id":698,"title":"ثورة القيسية واليمانية على العباسيين في الديار المصرية .","date":["العام الهجري :214","الشهر القمري : ربيع الأول","العام الميلادي :829"],"text":"كان على مصرَ عُمَير بن الوليد الباذغيسي التميمي أميرُ مصر، ولِيَ مِصرَ باستخلافِ أبي إسحاق محمد المعتَصِم له؛ لأن الخليفةَ المأمون كان ولَّى مصرَ لأخيه المعتصم بعد عزلِ عبد الله بن طاهر، وولى المعتَصِمُ عُميرَ بن الوليد على الصَّلاة، وسكَن العَسكرِ، وجعل على شُرطتِه ابنَه محمدًا؛ وعندما تمَّ أمرُه خرج عليه القيسيَّة واليمانية الذين كانوا خَرَجوا قبل تاريخه وعليهم عبد السَّلامِ وابن الجليس، فتهيأ عُمَيرُ بن الوليد وجمعَ العساكِرَ والجند، وخرج لقتالهم، وخرج معه أيضًا فيمن خرج الأميرُ عيسى بن يزيد الجلودي المعزول به عن إمرة مصرَ، واستخلف عميرٌ ابنَه مُحمدًا على صلاة مصر، وسافر بجيوشِه حتى التقى مع أهل الحوف القيسية واليمانية؛ فكانت بينهم وقعةٌ هائلة وقتالٌ ومعاركُ، وثبت كلٌّ من الفريقين حتى قُتِلَ عميرٌ في المعركة. فسار المعتَصِمُ إلى مصر، وقاتَلَهما فقتَلَهما وافتتح مصر، فاستقامت أمورُها واستعمل عليها عمَّالَه."},{"id":699,"title":"العباسيون ينهون فتنة القيسيَّة واليمانية في مصر .","date":["العام الهجري :214","الشهر القمري : شعبان","العام الميلادي :829"],"text":"وليَ عيسى بن يزيد الجلودي مصرَ مِن قِبَل أبي إسحاقَ محمَّد المعتَصِم بعد قتل القيسيَّة واليمانية عميرَ بنَ الوليد الباذغيسي التميمي عامِلَ المعتَصِم على الصلاة، ولَمَّا قَدِمَ عيسى بن يزيد مصر، قصَدَه قيسٌ ويمن على العادةِ، وقد كثُرَ جَمعُهم من أهل الحوف وقطَّاع الطريق، فوقع لعيسى معهم حروبٌ وفِتَن، وجمع عساكِرَه وخرج إليهم حتى التقاهم بمنية مطَر (بقرب مدينة عينِ شَمس) وقاتلهم، فكانت بينهم حروبٌ هائلة انكسر فيها الأميرُ عيسى بمن معه، وقُتِل من عسكَرِه خلائِقُ، وانحاز إلى مصر، وبلغ المأمونَ ذلك، فعَظُمَ عليه وطلب أخاه أبا إسحاقَ محمَّدًا المعتَصِمَ وندَبَه للخروجِ إلى مصر، وقال له: امْضِ إلى عمَلِك وأصلِحْ شأنَه، وكان المعتَصِمُ شُجاعًا مِقدامًا؛ فخرج المعتصِمُ مِن بغداد في أربعةِ آلاف من أتراكِه وسافر حتى قَدِمَ مِصرَ في أيام يسيرةٍ، وعيسى كالمحصورِ مع أهل الحوف، وقبلَ دُخولِه إلى مصرَ بدأ بقتالِ أهل الحوف من القيسيَّة واليمانية وقاتَلَهم وهزَمَهم، وقتل أكابِرَهم ووضَعَ السَّيفَ في القيسية واليمانية حتى أفناهم، وذلك في شعبانَ مِن السنة، ومَهَّدَ البلادَ وأباد أهلَ الفساد، ثم دخل الفسطاطَ وفي خدمته عيسى الجلودي وجميعُ أعيان المصريين."},{"id":700,"title":"الخليفة المأمون يطور بيت الحكمة ببغداد .","date":["العام الهجري :215","العام الميلادي :830"],"text":"أُنشِئَت هذه المكتبةُ في القرن الثاني الهجري ( الثامن الميلادي) على يدِ هارونَ الرشيد، وذلك بعد أن ضاقت مكتبةُ القَصرِ بما فيها من كتُبٍ, وعَجَزت عن احتواءِ القُرَّاء المتردِّدين عليها؛ ممَّا جعله يفكِّرُ في إخراجِها من القصر, وإفرادِها بمبنًى خاصٍّ بها, يَصلُحُ لاستيعابِ أكبَرِ عدَدٍ مِن الكتُبِ, ويكون مفتوحًا أمام كلِّ الدارسينَ وطُلَّابِ العِلمِ. فاختار لها مكانًا مُناسِبًا, وأقام عليه مبنًى مكَوَّنًا من عدَّةِ قاعات؛ قاعة للاطِّلاع, وقاعة للمُدارَسة, وقاعة لنَسخِ الكتُبِ الجديدة وتجليدِها, وقاعة للتَّرويحِ عن النَّفسِ وللاستراحةِ. ومسجِدًا للصلاةِ, ومكانًا يَبيتُ فيه الغُرَباء, تتوفَّرُ فيه مقوِّماتُ الحياةِ مِن طعامٍ وشَرابٍ وغَيرِه, ومخزنًا للكتُب, نظمَت فيه بحيثُ صار لكُلِّ فَنٍّ مِن الفنون العِلميَّة مكانٌ خاصٌّ به, وتُوضَعُ فيه مُرَتَّبةً في دواليبَ، ثم زوَّدها بما تحتاجُ إليه من أثاثٍ ومرافِقَ, وأحبارٍ وأوراقٍ للدارسين, وعيَّنَ لها المُشرِفينَ على إدارتِها, والعُمَّالَ القائمينَ على خدمة ورعايةِ زائريها. وواصلَ ابنُه المأمونُ بعده الاهتمامَ بتلك المكتبةِ، فأحضر مئاتِ النُّسَّاخ والشُّرَّاح والمُترجِمينَ مِن شَتَّى اللُّغات؛ لتعريبِ ونَقلِ الكتُبِ من لغَتِها الأصلية, حتى غَدَت من أعظَمِ المكتبات في العالَم, ووضع بها مرصدًا؛ ليكون تعليمُ الفلَكِ فيها تعليمًا عمليًّا، يجَرِّبُ فيها الطلابُ ما يدرُسونَه من نظريَّاتٍ عِلميَّةٍ, وبنى بها مستشفًى لعلاجِ المرضى وتعليمِ الطِّبِّ؛ إذ كان يؤمِنُ بأن العِلمَ النظري وحده لا جَدوى منه. وكتب إلى ملكِ الرومِ يسألُه الإذنَ في إنفاذِ ما عنده من العلومِ القديمة المخزونةِ المورَّثة عن اليونان, واجتمع لدى المأمونِ بذلك ثروةٌ هائلةٌ مِن الكتبِ القديمة, فشَكَّلَ لها هيئةً مِن المترجمينَ المَهَرة والشُّرَّاح والورَّاقينَ؛ للإشرافِ على ترميمِها ونَقلِها إلى العربيَّة, وعيَّنَ مسؤولًا لكلِّ لغةٍ يُشرِفُ على من يُترجِمونَ تُراثَها, وأجرى عليهم الرواتبَ العظيمة, حيث جعل لبعضِهم خمسَمائة دينارٍ في الشهر, أي ما يساوي 2كيلو جرام ذهبًا تقريبًا, بالإضافة إلى الأعطيات الأخرى, إذ أعطى على بعضِ الكتُبِ المُترجَمة وزنَها ذهبًا. وبعضُهم كان يقومُ بترجمة الأصلِ إلى لُغتِه هو, ثم يقومُ مترجِمٌ آخَرُ بنَقلِه إلى العربيَّةِ وغيرِها, ولم يقتَصِرْ دَورُ المترجمينَ على الترجمةِ فقط، وإنما قاموا بالتعليقِ على هذه الكتب، وتفسيرِ ما فيها من نظريَّات, ونَقْلها إلى حيِّز التطبيق, وإكمالِ ما فيها من نَقْصٍ, وتصويبِ ما فيها من خطأٍ؛ حيث كان عمَلُهم يُشبِهُ ما يسمَّى بالتحقيقِ الآن, وما إن انتهى عصرُ المأمون حتى كانت معظَمُ الكتُبِ اليونانيَّة والهنديَّة والفارسية وغيرِها من الكتب القديمة في علومِ الرياضةِ والفَلَك والطبِّ والكيمياءِ والهندسةِ موجودةً بصورتها العربيَّة الجديدةِ بمكتبة بيتِ الحكمةِ. كان للترجمةِ التي عَمِلَ عليها المأمونُ أثَرٌ واضِحٌ في تطوُّرِ الحركة العلميَّة لدى المسلمين إلَّا أنَّها نقَلَت معها بعضَ مُعتَقداتِ الأُمَم السابقة، وأفسدت على بعضِ المُسلِمين دينَهم. يقولُ شيخُ الإسلامِ ابنُ تيميَّة: \"أظهر اللهُ مِن نورِ النبوةِ شَمسًا طَمَسَت ضوءَ الكواكبِ، وعاش السَّلَفُ فيها بُرهةً طويلةً، ثم خَفِيَ بعضُ نورِ النبوة؛ فعُرِّبَ بعضُ كتُبِ الأعاجِمِ الفلاسفةِ مِن الرومِ والفُرس والهند في أثناءِ الدولة العباسيَّة، ثم طُلِبَت كتُبُهم في دولة المأمونِ مِن بلاد الروم فعُرِّبَت، ودَرَسَها الناسُ وظهر بسبب ذلك من البِدَعِ ما ظهر، وكان أكثَرُ ما ظهر من علومِهم الرياضيَّة كالحسابِ والهيئةِ، أو الطبيعةِ كالطبِّ أو المنطقيَّة، فأمَّا الإلهيَّةُ: فكلامُهم فيها نَزْرٌ، وهو مع نزارتِه ليس غالِبُه عندهم يقينًا، وعند المسلمينَ من العلومِ الإلهيَّة الموروثة عن خاتَمِ المُرسَلين ما ملأ العالمَ نُورًا وهدًى\". وقال أيضًا رحمه الله: \"إنَّ أمَّتَنا- أهلَ الإسلامِ- ما زالوا يَزِنون بالموازينِ العَقليَّة, ولم يسمَعْ سَلَفًا بذكرِ هذا المنطقِ اليوناني, وإنَّما ظهر في الإسلامِ لَمَّا عُرِّبَت الكتبُ الروميَّة في عهد دولة المأمونِ\""},{"id":701,"title":"خروج المأمون بنفسه لغزو الروم .","date":["العام الهجري :215","الشهر القمري : جمادى الأولى","العام الميلادي :830"],"text":"سار المأمونُ بنفسه لِغَزوِ الرُّومِ؛ لأنه ربما شعر أنَّ النَّاسَ قد ركنت للرفاهيةِ وضَعُفَت عندهم رُوحُ الجهادِ، كما أنَّ الفُرقةَ بدأت تعصِفُ بينهم بريحِها المُنتِنة؛ مما شجَّعَ كثيرًا من المتمرِّدينَ على الخروج، فسار مِن بغداد على طريقِ المَوصِل، حتى صار إلى منبج، ثم إلى دابق، ثم إلى أنطاكية، ثم إلى المصيصة وطرسوس، ودخل منها إلى بلاد الرُّوم، ودخل ابنُه العبَّاسُ مِن ملطية، فأقام المأمونُ على حِصنِ قرَّة حتى افتتحه عَنوةً، وهَدَمه، وقيل: إنَّ أهله طلبوا الأمانَ فأمَّنَهم المأمون، وفتح قبله حِصنَ ماجدة بالأمان، ووجَّه أشناس إلى حصنِ سندس، فأتاه برئيسِه، ووجَّه عجيفا وجعفرًا الخياطَ إلى صاحِبِ حِصنِ سناذ، فسَمِعَ وأطاع، ثم قفل راجعًا إلى دمشق."},{"id":702,"title":"عودة المأمون إلى غزو الروم .","date":["العام الهجري :216","الشهر القمري : جمادى الأولى","العام الميلادي :831"],"text":"عاد المأمونُ إلى بلاد الروم في هذه السَّنة بعد أن كان سار إليهم أوَّلَ السَّنة الماضية، وسببُ ذلك أنَّه بلغه أنَّ مَلِكَ الرومِ قتلَ ألفًا وستَّمائة مِن أهل طرسوس والمصيصة، فسار حتى دخل أرضَ الروم، وقيل كان سببُ دُخولِه إليها أنَّ مَلِكَ الرومِ كتب إليه وبدأ بنَفسِه، فسار إليه، ولم يقرأ كتابَه، فلمَّا دخل أرضَ الرومِ أناخ على أنطيغو، فخرجوا على صُلْحٍ، ثم سار إلى هرقلة، فخرج أهلُها على صلحٍ، ووجَّه أخاه أبا إسحاقَ المعتَصِم، فافتتح ثلاثينَ حِصنًا ومطمورةً، ووجَّه يحيى بن أكثم من طوانة، فأغار وقتل وأحرَقَ، فأصاب سبيًا ورجع؛ ثم سار المأمونُ إلى كيسوم، فأقام بها يومين، ثم ارتحل إلى دمشق."},{"id":703,"title":"خروج عبدوس الفهري على العباسيين بمصر .","date":["العام الهجري :216","الشهر القمري : جمادى الأولى","العام الميلادي :831"],"text":"انتفض الوجهُ البحري بمصرَ بزعامة عبدوس الفهري وانضم الأقباطُ إليهم، وحَشَدوا وجمعوا فكثُرَ عددُهم وساروا نحو الديارِ المصرية، فتجهَّزَ عيسى بن منصور وجمعَ العساكِرَ والجندَ لقتالهم، فضَعُف عن لقائِهم وتقهقر بمن معه، فدخلت الأقباطُ وأهل الغربيَّة مصرَ، وأخرجوا منها عيسى هذا على أقبَحِ وجهٍ؛ لسُوءِ سِيرتِه، وخرج معه أيضًا مُتولِّي خَراجِ مِصرَ وخلعوا الطاعةَ، فقدم الأفشين حيدر بن كاوس من بُرقةَ وتهيَّأ لقتال القوم، وانضمَّ إليه عيسى بنُ منصور ومن انضاف إليه، وتجمَّعوا وتجهَّزوا لقتال القوم وواقعوهم فظَفِروا بهم بعد أمورٍ وحروبٍ، وأسَروا وقَتَلوا وسَبَوا، ثم مضى الأفشين إلى الحوفِ وقاتَلَهم أيضًا لِمَا بلغه عنهم، وبدَّدَ جَمعَهم وأسَرَ منهم جماعةً كبيرةً بعد أن بضعَ فيهم وأبدَع، ودامت الحروبُ في السنة المستمرة بمصرَ في كل قليلٍ إلى أن قَدِمَها أميرُ المؤمنين عبد الله المأمونُ لخَمسٍ خلون من المحرَّم سنة سبع عشرة ومائتين، فسَخِطَ على عيسى بن منصور وحَلَّ لواءه وعزَلَه ونسب له كلَّ ما وقع بمصرَ ولِعُمَّاله؛ ثم جهَّزَ العساكِرَ لقِتالِ أهلِ الفساد، وأحضرَ بين يديه عبدوس الفهري فضُرِبَت عنُقُه ثم سار عسكرُه لقتال أسفَلِ الأرضِ أهلِ الغربيَّة والحوف، وأوقعوا بهم وسَبَوا القبطَ وقتلوا مقاتِلَتَهم وأبادوهم، وقمعوا أهلَ الفسادِ مِن سائِرِ أراضي مصرَ بعد أن قتَلوا منهم مقتلةً عظيمةً، ثم رحل الخليفةُ المأمون من مصر."},{"id":704,"title":"ابتداع المأمون التكبير عقب الصلوات الخمس .","date":["العام الهجري :216","الشهر القمري : رمضان","العام الميلادي :831"],"text":"كتب المأمونُ إلى نائِبِه ببغداد إسحاقَ بنِ إبراهيم أن يأخُذَ الجندُ بالتكبيرِ إذا صَلَّوا الجمعةَ، وبعد الصَّلواتِ الخَمسِ إذا قَضَوا الصلاةَ أن يَصيحوا قيامًا ويكَبِّروا ثلاثَ تكبيراتٍ، ففعل ذلك، فقال الناسُ: هذه بدعةٌ ثالثة."},{"id":705,"title":"المأمون يحاصر حصن لؤلؤة في بلاد الروم .","date":["العام الهجري :217","العام الميلادي :832"],"text":"ركِبَ المأمون إلى بلاد الروم فحاصر حِصنَ لؤلؤةَ مائة يومٍ، ثم ارتحلَ عنها واستخلف على حصارِها عجيف بن عنبسة، فخدعته الرومُ فأسَروه فأقام في أيديهم ثمانيةَ أيام، ثم انفَلَت منهم واستمَرَّ محاصِرًا لهم، فجاء توفيل ملِكُ الروم بنفسِه، فأحاط بجيشِه من ورائه، فبلغ المأمونَ فسار إليه، فلمَّا أحس توفيل بقدومِه هرب وبعث وزيرَه صنغل، فسأله الأمانَ والمصالحةَ، لكنَّه بدأ بنَفسِه قبل المأمون فرَدَّ عليه المأمونُ كتابًا بليغًا مضمونُه التقريعُ والتوبيخُ؛ قال فيه: وإنِّي إنما أقبل منك الدخولَ في الحنيفيَّة، وإلَّا فالسيفُ والقَتلُ، والسلامُ على من اتَّبع الهُدى."},{"id":706,"title":"تمرد علي بن هشام في أذربيجان .","date":["العام الهجري :217","الشهر القمري : جمادى الأولى","العام الميلادي :832"],"text":"كان المأمونُ استعمل عليَّ بنَ هِشامٍ على أذربيجان وغيرها، فبلغه ظُلمُه، وأخذُه الأموالَ، وقتلُه الرجالَ، فوجَّهَ إليه عجيف بن عنبسة، فثار به عليُّ بن هشام، وأراد قَتْلَه واللَّحاقَ ببابك، فظَفِرَ به عجيف، وقَدِمَ به على المأمونِ، فقتَلَه وقتل أخاه حبيبًا، وطِيفَ برأسِ عليٍّ في العراقِ وخراسان، والشام ومِصرَ، ثم ألقيَ في البحرِ."},{"id":707,"title":"المأمون يمتحن العلماء والفقهاء في مسألة خلق القرآن .","date":["العام الهجري :218","العام الميلادي :833"],"text":"لم يكتَفِ المأمونُ باعتناقِ مسألةِ القَولِ بخلقِ القرآن، بل كتب إلى عمَّالِه في الأمصارِ بامتحانِ العُلَماءِ في هذه المسألة من أجاب وإلَّا كان العقابُ، وربَّما بطانتُه من العلماء كانوا وراء هذا الامتحان، فكتب المأمونُ إلى نائبه ببغداد إسحاقَ بن إبراهيم بن مُصعَب يأمُرُه أن يمتَحِنَ القُضاةَ والمحَدِّثين بالقَولِ بخَلقِ القرآن، وأن يرسل إليه جماعةً منهم، وكتب إليه يستحِثُّه في كتابٍ مُطَوَّل، وكتب غيره مَضمونُها الاحتجاجُ على أنَّ القرآنَ مُحدَثٌ، وكُل مُحدَث مخلوقٌ، وهذا احتجاجٌ لا يوافِقُه عليه كثيرٌ مِن المتكلِّمينَ فَضلًا عن المحدِّثينَ؛ فإنَّ القائلينَ بأنَّ الله تعالى تقوم به الأفعالُ الاختياريَّة لا يقولونَ بأنَّ فِعلَه تعالى القائِمَ بذاتِه المقَدَّسة، مخلوقٌ، بل لم يكن مخلوقًا، بل يقولون: هو محدَثٌ وليس بمخلوق، بل هو كلامُ اللهِ القائِمُ بذاته المقدَّسة، وما كان قائمًا بذاته لا يكون مخلوقًا، وقد قال الله تعالى: {مَا يَأْتِيهِمْ مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ}، وقال تعالى، {وَلَقَدْ خَلَقْنَاكُمْ ثُمَّ صَوَّرْنَاكُمْ ثُمَّ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ) فالأمر بالسجودِ صدر منه بعد خلقِ آدم، فالكلامُ القائمُ بالذاتِ ليس مخلوقًا، والمقصودُ أن كتاب المأمونِ لَمَّا ورد بغدادَ قُرئ على الناس، وقد عيَّنَ المأمون جماعةً مِن المحدِّثينَ لِيُحضِرَهم إليه، وهم: محمد بن سعد كاتب الواقدي، وأبو مسلِم المُستملي، ويزيدُ بن هارون، ويحيى بن مَعين، وأبو خيثمة زُهير بن حرب، وإسماعيلُ بن أبي مسعود، وأحمد بن الدورقي، فبُعِثَ بهم إلى المأمونِ في الرقَّة، فامتحنهم بخلْقِ القرآنِ، فأجابوه إلى ذلك وأظهروا موافقتَه وهم كارهون، فردَّهم إلى بغداد وأمرَ بإشهارِ أمرِهم بين الفُقَهاء، ففعل إسحاقُ ذلك وأحضر خَلقًا من مشايخِ الحديثِ والفُقَهاءِ وأئمَّة المساجد وغيرِهم، فدعاهم إلى ذلك عن أمرِ المأمون، وذكَرَ لهم موافقة أولئك المحدِّثين له على ذلك، فأجابوا بمِثلِ جواب أولئك موافقةً لهم، ووقَعَت بين الناس فتنةٌ عظيمةٌ. ثم كتب المأمونُ إلى إسحاق أيضًا بكتابٍ ثانٍ يستدِلُّ به على القولِ بخَلقِ القُرآنِ بِشُبَهٍ من الدلائِلِ لا تحقيقَ تحتها ولا حاصلَ لها، بل هي من المُتشابِه، وأورد من القرآنِ آياتٍ هي حُجَّةٌ عليه، وأمَرَ نائبه أن يقرأ ذلك على النَّاسِ وأن يَدعُوَهم إليه وإلى القَولِ بخلقِ القرآن، فأحضَرَ أبو إسحاق جماعةً من الأئمَّة؛ منهم قاضي القضاة بشر بن الوليد الكندي، ومقاتل، وأحمد بن حنبل، وقُتَيبة، وعليُّ بن الجعْد، وغيرهم، وقال لبشرٍ: ما تقولُ في القرآن؟ قال: القرآنُ كلامُ الله، قال: لم أسألْك عن هذا، أمخلوقٌ هو؟ قال: الله خالِقُ كُلِّ شَيءٍ، قال: والقرآنُ شَيءٌ؟ قال: نعم، قال: أمخلوقٌ هو؟ قال: ليس بخالقٍ، قال: ليس عن هذا أسألُك، أمخلوقٌ هو؟ قال: ما أُحسِنُ غيرَ ما قلْتُ لك. قال إسحاقُ للكاتب: اكتُبْ ما قال، ثم سأل غيرَه وغيره ويجيبونَ بنَحوِ جوابِ بِشرٍ. من أنه يقالُ: لا يُشبِهُه شيءٌ مِن خَلقِه في معنًى من المعاني، ولا وجهٍ مِن الوجوهِ، فيقول: نعم، كما قال بِشرٌ. ثم سأل قتيبةَ، وعُبيد الله بن محمَّد، وعبد المنعم بن إدريس بن نبت، ووهب بن منبه وجماعةً، فأجابوا أنَّ القرآنَ مجعولٌ؛ لِقَولِه تعالى: {إِنَّا جَعَلْنَاهُ قُرْآنًا عَرَبِيًّا} والقرآنُ مُحدَثٌ لِقَولِه تعالى: {مَا يَأْتِيهِمْ مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ}. قال إسحاق: فالمجعولُ مَخلوقٌ، قالوا: لا نقولُ مخلوقٌ، لكن مجعولٌ. فكتب مقالَتَهم ومقالةَ غَيرِهم إلى المأمونِ."},{"id":708,"title":"اعتقال الإمام أحمد بن حنبل ومحمد بن نوح في بغداد .","date":["العام الهجري :218","العام الميلادي :833"],"text":"بعد أن أحضر إسحاقُ بنُ إبراهيمَ العُلَماءَ والمحدِّثينَ لامتحانِهم، كان مِن بينهم الإمامُ أحمَدُ، ومحمدُ بنُ نوح، وغيرُهم كثيرٌ، ولَمَّا انتهت النوبةُ إلى امتحانِ الإمامِ أحمَدَ بنِ حنبَل، قال له: أتقولُ إنَّ القرآنَ مَخلوقٌ؟ فقال: القرآنُ كلامُ اللهِ، لا أزيدُ على هذا، فقال له: ما تقولُ في هذه الرُّقعةِ؟ بالرقعةِ التي وافَقَ عليها قاضي القُضاةِ بِشرُ بن الوليد الكِندي، فقال: أقولُ: {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ} فقال رجلٌ من المعتزلة: إنَّه يقولُ: سَميعٌ بأذُنٍ، بصيرٌ بعَينٍ! فقال له إسحاقُ: ما أردتَ بقَولِك: سَميعٌ بصيرٌ؟ فقال: أردتُ منها ما أراده اللهُ منها؛ وهو كما وصف نفسَه، ولا أزيدُ على ذلك. فكتب جواباتِ القَومِ رَجُلًا رجلًا وبعثَ بها إلى المأمون، فلما وصَلَت جواباتُ القوم إلى المأمونِ، بعث إلى نائبه يمدَحُه على ذلك ويرُدُّ على كلِّ فَردٍ ما قال في كتابٍ أرسَلَه. وأمر نائِبَه أن يمتَحِنَهم أيضًا فمن أجاب منهم شُهِرَ أمرُه في الناس، ومن لم يجِبْ منهم فابعَثْه إلى عسكَرِ أميرِ المؤمنين مقيَّدًا مُحتَفِظًا به حتى يصِلَ إلى أميرِ المؤمنين فيرى فيه رأيَه، ومِن رأيِه أن يضرِبَ عُنُقَ مَن لم يقُلْ بِقَولِه. فعند ذلك عقد النائبُ ببغداد مجلسًا آخر وأحضر أولئك، وفيهم إبراهيمُ بنُ المهدي، وكان صاحبًا لبِشرِ بنِ الوليد الكندي، وقد نصَّ المأمونُ على قتلِهما إن لم يُجيبا على الفَورِ، فلما امتحنَهم إسحاقُ أجابوا كلُّهم مُكرَهينَ متأوِّلينَ قَولَه تعالى: {إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ} إلَّا أربعةً، وهم: أحمد بن حنبل، ومحمَّد بن نوح، والحسَنُ بن حمَّاد سجادة، وعُبيد الله بن عمر القواريري. فقيَّدَهم وأرصدهم ليبعَثَ بهم إلى المأمونِ، ثم استدعى بهم في اليومِ الثاني فامتحَنَهم فأجاب سجادة إلى القولِ بذلك فأُطلِقَ. ثم امتحَنَهم في اليوم الثالثِ فأجاب القواريريُّ إلى ذلك فأُطلِقَ قَيدُه، وأَخَّرَ أحمدَ بنَ حَنبل ومحمَّدَ بن نوحٍ الجندُ؛ لأنَّهما أصرَّا على الامتناعِ من القول بذلك، فأكَّدَ قيودَهما وجمَعَهما في الحديدِ، وبعَثَ بهما إلى الخليفةِ وهو بطرسوس، وكتب كتابًا بإرسالهما إليه. فسارا مُقَيَّدينِ في محارة على جمَلٍ متعادِلَينِ- رَضِيَ الله عنهما- وجعل الإمامُ أحمد يدعو الله عزَّ وجَلَّ ألَّا يجمَعَ بينهما وبين المأمونِ، وألَّا يَرَياه ولا يراهما، ثمَّ جاء كتابُ المأمونِ إلى نائبِه أنَّه قد بلغني أنَّ القومَ إنما أجابوا مُكرَهينَ متأوِّلينَ قَولَه تعالى: {إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ} وقد أخطؤوا في تأويلِهم دلك خطأً كبيرًا، فأرسَلَهم كلَّهم إلى أميرِ المؤمنين. فاستدعاهم إسحاقُ وألزَمَهم بالمسيرِ إلى طرسوس فساروا إليها، فلمَّا كانوا ببعض الطريقِ بلَغَهم موتُ المأمونِ، فرُدُّوا إلى الرقَّةِ، ثمَّ أُذِنَ لهم بالرجوعِ إلى بغداد، فاستجاب اللهُ سبحانَه دُعاءَ عَبدِه ووَلِيِّه الإمامِ أحمَدَ بنِ حَنبل."},{"id":709,"title":"خروج فضل بن أبي العنبر على دولة الأغالبة في المغرب .","date":["العام الهجري :218","العام الميلادي :833"],"text":"وجَّه زيادةُ اللهِ بنُ الأغلب، صاحِبُ إفريقية، جيشًا لمحاربةِ فضل بن أبي العنبر بجزيرة شريك، وكان مخالفًا لزيادةِ الله، فاستمَدَّ فَضلٌ بعبد السلامِ بن المفرج الربعي، وكان أيضًا مخالفًا مِن عَهدِ فِتنةِ منصور الترمذي، فسار إليه، فالتَقَوا مع عسكر زيادة الله، وجرى بين الطائفتينِ قِتالٌ شديدٌ عند مدينة اليهود بالجزيرة، فقُتِلَ عبد السلام، وحُمِلَ رأسُه إلى زيادة الله، وسار فضلُ بن أبي العنبر إلى مدينة تونس، فدخلها وامتنَعَ بها، فسَيَّرَ زيادةُ الله إليه جيشًا، فحصروا فضلًا بها وضَيَّقوا عليه حتى فتَحُوها منه، وقُتِلَ وقت دخولِ العَسكرِ كثيرٌ مِن أهلِها، وهرب كثيرٌ مِن أهل تونس لَمَّا مُلِكَت، ثم آمَنَهم زيادة الله، فعادوا إليها."},{"id":710,"title":"وفاة بشر المريسي من رؤوس المعتزلة .","date":["العام الهجري :218","العام الميلادي :833"],"text":"هو بِشرُ بنُ غياث بن أبي كريمة المِرِّيسي، شيخُ المعتزلة، وأحدُ من أضَلَّ المأمونَ، وقد كان هذا الرجلُ ينظُرُ أوَّلًا في شيءٍ مِن الفِقهِ، وأخذ عن أبي يوسُفَ القاضي، وروى الحديثَ عنه وعن حمَّاد بن سَلَمة، وسُفيانَ بنِ عُيَينة وغيرِهم، ثم غلب عليه عِلمُ الكلامِ, وقد نهاه الشافعيُّ عن تعلُّمِه وتعاطيه، فلم يقبل منه، وقال الشافعي: \"لَئِنْ يلقى اللهَ العبدُ بكُلِّ ذنبٍ- ما عدا الشِّركَ- أحَبُّ إليَّ مِن أن يلقاه بعِلمِ الكَلامِ\", فانسلخ المِرِّيسي من الورَعِ والتقوى، وجَرَّدَ القولَ بخَلقِ القرآن، ودعا إليه حتى كان عينَ الجَهميَّة في عصرِه وعالِمَهم، فمَقَتَه أهلُ العِلمِ، وكَفَّرَه عِدَّةٌ، ولم يُدرِكْ جَهمَ بنَ صفوانَ، بل تلقَّفَ مقالاتِه من أتباعِه، وحُكيت عنه أقوالٌ شنيعة، وكان مُرجِئًا، وإليه تُنسَبُ المريسِيَّة من المُرجِئة، وكان يقول: إنَّ السجودَ للشَّمسِ والقمرِ ليس بكُفرٍ، وإنَّما هو علامةٌ للكُفرِ، وكان يناظِرُ الشافعيَّ، وكان لا يُحسِنُ النحوَ، وكان يلحَنُ لحنًا فاحِشًا، وكان أبو زرعةَ الرازيُّ يقول: \"بِشرُ بن غياثٍ: زِنديقٌ\"، ومُناظرةُ عبدالعزيز الكناني لبِشرِ المِريِّسي مشهورةٌ، وهي المعروفةُ بالحيدة، ويقال: إنَّ أباه كان يهوديًّا صبَّاغًا بالكوفةِ، وكان يسكُنُ دَربَ المِريِّسي ببغداد، وتوفِّي ببغداد."},{"id":711,"title":"وفاة عبدالملك بن هشام راوي السيرة المشهور .","date":["العام الهجري :218","الشهر القمري : ربيع الآخر","العام الميلادي :833"],"text":"هو أبو محمد عبدالملك بن هشام بن أيوبَ المعافري، العلَّامةُ النَّحويُّ الأَخباريُّ، أبو محمد الذهلي السَّدوسي، وقيل: الِحمْيري المعافري البصري، نزيلُ مصر، هذَّبَ السيرةَ النبويَّةَ لابنِ إسحاقَ مُصَنِّفِها. سمعها مِن زياد البكائي صاحِبِ ابنِ إسحاق, وإنما نُسِبَت إليه، فيقال سيرةُ ابن هشام؛ لأنه هذَّبَها وزاد فيها ونقَصَ منها، وحَرَّر أماكِنَ، واستدرك أشياءَ، وكان إمامًا في اللغة والنحو، وقد كان مقيمًا بمصرَ، واجتمع به الشافعيُّ حين وردها، وتناشدَا من أشعارِ العرب شيئًا كثيرًا. كانت وفاتُه بمصر."},{"id":712,"title":"قيام المأمون بتوجيه ابنه العباس إلى أرض الروم .","date":["العام الهجري :218","الشهر القمري : جمادى الأولى","العام الميلادي :833"],"text":"وجَّه المأمونُ ابنَه العبَّاسَ إلى أرضِ الرومِ وأمَرَه بنزول الطوانةِ وبنائِها، وكان قد وجَّه الفَعَلةَ والفُروضَ، فابتدأ البناءَ وبناها ميلًا في ميلٍ، وجعل سورَها على ثلاثةِ فراسِخَ، وجعل لها أربعةَ أبواب، وبنى على كلِّ بابٍ حِصنًا."},{"id":713,"title":"وفاة الخليفة العباسي المأمون .","date":["العام الهجري :218","الشهر القمري : رجب","العام الميلادي :833"],"text":"هو أبو العبَّاسِ عبدُ الله بن هارون الرَّشيد بن محمد المهدي بن أبي جعفر المنصور المأمون العباسي. وُلِدَ سنة سبعين ومائة, واسمُ أمِّه: مراجل ماتت في نفاسِها به. قرأ العلمَ والأدبَ والأخبارَ، والعقليَّات وعلومَ الأوائل، وأمرَ بتعريبِ كُتُبِهم، وبالغ في تعريبها، وعَمِلَ الرصدَ فوق جبل دمشق، ودعا إلى القولِ بخَلْقِ القرآنِ وامتحنَ العُلَماءِ به. كان ذا حَزمٍ وعزمٍ، ورأيٍ وعقلٍ، وهيبةٍ وحِلمٍ، ومحاسِنُه كثيرةٌ في الجملة. كان أبيضَ رَبْعةً حسَنَ الوجهِ، تعلوه صُفرةٌ، قد وَخَطَه الشَّيبُ، وكان طويلَ اللِّحيةِ أعيَنَ ضَيِّقَ الجبينِ، على خَدِّه شامةٌ. أتته وفاةُ أبيه وهو بمروٍ سائرًا لغزو ما وراء النهرِ، فبُويِعَ مِن قِبَلِه لأخيه الأمينِ، ثم جرت بينهما أمورٌ وخُطوبٌ، وبلاءٌ وحروبٌ، إلى أن قُتِلَ الأمينُ، وبايع النَّاسُ المأمونَ في أوَّلِ سنةِ ثمان وتسعين ومائةٍ. كان متشيِّعًا فقد كانت كنيتُه أبا العباس، فلما استُخلِفَ اكتنى بأبي جعفرٍ، واستعمَلَ على العراق الحسَنَ بنَ سَهلٍ، ثم بايع بالعهدِ لعليِّ بنِ موسى الرضا ونَوَّه بذِكرِه، ونبَذَ السَّوادَ شِعارَ العباسيِّينَ، وأبدله بالخُضرة شعارِ العَلَويِّين. مرض المأمونُ مَرَضَه الذي مات فيه لثلاثَ عشرةَ خلَت من جُمادى الآخرة، فلمَّا مَرِضَ المأمونُ أمَرَ أن يُكتَبَ إلى البلادِ الكُتُب من عبد الله المأمونِ أميرِ المؤمنينَ، وأخيه الخليفةِ مِن بَعدِه أبي إسحاقَ محمَّد بن هارونَ الرشيد؛ وأوصى إلى المعتَصِم بحضرةِ ابنه العبَّاسِ، وبحضرة الفُقَهاء والقضاة والقُوَّاد، ثم بقيَ مريضًا إلى أن توفِّيَ قرب طرسوس ثم حمَلَه ابنُه العبَّاسُ، وأخوه المعتَصِمُ إلى طرسوس، فدفناه بدارِ خاقان خادِمِ الرَّشيد، وصلى عليه المعتَصِمُ، وكانت خلافتُه عشرينَ سنةً وخمسة أشهر وثلاثة وعشرين يومًا."},{"id":714,"title":"المعتصم بالله يتولى الخلافة العباسية .","date":["العام الهجري :218","الشهر القمري : رجب","العام الميلادي :833"],"text":"هو أبو إسحاقَ محمَّدُ بن هارون الرشيد، بويعَ له بالخلافةِ بعد موتِ المأمونِ، ولَمَّا بويِعَ له شَغَّبَ الجندُ، ونادوا باسمِ العبَّاسِ بنِ المأمون، فأرسل إليه المعتَصِمُ، فأحضره فبايَعَه، ثم خرج العبَّاسُ إلى الجندِ، فقال: ما هذا الحبُّ البارِدُ؟ قد بايعتُ عَمِّي، فسكَتوا، وأمَرَ المعتَصِمُ بخرابِ ما كان المأمونُ أمَرَ ببنائِه من طوانة، وحَمْل ما أطاق من السِّلاحِ والآلة التي بها وأحرقَ الباقيَ، وأعاد النَّاسَ الذين بها إلى البلادِ التي لهم، ثم ركِبَ المعتَصِمُ بالجنودِ قاصِدًا بغداد، ومعه العبَّاسُ بن المأمون، فدخلها يومَ السبت مستهَلَّ شَهرِ رمضان في أبَّهةٍ عظيمةٍ وتجَمُّلٍ تامٍّ."},{"id":715,"title":"الخليفة المعتصم يأمر بمواجهة طائفة الخرميَّة في همذان .","date":["العام الهجري :218","الشهر القمري : ذي القعدة","العام الميلادي :833"],"text":"دخل كثيرٌ من أهل الجبال، وهمذان، وأصبهان، وماسبذان، وغيرِها في دين الخرميَّة، وتجمَّعوا فعَسكَروا في عمَلِ همذان، فوجَّه إليهم المعتَصِمُ العساكِرَ، وكان فيهم إسحاقُ بن إبراهيمَ بنِ مُصعَب، وعقَدَ له على الجبال، فسار إليهم، فأوقع بهم في أعمالِ همذان، فقتَلَ منهم ستين ألفًا وهرب الباقونَ إلى بلد الرومِ، وقرئ كتابُه بالفتح يوم الترويةِ."},{"id":716,"title":"ظهور محمد بن القاسم ودعوته لنفسه في خراسان .","date":["العام الهجري :219","العام الميلادي :834"],"text":"ظهر محمَّدُ بن القاسم بن عمر بن علي بن الحسين بن علي بن أبي طالب، بالطالقان من خراسان، يدعو إلى الرضا من آل محمَّد، وكان ابتداءُ أمرِه أنَّه كان ملازمًا مسجدَ النبيِّ صلَّى الله عليه وسلَّم، حسَنَ السِّيرةِ، فأتاه إنسانٌ من خراسان كان مجاورًا، فلما رآه أعجَبَه طريقُه، فقال له: أنت أحَقُّ بالإمامةِ مِن كُلِّ أحَدٍ، وحَسَّنَ له ذلك وبايعه، وصار الخُراساني يأتيه بالنَّفَرِ بعد النفر مِن حُجَّاجِ خُراسان يبايعونه، فعل ذلك مُدَّةً. فلما رأى كثرةَ مَن بايعه من خراسانَ سارا جميعًا إلى الجوزجان، واختفى هناك، وجعل الخراساني يدعو النَّاسَ إليه، فعَظُم أصحابُه، وحمله الخراسانيُّ على إظهارِ أمْرِه، فأظهره بالطالقان، فاجتمع إليه بها ناسٌ كثير، وكانت بينه وبين قوَّادِ عبدِ الله بن طاهر وقَعاتٌ بناحيةِ الطالقان وجبالِها، فانهزم هو وأصحابه، وخرج هاربًا يريدُ بعضَ كور خراسان، وكان أهلُها كاتبوه، فلما صار بنسا، وبها والدُ بعضِ مَن معه، فلمَّا بَصُرَ به سأله عن الخبَرِ فأخبره، فمضى الأبُ إلى عامِلِ نسا فأخبَرَه بأمر محمد بن القاسم، فأعطاه العامِلُ عشرةَ آلاف درهم على دَلالَتِه، وجاء العامِلُ إلى محمد، فأخذه واستوثَقَ منه، وبعثه إلى عبدِ الله بن طاهر، فسيَّرَه إلى المعتصم، فحُبِسَ عند مسرور الخادمِ الكبير، وأجرى عليه الطَّعامَ، ووكَلَ به قومًا يحفَظونَه، فلمَّا كان ليلةُ الفطرِ اشتغلَ النَّاسُ بالعيد، فهرب من الحبسِ، دُلِّيَ إليه حبلٌ مِن كوَّة كانت في أعلى البيتِ، يدخل عليه منها الضوءُ، فلما أصبحوا أتَوْه بالطعام، فلم يَرَوه، فجعلوا لِمَن دلَّ عليه مائة ألفٍ، فلم يُعرَف له خبَرٌ."},{"id":717,"title":"استمرار محنة الإمام أحمد بن حنبل على يد المعتصم  .","date":["العام الهجري :219","العام الميلادي :834"],"text":"بعد أن كان الإمامُ أحمدُ قد قُيِّدَ وسِيرَ به إلى المأمونِ ثم عاد لبغداد لَمَّا وصلهم نبأُ وفاة المأمون، وتولى بعده المعتَصِمُ استمَرَّ على نفس الامتحان، فأحَضَره المعتَصِم وامتحنَه بالقولِ بخلقِ القُرآنِ فلم يُجِبْه الإمامُ أحمدُ، وكُلُّ ذلك وهو ثابِتٌ على قولِه: القرآنُ كَلامُ اللهِ غيرُ مخلوقٍ، فجُلِدَ جلدًا عظيمًا حتى غاب عقلُه، وتقَطَّعَ جِلدُه، وحُبِس مقيَّدًا- رحمه الله."},{"id":718,"title":"عبدُ الرحمن بن الحكم يحاصر مدينةِ طُليطِلة .","date":["العام الهجري :219","العام الميلادي :834"],"text":"سيَّرَ عبدُ الرحمن بن الحكم، صاحِبُ الأندلُسِ، جيشًا مع أميَّةَ بنِ الحكَمِ إلى مدينةِ طُليطِلة، فحصَرَها، وكانوا قد خالفوا الحَكَم، وخرجوا عن الطاعة، واشتَدَّ في حصرهم، وقطَعَ أشجارَهم، وأهلك زروعَهم، فلم يُذعِنوا إلى الطاعة، فرحل عنهم، وأنزل بقَلعةِ رباح جيشًا عليهم ميسرةُ، المعروف بفتى أبي أيوب، فلما أبعدوا منه خرجَ جمعٌ كثيرٌ مِن أهل طليطلة؛ لعلَّهم يجدون فرصةً وغَفلةً مِن مَيسرةَ فينالوا منه ومن أصحابِه غَرضًا، وكان ميسرةُ قد بلغه الخبَرُ، فجعل الكمينَ في مواضِعَ، فلما وصل أهلُ طُليطِلة إلى قلعة رباح للغارة، خرج الكمينُ عليهم من جوانبهم، ووضعوا السيفَ فيهم، وأكثروا القتَلَ، وعاد مَن سَلِمَ منهم منهزمًا إلى طليطِلة، وجُمِعَت رؤوس القتلى، وحُمِلَت إلى ميسرة، فلما رأى كثرَتَها عَظُمَت عليه، وارتاع لذلك، ووجد في نفسِه غمًّا شديدًا، فمات بعد أيامٍ يَسيرةٍ. كما حَدَثت في هذه السَّنةِ فِتنةٌ كبيرةٌ بطُليطلة تُعرفُ بملحمةِ العراس، قُتِلَ مِن أهلِها كثيرٌ."},{"id":719,"title":"المعتَصِم بالله يأمر بحرب الزطِّ (قطاع الطرق) .","date":["العام الهجري :219","الشهر القمري : جمادى الآخرة","العام الميلادي :834"],"text":"وجَّه المعتَصِمُ بالله عجيفَ بن عنبسة لحرب الزطِّ الذين كانوا غلَبوا على طريق البصرةِ، وعاثوا وأخذوا الغَلَّات من البيادر بكسكر وما يليها من البصرة، وأخافوا السبيلَ، ورتَّبَ عجيفٌ الخيلَ في كلِّ سكَّةٍ مِن سِكَكِ البريدِ، تركُضُ بالأخبارِ إلى المعتَصِم، فسار عجيف حتى نزل تحت واسط، وأقام على نهرٍ يقال له بردودا حتى سدَّه وأنهارًا أخَرَ كانوا يخرجون منها ويدخلون، وأخذ عليهم الطرُقَ، ثم حارَبَهم فأسَرَ منهم في معركةٍ واحدةٍ خمسَمائة رجلٍ، وقتل في المعركةِ ثلاثَمائة رجلٍ، فضرب أعناقَ الأَسرى، وبعث الرُّؤوسَ إلى بابِ المُعتَصِم. ثم أقام عجيف بإزاءِ الزطِّ خمسة عشر يوما فظَفِرَ منهم فيها بخلقٍ كثير، وكان رئيسُ الزطِّ رجلًا يقال له محمد بن عثمان، وكان صاحِبُ أمره إنسانًا يقال له سماق، ثم استوطن عجيفٌ وأقام بإزائهم سبعةَ أشهر."},{"id":720,"title":"المعتصم يبعث القائد الأفشين لقتال بابك الخُرَّمي .","date":["العام الهجري :220","العام الميلادي :835"],"text":"عقد المعتصِمُ للأفشين حيدر بن كاوس على الجبال، ووجَّهه لحرب بابك الخرمي، فسار إليه، وكان ابتداءُ خروجِ بابك سنةَ إحدى ومائتين، ثمَّ إنَّ الأفشين سار إلى بلادِ بابك، فنزل برزند، وعسكَرَ بها وضبَطَ الطرق والحصونَ فيما بينه وبين أردبيل، وأنزل محمَّدَ بن يوسف بموضعٍ يقال له خش، فحفرَ خندقًا وأنزل الهيثمَ الغنوي برستاق أرشق، فأصلح حِصنَه، وحفَرَ خَندقَه، وأنزل علويه الأعور، من قوَّاد الأبناء، في حصنِ النَّهرِ ممَّا يلي أردبيل، فكانت القوافِلُ تخرج من أردبيل ومعها من يحميها، حتى تنزل بحصنِ النَّهر، ثم يُسَيِّرُها صاحبُ حِصنِ النَّهرِ إلى الهيثم الغنوي، فيلقاه الهيثم بمن جاء إليه من ناحيةٍ في موضعٍ معروفٍ لا يتعَدَّاه أحَدُهم إذا وصل إليه، فإذا لَقِيَه أخذ ما معه، وسَلَّمَ إليه ما معه، ثم يسيرُ الهيثمُ بمن معه إلى أصحابِ أبي سعيد، فيلقونَه بمنتصف الطريق، ومعهم من خرجَ من العسكر، فيتسَلَّمون ما مع الهيثم ويُسلِّمونَ إليه ما معهم، وإذا سبق أحدُهم إلى المنتصف لا يتعدَّاه، ويسيرُ أبو سعيدٍ بمن معه إلى عسكر الأفشين، فيلقاه صاحب سيارة الأفشين، فيتسَلَّمُهم منه، ويسَلِّمُ إليه مَن صَحِبَه من العسكر، فلم يزل الأمرُ على هذا. وكانوا إذا ظَفِروا بأحدٍ من الجواسيس حملوه إلى الأفشين، فكان يُحسِنُ إليهم، ويهَبُ لهم، ويسألُهم عن الذي يعطيهم بابك، فيُضَعِّفُه لهم، ويقول لهم: كونوا جواسيسَ لنا فكان ينتَفِعُ بهم."},{"id":721,"title":"اقتتال القائد العباسي الأفشين وبابك الخرمي .","date":["العام الهجري :220","العام الميلادي :835"],"text":"وجَّه المعتصِمُ القائد العسكري التركي بغا الكبيرَ إلى الأفشين، ومعه مالٌ للجندِ والنفقات، فوصل أردبيل، فبلغ بابك الخبر، فتهيَّأ هو وأصحابُه ليقطعوا عليه قبل وُصولِه إلى الأفشين، فجاء جاسوسٌ إلى الأفشين، فأخبَرَه بذلك، فلما صَحَّ الخبَرُ عند الأفشين كتب بغا أن يُظهِرَ أنَّه يريد الرحيلَ، ويحمِل المالَ على الإبل، ويسير نحوه، حتى يبلغ حصنَ النَّهر، فيَحبِس الذي معه، حتى يجوزَ مَن صَحِبَه من القافلة، فإذا جازوا رجع بالمال إلى أردبيل. ففعل بغا ذلك، وسارت القافلةُ، وجاءت جواسيسُ بابك إليه، فأخبَروه أن المال قد سار فبلغ النَّهرَ، وركب الأفشين في اليومِ الذي واعدَ فيه بغا عند العصرِ، مِن برزند، فنزل خارِجَ خندق أبي سعيد، فلما أصبح ركِبَ سِرًّا ورحلت القافلة التي كانت توجَّهَت ذلك اليوم من النهر إلى ناحيةِ الهيثم، وتعبَّى بابك في أصحابِه، وسار على طريق النهر، وهو يظنُّ أن المالَ يُصادِفُه، فخرجت خيلُ بابك على القافلة، ومعها صاحِبُ النهر، فقاتَلَهم صاحبُ النهر، فقتلوه، وقتلوا من كان معه من الجند، وأخذوا جميعَ ما كان معهم، وعَلِموا أن المالَ قد فاتهم، وأخذوا عَلَمَه ولباسَ أصحابِه، فلبسوها وتنكَّروا ليأخذوا الهيثم الغنوي ومن معه أيضًا ولا يعلمونَ بخروج الأفشين، وجاؤوا كأنَّهم أصحابُ النهر، فلم يعرفوا الموضِعَ الذي يقف فيه علَمُ صاحب النهر، فوقفوا في غيرِه وجاء الهيثمُ فوقف في موضِعِه، وأنكر ما رأى، فوجَّهَ ابنَ عم له، فقال له: اذهَبْ إلى هذا البغيضِ فقُلْ له: لأيِّ شَيءٍ وقوفُك؟ فجاء إليهم فأنكَرَهم، فرجع إليه فأخبَرَه، فأنفذ جماعةً غيرَه، فأنكروهم أيضًا وأخبروه أنَّ بابك قد قتَلَ علويه، صاحبَ النهر، وأصحابَه، وأخذ أعلامَهم ولباسَهم، فرحل الهيثمُ راجعًا ونَجَت القافلةُ التي كانت معه، وبقيَ هو وأصحابُه في أعقابهم حاميةً لهم حتى وصلت القافلةُ إلى الحصن، وسيَّرَ رجلين من أصحابِه إلى الأفشين وإلى أبي سعيدٍ يُعَرِّفُهما الخبر، ودخل الهيثمُ الحصن، ونزل بابك عليه، وأرسل إلى الهيثمِ أن خَلِّ الحِصنَ وانصرِفْ، فأبى الهيثمُ ذلك، فحاربه بابك وهو يشرَبُ الخمرَ على عادته والحربُ مُشتَبِكةٌ، وسار الفارسان، فلقيا الأفشين على أقلَّ مِن فرسَخٍ، وأجرى الناسُ خَيلَهم طلقًا واحدًا حتى لَحِقوا بابك وهو جالِسٌ، فلم يُطِقْ أن يركَبَ، حتى وافته الخيلُ، فاشتبكت الحربُ، فلم يُفلِتْ من رَجَّالة بابك أحدٌ، وأفلت هو في نفرٍ يسيرٍ مِن خيَّالتِه، ودخل موقان وأقام بها فلمَّا كان في بعضِ الأيام مرَّت قافلة، فخرج عليها أصبهنذ بابك، فأخذها وقتَل مَن فيها، فقَحِطَ عسكرُ الأفشين لذلك، فكتب الأفشينُ إلى صاحب مراغة بحَملِ الميرة وتعجيلِها، فوجه إليه قافلةً عظيمة، ومعها جندٌ يسيرون بها فخرج عليهم سريةٌ لبابك، فأخذوها عن آخِرِها وأصاب العسكرَ ضِيقٌ شديد، فكتب الأفشين إلى صاحبِ شيروان يأمُرُه أن يحمِلَ إليه طعامًا، فحمل إليه طعامًا كثيرا وأغاث الناسَ، وقدِمَ بغا على الأفشين بما معه."},{"id":722,"title":"غضب المعتصم على الفضل بن مروان وعزله عن الوزارة .","date":["العام الهجري :220","الشهر القمري : رجب","العام الميلادي :835"],"text":"غَضِبَ المعتَصِمُ على الفضل بن مروان بعد المكانةِ العظيمةِ التي كانت له، وعَزَله عن الوَزارةِ وحبَسَه وأخذ أموالَه، وجعل مكانَه محمَّدَ بن عبدالملك بن الزيات، فكان المعتَصِمُ يقول: عصى اللهَ وأطاعني، فسلَّطني اللهُ عليه."},{"id":723,"title":"الخليفة المعتصم يأمر بتأسيس مدينة سامراء .","date":["العام الهجري :221","العام الميلادي :835"],"text":"خرج المعتَصِمُ إلى سامِرَّا لبنائِها، وكان سببُ ذلك أنَّه قال إني أتخوَّفُ هؤلاء الحربيَّةَ أن يَصيحوا صيحةً فيَقتُلوا غِلماني، فأريدُ أن أكونَ فوقهم، فإن رابني منهم شيءٌ أتيتُهم في البَرِّ والماء، حتى آتيَ عليهم، فخرج إليها فأعجَبَه مكانَها، وقيل: كان سببُ ذلك أنَّ المعتصِمَ كان قد أكثَرَ مِن الغِلمان الأتراك، فكانوا لا يزالونَ يَرَون الواحِدَ بعد الواحدِ قتيلًا، وذلك أنَّهم كانوا جفاةً، يركبون الدوابَّ، فيَركُضونَها إلى الشوارع، فيَصدِمون الرجُلَ والمرأةَ والصبيَّ، فيأخُذُهم الأبناءُ عن دوابِّهم، يَضرِبونَهم، وربما هلك أحَدُهم فتأذَّى بهم الناس. ثمَّ إن المعتَصِمَ رَكِبَ يومَ عيد، فقام إليه شيخٌ فقال له: يا أبا إسحاق، فأراد الجندُ ضَربَه، فمنعهم وقال: يا شيخُ، ما لك، ما لك؟ قال: لا جزاك اللهُ عن الجِوارِ خَيرًا، جاوَرْتَنا وجِئتَ بهؤلاء العُلوجِ مِن غِلمانِك الأتراك، فأسكَنْتَهم بيننا، فأيتمْتَ صِبيانَنا وأرمَلْتَ بهم نسوانَنا وقتَلْتَ رِجالَنا؛ والمعتَصِمُ يسمع ذلك، فدخل منزلَه، ولم يُرَ راكبًا إلى مثل ذلك اليومِ، فخرج فصلى بالناس العيدَ، ولم يدخُل بغداد، بل سار إلى ناحيةِ القاطول، ولم يرجِعْ بغداد. قال مسرور الكبير: سألني المعتَصِمُ أين كان الرشيدُ يتنَزَّه إذا ضَجِرَ ببغداد، قلت: بالقاطول، وكان قد بنى هناك مدينةً آثارُها وسورُها قائم، وكان المعتصِمُ قد اصطنع قومًا من أهلِ الحوف بمصر، واستخدمهم وسمَّاهم المغاربة، وجمع خَلقًا من سمرقند، وأشروسنة، وفرغانة، وسمَّاهم الفراغنة، فكانوا من أصحابِه، وبَقُوا بعده، فبُني بها الجامِعُ المشهورُ بمنارته الملْتَوية ذات الدَّرج الخارجي الملتَفِّ على المنارة، ويُذكَرُ أنَّ أصلَ الكلمةِ هو سُرَّ مَن رأى، ثم صارت سامِرَّا."},{"id":724,"title":"القضاء على حكم بابك الخرمي في أذربيجان .","date":["العام الهجري :222","العام الميلادي :836"],"text":"تقدَّمَ الأفشين حتى شارف الموضِعَ الذي كانت به الوقعةُ في العام الماضي، فاختار ثلاثةَ جبالٍ كان عليها حصونٌ فخُرِّبَت، فسَدَّ الطريقَ إلى تلك الجبال، حتى صارت كالحُصون، وأمر بحفرِ خَندقٍ على كلِّ طريقٍ وراء تلك الحجارةِ، وكان جماعةٌ مِن الخرمية يأتونَ إلى قرب خندق الأفشين فيَصيحون، فلم يترُك الأفشين أحدًا يخرجُ إليهم، فَعَلوا ذلك ثلاثةَ أيام، ثمَّ إنَّ الأفشين كَمَن لهم كمينًا، فإذا جاؤوا ثاروا عليهم، فهَرَبوا ولم يعودوا. وعبَّأ الأفشين أصحابَه، وأمر كلًّا منهم بلزومِ مَوضِعِه، وكان إذا أراد أن يتقدَّمَ إلى المكان الذي كانت به الوقعةُ عام أول، خلَّف بُخاراخذاه على رأسِ العقبة في ألف فارس، وستمائة راجل، يحفظونَ الطريقَ لئلا يأخُذَه الخرمية عليهم. وكان بابك إذا أحس بمجيئِهم وجَّه جمعًا من أصحابه، فيكمُنون في وادٍ تحت تلك العقبة، تحت بخاراخذاه، واجتهد الأفشين أن يعرفَ مكانَ كَمينِ بابك، فلم يعلَمْ بهم، وكان بابك يُخرِجُ عسكره فيقِفُ بإزاء هذه الكراديس، لئلَّا يتقَدَّمَ منهم أحدٌ إلى باب البذ. وكان يفَرِّقُ عساكِرَه كمينًا ولم يبقَ إلَّا في نفر يسير. فصارت مناوشةٌ بين بعض الخرمية وبعض جيش الأفشين كان من سبَبِها تحرُّك الكُمَناء من الخرمية، فقال الأفشين: الحمدُ لله الذي بيَّن مواضِعَ هؤلاء، فأقام الأفشين بخَندَقِه أيامًا فشكا المتطوِّعةُ إليه ضيقَ العلوفة، فوعد الأفشين الناسَ ليوم ذكره لهم، وأمر الناس بالتجهزِ وحَملِ المالِ والزادِ والماء، فاشتبَكَت الحربُ مع بابك طويلًا، فلما دخلت أعلامُ الفراغنة البذ، وصَعِدوا بها القصورَ، رَكِبَ الأفشين وصاح بالنَّاسِ، فدخل، ودخلوا، وصَعِدَ النَّاسُ بالأعلام فوق قصورِ بابك، وكان قد كَمَن في قصوره- وهي أربعةٌ- ستُّمائة رجل، فخرجوا على الناس، فقاتلوهم، ومَرَّ بابك، حتى دخل الواديَ الذي يلي هشتادسر، واشتغل الأفشين ومن معه بالحربِ على أبوابِ القصور، فأحضر النَّفاطين فأحرقوها وهدَمَ النَّاسُ القصور، فقتلوا الخرميَّة عن آخرهم، وأخذ الأفشين أولادَ بابك، وأمَّا بابك فإنه سار فيمن معه، وكانوا قد عادوا إلى البذ، بعد رجوعِ الأفشين، فأخذوا ما أمكَنَهم من الطعام والأموال، ولَمَّا كان الغدُ رجع الأفشين إلى البذ، وأمر بهدم القُصور وإحراقِها، فلم يدع منها بيتًا، وجاءت جواسيسُ الأفشين إليه فأعلموه بموضعِ بابك، فوجَّه الأفشينُ إلى كل موضع فيه طريقٌ إلى الوادي جماعةً من أصحابِه يحفظونَه، وقعد بابك في موضِعِه، فلم يزل في تلك الغيضةِ حتى فَنِيَ زاده، وخرج من بعض تلك الطرق، وسار بمن معه يريدونَ أرمينيةَ، فرآهم حرَّاسُ الأفشين، فلما رأى بابك العساكر ركب هو ومن معه، فنجا هو، وأخذ أبو السَّاجِ مُعاويةً، وأمَّ بابك، فأرسلهم إلى الأفشين. وسار بابك في جبال أرمينيةَ مُستخفيًا، فلقي ابنَ سنباط فأمَّنَه واحتفى به, ثم كتب ابنُ أسباط للأفشين بخبَرٍ بأمر بابك، واتَّفقَ معه على خطَّةٍ لمُداهمة بابك والقبضِ عليه, فبينما بابك وابنُ سنباط يتصيَّدان إذ خرج عليهما أبو سعيدٍ وبورماره في أصحابِهما فأخذوه وساروا به إلى الأفشين، فأدخله الأفشينُ بيتًا ووكَلَ به من يحفَظُه، فحبسه مع أخيه، وكتب إلى المعتَصِم بذلك، فأمره بالقدومِ بهما عليه. وكان وصولُ بابك إلى الأفشين ببرزند لعشرٍ خلون من شوال، وكان الأفشينُ قد أخذ نساءً كثيرةً وصبيانًا كثيرًا ذكروا أنَّ بابك أسَرَهم، وأنهم أحرارٌ من العرب والدَّهاقين، فأمر بهم فجُعلوا في حظيرةٍ كبيرة، وأمرهم أن يكتُبوا إلى أوليائهم، فكلُّ من جاء يعرِفُ امرأةً، أو صبيًّا أو جاريةً، وأقام شاهِدَينِ أخذه، فأخذ الناسُ منهم خلقًا كثيرًا وبقي كثيرٌ منهم."},{"id":725,"title":"إخضاع أهل طليطلة لعبدالرحمن بن الحكم .","date":["العام الهجري :222","الشهر القمري : رجب","العام الميلادي :837"],"text":"وقع عِصيانُ أهل طليطِلة على عبدِ الرحمنِ بنِ الحكم بن هشام، صاحِبِ الأندلس، وتم َّإنفاذُ الجيوش لمحاصرتها مرَّةً بعد مرة، فلمَّا كانت هذه السَّنةُ خرج جماعةٌ مِن أهلها إلى قلعةِ رباح، وبها عسكرٌ لعبد الرحمن، فاجتمعوا كلُّهم على حصر طليطلة، وضَيَّقوا عليها وعلى أهلِها وقطعوا عنهم باقيَ مرافِقِهم واشتَدُّوا في محاصرتِهم، فبَقُوا كذلك إلى أن سَيَّرَ عبد الرحمن أخاه الوليدَ بنَ الحكم إليها أيضًا، فرأى أهلَها وقد بلغ بهم الجَهدُ كُلَّ مبلغٍ، واشتد عليهم طولُ الحصار، وضَعُفوا عن القتال والدَّفعِ، فافتتحها قهرًا وعَنوةً، وأمر بتجديدِ القَصرِ على بابِ الِحصنِ الذي كان هُدِّمَ أيَّامَ الحَكَمِ، وأقام بها إلى آخِرِ شعبان من سنة ثلاثٍ وعشرين ومائتين، حتى استقَرَّت قواعِدُ أهلِها وسكَنوا."},{"id":726,"title":"هجوم ملك الروم على المسلمين بزبطرة .","date":["العام الهجري :223","العام الميلادي :837"],"text":"خرج توفيل بن ميخائيل ملِكُ الروم إلى بلادِ الإسلام، وأوقع بأهلِ زبطرة وغيرها، وكان سبَبُ ذلك أنَّ بابك لَمَّا ضَيَّقَ الأفشينُ عليه، وأشرف على الهلاك، كتب إلى مَلِك الروم توفيل يُعلِمُه أنَّ المعتَصِمَ قد وجَّهَ عساكِرَه ومقاتليه إليه، ولم يَبقَ على بابِه أحدٌ، فإن أردت الخروجَ إليه فليس في وجهِك أحدٌ يَمنَعُك؛ ظنًّا أن ذلك يخَفِّفُ عنه، فخرج توفيل في مائة ألفٍ، وقيل أكثر، منهم من الجندِ نَيِّفٌ وسبعون ألفًا وبقيَّتُهم أتباع، ومعهم من المحمِّرة الذين كانوا خرجوا بالجبالِ فلَحِقوا بالرُّومِ حين قاتَلَهم إسحاقُ بن إبراهيم بن مصعب، فبلغ زبطرة، فقتَلَ مَن بها من الرجال، وسَبى الذريَّةَ والنِّساءَ، وأغار على أهلِ ملطيَّة وغَيرِها من حصونِ المسلمين، وسبى المُسلِمات، ومَثَّلَ بمن صار في يدِه من المسلمينَ وسَمَل أعيُنَهم، وقطَعَ أنوفَهم وآذانَهم، فخرج إليهم أهلُ الثغورِ مِن الشامِ والجزيرة، إلَّا مَن لم يكن له دابَّةٌ ولا سِلاحٌ."},{"id":727,"title":"محاولة العباس بن المأمون قتل عمه المعتصم .","date":["العام الهجري :223","العام الميلادي :837"],"text":"كان العباسُ بنُ المأمون مع عَمِّه المعتَصِم في غزوةِ عَمُّورية، وكان عجيفُ بن عنبسة قد نَدَّمَه إذ لم يأخُذ الخلافةَ بعد أبيه المأمونِ، ولامَه على مبايعتِه عَمَّه المعتصِمَ ولم يزل به حتى أجابه إلى الفتك بعمِّه وأخذِ البيعةِ من الأمراء له، وجهَّزَ رجلًا يقال له الحارِثُ السَّمَرقندي وكان نديمًا للعبَّاسِ، فأخذ له البيعةَ مِن جماعةٍ مِن الأمراء في الباطنِ، واستوثَقَ منهم وتقَدَّم إليهم أنَّه يلي الفتكَ بعَمِّه، فلما فتحوا عَمُّوريَّة واشتغل الناسُ بالمغانم، أشار عليه أن يقتُلَه، فوعده مَضِيقَ الدَّربِ إذا رجَعوا، فلما رجعوا فَطِنَ المعتَصِمُ بالخبَرِ، فأمر بالاحتفاظِ وقُوَّةِ الحَرَس وأخذَ بالحَزمِ، واجتهد بالعزمِ، واستدعى بالحارِثِ السَّمرقنديِّ فاستقَرَّه فأقَرَّ له بجُملةِ الأمر، وأخْذِ البيعةِ للعبَّاسِ بنِ المأمون من جماعةٍ مِن الأمراء أسماهم له، فاستكثَرَهم المعتَصِمُ واستدعى بابنِ أخيه العبَّاسِ فقَيَّده وغَضِبَ عليه وأهانه، ثم أظهَرَ له أنه قد رَضِيَ عنه وعفا عنه، فأرسَلَه مِن القيدِ وأطلق سراحَه، فلما كان من اللَّيلِ استدعاه واستحكاه عن الذي كان قد دبَّرَه من الأمر، فشرَحَ له القضيَّةَ، وذكر له القِصَّةَ، فإذا الأمرُ كما ذكر الحارِثُ السمرقندي. فلما أصبح استدعى بالحارثِ فأخلاه وسأله عن القضيَّة ثانيًا فذكَرَها له كما ذكرها أوَّلَ مَرَّة، فقال: وَيحَك، إنِّي كنتُ حريصا على ذلك، فلم أجِدْ إلى ذلك سبيلًا بصِدقِك إيَّأي في هذه القِصَّة. ثم أمر المعتَصِمُ حينئذٍ بابن أخيه العبَّاسِ فقُيِّدَ وسُلِّمَ إلى الأفشين، وأمر بعجيف وبقيَّة الأمراءِ الذين ذكرهم فاحتفظَ عليهم، ثم أخَذَهم بأنواعِ النِّقْمات التي اقتَرَحها لهم، فقتَلَ كُلَّ واحدٍ منهم بنوعٍ لم يَقتُل به الآخرَ، ومات العباسُ بنُ المأمون بمنبج، فدفن هناك، وكان سبَبُ موتِه أنَّه أجاعه جوعًا شديدًا، ثم جيءَ بأكلٍ كثيرٍ، فأكلَ منه وطلَبَ الماءَ فمُنِعَ حتى مات، وأمر المعتَصِمُ بلَعْنِه على المنبرِ وسمَّاه اللَّعينَ."},{"id":728,"title":"القائد الأفشين يقود بابك الخرمي أسيراً إلى المعتَصِم .","date":["العام الهجري :223","الشهر القمري : صفر","العام الميلادي :838"],"text":"بعد أن أنهى الله فتنةَ بابك الخرمي، وقضى عليه وعلى جيشِه الأفشينُ ومن معه، وقبض على بابك وحَبَسه وراسَلَ المعتَصِمَ فأمره بتسييرهم إليه, فدخل الأفشينُ وبِصُحبتِه بابك على المعتَصِم سامرَّا، ومعه أيضًا أخو بابك في تجمُّلٍ عظيم، وقد أمر المعتَصِمُ ابنَه هارونَ الواثِقَ أن يتلقَّى الأفشين، وأمَرَ بابك أن يركَبَ على فيلٍ ليُشهَرَ أمرُه ويعرفوه، وعليه قباءُ ديباج وقَلَنْسُوة سمور مدورة، وقد هيؤوا الفيل وخَضَبوا أطرافَه ولَبَّسوه من الحرير والأمتعة التي تليق به شيئًا كثيرا، ولَمَّا أُحضِرَ بين يدي المعتَصِم أمر بقطعِ يَدَيه ورجليه وجَزِّ رأسِه وشَقِّ بَطنِه، ثم أمرَ بحَملِ رأسِه إلى خراسانِ وصَلبِ جُثَّته على خشبةٍ بسامِرَّا، وكان بابك قد شَرِبَ الخمرَ ليلةَ قَتلِه. لَمَّا قتَلَ المعتَصِمُ بابك الخرميَّ توَّجَ الأفشينَ وقلَّدَه وِشاحَينِ مِن جوهرٍ، وأطلق له عشرينَ ألفَ ألف درهمٍ، وكتب له بولايةِ السِّندِ، وأمَرَ الشعراءَ أن يدخُلوا عليه فيمدحوه على ما فعلَ مِن الخيرِ إلى المسلمين، وعلى تخريبِه بلادَ بابك التي يقال لها البذُّ، وتَرْكِه إيَّاها قِيعانًا وخَرابًا."},{"id":729,"title":"مقتل زعيم فرقة الخُرَّميَّة بابك الخرمي .","date":["العام الهجري :223","الشهر القمري : ربيع الأول","العام الميلادي :838"],"text":"هو بابَك الخُرَّمي (بابک خرمدین) زعيمٌ ديني فارسيٌّ، وقائدُ فرقة الخُرَّميَّة ظهر سنة 201هـ الموافق 816 م، في خلافةِ المأمون العباسي, وكثُرَ أتباعهُ، وقاد ثورةً على العباسيِّينَ بعد مصرعِ أبي مسلم الخراساني، استمَرَّت حوالى عشرينَ سنة، وكان أحد الشُّجعانِ، أخاف الإسلامَ وأهلَه، وهزم الجيوشَ العباسيَّة عشرين سنة، وغلبَ على أذربيجانَ وغَيرِها، وأراد أن يقيم المِلَّةَ المجوسيَّة، وعَظُم البلاء. فأنفق المأمونُ والمعتَصِمُ على حربِ بابك قناطيرَ مُقنطرةً مِن الذهَبِ والفِضَّة، وفي هذه السنة بعث المعتَصِمُ نفقاتٍ إلى جيشِه مع الأفشين، فكانت ثلاثينَ ألف ألف درهم، فكانت الحربُ مع بابك الخرمي فطَحَنه الأفشين، واستباح عسكَرَه، وأُخِذَت البذُّ- مدينةُ بابك- وهرب واختفى في غيضةٍ، ثم أُسِرَ بعد فصولٍ طويلة, ولَمَّا أُحضِرَ بابك بين يدي المعتَصِمَ، أمَرَ بقطع يَدَيه ورِجلَيه وجَزِّ رأسِه وشَقِّ بَطنِه، ثم أمَرَ بحَملِ رأسِه إلى خراسانَ، وصَلْبِ جُثَّتِه على خشبةٍ بسامِرَّا، فقُطِعَ دابِرُ الخرَّميَّة."},{"id":730,"title":"وفاة أمير إفريقية زيادة الله بن الأغلب .","date":["العام الهجري :223","الشهر القمري : رجب","العام الميلادي :838"],"text":"هو أبو محمَّد زيادةُ الله بن إبراهيم بن الأغلب أو زيادةُ الله الأوَّل، أميرُ إفريقيَّة، وكان أفصَحَ أهلِ بَيتِه لسانًا وأكثَرَهم أدبًا، وكان يقولُ الشعر، ويرعى الشعراءَ، كانت ولايته من قِبَل المأمون سنة 201هـ، فطالت أيَّامُه واستقام الأمر, وبنى زيادةُ الله في أيَّامِه سُورَ القيروان ودار سوسة وقنطرة باب الربيع، وحِصنَ الرباط بسوسة، وجامعَ القيروان بعد هَدمِه، وأنفق عليه سِتَّة وثمانين ألف دينار، وفتح جزيرةَ صقلِّيَّة على يد قاضيه أسَدِ بن الفرات. كان عمُرُه يوم مات إحدى وخمسين سنة وتسعة أشهر وثمانية أيام، وكانت إمارتُه إحدى وعشرين سنة وسبعة أشهر، وولِيَ بعده أخوه أبو عقالٍ الأغلبُ بنُ إبراهيم بن الأغلب."},{"id":731,"title":"الخليفة العباسي المعتصم بالله يفتح مدينة عمورية .","date":["العام الهجري :223","الشهر القمري : شوال","العام الميلادي :838"],"text":"لَمَّا فعل الرُّومُ ما فعلوا بأهلِ زبطرة وغيرِها، وكانت فِتنةُ بابك قد انتهت، سار المعتَصِمُ بجَيشِه قاصدًا فتحَ عَمُّوريَّة؛ إذ كانت تعَدُّ من أقوى مُدُنِ الروم، بل ربما كانت بمكانةِ القُسطنطينيَّة، فكان أوَّلَ الأمرِ أن التقى الأفشينُ مع الروم وهَزَمَهم شَرَّ هزيمةٍ، ثم سار المعتَصِمُ والأفشين وأشنان، كلٌّ على رأس جيشٍ، متوجِّهينَ إلى عمُّورية وكانت حصينةً ذاتَ سورٍ منيعٍ وأبراجٍ تحَصَّنَ أهلُها فيها، فنصَبَ المنجنيقَ وهدَمَ السُّورَ مِن جهةٍ كانت ضعيفةً دلَّهم عليها أحدُ الأسرى، فبعث نائِبُ البلد لمَلِك الروم كتابًا يُعلِمُه بالأمرِ، ولكن الكتابَ لم يَصِلْ حيث قُبِضَ على الغلامينِ اللذين كان معهما الكتابُ، ثم زاد الضربُ بالمنجنيق حتى انهدم ذلك الجزءُ، لكنه لا يزالُ صَغيرًا على دخولِ الجَيشِ، ثمَّ إنَّ الموكَّلَ بحِفظِ ذلك البرجِ مِن الروم لم يستَطِع الصمودَ، فنزل للقتال ولم يعاوِنْه أحدٌ من الروم, فأمر المعتَصِمُ المسلمين أن يدخلوا البلدَ مِن تلك الثغرةِ التي قد خلت من المقاتِلة، فركب المسلِمونَ نَحوَها، فجَعَلَت الرومُ يُشيرون إليهم ولا يَقدِرونَ على دفاعِهم، فلم يلتَفِت إليهم المُسلِمون، ثم تكاثروا عليهم ودخَلوا البلد قهرًا، وتتابع المسلمونَ إليها يكَبِّرونَ، وتفَرَّقَت الرومُ عن أماكِنِها، فجعل المسلِمونَ يَقتُلونهم في كلِّ مكانٍ حيث وجدوهم، وقد حَشَروهم في كنيسةٍ لهم هائلةٍ ففتحوها قَسرًا وقتلوا من فيها وأحرقوا عليهم بابَ الكنيسةِ، فاحتَرَقت فأُحرِقوا عن آخِرِهم، ولم يبقَ فيها موضِعٌ محصَّنٌ سوى المكانِ الذي فيه نائب عمورية إلى ملك الروم واسمه مناطس في، ثم أُنزِلَ مُهانًا وأَخَذَ المسلمونَ من عمُّورية أموالًا لا تحَدُّ ولا تُوصَفُ، فحَمَلوا منها ما أمكن حمْلُه، وأمر المعتَصِمُ بإحراقِ ما بقيَ من ذلك، وبإحراقِ ما هنالك من المجانيقِ والدبَّابات وآلات الحربِ؛ لئلَّا يتقوَّى بها الرومُ على شيءٍ مِن حربِ المسلمين، ثم انصرف المعتَصِمُ راجعًا إلى ناحية طرسوس."},{"id":732,"title":"خروج مازيار بن قارن على نائب خراسان .","date":["العام الهجري :224","العام الميلادي :838"],"text":"خرج رجلٌ بآمل طبرستان يقال له مازيار بن قارن بن يزداهرمز، وكان لا يرضى أن يدفَعَ الخراجَ إلى نائب خراسان عبد الله بن طاهر بن الحُسَين، بل يبعثه إلى الخليفةِ ليقبِضَه منه، فيبعث الخليفةُ من يتلقى الحملَ إلى بعض البلاد ليقبِضَه منه ثم يدفَعُه إلى ابن طاهر، ثم آل أمرُه إلى أن وثب على تلك البلادِ وأظهر المخالفةَ للمُعتَصِم، وقد كان المازيار هذا ممَّن يكاتب بابك الخرميَّ ويَعِدُه بالنصر، ويقال: إنَّ الذي قوَّى رأس مازيار على ذلك الأفشينُ لِيَعجِزَ عبدُ الله بن طاهر عن مقاومتِه فيُولِّيه المعتصِمُ بلاد خراسان مكانَه، فبعث إليه المعتصِمُ محمَّدَ بن إبراهيم بن مصعب- أخا إسحاقَ بن إبراهيم- في جيشٍ كثيف، فجرت بينهم حروبٌ طويلةٌ، وكان آخِرَ ذلك أسْرُ المازيارِ وحَملُه إلى ابنِ طاهر، فاستقَرَّه عن الكتب التي بعثها إليه الأفشينُ فأقَرَّ بها، فأرسله إلى المعتَصِمُ وما معه من أموالِه التي احتُفِظَت للخليفة، وهي أشياءُ كثيرةٌ جِدًّا من الجواهر والذهَبِ والثياب، فلما أُوقِفَ بين يدي الخليفةِ سأله عن كتُبِ الأفشين إليه فأنكَرَها، فأمر به فضُرِبَ بالسياط حتى مات، وكان ذلك عام 225هـ، وصُلِبَ إلى جانبِ بابك الخرمي على جسرِ بغداد، وقُتِلَ عُيونُ أصحابِه وأتباعِه."},{"id":733,"title":"خروج منكجور على المعتصم في أذربيجان .","date":["العام الهجري :224","العام الميلادي :838"],"text":"لَمَّا فرَغَ الأفشينُ مِن بابك وعاد إلى سامِرَّا استَعمَلَ على أذربيجان منكجورَ- وهو من أقارِبِه- فوجد في بعض قرى بابك مالًا عظيمًا ولم يُعلِمْ به المعتَصِم، ولا الأفشين، فكتب صاحِبُ البريد إلى المعتَصِم، وكتب منكجور يُكَذِّبه، فتناظرا، فهم منكجور ليقتُلَه، فمنعه أهلُ أردبيل، فقاتَلَهم منكجور، وبلغ ذلك المعتَصِم، فأمر الأفشينَ بعزل منكجور، فوجَّه قائدًا في عسكرٍ ضَخمٍ، فلما بلغ منكجورَ الخبَرُ خلع الطاعةَ، وجمع الصعاليكَ، وخرج من أردبيل، فواقعه القائِدُ فهَزَمه، وسار منكجورُ إلى حِصنٍ من حصون أذربيجان التي كان بابك خَرَّبها، فبناه وأصلَحَه وتحَصَّن فيه، فبَقِيَ به شهرًا، ثم وثَبَ به أصحابُه، فأسلَمَه إلى قائدِ الأفشين، فقَدِمَ به إلى سامِرَّا فحبَسَه المعتصم، واتَّهَمَ الأفشينَ في أمره، وكان قدومه سنة خمس وعشرين ومائتين، وقيل: إن ذلك القائِدَ الذي أنفذ إلى منكجور كان بغا الكبيرَ، وإن منكجور خرج إليه بأمانٍ."},{"id":734,"title":"هزيمة نصارى الأندلس على يد عبد الرحمن بن الحَكَم .","date":["العام الهجري :224","العام الميلادي :838"],"text":"سيَّرَ عبدُ الرحمن بن الحَكَم عبدَ اللهِ المعروفَ بابنِ البَلنسيِّ إلى بلادِ العَدُوِّ، فوصلوا إلى \"ألبة\" والقلاعِ، فخرج المشركونَ إليه في جَمعِهم، وكان بينهم حربٌ شديدة وقتالٌ عظيم، فانهزم المشركونَ، وقُتلَ منهم ما لا يُحصى، وجُمِعَت الرؤوس أكداسًا، وفي هذه السنة أيضًا خرج لذريق في عسكَرِه، وأراد الغارةَ على مدينةِ سالم من الأندلس، فسار إليه عبدُ الرحمن بن الحَكَم فوتون بن موسى في عسكَرٍ جرار، فلَقِيَه وقاتَلَه، فانهزم لذريقُ وكَثُر القتلُ في عسكَرِه، وسار فوتون إلى الحصنِ الذي كان بناه أهلُ ألبة بإزاء ثُغورِ المسلمين، فحَصَره، وافتَتَحه وهَدَمه."},{"id":735,"title":"وفاة أبي عبيد القاسم بن سلام .","date":["العام الهجري :224","العام الميلادي :838"],"text":"هو القاسِمُ بنُ سلَّام الهروي الأزدِيُّ ولاءً، ولد بمدينة هراة سنة 157هـ, أحد أئمَّة اللُّغة والفقه والحديثِ، والقرآن والأخبار وأيَّام الناس، كان أبوه عبدًا روميًّا, فطلب أبو عبيدٍ العِلمَ وسَمِعَ الحديثَ ودرسَ الأدبَ والفقه، ثم ارتحل إلى العراقِ نحوَ سنة 176هـ، له المصنَّفات المشهورة المنَتِشرة بين الناس، حتى يقال: إنَّ الإمامَ أحمدَ كتب كتابَه الغريبَ بِيَدِه- وهو أشهر كتُبِه- قال هلالُ بن العلاء الرقي: \"مَنَّ الله على المسلمينَ بهؤلاء الأربعة: الشافعيُّ، تفَقَّه في الفقه والحديث، وأحمدُ بن حنبل في المحنة، ويحيى بن مَعينٍ في نفي الكَذِب، وأبو عُبَيد في تفسيرِ غَريبِ الحديثِ، ولولا ذلك لاقتحم النَّاسُ المهالِكَ\"، وكان أبو عبيدٍ قد ولد بهراة، وأقام في بغداد، ثم انتقل إلى مصر، وكانت وفاتُه بمكَّة- رحمه اللهُ تعالى، وجزاه عن الإسلام والمسلمين خيرًا."},{"id":736,"title":"قيام الدولة اليعفرية بصنعاء .","date":["العام الهجري :225","العام الميلادي :839"],"text":"هي ثاني دولة مستقِلَّة تقوم في اليمَنِ ويُنسَبُ اليعفريون إلى الملوك الحِمْيَريين، ويعتبر يعفرُ بن عبد الرحيم المؤسِّسَ الفعليَّ لهذه الدولة، وكان الخليفةُ المعتَمِد قد عيَّنه عاملًا على صنعاءَ قبل أن يستقِلَّ بالسلطة ويؤسِّسَ الدولة، ولكِنَّ الخلافاتِ نَشَبت بين أفراد الأسرة اليعفريَّة، فضَعُف مركزُها لتنتهي لاحقًا وتدخُلَ في طاعة دولة الأئمَّة. في آخِرِ عهدِ المتوكِّلِ ابتدأت الدولةُ اليعفرية بصنعاء، وكان جَدُّهم عبدُ الرحيم بن إبراهيم الحوالي نائبًا عن جعفرِ بنِ سليمان بن علي الهاشميِّ، الذي كان واليًا للمعتَصِم على نجدٍ واليمَنِ وصَنعاءَ وما إليها، ولَمَّا توفي عبد الرحيم قام في الولايةِ مقامَه ابنُه يعفر بن عبد الرحيم، وهو رأس الدولة ومبدأُ استقلالِها إلَّا أنَّه كان يهابُ آلَ زياد ويدفَعُ لهم خَراجًا يُحمَلُ إلى زَبيدٍ، كأنَّه عامِلٌ لهم ونائبٌ عنهم، وكان ابتداءُ استقلالِ يعفر بن عبد الرحيم سنة 247هـ، واستمَرَّ مُلْكُ صنعاءَ في أعقابِه إلى سنة 387هـ"},{"id":737,"title":"وفاة الأغلب بن إبراهيم صاحب إفريقية .","date":["العام الهجري :226","الشهر القمري : ربيع الآخر","العام الميلادي :841"],"text":"هو أبو عِقالٍ الأغلَبُ بن إبراهيم بن أغلب، أخو زيادة الله، كانت ولايتُه من قِبَل المعتَصِم بالله، وهو رابِعُ أمراء إفريقية مِن بني الأغلَبِ، ولم تطُلْ مُدَّةُ أيامِه، كانت ولايتُه سنتين وسبعةَ أشهر وسبعة أيَّام, لَمَّا تولَّى أبو عقالٍ أحسَنَ إلى الجند، وأزال مظالمَ كثيرةً، وزاد العُمَّالَ في أرزاقهم، وكَفَّ أيديَهم عن الرعية، وقطَعَ النَّبيذَ والخَمرَ عن القيروان. وكانت أيَّامُه أيَّامَ دَعةٍ وسكونٍ سوى عام 224هـ؛ انتفَضَ بعضُ الخوارجِ فسَيَّرَ إليهم عيسى بن ربعان فأخضَعَهم، ولَمَّا توفِّيَ ولِيَ أبو العباسِ محمَّد بن الأغلب بن إبراهيم بن الأغلب بلادَ إفريقيَّة بعد وفاةِ والده، ودانت له إفريقيَّة."},{"id":738,"title":"قتل أفشين أكبر قائد عسكري عباسي .","date":["العام الهجري :226","الشهر القمري : شعبان","العام الميلادي :841"],"text":"هو حَيدرُ بنُ كاوس الملقَّب بالأفشين، أصلُه من التُّرك مِن أشروسنة تركستان، كان مجوسيًّا مِن سُلالةِ حُكَّام أشروسنة، اعتنق الإسلامَ زمنَ المأمونِ وأقام ببغدادَ عند المعتصِم، وعَظُم محلُّه عنده, وهو من كِبارِ قادةِ المأمونِ والمعتَصِم، تولى إخمادَ الكثيرِ مِن الفِتَن والثَّوراتِ، وأهمُّها ثورةُ بابك الخرمي، ولكن كان يطمَحُ لتولِّي خُراسان بدل عبدالله بن طاهرٍ، فقيل: إنَّه هو الذي حرَّضَ المازيار للخروجِ على ابنِ طاهرٍ حتى يولِّيَه المعتَصِمُ حَربَه، ومِن ثمَّ ولايةَ خُراسان، ولَمَّا قُبِض على المازيار أقَرَّ بكُتُب الأفشين له، فغَضِبَ المعتَصِمُ منه وأمر بالقبضِ عليه، فتمَّ ذلك ليلًا فحبَسَه ثمَّ عَمِلَ له مجلِسَ قَضاءٍ بحُضورِ أحمدَ بنِ أبي دؤاد المعتزلي، ووزيرِه محمَّد بن عبد الملك بن الزيَّات، ونائبِه إسحاقَ بنِ إبراهيم بن مصعب، فاتُّهِم الأفشينُ في هذا المجلس بأشياءَ تدُلُّ على أنَّه باقٍ على دينِ أجدادِه مِن الفُرسِ، وكان ذلك في أواخِرِ عام 225هـ، ثم بقي في السجنِ إلى أن مات فيه، ثم أُخرِجَ فصُلِبَ بجَنبِ بابك الخرمي ثمَّ أُنزِلَ وأُحرِقَ."},{"id":739,"title":"خروج المبرقع أبو حرب اليماني في فلسطين .","date":["العام الهجري :227","العام الميلادي :841"],"text":"خرج بفلسطينَ المُبرقَعُ أبو حربٍ اليمانيُّ الذي زعَمَ أنَّه السُّفياني، فدعا بالأمرِ بالمعروفِ والنَّهيِ عن المنكرِ أولًا، إلى أن قَوِيَت شَوكتُه، فادعى النبوَّةَ. وكان سببُ خُروجِه أن جنديًّا أراد النزولَ في داره، فمنَعَتْه زوجتُه، فضَرَبها الجنديُّ بسوطٍ فأثَّرَ في ذراعها، فلما جاء المُبرقَعُ شكَت إليه، فذهب إلى الجنديِّ فقَتَله وهَرَب، ولَبِسَ بُرقعًا لئلَّا يُعرَف، ونزل جبالَ الغَور مُبرقَعًا، وحَثَّ الناسَ على الأمرِ بالمعروف والنهيِ عن المنكر، فاستجاب له قومٌ مِن فلَّاحي القُرى، وقَوِيَ أمرُه، فسار لحَربِه رجاءُ الحضاريُّ- أحدُ قُوَّاد المعتَصِم- في ألفِ فارسٍ، وأتاه فوجَده في مائةِ ألفٍ، فعسكر بإزائِه ولم يجسِرْ على لقائِه. فلمَّا كان أوانُ الزِّراعةِ تفَرَّقَ أكثَرُ أصحابِه في فلاحتِهم وبَقِيَ في نحو الألفينِ، فواقعه عند ذلك رجاءُ الحضاريُّ المذكور، وأسَرَه وحبَسَه حتى مات خنقًا في آخِرِ هذه السَّنةِ."},{"id":740,"title":"فتنة القيسية بدمشق .","date":["العام الهجري :227","العام الميلادي :841"],"text":"لَمَّا مات المعتَصِم ثارت القيسيَّة بدمشقَ وعاثوا وأفسَدوا وحَصَروا أميرَهم، فبعث الواثِقُ إليهم رجاءَ بنَ أيوب الحضاري، وكانوا مُعسكِرينَ بمَرج راهط، فنزل رجاءٌ بدير مران، ودعاهم إلى الطاعةِ، فلم يَرجِعوا فواعَدَهم الحربَ بدَومة يومَ الاثنين. فلما كان يومُ الأحد، وقد تفَرَّقت، سار رجاءٌ إليهم، فوافاهم وقد سار بعضُهم إلى دومة، وبعضُهم في حوائجه، فقاتَلَهم وقتل منهم نحوَ ألف وخمسمائة، وقُتِلَ مِن أصحابِه نحوُ ثلاثمائة، وهرَبَ مُقَدَّمُهم ابنُ بيهس، وصَلَحَ أمرُ دمشق."},{"id":741,"title":"وفاة الخليفة العباسي المعتصم  .","date":["العام الهجري :227","الشهر القمري : ربيع الأول","العام الميلادي :842"],"text":"هو أبو إسحاقَ محمَّد المعتَصِم بالله بن هارون الرَّشيد بن محمد المهدي بن عبد الله المنصور بن محمد بن علي بن عبد الله بن العباس، ثامِنُ الخُلَفاءِ العباسيِّينَ، وُلِدَ سنة 179ه يوم الخميسِ لثماني عشرة مَضَت من ربيع الأول، بُويع بالخلافةِ يوم الخميس لاثنتي عشرة ليلةً بَقِيَت من رجب سنة ثماني عشرة ومائتين، وبعد ذلك بأيَّامٍ اجتمع جماعةٌ من الجند وشغَّبوا وتحدَّثوا في بيعةِ العبَّاسِ بنِ المأمونِ وأظهروا خلافَ المعتَصِم، ومَضَوا بأسْرِهم إلى مضارِبِ العبَّاسِ فخرج إليهم وقال لهم: أيَّ شيءٍ تُريدونَ منِّي؟ قالوا: نبايعُك بالخلافةِ، قال: أنا قد بايعتُ عمِّي ورَضيتُ به، وهو كبيرى وعندي بمنزلةِ المأمونِ، فانصرفوا خائبينَ، واستمَرَّت في عهدِه فِتنةُ القَولِ بخَلقِ القُرآن, وإنَّما حثَّ المعتَصِمَ على ذلك وحمَلَه على ما فعل به أحمَدُ بنُ أبى دؤادَ؛ لأنَّه كان معتزليًّا، وكان الإمامُ أحمدُ إمامَ السُّنَّة. وحين أحضَرَه المعتَصِم بين يديه سلَّم وتكلَّم بكلامٍ أعجب النَّاسَ، فالتَفَت المعتَصِمُ إلى ابنِ أبى دؤاد، وقال: ذكرتُم أنَّ الرجُلَ عامِّيٌّ، وأراه يذكُرُ بَيتًا قديمًا وشهد له كلُّ من حضر بأنَّه مِن سُراةِ بني شَيبانَ، ثمَّ قال: وذكَرْتُم لي أنَّه جاهِلٌ، وما أراه إلَّا مُعرِبًا فَصيحًا، فأكرَمَ الإمامَ أحمدَ. وكان الإمامُ أحمَدُ بنُ حنبل إلى أن مات يُثني على المعتَصِم ويذكُرُ فِعلَه به ويترحَّمُ عليه. غزا المعتَصِمُ مدينةَ عَمُّوريَّة، وهي من أعظَمِ مُدُنِ الرُّوم كالقُسطنطينيَّة لرَدِّ عدوانِ مَلِك الرومِ على المسلمينَ في زبطرة، فكانت غزوةً مشهورةً نصر اللهُ فيها الإسلامَ والمُسلِمينَ، وكان بدءُ عِلَّتِه أنَّه احتجم أوَّلَ يومٍ في المحَرَّم، واعتَلَّ عِندَها،وكانت خلافتُه ثماني سنينَ وثمانية أشهُر ويومين، وتوفِّيَ بمدينةِ سامِرَّاء."},{"id":742,"title":"تولِّي الواثق بالله الخلافة .","date":["العام الهجري :227","الشهر القمري : ربيع الأول","العام الميلادي :842"],"text":"بويِعَ الواثِقُ باللهِ هارونُ بنُ المعتَصِم في اليومِ الذي توفِّيَ فيه أبوه، وكان يكنَّى أبا جعفرٍ، وأمُّه أمُّ ولَدٍ روميَّة، تسمَّى قراطيس."},{"id":743,"title":"وفاة بشر الحافي .","date":["العام الهجري :227","الشهر القمري : ربيع الأول","العام الميلادي :842"],"text":"هو بِشرُ بنُ الحارثِ بنِ علي المعروفُ بالحافي، مِن أهلِ مَروٍ، ولِدَ سنة 152هـ سكن بغدادَ، كان من أكابرِ الزُّهَّاد، وأخبارُه في الزُّهدِ والوَرَع مشهورةٌ جِدًّا ومعروفة، أثنى عليه غيرُ واحدٍ مِن الأئمَّةِ في عبادتِه وزهادتِه وورَعِه ونُسكِه وتقَشُّفِه. قال الإمامُ أحمد يوم بلَغَه مَوتُه: \"لم يكُنْ له نظيرٌ إلَّا عامِرُ بنُ عبد قيس، ولو تزوَّجَ لتَمَّ أمْرُه\"، وذكر غيرُ واحدٍ أن بِشرًا كان شاطِرًا في بدءِ أمْرِه، وأنَّ سبَبَ تَوبتِه أنَّه وجد رقعةً فيها اسمُ اللهِ عَزَّ وجلَّ، في أتونِ حَمَّام، فرفعها ورفع طرْفَه إلى السَّماءِ، وقال: سيِّدي اسمُك ههنا مُلقًى يُداسُ! ثم ذهب إلى عطَّارٍ فاشترى بدرهمٍ غالية وضَمَّخَ تلك الرقعةَ منها، ووضعها حيثُ لا تُنالُ، فأحيا اللهُ قلْبَه وألهَمَه رُشدَه، وصار إلى ما صار إليه من العبادةِ والزَّهادة، ورحَل بِشرٌ في طلَبِ العِلمِ إلى مكَّة والكوفةِ والبصرة، وسَمِعَ مِن وَكيعٍ وشَريكِ بن عبد الله، وإسماعيل بن عُلَيَّة وحمَّاد بن زيد، ومالك بن أنس، وأبي يوسفَ القاضي، وابن المبارك، وهُشَيم، والمعافى بن عِمران، والفُضَيل بن عياض، وأبي نُعَيمٍ، في خَلْقٍ كثيرٍ. غيرَ أنَّه لم يتصَدَّ للراويةِ، فلم يُضبَطْ عنه من الحديثِ إلَّا اليسيرُ. قال إبراهيم الحربي: \"ما أخرَجَت بغدادُ أتَمَّ عَقلًا منه، ولا أحفَظَ للِسانِه منه، ما عُرِفَ له غِيبةٌ لمسلمٍ، وكان في كُلِّ شَعرةٍ منه عَقلٌ، ولو قُسمَ عَقلُه على أهلِ بغداد لصاروا عُقَلاءَ وما نقَصَ مِن عَقلِه شَيءٌ\". وحين مات اجتمع في جنازتِه أهلُ بغداد عن بَكرةِ أبيهم، فأُخرِجَ بعد صلاةِ الفَجرِ فلم يستقِرَّ في قَبرِه إلَّا بعد العَتَمة، فرَحِمَه اللهُ تعالى وأعلى درجَتَه."},{"id":744,"title":"خروج عامل مدينة تطيلة موسى بن موسى على أمير الأندلس .","date":["العام الهجري :228","العام الميلادي :842"],"text":"سبَبُ ذلك أنَّ موسى بن موسى كان من أعيانِ قُوَّادِ عبد الرحمن، وهو العامِل على مدينةِ تَطيلة، فجرى بينه وبين القُوَّادِ تحاسُدٌ سنةَ سَبعٍ وعشرين، فعصِيَ موسى بن موسى على عبد الرحمنِ بنِ الحَكَم، فسَيَّرَ إليه جيشًا واستعمل عليهم الحارِثَ بنَ يزيغ والقُوَّاد، فاقتتلوا عند برجة، فقُتل كثيرٌ من أصحاب موسى، وقُتِلَ ابنُ عَمٍّ له، وعاد الحارِثُ إلى سرقسطة، فسيَّرَ موسى ابنَه ألب بن موسى إلى برجة، فعاد الحارِثُ إليها وحصَرَها فمَلَكَها وقتَلَ ابنَ موسى، وتقَدَّمَ إلى أبيه فطلبه فحضر، فصالحه موسى على أن يخرُجَ عنها، فانتقل موسى إلى أزبيط، وبقِيَ الحارث يتطَلَّبُه أيامًا ثم سار إلى أزبيط، فحصر موسى بها فأرسل موسى إلى غرسية، وهو مِن ملوك الأندلسيِّينَ المُشرِكينَ، واتَّفقا على الحارث، واجتمعا وجعلا له كمايِنَ في طريقِه، واتخذَ له الخيلَ والرِّجالَ بموضِعٍ يقال له بلمسة على نهرٍ هناك، فلمَّا جاء الحارِثُ النَّهرَ خرج الكُمَناءُ عليه، وأحدَقوا به، وجرى معه قِتالٌ شديد، وكانت وقعةً عظيمةً، وأصابه ضربةٌ في وجهِه فَلَقَت عينَه، ثم أُسِرَ في هذه الوَقعةِ، فلمَّا سَمِعَ عبدُ الرحمن خبَرَ هذه الوقعةِ، عَظُمَ عليه، فجهَّزَ عسكرًا كبيرًا واستعمل عليه ابنَه محمدًا، وسيَّرَه إلى موسى في شهر رمضان من سنة تسع وعشرين ومائتين، وتقَدَّمَ محمد إلى بنبلونة، فأوقع عندها بجمعٍ كثيرٍ مِن المشركين، وقُتِلَ فيها غرسية، وكثيرٌ من المشركين، ثم عاد موسى إلى الخلافِ على عبد الرحمن، فجَهَّزَ جيشًا كبيرًا وسَيَّرَهم إلى موسى، فلمَّا رأى ذلك طلَبَ المُسالَمةَ، فأُجيبَ إليها وأعطى ابنَه إسماعيلَ رهينةً، وولَّاه عبدُ الرحمن مدينةَ تطيلة، فسار موسى إليها فوصلها وأخرجَ كلَّ من يخافُه، واستقَرَّت تطيلةُ في عمالتِه."},{"id":745,"title":"عبد الرحمن بن الحكم يقضي على مجوس الأندلس .","date":["العام الهجري :230","الشهر القمري : صفر","العام الميلادي :844"],"text":"خرج المجوسُ كما سمَّاهم الأندلسيُّون، وهم النرماند أو الفايكونغ، في نحو ثمانين مركبًا، فحَلُّوا بأشبونة، ثمَّ أقبلوا إلى قادس، وشذونة، ثم قَدِموا على إشبيلية فدخَلوها قَسرًا، واستأصلوا أهلَها قَتلًا وأسْرًا. فبَقُوا بها سبعة أيام، يسقونَ أهلَها كأسَ الحِمامِ. واتَّصلَ الخبَرُ بالأميرِ عبدِ الرحمن بن الحَكَم، فقَدِمَ على الخيلِ عيسى بن شهيد الحاجِب، وتوجَّه بالخيلِ عبدُ الله ابن كليب وابنُ رستم وغيرُهما من القوَّاد، واحتل بالشَّرف. وكتب إلى عمَّال الكور في استنفارِ النَّاس، فحَلُّوا بقُرطبة، ونفَرَ بهم نصرُ الفتى. وتوافت للمجوسِ مراكِبُ على مراكِبَ، وجعلوا يَقتُلونَ الرِّجالَ، ويَسْبُونَ النساء، ويأخذون الصِّبيان، وذلك بطولِ ثلاثة عشر يومًا، وكانت بينهم وبين المسلمينَ ملاحِمُ. ثم نهضوا إلى قبطيل، فأقاموا بها ثلاثةَ أيَّام، ودخلوا قورة، على اثني عشرَ ميلًا من إشبيلية، فقتلوا من المسلمين عددًا كثيرًا، ثم دخلوا إلى طليلطِة، على ميلين من إشبيلية، فنزلوها ليلًا، وظهروا بالغَداةِ بمَوضعٍ يُعرَف بالنخارين، ثم مَضَوا بمراكبهم، واعتَرَكوا مع المسلمين. فانهزم المسلمون، وقُتِلَ منهم ما لا يُحصى. ثم عادوا إلى مراكِبِهم. ثم نهضوا إلى شذونة، ومنها إلى قادس، وذلك بعد أن وجَّه الأميرُ عبدُ الرحمن قوَّادَه، فدافعهم ودافَعوه، ونُصِبَت المجانيقُ عليهم، وتوافت الأمدادُ مِن قُرطُبة إليهم. فانهزم المجوسُ، وقُتِلَ منهم نحوٌ من خمسمائة عِلجٍ، وأصيبت لهم أربعةُ مراكِبَ بما فيها، فأمر ابنُ رستم بإحراقِها وبَيعِ ما فيها من الفَيءِ. ثم كانت الوقعةُ عليهم يوم الثلاثاء لخَمسٍ بقين من صفر، قُتِلَ فيها منهم خلقٌ كثيرٌ، وأُحرِقَ مِن مراكبهم ثلاثون مَركبًا. وعلق من المجوس بإشبيليةَ عددٌ كثيرٌ، ورُفِعَ منهم في جذوعِ النَّخلِ التي كانت بها. وركب سائِرُهم مراكِبَهم، وساروا إلى لبلة، ثم توجَّهوا منها إلى الأشنونة فانقطع خَبَرُهم. ولَمَّا قتل اللهُ أميرَهم، وأفنى عديدَهم، وفتح فيهم، خرجت الكتُبُ إلى الآفاقِ بخبَرِهم. وكتب الأميرُ عبد الرحمن إلى مَن بطنجةَ مِن صِنهاجة، يُعلِمُهم بما كان مِن صُنعِ الله في المجوس، وبما أَنزَلَ فيهم من النِّقمةِ والهَلَكةِ، وبعثَ إليهم برأسِ أميرِهم وبمائتي رأسٍ مِن أنجادِهم."},{"id":746,"title":"إخضاع بني سليم وبني هلال من قبائل أعراب المدينة .","date":["العام الهجري :230","الشهر القمري : جمادى الآخرة","العام الميلادي :845"],"text":"كان سببُ ذلك أنَّ بني سُليم كانت تُفسِدُ حولَ المدينة بالشَّرِّ، ويأخذون ما أرادوا من الأسواقِ بالحجازِ بأيِّ سِعرٍ أرادوا، وزاد الأمرُ بهم إلى أن وقَعُوا بناسٍ مِن بني كِنانة وباهلة، فأصابُوهم، وقتلوا بعضَهم، فوَجَّهَ محمَّدُ بن صالح- عامِلُ المدينةِ- إليهم حمَّادَ بنَ جريرٍ الطبري، وكان مَسلَحةً لأهل المدينة، في مائتي فارسٍ، وأضاف إليهم جندًا غيرَهم، وتَبِعَهم متطوِّعة، فسار إليهم حمَّاد، فلَقِيَهم بالرويثة، فاقتتلوا قتالًا شديدًا فانهزمت سودانُ المدينةِ بالنَّاسِ، وثَبَت حمَّادٌ وأصحابُه، وقُرَيشٌ والأنصارُ، وقاتلوا قتالًا عظيمًا، فقُتِل حمَّادٌ وعامةُ أصحابِه وعَدَدٌ صالحٌ مِن قريشٍ والأنصار، وأخذ بنو سُلَيم الكُراعَ والسِّلاحَ، والثياب، فطَمِعوا ونهبوا القُرى والمناهِلَ ما بين مكَّة والمدينة، وانقطع الطريقُ. فوَجَّه إليهم الواثِقُ بغا الكبيرَ أبا موسى في جمعٍ من الجند، فقَدِمَ المدينةَ في شعبان، فلَقِيَهم ببعض مياه الحرَّة من رواء السورقية قريتِهم التي يأوُون إليها وبها حُصون، فقتل بغا منهم نحوًا من خمسين رجلًا وأسر مِثلَهم، وانهزم الباقون، وأقام بغا بالسَّورقية، ودعاهم إلى الأمانِ على حُكم الواثق، فأتوه متفَرِّقين فجَمَعَهم، وترك من يُعرَفُ بالفسادِ، وهم زُهاءَ ألفِ رجل، وخلَّى سبيل الباقين، وعاد بالأَسْرى إلى المدينة، فحبَسَهم ثم سار إلى مكَّة. فلما قضى حَجَّه سار إلى ذاتِ عِرقٍ بعد انقضاء الموسِمِ، وعرض على بني هلالٍ مِثلَ الذي عرضَ على بني سُليم، فأقبلوا وأخذ من المفسدينَ نحوًا من ثلاثمائةِ رَجُلٍ، وأطلق الباقين، ورجع إلى المدينةِ فحَبَسَهم."},{"id":747,"title":"الخليفة الواثق بالله يأمر بامتحان العلماء في مسألة خلق القرآن .","date":["العام الهجري :231","العام الميلادي :845"],"text":"لم تَزَل هذه الفتنةُ ساريةً مِن أيام المأمونِ إلى أيَّامِ المُعتَصِم ثمَّ إلى أيام الواثق، فبَقِيَ على نفسِ مِنوالِ صاحِبَيه السابقَينِ، يمتَحِنُ العلماء بمسألة خَلْقِ القرآنِ ومسألةِ رؤية الله تعالى يومَ القيامة، وسُجِنَ مَن سُجِن وقُتِل من قُتل بسبب هذا، حتى ورد كتابُ الخليفةِ هارون الواثقُ إلى الأعمالِ بامتحانِ العُلَماءِ بخلقِ القُرآنِ، وكان قد منع أبوه المعتَصِمُ ذلك، فامتحَنَ الناسَ ثانيًا بخَلْقِ القرآن. ودام هذا البلاءُ بالنَّاسِ إلى أن مات الواثِقُ وبُويع المتوكِّلُ جَعفرٌ بالخلافة، في سنة اثنتينِ وثلاثين ومائتين، فرفع المتوكِّلُ المِحنةَ ونشَرَ السُّنَّةَ، بل إنَّ الأمرَ استفحَلَ بالواثِقِ أكثَرَ مِن ذلك؛ فإنَّه أمَرَ أيضًا بامتحانِ الأُسارى الذين وَفِدوا من أَسْرِ الفِرنجِ بالقَولِ بخَلقِ القُرآنِ وأنَّ اللهَ لا يُرى في الآخرةِ، فمن أجاب إلى القَولِ بخَلقِ القُرآنِ وأنَّ الله لا يرى في الآخرةِ فُودِيَ، وإلَّا تُرِكَ في أيدي الكُفَّار، وهذه بدعةٌ صَلعاءُ شَنعاءُ، عَمْياءُ صَمَّاءُ، لا مُستنَدَ لها مِن كِتابٍ ولا سُنَّةٍ ولا عقلٍ صَحيحٍ، بل الكتابُ والسُّنَّة والعَقلُ الصَّحيحُ بخِلافِها."},{"id":748,"title":"محمد بن عبد الرحمن أمير الأندلس يحاصر مدينة ليون .","date":["العام الهجري :231","العام الميلادي :845"],"text":"غزا بالصائفة جليقية محمَّد بن الأمير عبد الرحمن بن الحَكَم، فحَصَرها، وحصَرَ مدينة ليون، ورماها بالمجانيقِ. فلمَّا أيقنَ أهلُها بالهلاك خرجوا ليلًا، ولجؤوا إلى الجبالِ والغِياض، فأحرقَ محمَّدٌ ما فيها، وأراد هدمَ سُورِها، فوجد سعتَه ثمانيَ عشرة ذراعًا فتركه، وأمعن في بلادِ الشِّركِ قتلًا وسبيًا."},{"id":749,"title":"الخليفة الواثق يمتحن أسارى المسلمين في الروم بمسألة خلق القرآن .","date":["العام الهجري :231","الشهر القمري : محرم","العام الميلادي :845"],"text":"وقَعَت مُفاداةُ الأُسارى بين المسلمينَ والرُّوم، واجتمع المسلِمونَ على نهرِ اللَّامس، على مسيرةِ يومٍ مِن طرسوس، واشترى الواثِقُ من بغداد وغيرِها من الروم، وعقَدَ الواثِقُ لأحمد بن سعيد بن سلم بن قُتيبة الباهلي على الثغور والعواصِم، وأمره بحضورِ الفِداءِ هو وخاقان الخادِم، وأمَرَهما أن يمتحنا أَسرى المُسلِمينَ، فمن قال: القرآنُ مَخلوقٌ، وإنَّ اللهَ لا يُرى في الآخرةِ، فوُدِيَ به، وأعطِيَ دِينارًا، ومن لم يقُلْ ذلك تُرِكَ في أيدي الرُّومِ. فاجتمع المسلِمونَ ومن معهم من الأَسرى على النَّهرِ، وأتت الرومُ ومَن معهم من الأَسرى، وكان النَّهرُ بين الطائفَتَينِ، فكان المسلِمونَ يُطلِقونَ الأسيرَ فيُطلِقُ الرُّومُ مِن المسلمينَ، فيلتقيانِ في وسط النَّهرِ، ويأتي هذا أصحابُه، فإذا وصل الأسيرُ إلى المسلمينَ كَبَّروا، وإذا وصل الأسيرُ إلى الرومِ صاحوا حتى فَرَغوا، وكان عِدَّةُ أسرى المسلمين أربعةَ آلافٍ وأربعَمائة وستين نفسًا، والنِّساء والصبيان ثمانيمائة، وأهلُ ذِمَّة المسلمين مائةُ نفس، وكان النهر مخاضةً تَعبُرُه الأسرى، وقيل، بل كان عليه جِسرٌ."},{"id":750,"title":"مقتل أحمد بن نصر الخزاعي بسبب عدم قوله بخلق القرآن .","date":["العام الهجري :231","الشهر القمري : رمضان","العام الميلادي :846"],"text":"هو أبو عبدِ اللهِ أحمَدُ بنُ نصرِ بن مالك بن الهيثم الخُزاعي المروزي، ثم البغدادي، الإمامُ الكبيرُ الشَّهيدُ، ثِقةٌ فاضِلٌ، مِن كبارِ العُلَماء الآمِرينَ بالمعروفِ والنَّاهينَ عن المُنكَر. كان أحمَدُ بنُ نصرٍ يُخالِفُ مَن يقولُ: القُرآنُ مخلوقٌ، ويُطلِقُ لِسانَه فيه، مع غِلظةِ بالواثق، وكان يقولُ- إذا ذكَرَ الواثِقَ: فعَلَ هذا الخِنزيرُ، وقال هذا الكافِرُ، وفشا ذلك، فكان يغشاه رجلٌ يُعرَفُ بأبي هارونَ الشَّداخ وآخَرُ يقال له طالب، وغيرُهما، ودَعَوا الناسَ إليه، فبايعوه على الأمرِ بالمعروفِ والنَّهيِ عن المنكر، وفرَّقَ أبو هارون وطالِبٌ في الناسِ مالًا، فأعطيا كلَّ رجلٍ دينارًا، واتَّعَدوا ليلةَ الخميس لثلاثٍ خَلَت من شَعبانَ لِيَضرِبوا الطبلَ فيها ويثوروا على السُّلطانِ، فافتضحَ أمرُهم فأرسل الواثِقُ إلى أحمدَ بنِ نصرٍ، فأخَذَه وهو في الحمَّامِ، وحمل إليه، وفَتَّش بيته، فلم يوجَدْ فيه سلاحٌ، ولا شيءٌ من الآلاتِ، فسَيَّرَهم محمد بن إبراهيم إلى الواثِقِ مُقَيَّدينَ على أُكُفِ بِغالٍ ليس تحتَهم وِطاءٌ، إلى سامِرَّا وكان قد أعدَّ له مجلِسَ قضاءٍ، فقال الواثِقُ: ما تقولُ بالقرآنِ؟ قال: كلامُ اللهِ، فقال الواثِقٌ: أمخلوقٌ هو؟ قال: كلامُ الله. قال: فما تقولُ في ربِّك أَتَراه يومَ القيامة؟ قال: يا أميرَ المؤمنينَ، قد جاءت الأخبارُ عن رسولِ الله صلى اللهُ عليه وسلَّم، أنَّه قال: ((تَرَونَ ربَّكم يومَ القيامةِ كما تَرَون القمَرَ- قال- لا تُضامُونَ في رُؤيتِه)) فنحن على الخبَرِ، فقال الواثِقُ لِمَن حوله: ما تقولونَ فيه؟ فقال عبدُ الرحمن بن إسحاق- وكان قاضيًا على الجانبِ الغربيِّ- وعِزِّكَ يا أميرَ المؤمنينَ، هو حلالُ الدَّمِ، وقال بعضُ أصحابِ ابنِ أبي دؤاد: اسقِني دَمَه، وقال ابنُ أبي دؤاد: هو كافِرٌ يُستتابُ، لعلَّ به عاهةً ونقْصَ عَقلٍ، كأنَّه كَرِهَ أن يُقتَلَ بسَببِه، فقال الواثِقُ: إذا رأيتُموني قد قمتُ إليه، فلا يقومَنَّ أحَدٌ، فإنِّي أحتَسِبُ خطايَ إليه، ودعا بالصَّمصامة- سيفِ عمرِو بنِ مَعدِيَكرِب الزبيدي- ومشى إليه، وهو في وسط الدار على نِطعٍ، فضربه على حبلِ عاتِقِه، ثمَّ ضربَ سيما الدمشقيُّ رقبَتَه، وحزَّ رأسَه، وطعنه الواثِقُ بطَرفِ الصمصامة في بطنِه، وحُمِلَ رأسُه إلى بغداد فنُصِبَ بها وأقيمَ عليه الحرَسُ، وكتَبَ في أذُنِه رقعة: هذا رأسُ الكافرِ، المُشرِك الضالِّ، أحمد بن نصر؛ فلم يزَلْ مَصلوبًا ستَّ سنين، ثمَّ حُطَّ وجُمِعَ بين رأسِه وبدنِه، ودفن بالجانبِ الشَّرقيِّ مِن بغداد في عهد المتوكِّل، وتتبَّعَ الواثِقُ أصحابَ أحمدَ بنِ نصر، فجُعِلوا في الحُبُوس، فرحمةُ اللهِ على أحمدَ بنِ نَصرٍ، وإنَّا لله وإنَّا إليه راجعون، ذكره الإمامُ أحمدُ بنُ حنبل يومًا، فقال: \"رَحِمَه اللهُ، ما كان أسخاه بنَفسِه لله! لقد جاد بنَفسِه له\"."},{"id":751,"title":"استقلال إمارة بني يعفر عن العباسيين وظهور أوَّل إمام زَيديٍّ في صنعاء .","date":["العام الهجري :232","العام الميلادي :846"],"text":"في حوالَيْ عامِ 232هـ ومع ضَعفِ الحُكام العباسيِّينَ بدأت تظهرُ أطماعُ بعضِ الوُلاةِ المحلِّيينَ في كَوْكبانَ وعلى رأسِهم يَعفُرُ بنُ عبدِ الرحمنِ الحَوَاليُّ. ومع أواخِرِ القرنِ التاسعِ الميلاديِّ، أصبحت اليَمنُ قاعدةَ عملياتٍ لحركةِ الشِّيعةِ الفاطميِّينَ. وقد عهِدَ يَعفُرُ بالسُّلطةِ لابنِه محمدٍ الذي فضَّلَ أن تكونَ مِن صَنعاءَ، ثم عهِدَ محمدُ بنُ يَعفُرَ بالسُّلطةِ بعدَ ذلك لابنِه إبراهيمَ، الذي اختَلَف مع أبيه على أسلوبِ الحُكم، وانتهي الأمرُ بقتلِ أبيه عامَ 892م/269هـ. تَبِعَ ذلك فوضى وتمَرُّدٌ بينَ القبائلِ وأهالي القُرى بَينَ السُّنِّيِّينَ والشِّيعةِ، وعَمَّ التَّوتُّرُ شوارعَ صَنعاءَ حتى أرسلَ الخليفةُ العباسيُّ في بغدادَ آنذاكَ، علِيَّ بنَ الحُسَينِ إلى اليَمنِ لِيقضيَ على الفِتنةِ ويَضعَ نهايةً لِلتَّمرُّدِ. بعدَ استِدعاءِ ابنِ الحُسَينِ إلى بَغدادَ عامَ 895م/282هـ. اهتزَّتِ الأمورُ في صَنعاءَ، وحينَئِذٍ ظهرَ أوَّلُ إمامٍ زَيديٍّ ليتوَلَّى زِمامَ الأمرِ، وهو الإمامُ الهادي إلى الحقِّ يحيى بنُ الحُسَينِ، ولكنَّه لم يَستطِعْ أن يحُدَّ مِنَ الصِّراعاتِ، فعادَ بنو يَعفُرَ إلى الحُكمِ، ومع وفاةِ آخِرِ حُكَّامِهم عبدِ اللهِ بنِ قَحطانَ، انتهى حُكمُهم، وظلَّتِ البِلادُ في حالةِ فوضى سياسيةٍ إلى أن جاء إلى الحُكمِ سُلالةٌ أُخرى حاكمةٌ، وهم بَنو الصُّليحيِّ عامَ 1047م/439هـ."},{"id":752,"title":"وفاة الخليفة العباسي الواثق .","date":["العام الهجري :232","الشهر القمري : ذي الحجة","العام الميلادي :847"],"text":"هو الواثِقُ هارون بن محمد المعتصِم بالله بن هارون الرشيد، تاسِعُ الخُلَفاء العباسيين، ولد ببغداد سنة 200هـ، ومُدَّة خلافتِه خمسُ سنين وتسعة أشهر وخمسة أيام، وقيل سبعة، وفي نفسِ اليوم بويع لأخيه المتوكِّل بالخِلافةِ."},{"id":753,"title":"تولي المتوكل الخلافة العباسية .","date":["العام الهجري :232","الشهر القمري : ذي الحجة","العام الميلادي :847"],"text":"وكانت الأتراكُ قد عَزَموا على توليةِ محمَّدِ بنِ الواثق، فاستصغروه فتَرَكوه وعَدَلوا إلى أخيه جعفر، وكان عُمُره إذ ذاك ستًّا وعشرين سنة، وكان الذي ألبَسَه خِلعةَ الخلافة أحمدَ بن أبي دؤاد القاضي، وكان هو أوَّلَ مَن سلَّم عليه بالخلافةِ، وبايعه الخاصَّةُ والعامَّةُ، وكانوا قد اتَّفَقوا على تسميته بالمنتَصِر بالله، إلى صبيحةِ يوم الجمعة، فقال ابنُ أبي دؤاد: رأيت أن يلقَّبَ بالمتوكِّل على الله، فاتَّفَقوا على ذلك، وكُتِبَ إلى الآفاق."},{"id":754,"title":"ثورة سالم بن غلبون بإفريقيا .","date":["العام الهجري :233","الشهر القمري : محرم","العام الميلادي :847"],"text":"عزل محمَّدُ بن الأغلبِ- أميرُ إفريقيَّةَ- عامِلَه على الزاب، واسمُه سالم بن غلبون، فأقبلَ يريدُ القيروانَ، فلما صار بقلعةِ يلبسير أضمَرَ الخلافَ وسار إلى الأربس، فمَنَعه أهلُها من الدخول إليها، فسار إلى باجة، فدخلها واحتمى بها فسيَّرَ إليه ابنُ الأغلب جيشًا عليهم خفاجةُ بن سفيان، فنزل عليه وقاتَلَه، فهرب سالمٌ ليلًا، فاتبعه خفاجة، فلَحِقَه وقتَلَه، وحمَلَ رأسَه إلى ابنِ الأغلب، وكان أزهرُ بن سالم عند ابنِ الأغلب محبوسًا فقَتَله."},{"id":755,"title":"وفاة يحيى بن معين .","date":["العام الهجري :233","الشهر القمري : صفر","العام الميلادي :847"],"text":"هو الإمامُ الحافِظُ الجَهبَذُ، شيخُ المحَدِّثين، أبو زكريَّا يحيى بن مَعِينِ بنِ عون بن زياد بن بسطام. الغطفانيُّ, ثم المُرِّي مولاهم البغدادي. ولد سنة ثمان وخمسينَ ومائة. أحدُ أعلامِ أئمَّة الحديثِ، سيِّدُ الحفَّاظِ، إمامُ عَصرِه بالجَرح ِوالتَّعديلِ، وإليه المنتهى والمرجِعُ بذلك، وقال الإمام أحمد: \"كلُّ حديثٍ لا يَعرِفُه يحيى، فليس بحديثٍ\"، له كتابٌ في العِلَلِ، وكتابٌ في الجَرحِ والتعديل، توفِّيَ بالمدينةِ وغُسِّلَ على الأعوادِ التي غسِّلَ عليها رسولُ الله صلَّى الله عليه وسلَّم، ونادى منادٍ في جنازتِه: هذا الذي كان يذُبُّ الكَذِبَ عن رسولِ اللهِ صلَّى الله عليه وسلَّم، ودُفِنَ في البقيعِ- رحمه الله تعالى، وجزاه عن الإسلامِ والمُسلِمينَ خَيرًا."},{"id":756,"title":"خروج محمد بن البعيث بأذربيجان على الخليفة المتوكل .","date":["العام الهجري :234","العام الميلادي :848"],"text":"خرج محمَّدُ بنُ البعيث بن حلبس عن الطاعةِ في بلاده أذربيجان، وأظهر أن المتوكِّلَ قد مات، والتفَّ عليه جماعةٌ مِن أهلِ تلك الرساتيق، ولجأ إلى مدينةِ مرند فحصَّنَها، وجاءته البعوثُ مِن كلِّ جانبٍ، وأرسل إليه المتوكِّلُ جيوشًا يَتبَعُ بَعضُها بعضًا، فنصبوا على بلده المجانيقَ مِن كلِّ جانب، وحاصروه محاصرةً عظيمةً جِدًّا، وقاتلهم مُقاتلةً هائلة، وصبَرَ هو وأصحابُه صبرًا بليغًا، وقَدِمَ بغا الشرابي لمحاصرتِه، فلم يزَلْ به حتى أسَرَه واستباح أموالَه وحريمَه، وقتل خَلقًا مِن رؤوسِ أصحابِه، وأسَرَ سائِرَهم وانحَسَمت مادةُ ابن البعيث، وأُرسِلَ ابنُ البعيث إلى سامِرَّا وحُبِسَ، ثم شُفعَ له عند المتوكِّل، فلم يقتُلْه، ولكنه مات بعد شهر في سامرَّا."},{"id":757,"title":"الخليفة العباسي المتوكل يلغي القول بخلق القرآن .","date":["العام الهجري :234","العام الميلادي :848"],"text":"بعد أن تمكَّنَ المتوكِّلُ من الخلافةِ ولم يكُنْ على مذهَبِ أخيه ومَن قَبلَه في مسألةِ خَلْقِ القرآنِ، وخاصَّةً أنَّه لم يُقَرِّبْ أحمدَ بنَ أبي دؤاد المعتزليَّ، كما كان مقرَّبًا للواثِقِ، فأمر وكتَبَ بالكَفِّ عن امتحانِ النَّاسِ بمسألةِ خَلقِ القُرآنِ، حتى هدَّدَ بالقتلِ مَن امتحَنَ فيها وأعاد القولَ فيها، ونشَرَ السُّنَّةَ, واستقدم الإمامَ أحمَدَ إليه واعتذَرَ إليه، وشاوره بمن يُرشَّحُ للقضاءِ، فرشَّحَ له ابنَ أكثَمَ."},{"id":758,"title":"خروج عمرو بن سليم على دولة الأغالبة في أفريقيا .","date":["العام الهجري :234","العام الميلادي :848"],"text":"خرج عَمرُو بنُ سُليم التجيبي- المعروفُ بالقويع- على محمَّدِ بنِ الأغلب أميرِ إفريقيَّة، فسيَّرَ إليه جيشًا، فحصره بمدينةِ تونس، فلم يبلُغوا منه غرضًا فعادوا عنه. فلما دخَلَت سنة خمس وثلاثين سيَّرَ إليه ابن الأغلب جيشًا، فالتَقَوا بالقرب من تونس، ففارق جيشَ ابنِ الأغلب جمعٌ كثيرٌ، وقصدوا القويعَ فصاروا معه، فانهزم جيشُ ابن الأغلب وقَوِيَ القُويع؛ فلما دخلت سنةُ ستٍّ وثلاثين سيَّرَ محمد بن الأغلب إليه جيشًا، فاقتتلوا فانهزم القويعُ، وقتلَ من أصحابِه مَقتَلة عَظيمة، وأدرك القويعَ إنسانٌ، فضرَبَ عُنُقَه، ودخل جيشُ ابن الأغلب مدينة تونس بالسَّيفِ في جمادى الأولى."},{"id":759,"title":"وفاة علي بن المديني .","date":["العام الهجري :234","الشهر القمري : ذي القعدة","العام الميلادي :849"],"text":"هو عليُّ بنُ عبدالله بن جعفر المعروفُ بابنِ المديني، إمامُ عَصرِه في الجرحِ والتَّعديلِ والعِلَل، وُلِدَ سنةَ إحدى وستين ومائةٍ، أحدُ الأعلامِ، وصاحبُ التصانيفِ، روى عنه الأئمَّةُ: البُخاري، وأحمد، والنَّسائي، وغيرُهم، قال ابن عُيَينة: \"لولا ابنُ المدينيِّ ما جَلَستُ\"، وقال النَّسائيُّ: \"كأنَّ اللهَ خلَقَ عليَّ بن المديني لهذا الشأنِ\"، وقيل للبخاريِّ ما تشتهي؟ قال: \"أقدَمُ العِراقَ وعَلِيُّ بنُ عبدالله حيٌّ فأجالِسُه\". وقال البخاري: \"ما استصغَرْتُ نفسي عند أحدٍ إلَّا عند عليِّ بنِ المَدِيني\" له كتابُ العِلَل، وقَولُه في الجرحِ والتَّعديلِ مُقَدَّمٌ، توفِّيَ في سامرا، فرَحِمَه الله تعالى وجزاه عن الإسلامِ والمسلمينَ خَيرًا."},{"id":760,"title":"الخليفة المتوكل يأمر بتمييز أهل الذمة عن المسلمين .","date":["العام الهجري :235","العام الميلادي :849"],"text":"أمر المتوكِّلُ أهلَ الذِّمَّة بلُبسِ الطَّيالِسة العسليَّة، وشَدِّ الزنانيرِ، ورُكوبِ السُّروجِ بالركب الخشَب، وعَمَل كُرَتَين في مؤخَّرِ السروج، وعمَل رُقعَتَين على لباسِ مَماليكِهم مُخالِفَتينِ لِلَونِ الثوب، كلُّ واحدةٍ منهما قَدْرُ أربعة أصابِعَ، ولونُ كلِّ واحدةٍ منهما غيرُ لون الأخرى، ومن خرجَ مِن نسائهم تلبس إزارًا عسليًّا، ومنعهم من لباسِ المناطِقِ، وأمَرَ بهَدمِ بِيَعِهم المُحدَثة، وبأخْذِ العُشرِ مِن منازِلِهم، وأن يُجعَلَ على أبوابِ دُورِهم صُوَرُ شَياطينَ مِن خشَبٍ، ونهى أن يُستعانَ بهم في أعمالِ السُّلطانِ، ولا يُعَلِّمَهم مسلِمٌ، وأن يُظهِروا في شَعانينِهم صَليبًا، وأن يستعملوه في الطريقِ، وأمر بتسويةِ قبورِهم مع الأرضِ، وكتب في ذلك إلى الآفاقِ."},{"id":761,"title":"ظهور محمود بن الفرج في سامرا يزعم أنه نبي .","date":["العام الهجري :235","العام الميلادي :849"],"text":"خرج رجلٌ يقال له محمودُ بن الفَرَج النيسابوري، وهو ممَّن كان يتردَّدُ إلى خشَبةِ بابك وهو مصلوبٌ فيقعُدُ قريبًا منه، وذلك بقُربِ دار الخلافةِ بسُرَّ من رأى، فادَّعى أنَّه نبيٌّ، وأنَّه ذو القرنينِ، وقد اتَّبَعه على هذه الضَّلالة ووافَقَه على هذه الجَهالةِ جماعةٌ قليلونَ، وهم تسعة وعشرون رجلًا، وقد نظَمَ لهم كلامًا في مصحَفٍ له- قبَّحه الله- زعم أنَّ جبريلَ جاءه به من الله، فأتيَ به وبأصحابِه المتوكِّل، فأمر به فضُرِبَ ضربًا شديدًا وحُمِلَ إلى بابِ العامَّة، فأكذب نَفسَه، وأمَرَ أصحابَه أن يَضرِبَه كلُّ رجلٍ منهم عشرَ صفعاتٍ، ففعلوا وأخذوا له مُصحفًا فيه كلامٌ قد جمعه، وذكر أنَّه قرآنٌ، وأنَّ جبريل نزل له، ثمَّ مات من الضَّربِ في ذي الحجَّة، وحُبِسَ أصحابُه، ثم اتَّفقَ مَوتُه في يوم الأربعاء لثلاثٍ خَلَونَ مِن ذي الحجة من هذه السَّنةِ."},{"id":762,"title":"أخذ الخليفة العباسي المتوكل العهد لأولاده .","date":["العام الهجري :235","العام الميلادي :849"],"text":"عقد المتوكل البيعة لبنيه الثلاثة بولاية العهد وهم محمد، ولقبه المنتصر بالله، وأبو عبد الله محمد؛ وقيل طلحة، وقيل الزبير، ولقبه المعتز بالله، وإبراهيم، ولقبه المؤيد بالله، وعقد لكل واحد منهم لواءين أحدهما أسود وهو لواء العهد، والآخر أبيض وهو لواء العمل، وأعطى كل واحد منهم عدة ولايات."},{"id":763,"title":"وفاة أبي بكر بن أبي شيبة صاحب المصنف .","date":["العام الهجري :235","العام الميلادي :849"],"text":"هو الإمامُ العَلَمُ, سَيِّدُ الحفَّاظ, أبو بكر عبدُالله بن محمد بن القاضي أبي شيبة إبراهيم بن عثمان بن خُوَاستَى العبسي مولاهم, الكوفي. ولد بالكوفةِ عام 159هـ. أحدُ أعلام الحديثِ، صاحِبُ المصَنَّف المعروف. أخو الحافظ عثمانَ بنِ أبي شيبة، والقاسمِ بن أبي شيبة الضَّعيف. فالحافظ إبراهيمُ بن أبي بكر هو ولَدُه, والحافِظُ أبو جعفر محمد بن عثمان هو ابنُ أخيه, فهُم من بيتِ علم, وأبو بكر: أجَلُّهم. قال أبو عُبيدٍ: انتهى عِلمُ الحديثِ إلى أربعةٍ: أحمدَ بنِ حنبل، وأبي بكرِ بنِ أبي شيبة، ويحيى بنِ مَعين، وعليِّ بنِ المَديني؛ فأحمدُ أفقَهُهم فيه، وأبو بكرٍ أسرَدُهم، ويحيى أجمَعُ له، وابنُ المَديني أعلَمُهم به. قَدِمَ ابنُ أبي شيبة بغداد وحَدَّثَ بها، وله كتاب التفسيرِ، والأحكام، والمُسنَد المصَنَّف."},{"id":764,"title":"الخليفة المتوكل يتخلص من الأتراك بعد تدخُّلُهم في شؤونِ الدَّولةِ .","date":["العام الهجري :235","الشهر القمري : جمادى الآخرة","العام الميلادي :850"],"text":"كان إيتاخُ التركي قائدَ جيشِ المتوكِّلِ وإليه المغاربة، والأتراك، والأموال، والبريد، والحِجابة، ودارُ الخلافة, وكان الأتراكُ بعد أن رشَّحوا المتوكِّلَ للخلافةِ بعد أبيه، بدأ تدخُّلُهم في شؤونِ الدَّولةِ، فلمَّا تمكَّنَ المتوكِّلُ من الخلافةِ، وقد أدرك خطرَ الأتراكِ على الدولةِ، عَمِلَ على تَصفيتِهم، وبدأ بمربِّيه إيتاخَ التركيِّ، فلما عاد إيتاخ مِن مكَّةَ، وكان حاجًّا تلك السنةَ كتب المتوكِّلُ إلى إسحاقَ بنِ إبراهيم ببغداد يأمُرُه بحَبسِه، فاحتال عليه إسحاقُ حتى حبَسَه، وقَيَّدَ إيتاخ، وجَعَلَ في عنُقِه ثمانين رطلًا فمات. وقيل: إنَّ موتَه كان بالعَطَشِ، وأنَّه أُطعِمَ فاستسقى، فمُنِعَ الماءَ حتى مات عطشًا."},{"id":765,"title":"الخليفة العباسي المتوكل يأمر بهدم قبر الحسين بن علي .","date":["العام الهجري :236","العام الميلادي :850"],"text":"أمَرَ المتوكِّلُ بهَدمِ قَبرِ الحُسَين بنِ عليِّ بنِ أبي طالب وما حولَه من المنازلِ والدُّورِ، ونودي في الناسِ: مَن وُجِدَ هنا بعد ثلاثةِ أيَّامِ ذَهَبتُ به إلى المطبق (سجن من سجون بغداد)، فلم يبقَ هناك بَشَرٌ، واتُّخِذَ ذلك الموضِعُ مَزرعةً تُحرَثُ وتُستغَلُّ."},{"id":766,"title":"ثورة حبيب البرنسي في الأندلس .","date":["العام الهجري :236","العام الميلادي :850"],"text":"ثار رجُلٌ من البربر، يقالُ له حبيبٌ البرنسي، بجبال الجزيرة؛ فتجَمَّع إليه جماعةٌ من أهل الشَّرِّ والفساد في الأرضِ، فشَنَّ بهم الغارةَ على قُرى رية وغيرها، فأشاع الأذى، ونهبَ وقتَل وسَبى،، فأخرج إليه عبدُ الرحمن الأجنادَ، فلما وصلوا إليه ألْفَوُا البربرَ قد قَصَدوا حبييًا ومن تجمَّعَ إليه، فتغَلَّبوا على المعقل الذي كان انضوى إليه، وأخرجوه عنه، وقتلوا عدةً كثيرةً من أصحابه. وافتَرَق بقيَّتُهم عنه، ودخل حبيبٌ في غِمارِ النَّاسِ. وطُفِئَت ثائِرتُه، فكتب الأميرُ عبد الرحمن إلى عمَّالِ الكور بالبَحثِ عنه, وطُلِبَ دهرًا فلم يُظفَرْ به."},{"id":767,"title":"ظهور رجل من المعلِّمينَ بشَرقِ الأندلس يدعي النبوءة .","date":["العام الهجري :237","العام الميلادي :851"],"text":"قام رجلٌ من المعلِّمينَ بشَرقِ الأندلس، فادَّعى النبوءةَ، وتأوَّلَ القرآن على غيرِ تأويلِه، فاتَّبَعه جماعةٌ مِن الغوغاء، وقام معه خَلقٌ كثيرٌ، وكان من بعض شرائِعِه النهيُ عن قَصِّ الشعرِ وتقليم الأظفار، ويقول: [لا تغييرَ لخلق الله] فبعث إليه يحيى بنُ خالد، فأتى به. فلما دخل عليه كان أوَّل ما خاطبه به أنْ دعاه إلى اتِّباعِه والأخذِ بما شرَع، فشاور فيه أهلَ العِلمِ، فأشاروا بأن يُستَتابَ، فإن تاب وإلَّا قُتِلَ. فقال: كيف أتوبُ مِن الحقِّ الصَّحيحِ؟! فأمَرَ بصَلبِه. فلمَّا رُفِعَ في الخشبة، قال: أتقتلونَ رجلًا أن يقول: ربِّي الله! فصَلَبَه، وكتَبَ إلى الأميرِ يُخبِرُه."},{"id":768,"title":"بداية ظهور يعقوب بن الليث الصفار في سجستان .","date":["العام الهجري :237","العام الميلادي :851"],"text":"كان صالحُ بنُ النضر الكناني من أهلِ بُست، قد ظهر بتلك الناحية يقاتِلُ الخوارج، وسمَّى أصحابَه المتطوِّعةَ، حتى قيل له: صالح المطوِّعي وصَحِبَه جماعةٌ؛ منهم: درهم بن الحسن، ويعقوب بن الليث, وغَلَبوا على سجستان، ثم أخرَجَهم عنها طاهرُ بن عبد الله أميرُ خراسان. وهلك صالح إثر ذلك، وقام بأمر المتطوِّعةِ دِرهمُ بن الحسن، فكَثُرَ أتباعه. وكان يعقوبُ بن الليث شهمًا، وكان دِرهَم مُضعفًا، واحتال صاحِبُ خراسان حتى ظَفِرَ بدرهم وحَبَسه ببغداد، فاجتمعت المتطوِّعةُ على يعقوب بن الليث، وملَّكوه أمْرَهم؛ لِمَا رأَوا من تدبيرِه، وحُسنِ سياستِه، وقيامِه بأمورهم، وقام بقتال الخوارجِ الشراةِ، وأتيح له الظَّفَرُ عليهم، وأثخن فيهم وخرَّبَ قُراهم، وكانت له شريةٌ في أصحابه لم تكن لأحدٍ قَبله، فحَسُنَت طاعتُهم له وعَظُمَ أمرُه، ومَلَك سجستانَ مُظهِرًا طاعةَ الخليفةِ وكاتِبِه، وقلَّدَه حرب الشراة، فأحسن الغَناءَ فيه وتجاوَزَه إلى سائر أبوابِ الأمرِ بالمعروف والنهي عن المنكر, فاستبَدَّ يعقوبُ بالأمر، وضَبَط البلاد، وقَوِيَت شوكتُه وقصَدتْه العساكِرُ من كلِّ ناحية."},{"id":769,"title":"وفاة الخوارزمي واضع علم الجبر .","date":["العام الهجري :237","العام الميلادي :851"],"text":"هو أبو عبدالله- وقيل: أبو جعفر- محمَّد بن موسى الخوارزمي، رياضيٌّ فلَكيٌّ جغرافيٌّ مؤرِّخٌ، من أهل خوارزم, وقيل ولد عام 164هـ بخوارزم, وكان يُنعَت بالأستاذِ، أقامه المأمونُ قَيِّمًا على خزانة كتُبِ بيتِ الحكمة، وعَهِدَ إليه بجَمعِ الكتب اليونانية وترجَمتِها، ترجم كتابَ بطليموس المجسطي، فصار أساسَ عِلمِ الفلك، ووضع جدولًا فلكِيًّا للمواقع الجغرافيَّة بحسب الابتعادِ التدريجيِّ عن خطِّ الزوال، يعتبَرُ أكبَرَ رياضيٍّ في عصره، أسس علمَ الجَبرِ، وله كتابُ الجبر والمقابلة، وكتب صورة الأرضِ وغيرها. وقد بيَّن الخَوارزميُّ في مُقدِّمة كتابه \" الجبر والمقابلة\" أن الخليفةَ المأمونَ هو الذي طلَبَ منه أن يُؤلِّفَ كتابَ الجَبرِ والمقابلة؛ كي يسهُلَ الانتفاعُ به في كلِّ ما يحتاجُ إليه الناس. وقد قال- رحمه الله- في مقدِّمة كتاب \"الجبر والمقابلة\": \"وقد شجَّعني ما فضَّلَ اللهُ به الإمامَ المأمونَ، أميرَ المؤمنينَ، مع الخلافةِ التي حاز له إرثَها وأكرَمَه بلباسِها وحَلَّاه بزينتها, من الرغبةِ في الأدَبِ وتقريبِ أهلِه وإدنائِهم وبَسْطِ كَنَفِه لهم، ومعونته إيَّاهم على إيضاحِ ما كان مستهمًّا، وتسهيل ما كان وعرًا، على أن ألَّفْتُ من كتابِ الجبر والمقابلة كتابًا مُختصَرًا، حاصِرًا لِلَطيفِ الحسابِ وجَليلِه؛ لِمَا يَلزمُ النَّاسَ مِن الحاجة إليه في مواريثِهم ووصاياهم، وفي مُقاسماتِهم وأحكامِهم وتجاراتِهم، وفي جميعِ ما يتعاملون به بينهم من مساحةِ الأراضي وكَرْيِ الأنهار والهندسة، وغير ذلك من وجوهِه وفنونِه، مُقدِّمًا لحُسْن النيَّة فيه، راجيًا لأن يُنزِلَه أهلُ الأدبِ- بفَضلِ ما استُودِعوا من نِعَمِ الله تبارك وتعالى، وجليلِ آلائه، وجميلِ بلائِه عندهم- منزلتَه، وباللهِ توفيقي في هذا وغيرِه، عليه توكَّلْتُ وهو ربُّ العَرْشِ العظيم\" وقيل: توفي عام 232هـ"},{"id":770,"title":"الخليفة المتوكل يعزل ابن أبي دؤاد المعتزلي وينصر السنة .","date":["العام الهجري :237","الشهر القمري : صفر","العام الميلادي :851"],"text":"غَضِبَ المتوكِّلُ على ابنِ أبي دؤاد القاضي المعتزليِّ، وكان على المظالمِ، فعَزَله عنها واستدعى يحيى بنَ أكثَمَ، فولاه قضاءَ القُضاةِ والمظالمِ أيضًا. وفي ربيع الأوَّل أمر الخليفةُ بالاحتياطِ على ضِياعِ ابنِ أبي دؤاد، وأخَذَ ابنَه أبا الوليد محمَّدًا فحَبَسه في يوم السبتِ لثلاثٍ خَلَونَ من ربيع الآخر، وأمَرَ بمصادرتِه، فحَمَل مائةَ ألفِ وعشرين ألف دينار، ومن الجواهِرِ. كان ابنُ أبي دؤاد قد أصابه الفالجُ (الشلل النصفي) بعد أن دعا على نفسِه إن لم يكُن الواثِقُ قد قتَلَ أحمدَ بنَ نصرٍ كافرًا, ثم نفى المتوكِّلُ أهلَ ابن أبي دؤاد من سامِرَّا إلى بغداد مُهانين، وفي عيدِ الفطر من هذا العام أمَرَ المتوكِّل بإنزالِ جُثَّة أحمدَ بنِ نصرٍ الخُزاعي والجَمعِ بين رأسِه وجَسَدِه وأن يُسَلَّم إلى أوليائِه، ففَرِحَ النَّاسُ بذلك فرحًا شديدًا، واجتمع في جنازتِه خَلقٌ كثيرٌ جِدًّا، وكان يومًا مَشهودًا, ثمَّ كتب المتوكِّلُ إلى الآفاقِ بالمَنعِ مِن الكلامِ في مسألةِ الكلامِ، والكَفِّ عن القولِ بخَلقِ القرآن، وأنَّ من تعلَّمَ عِلمَ الكلامِ لو تكلَّمَ فيه  فالمطبق (سجن من سجون بغداد) مأواه إلى أن يموتَ. وأمر الناسَ ألَّا يشتغِلَ أحدٌ إلَّا بالكتابِ والسنَّةِ لا غيرُ، ثمَّ أظهر إكرامَ الإمامِ أحمدَ بنِ حنبل واستدعاه من بغدادَ إليه، فاجتمع به فأكرمَه وأمَرَ له بجائزةٍ سَنِيَّةٍ فلم يقبَلْها، وخلع عليه خِلعةً سَنيَّةً مِن ملابسِه فاستحيا منه أحمدُ كثيرًا، فلبسها إلى الموضِعِ الذي كان نازلًا فيه، ثمَّ نزعها نزعًا عنيفًا وهو يبكي- رحمه الله تعالى- وارتفَعَت السُّنَّة جِدًّا في أيام المتوكِّل- عفا الله عنه- وكان لا يولِّي أحدًا إلا بعد مشورةِ الإمام أحمد، وكانت ولايةُ يحيى بن أكثم قضاءَ القضاةِ مَوضِعَ ابنِ أبي دؤاد عن مشورتِه، وقد كان يحيى بن أكثَم هذا من أئمَّة السنة، وعُلماء الناس، ومن المعظِّمين للفقه والحديث واتِّباع الأثَر."},{"id":771,"title":"الخليفة المتوكل ينتقم من البطارقة لقتلهم عامل أرمينية .","date":["العام الهجري :237","الشهر القمري : رمضان","العام الميلادي :852"],"text":"وكان سببُ ذلك أنَّ يوسُفَ بنَ محمَّد- عامِلَ أرمينيَّةَ- لَمَّا سار إلى أرمينية خرج إليه بِطْريقٌ يقال له بقراط بن أشوط، ويقال له بِطريقُ البطارقة، يطلبُ الأمان، فأخذه يوسُفُ وابنُه نعمة، فسيَّرَهما إلى باب الخليفة، فاجتمع بطارقة أرمينية مع ابن أخي بقراط بن أشوط، وتحالفوا على قتلِ يوسُفَ، ووافقهم على ذلك موسى بن زرارة، وهو صِهرُ بقراط على ابنتِه، فأتى الخبَرُ يوسف، ونهاه أصحابُه عن المُقام بمكانه، فلم يقبَلْ، فلما جاء الشِّتاء، ونزل الثلج، مكثوا حتى سكنَ الثلج، ثم أتَوه وهو بمدينة طرون، فحصروه بها فخرج إليهم من المدينة فقاتَلَهم، فقتلوه وكلَّ مَن قاتل معه، وأمَّا من لم يقاتِلْ معه، فقالوا له: انزِعْ ثيابَك، وانجُ بنَفسِك عريانًا، ففعلوا ومَشَوا حفاةً عُراةً، فهلك أكثَرُهم من البرد، وسقطت أصابِعُ كثيرٍ منهم، ونجوا، وكان يوسُفُ قبل ذلك قد فَرَّق أصحابَه في رساتيق عمله، فوجَّه إلى كلِّ طائفة منهم طائفةً من البطارقة، فقتلوهم في يومٍ واحد، فلما بلغ المتوكِّلَ وجَّه بغا الكبير إليهم، طالبًا بدَمِ يوسُفَ، فسار إليهم على المَوصِل والجزيرة، فبدأ بأرزن، وبها موسى بن زرارة، فحمَلَ بغا موسى بنَ زرارة إلى المتوكل، وأباح قَتَلَة يوسف، فقتل منهم زُهاءَ ثلاثين ألفًا وسبى منهم خلقًا كثيرًا، فباعهم وسار إلى بلاد الباق، فأسَرَ أشوط بن حمزة أبا العباس."},{"id":772,"title":"الروم يحتلون دمياط ثم ينسحبون .","date":["العام الهجري :238","العام الميلادي :852"],"text":"جاء ثلاثُمائة مركَبٍ للرُّومِ مع ثلاثةِ رُؤساء، فأناخ أحدُهم في مائةِ مركَبٍ بدمياط، وكان على معونةِ مِصرَ عَنبسةُ بن إسحاق الضبِّي، فلما حضَرَ العيدُ أمَرَ الجندَ الذين بدمياط أن يَحضُروا مصر، فساروا منها، فاتَّفَق وصولُ الرومِ وهي فارغةٌ من الجندِ، فنَهَبوا وأحرقوا وسَبَوا، وأحرقوا جامِعَها، وأخذوا ما بها من سلاحٍ ومَتاعٍ، وقَنْدٍ، وغير ذلك، وسَبَوا من النساء المُسلِمات والذِّمِّيات نحو ستمائة امرأة، وأوقَروا سُفُنَهم من ذلك، وكان عنبسةُ قد حَبَس ابنَ الأكشف بدمياط، فكسَرَ قَيدَه، وخرج يقاتِلُهم، وتَبِعَه جماعةٌ، وقتَلَ من الروم جماعةً، وسارت الرومُ إلى أشنوم تنيس من قرى مصر قديما، وكان عليه سورٌ وبابان من حديدٍ قد عَمِلَه المعتَصِم، فنهبوا ما فيه من سلاحٍ، وأخذوا البابينِ، ورجعوا ولم يَعرِضْ لهم أحدٌ."},{"id":773,"title":"وفاة أمير الأندلس عبدالرحمن الأوسط .","date":["العام الهجري :238","الشهر القمري : صفر","العام الميلادي :852"],"text":"هو أبو المطَرِّف عبدالرحمنِ بنُ الحكَم بن هشام بن عبدالرحمن الداخل، رابِعُ أمراء الأندلس، ويلقَّبُ بالأوسط، أو عبدالرحمن الثاني، ولد عام 176هـ, كان مكثرًا للغَزو، فتصدى للثوراتِ الداخليَّة وعدوان النَّصارى في شمال الأندلُسِ، وغارات النورماند البحريَّة, وكان يحِبُّ العِمرانَ، فبنى المساجِدَ والقصور، وفي عَهدِه كَثُرت وفودُ المشارقة العلماء. توفِّي في قرطبة بعد حُكمٍ دام 32 سنةً، مخلِّفًا من الأولاد 150 من الذكور، و50 من الإناثِ، ثمَّ تولى مِن بعده ابنُه محمد، المعروف بمحمد الأول، الذي دامت إمارتُه 34 عامًا."},{"id":774,"title":"القائد بغا الكبير يحاصر مدينة تفليس ويستولى عليها .","date":["العام الهجري :238","الشهر القمري : ربيع الأول","العام الميلادي :852"],"text":"حاصَرَ بغا مدينة تفليس، وعلى مقَدِّمته زيرك التركي، فخرج إليه صاحبُ تفليس إسحاقُ بنُ إسماعيل فقاتله، فأُسِرَ إسحاق، فأمر بغا بضَربِ عُنُقِه وصَلبِه، وأمَرَ بإلقاء النارِ في النفطِ إلى نحو المدينة، وكان أكثَرُ بنائها من خشَبِ الصَّنَوبر، فأَحرَقَ أكثَرَها، وأحرقَ من أهلِها نحوًا من خمسين ألف إنسان، وخَمِدَت النار بعد يومينِ; لأنَّ نارَ الصنوبر لا بقاء لها، ودخل الجندُ فأسَروا من بقي من أهلِها، واستَلَبُوهم حتى استَلَبوا الموتى. ثمَّ سار بغا إلى مدنٍ أخرى ممَّن كان يمالئُ أهلُها مع من قَتَل نائبَ أرمينية يوسُفَ بن محمد بن يوسف؛ أخذًا بثأره، وعقوبةً لِمَن تجرَّأ عليه."},{"id":775,"title":"وفاة إسحاق بن راهويه .","date":["العام الهجري :238","الشهر القمري : شعبان","العام الميلادي :853"],"text":"هو الإمامُ الكبيرُ، شَيخُ المَشرِق، سيِّدُ الحُفَّاظ، أبو يعقوب: إسحاق بن إبراهيم بن مَخلَد الحنظلي التيميُّ المروزي، المعروف بابنِ راهَوَيه، ولد بمرو عام 161هـ كان مِن أهل مرو، وسكن نيسابور، أحدُ الأئمَّة الحُفَّاظ، شيخ البخاريِّ وأحمد ومسلم وغيرهم، فكُلُّهم روى عنه، قال الحسن بن عبد الصمد: سمعتُ إسحاقَ بن إبراهيم يقول: أحفَظُ سبعينَ ألف حديثٍ كأنَّها نُصبَ عيني. اجتمع فيه الحديثُ والفِقهُ، والحِفظُ والدِّينُ والوَرَعُ، ولإسحاقَ تصانيفُ، وكان صاحِبَ فقهٍ كالإمام أحمد، وله مسائل مشهورة، قال إسحاقُ: قال لي عبدُ الله بن طاهر أميرُ خراسان: لمَ قيلَ لك: ابنُ راهَوَيه؟ وما معنى هذا، وهل تكرهُ أن يقال لك هذا؟ قلتُ: اعلَمْ- أيُّها الأميرُ- أنَّ أبي وُلِدَ في الطريقِ، فقالت المراوزة: راهَوَيه؛ لأنَّه وُلِدَ في الطريق، وكان أبي يكرهُ هذا، وأمَّا أنا فلستُ أكرهُ ذلك."},{"id":776,"title":"الخليفة العباسي المتوكل يزيد في التغليظ على أهل الذمة .","date":["العام الهجري :239","العام الميلادي :853"],"text":"أمرَ المتوكِّلُ بأخذِ أهلِ الذِّمَّة بلُبسِ ذِراعَينِ عَسليتيَّن على الأقبيةِ والدراريع، وبالاقتصارِ في مراكِبِهم على ركوبِ البِغالِ والحَميرِ دون الخَيلِ والبَراذينِ، وأمر المتوكِّلُ بهدمِ البِيَعِ المُحدَثةِ في الإسلامِ."},{"id":777,"title":"إصلاح قلعة رباح بالأندلس بعد أن هدم أهلُ طليطِلة سورها .","date":["العام الهجري :239","العام الميلادي :853"],"text":"سيَّرَ محمَّدُ بن عبد الرحمن جيشًا مع أخيه الحكَمِ إلى قلعةِ رباح، وكان أهلُ طليطِلة قد خَرَّبوا سُورَها وقتَلوا كثيرًا من أهلِها، وأصلح الحكَمُ سُورَها وأعاد مَن فارَقَها من أهلها إليها، وأصلح حالَها، وتقدَّمَ إلى طليطِلة فأفسد في نواحيها وشَعثِها وسيّرَ محمد أيضًا جيشًا آخَرَ إلى طليطلة، فلما قاربوها خرجت عليهم الجنودُ مِن المكامن، فانهزم العسكَرُ، وأصيب أكثرُ من فيه."},{"id":778,"title":"وفاة الحافظ الكبير عثمان بن أبي شيبة  .","date":["العام الهجري :239","الشهر القمري : محرم","العام الميلادي :853"],"text":"هو الإمامُ الحافِظُ الكبيرُ المفَسِّر: أبو الحسن عثمانُ بن محمد بن القاضي بن أبي شيبة إبراهيم خواستى العبسي مولاهم الكوفي، صاحب التصانيفِ، وأخو الحافظ أبي بكرِ بن أبي شيبة، صاحب كتاب \"المصنَّف\" والقاسِم بن أبي شيبة الضعيف.  فهم من بيت علم, وأبو بكر: أجلُّهم. وهو شيخُ البخاري ومسلم، وقد أكثَرَ عنه البخاري في (صحيحه)."},{"id":779,"title":"معركة وادي سليط وانتصار المسلمين على أهل طليطلة وحلفائهم .","date":["العام الهجري :240","العام الميلادي :854"],"text":"خرج الأميرُ محمد بنفسِه إلى طليطلة. فلمَّا عَلِمَ أهلُها بذلك، أرسلوا إلى أردن بن إذفونش صاحِبِ جليقية، يعلمونَه بحَركتِه ويستَمِدُّون به. فبعث إليهم أخاه غثون في جمعٍ عظيمٍ مِن النصارى. فلمَّا عَلِمَ بذلك الأميرُ محمد، وقد كان قاربَ طليطلة، أعملَ الحيلةَ والكيد، وأخذ بالحَزمِ، فعبَّأَ الجيوشُ، وكمَنَ الكمائِنَ بناحية وادي سليط، ثم نصب الردودَ، وطلع في أوائلِ العسكر في قِلَّةٍ من العدد. فلما رأى ذلك أهلُ طليطلة، أعلموا العِلجَ بما عاينُوه من قِلَّةِ المسلمين، فتحرك العِلجُ فَرِحًا، وقد طَمِعَ في الظَّفَر والغنيمةِ وانتهاز الفرصة. فلما التقى الجمعانِ، خرجت الكمائنُ عن يمين وشمال، وتواترت الخيلُ أرسالًا على أرسال، حتى غشى الأعداءَ منهم ظُلَلٌ كالجبال، فانهزم المشرِكونُ وأهلُ طليطلة، وأخَذَتهم السِّلاح، قطعًا بالسيوفِ، وطعنًا بالرماح، فقتل اللهُ عامَّتَهم، وأباد جماعَتَهم. وحُزَّ مِن رؤوسِهم ممَّا كان في المعركة وحواليها ثمانيةُ آلاف رأس، وجُمِعَت ورُصَّت؛ فصار منها جبلٌ علاه المُسلِمونَ، يكَبِّرون ويهلِّلون ويَحمَدونَ ربَّهم ويَشكُرون. وبعث الأميرُ محمَّد بأكثَرِها إلى قرطبة، وإلى سواحِلِ البحر، وإلى العدوة. وانتهى عددُ مَن فُقِدَ منهم في هذه الوقعةِ إلى عشرينَ ألفًا."},{"id":780,"title":"ثورة أهل حمص على عاملهم أبي المُغيث موسى الرافعي .","date":["العام الهجري :240","العام الميلادي :854"],"text":"وثب أهلُ حِمصٍ بعامِلِهم أبي المُغيث موسى بن إبراهيم الرافعي، وكان قتَلَ رجلًا من رؤسائِهم، فقتلوا جماعةً مِن أصحابه، وأخرجوه، وأخرجوا عامِلَ الخراج، فبعث المتوكِّلُ إليهم عتَّاب بن عتاب، ومحمد بن عبدويه الأنباري، وقال لعتَّاب: قلْ لهم: إنَّ أميرَ المؤمنينَ، قد بَدَّلَكم بعامِلِكم، فإن أطاعوا فوَلِّ عليهم محمد بن عبدويه، فإن أبَوْا فأقمْ وأعلِمْني، حتى أُمِدَّك برجالٍ وفُرسانٍ، فساروا إليهم، فرَضُوا بمحمد بن عبدويه، فعَمِلَ فيهم الأعاجيبَ، حتى أحوَجَهم إلى محاربتِه, فأساء إليهم وعَسَف فيهم، فوثبوا به، وأمَدَّه المتوكِّلُ بجُندٍ مِن دمشق والرملة، فظفر بهم وقتلَ منهم جماعة، وأخرج النَّصارى منها، وهدَمَ كنائِسَهم، وأدخل منها بيعةً في الجامِعِ كانت تجاوِرُه."},{"id":781,"title":"وفاة أفلح بن عبدالوهاب الإباضي إمامُ الرستميَّة بالمغرب الأوسط .","date":["العام الهجري :240","العام الميلادي :854"],"text":"هو أفلحُ بن عبدالوهاب بن عبدالرحمن بن رستم، إمامُ الرستميَّة الإباضيَّة الثالث في تاهرت، بويع له للإمامة بعد أبيه عام 190هـ، كان حازِمًا للأمورِ، وقد خرجت عليه كثيرٌ من الحروبِ والفِتَن، كان مؤيِّدًا للأُمَويِّين في الأندلس، وهو الذي أحرق مدينةَ العباسيَّة التي بناها الأغالبةُ عام 239هـ وكافأه على ذلك عبدُالرحمن الأوسط أميرُ الأندلس بمائة ألف دِرهَم، ودامت إمامتُه للرستمية خمسين سنة، واستخلف بعدَه ابنُه أبو اليقظان."},{"id":782,"title":"وفاة ابن أبي دؤاد المعتزلي .","date":["العام الهجري :240","الشهر القمري : محرم","العام الميلادي :854"],"text":"هو أبو عبدِ الله أحمدُ بنُ أبي دؤاد فرج بن جرير بن مالك بن عبد الله بن عباد بن سلام، ولد سنةَ ستين ومائة بقِنَّسرينَ، ونشأ بدمشق, وكان أبوه تاجرًا يَفِدُ إلى الشام، ثم وفد إلى العراق وأخذ ولَدَه هذا معه إلى العراق، فارتحل للبصرةِ، واتصل ابن أبي دؤاد بأصحاب واصلِ بنِ عطاء، وعنهم أخذ مذهَبَ الاعتزالِ، ثم اتَّصلَ بالمأمونِ فكان قاضيَ القُضاةِ، وكان موصوفًا بالجود والسَّخاءِ وحُسنِ الخُلقِ ووُفورِ الأدب، غيرَ أنَّه أعلن بمذهب الجهميَّة، وحمل السلطانَ على امتحانِ النَّاسِ بخَلقِ القرآن، لم يكُنْ بعد البرامكةِ أكرَمُ منه، ولولا ما وضع مِن نفسِه مِن محبَّة المحنةِ، لاجتمعت عليه الإنسُ. حثَّ المأمونَ على امتحانِ العُلَماءِ والناسِ بمسألةِ خَلقِ القرآن، وبَقِيَ كذلك مع المعتَصِم ومع الواثِقِ، كلُّ ذلك هو رأسُ الفتنةِ وفَتيلُ نارِها، حتى جاء المتوكِّلُ، وكان ابن أبي دؤاد قد دعا على نفسِه إن لم يكُن الواثِقُ قد قتل أحمدَ بنَ نَصرٍ كافرًا، فأصابه اللهُ بالفالجِ، فبقي أربع سنينَ مَحبوسًا بمَرَضِه ذلك، فعزله المتوكِّلُ وأمر بمصادرةِ أموالِه، فصولح على سِتَّة عشر مليون درهمٍ، توفِّيَ في بغداد عن ثمانين سنةً- عامَلَه اللهُ بما يستَحِقُّ."},{"id":783,"title":"الخليفة المتوكل يفتدي أسرى المسلمين من ملكة الروم .","date":["العام الهجري :241","العام الميلادي :855"],"text":"كان الفِداءُ بين المُسلِمينَ والروم، بعد أن قَتَلَت تدورة- ملكةُ الرُّومِ- من أسرى المسلمينَ اثني عشر ألفًا، فإنَّها عَرَضت النصرانيَّة على الأسرى، فمن تنَصَّرَ جعَلَتْه أسوةَ مَن قَبلَه من المتنصِّرة، ومن أبى قتَلَتْه، وأرسلت تطلُبُ المفاداةَ لِمَن بقي منهم، فأرسل المتوكِّلُ شنيفًا الخادم، فأذِنَ له فحضره واستخلف على القضاءِ ابنَ أبي الشوارب، وهو شابٌّ، ووقع الفداءُ على نهر اللامس، فكان أسرى المُسلمينَ مِن الرجال سبعمائة وخمسة وثمانين رجلًا، ومن النساء مائة وخمسًا وعشرينَ امرأة."},{"id":784,"title":"تمرد طائفة البُجاة من سودان بلاد النُّوبة على الخليفة المتوكل .","date":["العام الهجري :241","العام الميلادي :855"],"text":"البُجاة هم طائفةٌ مِن سودان بلاد المغرب، وكذا النُّوبة وشنون وزغرير ويكسوم، وأممٌ كثيرةٌ لا يعلَمُهم إلا الله، وفي بلادِ هؤلاء معادنُ الذهب والجوهر، وكان عليهم حملٌ في كُلِّ سَنةٍ إلى ديار مصر من هذه المعادنِ، فلما كانت دولةُ المتوكِّل امتنعوا من أداءِ ما عليهم سنينَ مُتَعدِّدة، فكتب نائِبُ مِصرَ إليه يُعلِمُه بذلك، فلما شاور المتوكِّلُ في أمرِهم أعلموه أنَّهم في أرضٍ بعيدةٍ، ومن أراد قتالَهم عليه التزوُّدُ كثيرًا، وإذا فَنِيَ الزاد هَلَكوا بأرضِهم، وأنَّهم يُمكِنُهم الاستنجادُ بالنُّوبةِ والحبوش، ففَتَرَ المتوكِّلُ عن قتالهم فتفاقم أمرُهم حتى أخافوا الصعيدَ، فعرض محمد بن عبدالله القمي أن يحارِبَهم فتجهَّزَ لهم بجيشٍ، وأمر أن يبقى بجانبِ السواحل حتى يأتيه المدَدُ منها، فسار إليهم في جيشِه، فلما رأوه على تلك الهيئةِ بَقُوا يراوِغونَه كالثَّعالِبِ حتى يفنى زادُهم فيقتُلونَهم، ولكِنْ لَمَّا رأوا أنَّ المراكِبَ تأتيهم بالمَدَدِ من الشاطئ على النيلِ، أيقنُوا أنَّه لا مفَرَّ مِن حَربِهم، فكَرُّوا إليه وكانت لهم جِمالٌ قويَّةٌ، لكنها سريعةُ النفورِ، فأعمل جيشُ القميِّ الأجراسَ والطبولَ فنَفَرت إبِلُهم، فقُتِلَ منهم الكثيرُ، ولكِنَّ رئيسَهم علي بابا هرَب، ثم إنه طلبَ الأمانَ على أن يُعطِيَ ما كان منَعَه كُلَّ تلك السنين وأن يعود على ما كان عليه من الخَراجِ، فأعطاه الأمانَ وسَيَّرَه إلى المتوكِّلِ الذي أكرمه وأعاده إلى بلادِه."},{"id":785,"title":"ثورة أهل حمص على عاملهم محمد بن عبدويه الأنباري .","date":["العام الهجري :241","الشهر القمري : محرم","العام الميلادي :855"],"text":"بعد أن وثب أهلُ حِمصٍ العامَ الماضي على أبي المُغيثِ موسى بن إبراهيم الرافعي، ثم أبدلهم المتوكل بمحمد بن عبدويه الأنباري ورضوا به، لم يَسِرْ بهم العامِلُ الجديدُ سِيرةً حَسنةً، بل فعل فيهم الأعاجيبَ، فوثب أهلُ حمص بعامِلِهم الجديد محمد بن عبدويه، وأعانَهم عليه قومٌ مِن نصارى حمص، فكتب إلى المتوكِّلِ، فكتب إليه يأمُرُه بمناهَضتِهم، وأمَدَّه بجندٍ مِن دمشق والرملة، فظفر بهم، فضرب منهم رجُلَينِ مِن رؤسائهم حتى ماتا وصَلَبَهما على باب حمص، وسَيَّرَ ثمانية رجال وأمَرَ المتوكلُ بإخراج النَّصارى منها، وهَدْمِ كنائِسِهم، وبإدخالِ البيعةِ التي إلى جانِبِ الجامع إلى الجامِعِ، ففعل ذلك."},{"id":786,"title":"وفاة الإمام أحمد بن حنبل .","date":["العام الهجري :241","الشهر القمري : ربيع الأول","العام الميلادي :855"],"text":"هو أبو عبدِ الله أحمدُ بنُ مُحمَّد بن حنبل بن هلال بن أسَدٍ الشَّيباني المروزي، نزيل بغداد، أحدُ الأئمَّة الأربعة المشهورينَ في الفقهِ، ثِقةٌ حافِظٌ، فقيهٌ حُجَّةٌ، وهو رأسُ الطَّبقة العاشرة، خرجت أمُّه من مرو وهي حامِلٌ به، فولدته في بغداد، في شهرِ ربيع الأول سنة أربع وستين ومائة، وقيل: إنَّه وُلِدَ بمَروٍ وحُمِلَ إلى بغداد وهو رضيعٌ. نشأ وتعلَّمَ ببغداد. كان مخضوبًا، طُوالًا، أسمرَ شديدَ السُّمرةِ. توفِّيَ والِدُه وهو شابٌّ, وتزوَّجَ بعد الأربعينَ. ورحل كثيرًا. وعُنِيَ بطلب الحديث، تفَقَّه على الشافعي، وكان له اجتهادٌ حتى صار إمامًا في الحديث والعِلَل، إمامًا في الفِقهِ، كلُّ ذلك مع وَرَعٍ وزُهدٍ وتقَشُّف، وإليه تُنسَبُ الحنابلة، هو الذي وقَفَ وقفَتَه المشهورةَ في مسألةِ خَلقِ القرآن فأبى أن يجيبَهم على بدعتِهم، فضُرِبَ بالسِّياطِ أيَّامَ المعتَصِم والواثِقِ، وبَقِيَ قبلها تحت العذابِ قُرابةَ الأربع سنينَ، وكلُّ ذلك هو ثابتٌ بتثبيت الله له، ثمَّ في عهد الواثقِ مُنِعَ من الفُتيا، وأُمِرَ بلُزومِ بَيتِه كإقامةٍ جَبريَّةٍ، ولم ينفرِجْ أمرُه حتى جاء المتوكِّلُ ورفع هذه المحنةَ، بقي قرابةَ الأربع عشرة سنةً في هذه المحنةِ بين ضَربٍ وحَبسٍ وإقامةٍ جَبريَّة، فكان من الذين قال اللهُ فيهم: {وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآيَاتِنَا يُوقِنُونَ} [السجدة: 24]، وكان الذين ثَبَتوا على الفتنةِ فلم يجيبوا بالكليَّة: خمسة: أحمدُ بن حنبل وهو رئيسهم، ومحمَّد بن نوح بن ميمون الجند النيسابوري- ومات في الطريقِ- ونُعَيم بن حماد الخزاعي- وقد مات في السِّجنِ- وأبو يعقوب البويطي- وقد مات في سِجنِ الواثقِ على القول بخلق القرآنِ، وكان مُثقلًا بالحديد- وأحمدُ بنُ نصر الخزاعي، قَتَلَه الواثق، قال يحيى بن معين: \"كان في أحمدَ بنِ حَنبل خِصالٌ ما رأيتُها في عالم قَطُّ: كان مُحدِّثًا، وكان حافِظًا، وكان عالِمًا، وكان وَرِعًا، وكان زاهِدًا، وكان عاقِلًا\" قال الشافعي: \"خرجتُ من العراق فما تركت رجلًا أفضَلَ ولا أعلَمَ ولا أورَعَ ولا أتقى من أحمدَ بنِ حنبل\" وقال المُزَني: أحمدُ بن حنبل يومَ المحنة، وأبو بكرٍ يومَ الرِّدَّة، وعُمَرُ يومَ السقيفة، وعُثمانُ يومَ الدار، وعليٌّ يومَ الجَمَلِ وصِفِّين\"، وكان- رحمه الله- إمامًا في الحِفظِ، قال أبو زرعة: \"كان أحمدُ بنُ حنبل يحفَظُ ألفَ ألف حديثٍ، فقيل: له وما يدريك، قال: ذاكرتُه فأخذت عليه الأبوابَ\", وقيل لأبي زُرعةَ: من رأيتَ من المشايخ المحدِّثين أحفَظَ؟ فقال: أحمد بن حنبل، حَزَرتُ كُتُبَه اليومَ الذي مات فيه، فبلغت اثني عشر حِملًا وعِدلًا، ما كان على ظَهرِ كتابٍ منها حديثُ فلان، ولا في بطنِه حديثُ فلانٍ، وكلُّ ذلك كان يحفَظُه عن ظَهرِ قَلبِه\", وقال إبراهيم الحربي: \"رأيتُ أحمدَ بنَ حنبل كأنَّ اللهَ قد جمع له عِلمَ الأوَّلينَ والآخِرينَ مِن كلِّ صِنفٍ، يقولُ ما شاء، ويُمسِكُ ما شاء\". له كتابُ المُسنَد المشهورُ، وله غيرُ ذلك في الجرحِ والتعديل والعِلَل، توفي في بغداد، وكانت جنازتُه مشهودةً, وقيل: لَمَّا مات الإمامُ أحمد صلَّى عليه ألفُ ألفٍ وسِتُّمائة ألف رجلٍ، وأسلم وراءَ نَعشِه أربعةُ آلافِ ذِمِّي مِن هَولِ ما رأَوا.، فرَحِمَه اللهُ تعالى، وجزاه الله خيرًا عن الإسلامِ والمسلمين."},{"id":787,"title":"وفاة محمد بن الأغلب أمير أفريقيا .","date":["العام الهجري :242","العام الميلادي :856"],"text":"هو أبو العبَّاسِ محمَّدُ بن الأغلب أمير إفريقيَّة، تولى الإمارةَ بعد موت أبيه عام 226هـ، ودانت له إفريقيَّةُ، وشَيَّدَ مدينةً بقرب تاهرت، وسمَّاها العباسية، وذلك سنة 227هـ, حاول أخوه أبو جعفرٍ أن يأخُذَ الإمارةَ منه عام 231هـ، لكنَّه تغلب عليه ونفاه، ثم ثار عليه سالمُ بنُ غلبون وعمرو بن سليم. توفِّيَ وعمره ستٌّ وثلاثون سنةً، دامت إمارتُه خمس عشرة سنة وثمانية أشهر، وولِيَ بعدَه ابنُه أحمد إمارةَ إفريقيَّة."},{"id":788,"title":"الجيوش الأندلسية تدخل برشلونة .","date":["العام الهجري :242","العام الميلادي :856"],"text":"كتب الأميرُ محمَّدُ بنُ عبدالرحمن إلى موسى بن موسى بحَشدِ الثُّغورِ والدُّخولِ إلى برشلونة، فغزاها وافتتح في هذه الغَزاةِ حِصنَ طراجة، وهي مِن آخر أحواز برشلونة، ومِن خُمُسِ ذلك الحِصنِ زِيدَت الزَّوائِدُ في المسجد الجامِعِ بسَرقسطة، وكان الذي أسَّسَه ونصب محرابَه حنش الصنعاني، وهو من التابعينَ."},{"id":789,"title":"الأميرُ محمَّد بن عبد الرحمن يقضي على فتنة أهل طليطلة في الأندلس .","date":["العام الهجري :243","العام الميلادي :857"],"text":"وقَعَت في هذه السَّنةِ وَقعةٌ عَظيمةٌ في أهل طليطِلة، وذلك أنَّهم خرجوا إلى طلبيرة، فخرج إليهم قائِدُها مسعود بن عبد الله العريف، بعد أن كمَنَ لهم الكمائِنَ، فقتلهم قتلًا ذريعًا، وبعث إلى قُرطبةَ بسَبعمائة رأسٍ مِن رؤوس أكابِرِهم، ثم في سنة 244هـ خرج الأميرُ محمَّد بنَفسِه إلى طليطلة، وعدَدُهم قد قَلَّ، بتواتر الوقائِعِ عليهم، ونزولِ المصائبِ بهم، فلم تكن لهم حربٌ إلا بالقنطرة. ثم أمر الأميرُ بقَطع ِالقنطرة، وجَمَع العُرَفاء من البنَّائين والمُهندسين، وأداروا الحيلةَ مِن حيث لا يشعُرُ أهل طليطلة. ثم نزلوا عنها، فبينما هم مجتَمِعونَ بها، إذ اندَقَّتْ بهم، وتهدَّمَت نواحيها، وانكفأتْ بمن كان عليها من الحُماة والكُماة، فغَرَقوا في النهرِ عن آخرهم. فكان ذلك من أعظَمِ صُنعِ اللهِ فيهم. ثم في سنة 245هـ دعا أهلُ طليطلة إلى الأمانِ، فعقَدَه الأميرُ لهم، وهو الأمانُ الأوَّلُ."},{"id":790,"title":"دخول الخليفة العباسي المتوكل دمشق وعزمه على اتخاذها مقرًا له .","date":["العام الهجري :244","الشهر القمري : صفر","العام الميلادي :858"],"text":"خرج المتوكِّلُ من العراقِ قاصدًا دِمشقَ فأدركه الأضحى في الطريق ولم يَصِل دمشق إلَّا في أوَّلِ هذه السنة، فدخل الخليفةُ المتوكِّلُ إلى مدينة دمشق في أُبَّهة الخلافةِ، وكان يومًا مشهودًا، وكان عازمًا على الإقامة بها، وأمَرَ بنقل دواوينِ المُلْك إليها، وأمَرَ ببناء القصور بها، فبُنِيَت بطريق داريا، فأقام بها مدَّةً، ثم إنَّه استوخَمَها ورأى أنَّ هواءَها بارِدٌ نَدِيٌّ وماءَها ثقيلٌ بالنسبة إلى هواءِ العِراقِ ومائِها، ورأى الهواء بها يتحَرَّك من بعد الزوالِ في زمن الصيف، فلا يزالُ في اشتدادٍ وغُبارٍ إلى قريبٍ مِن ثُلُث الليل، ورأى كثرةَ البَراغيث بها، ودخل عليه فَصلُ الشتاء فرأى من كثرةِ الأمطارِ والثلوج أمرًا عجيبًا، وغَلَت الأسعارُ وهو بها؛ لكثرة الخَلقِ الذين معه، وانقَطَعت الأجلابُ بسبَبِ كثرةِ الأمطارِ والثلوج، فضَجِرَ منها، ثم رجع من آخِرِ السَّنة إلى سامِرَّا بعد ما أقام بدمشق شهرين وعشرة أيام، ففرح به أهلُ بغداد فرحًا شديدًا."},{"id":791,"title":"فتح المُسلِمين مَدينةَ قصريانة في بلاد الروم .","date":["العام الهجري :244","الشهر القمري : شوال","العام الميلادي :859"],"text":"فتح المُسلِمونَ مَدينةَ قصريانة، وهي المدينةُ التي بها دارُ المُلْك بصقلية، وكان المَلِكُ قبلها يسكُنُ سرقوسة، فلما مَلَك المسلمونَ بعضَ الجزيرة نقل دارَ المُلك إلى قصريانة لحصانَتِها. وسبَبُ فَتحِها أنَّ العبَّاسَ بنَ الفَضلِ- أميرَ صقلية- سار في جيوشِ المسلمين إلى مدينة قصريانة، وسرقوسة، وسيَّرَ جيشًا في البحر، فلَقِيَهم أربعون شلندي للرُّوم، فاقتتلوا أشَدَّ قتال، فانهزم الرومُ، وأخذ منهم المسلمون عَشرَ شلنديات برجالِها، وعاد العباس بنُ الفضل إلى مدينته. فلما كان الشتاءُ سَيّرَ سرية، فبلغت قصريانة، فنهبوا وخَرَّبوا، وعادُوا ومعهم رجلٌ كان له عند الرومِ قَدْرٌ ومَنزِلةٌ، فأمر العبَّاسُ بقَتلِه، فقال: استَبْقِني، ولك عندي نصيحةٌ، قال: وما هي؟ قال: أُمَلِّكُك قصريانةَ، والطريقُ في ذلك أنَّ القَومَ في هذا الشتاءِ وهذه الثلوجِ آمِنونَ مِن قَصدِكم إليهم، فهم غيرُ مُحتَرِسينَ، تُرسِلُ معي طائفةً مِن عسكَرِكم حتى أُدخِلَكم المدينةَ. فانتخب العبَّاسُ ألفَي فارسٍ أنجادٍ أبطالٍ، وسار إلى أن قارَبَها، وكمن هناك مستَتِرًا وسيَّرَ عَمَّه رباحًا في شُجَعانِهم، فساروا مستخفِينَ في الليل، فنَصَبوا السَّلاليمَ، وصَعِدوا الجبل، ثم وصَلوا إلى سور المدينةِ، قريبًا من الصُّبحِ، والحَرَسُ نيام، فدخلوا من نحوِ بابٍ صغيرٍ فيه، فدخل المُسلِمونَ كُلُّهم، فوَضَعوا السيفَ في الروم، وفَتَحوا الأبواب. وجاء العباسُ في باقي العسكَرِ، فدخلوا المدينةَ وصَلَّوا الصبحَ يومَ الخميس منتصَفَ شوال، وبنى فيها في الحالِ مَسجِدًا ونصَبَ فيه مِنبرًا وخطب فيه يومَ الجمعة، وقَتَل من وَجَد فيها من المُقاتِلة، وأخذوا ما فيها من بناتِ البَطارقةِ بحُليهِنَّ، وأبناء الملوك، وأصابوا فيها ما يَعجِزُ الوصفُ عنه، وذَلَّ الشِّركُ يومئذٍ بصَقَلِّيَّة ذلًّا عَظيمًا. ولَمَّا سمع الروم أرسَلَ مَلِكُهم بِطريقًا من القُسطنطينية في ثلاثِمائة شلندي وعسكَرٍ كثيرٍ، فوصلوا إلى سرقوسة، فخرج إليهم العبَّاسُ من المدينة، ولَقِيَ الرُّومَ وقاتَلَهم، فهَزَمهم، فرَكِبوا في مراكِبِهم هاربين، وغَنِمَ المُسلِمونَ منهم مائةَ شلندي، وكَثُرَ القتلُ فيهم، ولم يُصَبْ من المسلمينَ ذلك اليومَ غيرُ ثلاثةِ نَفَرٍ بالنشاب."},{"id":792,"title":"ملك الروم يطلب من الخليفة المتوكل المفاداة بين الأسرى .","date":["العام الهجري :245","الشهر القمري : صفر","العام الميلادي :859"],"text":"بعث مَلِكُ الرُّوم بأسرى من المسلمينَ، ويسألُ المُفاداة بمن عنده وكان الذي قَدِمَ من قِبَل صاحب الروم رسولًا إلى المتوكِّلِ شَيخًا يُدعى أطرو بيليس، معه سبعةٌ وسبعون رجلًا من أسرى المسلمين أهداهم ميخائيل بن توفيل ملك الروم إلى المتوكِّلِ، فأنزل على شنيف الخادم، ثم وجَّه المتوكِّلُ نصر بن الأزهر مع رسولِ صاحِبِ الروم، فشخص في هذه السنة ولم يقَع الفداءُ إلَّا في سنة ستٍّ وأربعين."},{"id":793,"title":"خروج النورماند (المجوس) في الأندلس .","date":["العام الهجري :245","الشهر القمري : ربيع الأول","العام الميلادي :859"],"text":"خرج المجوسُ (النورماند) إلى ساحِلِ البحر بالغرب، في اثني وستين مركبًا، فوجدوا البحر محروسًا، ومراكِبَ المُسلِمينَ مُعَدَّة، تجري من حائطِ إفرنجة إلى حائطِ جليقية في الغرب الأقصى، فتقدم مركبانِ مِن مراكبِ المجوسِ، فتلاقت بهم المراكِبُ المُعَدَّة، فوافَوا هذين المركبينِ في بعضِ كُسورِ باجة؛ فأخذوهما بما كان فيهما من الذهَبِ والفِضَّة والسَّبيِ والعُدَّة. ومَرَّت سائر مراكِبِ المجوس في الريفِ حتى انتهت إلى مصبِّ نهرِ إشبيلية في البحر، فأخرج الأميرُ الجيوش، ونفر النَّاسُ مِن كُلِّ أوبٍ، وكان قائدُهم عيسى بن الحسن الحاجب. وتقَدَّمت المراكِبُ مِن مَصَبِّ نهر إشبيلية حتى حلَّت بالجزيرة الخضراء، فتغلبوا عليها، وأحرقوا المسجِدَ الجامع بها، ثمَّ جازُوا إلى العدوة فاستباحوا أريافَها، ثم عادوا إلى ريفِ الأندلس، وتوافَوا بساحل تدمير، ثم انتهوا إلى حصنِ أوربولة، ثم تقَدَّموا إلى إفرنجة فشَتوا بها، وأصابوا بها الذراريَّ والأموالَ، وتغلَّبوا بها على مدينةٍ سكنوها، فهي منسوبةٌ إليهم إلى اليوم، حتى انصرفوا إلى ريفِ بحرِ الأندلس، وقد ذهب من مراكِبِهم أكثرُ مِن أربعين مركبًا، ولَقِيَهم مراكبُ الأمير محمد، فأصابوا منها مركبينِ بريف شذونة، فيها الأموالُ العظيمة. ومضت بقيَّةُ مراكِبِ المجوس."},{"id":794,"title":"الحرب بين البربر وابن الأغلب في أفريقيا .","date":["العام الهجري :245","الشهر القمري : جمادى الآخرة","العام الميلادي :859"],"text":"وقَعَت بين البربرِ وعسكَرِ أبي إبراهيم أحمدَ بنِ محمد بن الأغلب وقعةٌ عظيمةٌ، وسبَبُها أنَّ بربرَ لهان امتنعوا على عاملِ طرابلس من أداءِ عُشورِهم وصَدقاتِهم، وحاربوه فهَزَموه، فقصد لبدة فحَصَّنَها وسار إلى طرابلس، فسَيَّرَ إليه أحمد بن محمد الأمير جيشًا مع أخيه زيادةِ الله، فانهزم البربَرُ، وقُتل منهم خلقٌ كثيرٌ، وسيَّرَ زيادةُ الله الخيلَ في آثارهم، فقَتَلَ من أدرك منهم، وأسَرَ جماعةً، فضُرِبَت أعناقُهم، وأحرقَ ما كان في عسكَرِهم، فأذعن البربرُ بعدها وأعطوا الرَّهنَ، وأدَّوا طاعتَهم."},{"id":795,"title":"بناء مسجد القرويين الجامع بالمغرب .","date":["العام الهجري :245","الشهر القمري : رمضان","العام الميلادي :859"],"text":"يعتبر مَسجِدُ القُرَويِّينَ بفاس من أعرَقِ المساجد المغربيَّة وأقدَمِها. وتكادُ تُجمِعُ الدراسات التاريخية على أنَّ هذا المسجِدَ بَنَتْه فاطمةُ الفِهريَّة (أم البنين) في عهدِ دولة الأدارِسة، أمَّا بداية بناء مسجد القُرويين فشُرِعَ في حفر أساسِ مَسجِدِ القرويين والأخذِ في أمرِ بنائِه هذه السَّنة بمطالعةِ الإدريسي يحيى الأوَّل، وأمُّ البنين فاطمةُ الفِهريَّة هي التي تطَوَّعَت ببنائه وظَلَّت صائمةً مُحتَبِسةً إلى أن انتهت أعمالُ البناءِ وصَلَّت في المسجدِ شُكرًا لله، عِلمًا أنَّه وجد لوحةٌ مَنقوشةٌ عُثِرَ عليها- عند أعمال الترميم- في البلاط الأوسطِ، فوق قَوسِ المحراب القديم الذي كان للقُرَويين قبل قيام المُرابطين بتوسِعةِ المسجد، لقد اكتُشِفَت مدفونةً تحت الجبس، وقد كُتِبَ عليها- في جملة ما كتب- بخَطٍّ كوفيٍّ إفريقيٍّ عَتيقٍ: بُني هذا المسجِدُ في شَهرِ ذي القعدة مِن سنة ثلاث وستين ومائتين، ممَّا أمر به الإمام- أعزَّه الله- داودُ بنُ إدريس، أبقاه الله... ونصره نصرًا عزيزًا."},{"id":796,"title":"فتح المسلمين حِصنَ أنطاكية وتبادل الأسرى مع الروم .","date":["العام الهجري :246","العام الميلادي :860"],"text":"غزا عمرُو بنُ عبد الله الأقطَع الصائفةَ، فأخرج سبعةَ عشرَ ألف رأس، وغزا قريباس، وأخرج خمسةَ آلافِ رأس، وغزا الفضلُ بن قارن بحرًا في عشرينَ مركبًا، فافتتح حِصنَ أنطاكية، وغزا بلكاجور، فغَنِمَ وسَبَى، وغزا عليُّ بن يحيى الأرمني، فأخرج خمسةَ آلافِ رأس، ومن الدوابِّ والرمك والحمير، ونحوًا من عشرةِ آلاف رأس، وفيها كان الفداءُ على يدِ عليِّ بنِ يحيى الأرمني، ففُودِيَ بألفين وثلاثمائة وسبعة وستين نفسًا."},{"id":797,"title":"بداية قيام دولة الزيديين في صعدة وصنعاء باليمن .","date":["العام الهجري :246","العام الميلادي :860"],"text":"تزعَّمَ بنو الرسي بصَعدة وصنعاء، وقام الحسَنُ بن قاسم الرسي بتأسيسِ دولَتِهم، وهم من الأئمَّة الزيديِّين، والقاسم الرسي هو القاسِمُ بن إبراهيم المعروف بطباطبا بن إسماعيلَ بنِ الحسن بن الحسن بن علي بن أبي طالب، وكان بُويِعَ بالإمامةِ بعد موت أخيه محمَّد، وبقي متخَفِّيًا مدةً هاربًا من بلد لآخرَ، حتى استقَرَّ بأرمينية في الرسِّ، وفيها مات فعُرِفَ بالرسِّي."},{"id":798,"title":"غزو العباس بن الفضل بلاد الروم .","date":["العام الهجري :246","العام الميلادي :860"],"text":"نكث العهدَ كثيرٌ مِن قِلاعِ صَقَلية وهي: وسطر، وابلا وابلاطنوا وقلعة عبد المؤمن، وقلعة البلوط، وقلعة أبي ثور، وغيرها من القلاع، فخرج العباسُ بنُ الفضل إليهم، فلَقِيَهم عساكِرُ الروم، فاقتتلوا فانهزم الرومُ، وقُتل منهم كثير. وسار إلى قلعةِ عبد المؤمن وقلعة ابلاطنوا فحصرها، فأتاه الخبر بأنَّ كثيرًا من عساكر الرُّومِ قد وصلت، فرحل إليهم، فالتقوا بجفلودى، وجرى بينهم قتالٌ شديد، فانهزمت الروم، وعادوا إلى سرقوسة، وعاد العباسُ إلى المدينة، وعَمَر قصريانة، وحصَّنَها وشَحَنها بالعساكر. وفي سنة سبع وأربعين ومائتين سار العبَّاسُ إلى سرقوسة، فغَنِم، وسار إلى غيران قرقنة، فاعتَلَّ ذلك اليوم، ومات بعد ثلاثة أيام، ثالثَ جمادى الآخرة، فدُفِنَ هناك فنَبَشَه الروم، وأحرقوه، وكانت ولايتُه إحدى عشرة سنة، وأدام الجهادَ شِتاءً وصَيفًا، وغزا أرضَ قلورية وانكبردة وأسكَنَها المسلمين."},{"id":799,"title":"أميرُ الأندلس محمَّد بن عبد الرحمن يغزو أرض بنبلونة .","date":["العام الهجري :246","العام الميلادي :860"],"text":"أغزى الأميرُ محمَّد بن عبد الرحمن إلى أرضِ بنبلونة أحدَ قوَّاده، فخرج في هذه الغزوة خروجًا لم يُخرَجْ قَبلَه مِثله جَمعًا وكثرةً، وكمالَ عِدَّة، وظهورَ هيبةٍ. وكان ابنُ غرسية صاحِبُ بنبلونة إذ ذاك متظافِرًا مع أزدون صاحب جليقية، فأقام هذا القائِدُ يدوِّخُ أرضَ بنبلوبة، متردِّدًا فيها اثنين وثلاثين يومًا، يخرِّبُ المنازل، وينسِفُ الثمار، ويفتح القُرى والحصون. وافتتح في الجملة حِصنَ قشتيل، وأخذَ فيه فرتون بن غرسية المعروف بالأنفر، وقَدِمَ به إلى قرطبة، فأقام بها محبوسًا نحوًا من عشرين سنة، ثم رَدَّه الأميرُ إلى بلده، وعُمرُ فرتون مائة وست وعشرون سنة."},{"id":800,"title":"اغتيال الخليفة العباسي المتوكل وتولي ابنه المنتصر الخلافة .","date":["العام الهجري :247","الشهر القمري : شوال","العام الميلادي :862"],"text":"كان مَقتلُ الخليفةِ المتوكِّلِ على الله على يَدِ وَلَدِه المنتَصِر، وكان سببُ ذلك أن المتوكِّلَ أمَرَ ابنَه عبدَ الله المعتَزَّ أن يخطُبَ بالناسِ في يومِ جمعة، فأدَّاها أداءً عظيمًا بليغًا، فبلغ ذلك من المنتَصِر كلَّ مبلغٍ، وحَنقَ على أبيه وأخيه، وزاد ذلك أنَّ المتوكِّلَ أراد من المنتَصِر أن يتنازلَ عن ولايةِ العهد لأخيه المعتَزِّ فرفض، وزاد ذلك أيضًا أنَّه أحضَرَه أبوه وأهانَه وأمَرَ بضَربِه في رأسِه وصَفْعِه، وصَرَّحَ بعَزلِه عن ولايةِ العَهدِ، فاشتَدَّ أيضًا حَنقُه أكثَرَ ممَّا كان، فلمَّا كان يومُ عيدِ الفِطرِ خطَبَ المتوكِّلُ بالنَّاسِ وعنده بعضُ ضَعفٍ مِن عِلَّةٍ به، ثم عدَلَ إلى خيامٍ قد ضُرِبَت له أربعةُ أميالٍ في مثلِها، فنزل هناك ثم استدعى في يومِ ثالثِ شَوَّال بنُدَمائِه على عادتِه في سَمَرِه، ثمَّ تمالأ ولَدُه المنتصِرُ وجماعةٌ مِن الأمراءِ على الفَتكِ به فدخلوا عليه ليلةَ الأربعاءِ لأربعٍ خَلَونَ مِن شَوَّال، وهو على السِّماطِ، فابتدروه بالسُّيوفِ فقَتَلوه، وكانت مدةُ خلافتِه أربعَ عشرةَ سَنةً وعَشرةَ أشهر وثلاثة أيام، ثم ولَّوا بعده ولَدَه المنتَصِر، وبعث إلى أخيه المعتَزِّ فأحضَرَه إليه فبايعه المعتَزُّ، وقد كان المعتَزُّ هو وليَّ العَهدِ مِن بعدِ أبيه، ولكِنَّه أكرَهَه، وخاف فسَلَّمَ وبايعَ، ومِن المعروفِ أنَّ الأتراكَ الذين كان قد قَرَّبَهم الواثقُ وجعَلَهم قوَّادَه الأساسيِّينَ قد حَقَدوا على المتوكِّلِ، فكان ذلك من أسبابِ تَمالُئِهم على قَتلِه، وباغتيالِ المتوكِّلِ يعتبَرُ العصرُ العباسيُّ الأوَّلُ قد انتهى، وهو عصرُ القُوَّة، وبدأ العصرُ الثاني- عصرُ الضَّعفِ والانحدارِ- بالمنتصرِ؛ وذلك لأنَّ الخِلافةَ أصبحت صورةً ظاهريَّةً، والحُكمُ الحقيقيُّ هو للقُوَّاد العسكريِّين."},{"id":801,"title":"وفاة الخليفة العباسي المتوكل على الله .","date":["العام الهجري :247","الشهر القمري : شوال","العام الميلادي :862"],"text":"هو أميرُ المؤمنينَ أبو الفضلِ بنِ المعتَصِم بالله محمَّد بن هارون الرَّشيد القُرَشي العبَّاسي البغدادي. ولِدَ سنةَ خَمسٍ ومائتين، وبويعَ في ذي الحِجَّة سنةَ اثنتينِ وثلاثين بعد الواثقِ, وتلقَّبَ بالمتوكِّل على الله. وكان أسمَرَ مليحَ العينينِ، نحيفَ الجِسمِ خفيفَ العارِضَينِ، إلى القِصَرِ أقرَب. وأمُّه أمُّ ولد اسمُها: شجاع. قال خليفة: \"استُخلِفَ المتوكِّلُ، فأظهرَ السُّنَّةَ وعَمِلَ بها في مجلِسِه، وكتبَ إلى الآفاقِ برَفعِ المحنةِ؛ خلْق القرآنِ، وإظهارِ السُّنَّة وبَسْطِها ونصرِ أهلِها\"، كان إبراهيمُ بن محمد التيمي قاضي البصرة يقول: الخلفاءُ ثلاثة: \"أبو بكرٍ الصِّديقُ يومَ الرِّدَّة، وعمرُ بنُ عبد العزيز في رَدِّ مظالمِ بني أميَّة، والمتوكِّلُ في محوِ البِدَع وإظهارِ السُّنَّة\". وقد قِدَمَ المتوكِّلُ دمشقَ في صفر سنة أربع وأربعين، وعزم على المُقام بها وأعجَبَته، ونقل دواوينَ المُلك إليها. وأمرَ بالبناء بها. وأمر للأتراكِ بما أرضاهم من الأموالِ، وبنى قصرًا كبيرًا بداريَّا من جهة المزَّة، لكنَّه عاد إلى سامرَّا, وقد قتله ابنُه المنتصِرُ بعد أن تآمرَ مع الأتراكِ على قَتلِه."},{"id":802,"title":"خلع المعتَز والمؤيَّد أبناء المتوكِّل من ولاية العهد .","date":["العام الهجري :248","الشهر القمري : محرم","العام الميلادي :862"],"text":"خُلِعَ المعتَزُّ والمؤيَّدُ ابنا المتوكِّل من ولاية العهد؛ وكان سببُ خَلعِهما أنَّ المنتصرَ لَمَّا استقامت له الأمور، قال أحمد بن الخصيب لوصيف بغا: إنَّا لا نأمَنُ الحَدَثانَ وأن يموتَ أميرُ المؤمنين، فيلي المعتزُّ الخلافةَ، فيُبيدُ خَضراءَنا ولا يُبقي منا باقيةً؛ والآنَ الرأيُ أن نعمل في خلعِ المعتَزِّ والمؤيَّد، فجدَّ الأتراك في ذلك، وألحُّوا على المنتصر، وقالوا نخلَعُهما من الخلافة، ونبايِعُ لابنك عبد الوهاب؛ فلم يزالوا به حتى أجابَهم، وأُحضر المعتَزُّ والمؤيَّدُ بعد أربعين يومًا من خلافةِ المنتصِر، وجُعِلا في دارٍ وأُبقِيا وأُكرِها على خَلعِ أنفُسِهما، وكتبا بذلك كتابًا، قال فيه المعتزُّ: «إنَّ أبي عقدَ البيعةَ لي بعد أخي، وكنتُ صغيرَ السِّنِّ، والآن فحيثُ تبيَّنتُ رُشدي وعَقَلتُ، علمتُ أنى لا أصلُحُ لهذا الأمرِ ولا أقومُ به، واشهدوا عليَّ أنَّني قد خلعتُ نفسي عمَّا كان رشَّحَني له أبى» وأُلزِمَ المؤيَّدُ بمثل ذلك، وأُمِرَ بالكتابِ أن يُنشَرَ في الآفاقِ ليُعلَمَ بأمرِه."},{"id":803,"title":"وفاة  الخليفة العباسي المنتصر بالله .","date":["العام الهجري :248","الشهر القمري : ربيع الأول","العام الميلادي :862"],"text":"هو أبو جعفر \"المنتصر بالله\" محمد بن جعفر المتوكِّل، وأمُّه أمُّ ولدٍ روميَّةٌ اسمُها حبشية. وكان أعينَ أسمَرَ أقنى, مليحَ الوجهِ, رَبْعةً, كبيرَ البطن, مَهيبًا، لَمَّا قُتِل أبوه دخل عليه التُّركُ ومعهم قاضي القضاة جعفر بن عبد الواحد الهاشمي، فقال له: بايِعْ. قال: وأين أمير المؤمنين؟ -يعني: المتوكِّل- قال: قتله الفتحُ بن خاقان. قال: وأين الفتح? قال: قتله بغا, فبايعه القاضي ثم الوزير وكبار قادة الترك, ثم تحوَّل من الجعفري إلى سامراء، وولَّى وزارتَه أحمد بن الخصيب, وأراد المعتزُّ أن يمتنِعَ من البيعة للمنتصر، فقال له بغا الشرابي: أخوك محمَّد أقدمَ على قتلِ أبيك، وأخافُ أن يقتُلَك فبايِعْ، فبايَعَه. ثم صالحَ المنتصِرُ إخوتَه عن ميراثهم على أربعةَ عشر ألفَ ألفِ درهم، ونفى عمَّه عليًّا إلى بغداد، ورسم عليه, وكان المنتصِرُ وافر العقل, راغبًا في الخير, قليلَ الظُّلم. على الرَّغمِ مِن أنَّ المنتصِرَ كان قد تمالأ مع الأتراكِ على قتل أبيه المتوكِّل عندما قرَّرَ أن يعزِلَه من ولاية العهد ويولِّيَها أخاه المعتَزَّ، إلَّا أن المنتصرَ  كان يقول: يا بغا أين أبي? من قتَلَ أبي?! ويسُبُّ الأتراك، ويقول: هؤلاء قتَلَة الخلفاء، فقال بغا الصغيرُ للذين قتَلوا المتوكِّل: ما لكم عند هذا رِزقٌ، فعَمدوا عليه وهَمُّوا، فعَجَزوا عنه؛ لأنَّه كان شجاعًا مَهيبًا يَقِظًا متحرِّزًا، فتحَيَّلوا عليه إلى أن دسُّوا إلى طبيبِه ابن طيفور ثلاثين ألف دينار عند مَرَضِه، فأشار بفَصدِه, ثمَّ فصَدَه بريشةٍ مَسمومةٍ، فمات منها,  وكانت مُدَّةُ خلافته ستةَ أشهُر، ثم تولَّى الخلافةَ بعده أبو العباس \"المستعين بالله\" أحمد بن محمد المعتصِم."},{"id":804,"title":"تولي المستعين بالله بن المعتصم الخلافة العباسية .","date":["العام الهجري :248","الشهر القمري : ربيع الأول","العام الميلادي :862"],"text":"بُويعَ أحمد بن محمد بن المعتَصِم بالخلافة؛ وكان سببَ ذلك أنَّ المنتصِرَ لَمَّا توفِّي اجتمع الموالي على الهارونيَّة من الغد، وفيها بغا الكبيرُ، وبغا الصغير، وأتامش، وغيرهم، فاستحلفوا قوَّاد الأتراك، والمغاربة، والشروسنية على أنْ يرضَوا بمن رضِيَ به بغا الكبير، وبغا الصغير، وأتامش، وذلك بتدبيرِ أحمد بن الخصيب، فحَلَفوا وتشاوروا وكَرِهوا أن يتولَّى الخلافةَ أحد من ولد المتوكِّل؛ لئلَّا يغتالَهم، واجتمعوا على أحمدَ بن محمد بن المعتصم، وقالوا: لا تَخرجُ الخلافةُ مِن ولد مولانا المعتَصِم، فبايعوه وهو ابنُ ثمانٍ وعشرين سنة، ولقَّبوه بالمستعين بالله، وتكنى بأبي العباس، فاستكتب أحمدَ بن الخصيب، واستوزر أتامش."},{"id":805,"title":"تولي خفاجة بن سفيان إمارة صقلية  .","date":["العام الهجري :248","الشهر القمري : جمادى الأولى","العام الميلادي :862"],"text":"بعد وفاة أمير صقليَّة العباسِ بن الفضل، ولَّى الناسُ عليهم ابنَه عبد الله بن العباس، وكتبوا إلى أميرٍ بإفريقيَّة بذلك، وأخرج عبد الله السرايا ففتحَ قِلاعًا متعَدِّدة منها: جبل أبي مالك، وقلعة الأرمنين، وقلعة المشارعة، فبقي كذلك خمسة أشهر، ووصل من إفريقية خفاجة بن سفيان أميرًا على صقليَّة، فأوَّلُ سريَّةٍ أخرجها سريَّةٌ فيها ولدُه محمود، فقصَدَ سرقوسة فغَنِم،  فخرج إليه أهلُها فقاتلهم حتى ظَفِرَ بهم. وعاد فاستأمن إليه أهل رغوس."},{"id":806,"title":"وفاة بغا الكبير أبو موسى التركي .","date":["العام الهجري :248","الشهر القمري : جمادى الآخرة","العام الميلادي :862"],"text":"هو بغا الكبير أبو موسى التركي، مُقَدَّمُ قُوَّادِ المتوكِّل وأكبَرُهم، كان شجاعًا مِقدامًا وله همَّةٌ عالية وهيبة، ووقْعٌ في النُّفوسِ، وكان مملوكًا للحسن بن سهل الوزير، وكان يُحمَّق ويجهَّل في رأيه، أسهم في اغتيالِ الخليفة المتوكِّل، ثم سيطر على الخليفة المستعين الذي لم يكُنْ له من الأمر شيءٌ غير الاسم، فغَلَب على المستعين هو ووصيفُ الأمير، حتى قيل: خليفةٌ في قفصٍ بين وصيف وبغا ** يقول ما قالا له كما يقولُ البَبَّغا. له عِدَّةُ فتوحات ووقائع، باشر الكثيرَ من الحروب فما جُرِح قط، وخلَّف أموالًا عظيمة، وكان بغا دَيِّنًا من بين الأتراك، وكان من غِلمانِ المعتصم، يشهد الحروبَ العظام، ويباشِرُها بنفسه، فيخرجُ منها سالِمًا، ويقول: الأجَلُ جوشن، مرض بغا الكبير في جمادى الآخرة فعاده المستعينُ في النصف منها، ومات بغا من يومِه عن سن ستين سنة، فعقد المستعين لموسى بن بغا على أعمالِه وعلى أعمالِ أبيه كلِّها، وولي ديوانَ البريد."},{"id":807,"title":"وفاة أمير خراسان طاهر بن عبدالله .","date":["العام الهجري :248","الشهر القمري : رجب","العام الميلادي :862"],"text":"توفِّيَ طاهِرُ بن عبدالله بن طاهر بن الحُسين الخزاعي، أميرُ خراسان وابنُ أميرها, وكان قد ولِيَ إمرة خراسان بعد أبيه ثماني عشرة سنة, فلما ورد على المستعين وفاةُ طاهر بن عبدالله، عقدَ لابنه محمَّد بن طاهر على خراسان، ولمحمد بن عبدالله بن طاهرٍ على العراق، وجعل إليه الحَرَمين، والشُّرطة"},{"id":808,"title":"غزو عبد الملك بن العباس نصارى شمال الأندلس .","date":["العام الهجري :249","العام الميلادي :863"],"text":"خرج عبد الرحمن بن الأمير محمَّد إلى حصون ألبة والقلاع؛ وكان القائِدُ عبد الملك بن العباس؛ فافتتَحها، وقتَل الرجال، وهدَمَ البُنيان؛ وانتقل في بسائطِها من موضع إلى موضع يحطِمُ الزروع، ويقطَعُ الثمار. وأخرج أردون بن إذفونش أخاه إلى مضيق الفجِّ ليقطع بالمُسلمين، ويتعرَّضَهم فيه؛ فتقَدَّم عبد الملك فقاتَلَهم على المَضِيقِ، حتى هزمهم وقتَلَهم وبدَّدَهم؛ ثم وافَتْهم بقيَّة العساكر، وأظلَّتهم الخيلُ من كل الجهات؛ فصبر أعداءُ الله صبرًا عظيما؛ ثم انهزموا. ومنح الله المسلمينَ أكتافَهم، فقُتِلوا قتلًا ذريعًا، وقُتِل لهم تسعة عشر قومسًا من كبار قوَّادهم."},{"id":809,"title":"شغب العامة ببغداد وسامرا بسبب تسلط الأتراك .","date":["العام الهجري :249","الشهر القمري : صفر","العام الميلادي :863"],"text":"كان سبَب ذلك أنَّه لَمَّا وصل خبَرُ مقتل عمر بن عبيد الله، وعلي بن يحيى، أثناءَ غَزوِهما للروم للشاكريَّة والجند ببغداد وسامرَّا وما قرب منهما، وكانا من شجعان الإسلام، شَقَّ ذلك عليهم، وما لَحِقَهم من استعظامِهم قتلَ الأتراك للمتوكِّل، واستيلائِهم على أمور المسلمين، يقتلون من يريدون من الخُلَفاء، ويستخلفون من أحبُّوا من غير ديانةٍ، ولا نظَرٍ للمُسلمين، فاجتمعت العامَّة ببغداد وأخذوا في الصُّراخ، والنداء بالنفير، وانضَمَّ إليها الأبناء، والشاكرية تُظهِرُ أنَّها تطلب الأرزاق، ففَتَحوا السجون، وأخرجوا من فيها وأحرَقوا أحدَ الجسرين وقَطَعوا الآخَرَ، وانتهبوا دار بِشرٍ وإبراهيم ابنَي هارون، كاتبي محمد بن عبد الله، ثم أخرجَ أهلُ اليَسارِ من بغداد وسامرَّا أموالًا كثيرةً، ففَرَّقوها فيمن نهضَ إلى الثغور، وأقبلت العامَّةُ من نواحي الجبال وفارس والأهواز وغيرِها لغزو الروم، فلم يأمُر الخليفة في ذلك بشيءٍ ولم يوجِّهْ عسكرَه، ووثب نفرٌ من الناس لا يُدرى من هم بسامرَّا ففتحوا السجنَ، وأخرجوا من فيه، فبعث المستعينُ بالله في طَلَبِهم جماعةً من الموالي، فوثب العامَّةُ بهم فهزموهم، فركب بغا وأتامش ووصيفٌ وعامَّة الأتراك، فقَتَلوا من العامَّةِ جماعةً، فرُمِيَ وصيف بحجر، فأمَرَ بإحراق ذلك المكان، وانتهبت المغاربة، ثم سكَنَ ذلك آخرَ النهار."},{"id":810,"title":"عمر بن عبيد الله الأقطع يغزو بلاد الروم .","date":["العام الهجري :249","الشهر القمري : رجب","العام الميلادي :863"],"text":"غزا جعفر بن دينار الصائفةَ، فافتتح حصنا ومطأمير، واستأذنه عمر بن عبيد الله الأقطع في المسيرِ إلى بلاد الروم، فأذن له، فسار في خلقٍ كثير من أهل ملطيَّة، فلقيه الملِكُ في جمع عظيم من الروم بمرج الأسقف، فحاربَه محاربةً شديدةً قُتِلَ فيها من الفريقينِ خَلقٌ كثير، ثم أحاطت به الروم، وهم خمسون ألفًا، وقتل عمر وممَّن معه ألفان من المسلمين، فلما قُتِلَ عمر بن عبيد الله خرج الرومُ إلى الثغور الجزرية، وكلبوا عليها وعلى أموالِ المسلمين وحَرَمِهم، فبلغ ذلك علي بن يحيى وهو قافِلٌ من أرمينية إلى ميافارقين في جماعةٍ من أهلها ومن أهل السلسلة، فنفَرَ إليهم، فقُتِلَ في نحوٍ من أربعمائة رجلٍ"},{"id":811,"title":"ظهور يحيى بن عمر الطالبي بالعراق .","date":["العام الهجري :250","العام الميلادي :864"],"text":"كان ظهور أبي الحسين يحيى بن عمر بن يحيى بن حسين بن زيد بن علي بن الحسين بن علي بن أبي طالب، أنَّه أصابته فاقةٌ شديدةٌ فدخل سامرَّا فسأل وصيفًا أن يجري عليه رزقًا فأغلظ له القولَ، فرجع إلى أرض الكوفة فاجتمع عليه خلقٌ من الأعراب، وخرج إليه خلقٌ من أهل الكوفة، فنزل على الفلوجة، وقد كثُرَ الجمع معه، فكتب محمد بن عبد الله بن طاهر نائبُ العراق إلى عامِلِه يأمُرُه بقتالِه، وظهر أمرُه بالكوفة واستحكم بها، والتفَّ عليه خلقٌ من الزيدية وغيرِهم، ثم خرج من الكوفة إلى سوادِها ثم كرَّ راجِعًا إليها، فتلقاه عبد الرحمن بن الخطاب الملقَّب وجه الفلس، فقاتله قتالًا شديدًا، فانهزم وجه الفلس، ودخل يحيى بن عمر الكوفةَ ودعا إلى الرضى من آل محمد، وقوي أمرُه جدًّا، وصار إليه جماعةٌ كثيرة من أهل الكوفة، وتولَّاه أهل بغداد من العامَّة وغيرِهم ممَّن يُنسَبُ إلى التشيُّع، وأحبوه أكثَرَ من كل من خرج قبله من أهل البيتِ، وشرع في تحصيلِ السلاحِ وإعداد آلاتِ الحرب وجَمْعِ الرجال، وقد هرب الحسينُ بن إسماعيل نائبُ الكوفة منها إلى ظاهِرِها، واجتمع إليه أمدادٌ كثيرة من جهة الخليفة مع محمد بنِ عبد الله بن طاهر، واستراحوا وجمَعوا خيولَهم، فلما كان اليومُ الثاني عشر من رجب، أشار من أشار على يحيى بن عمر ممَّن لا رأي له، أن يركَبَ ويناجز الحُسين بن إسماعيل ويكبِسَ جيشه، فركب في جيشٍ كثير من خلقٍ من الفرسان والمشاة أيضًا من عامَّة أهل الكوفة بغير أسلحةٍ، فساروا إليهم فاقتتلوا قتالًا شديدًا في ظلمة آخر الليل، فما طلع الفجرُ إلَّا وقد انكشف أصحابُ يحيى بن عمر، وقد تقنطَرَ به فرسه، ثم طُعِنَ في ظهرِه فخَرَّ، فأخذوه وحزُّوا رأسَه وحملوه إلى الأمير الحسين بن إسماعيل فبعَثَه إلى ابن طاهر، فأرسله إلى الخليفة من الغدِ مع رجل يقال له عمر بن الخطاب، أخي عبد الرحمن بن الخطاب، فنُصِبَ بسامرَّا ساعة من النهار ثم بُعِثَ به إلى بغداد فنُصِبَ عند الجسر، ولم يمكِنْ نصبُه من كثرة العامَّة فجُعِلَ في خزائن السلاح، وكان الخليفة قد وجَّه أميرًا إلى الحسين بن إسماعيل نائب الكوفة، فلما قُتِلَ يحيى بن عمر دخلوا الكوفة فأراد ذلك الأميرُ أن يضع في أهلِها السيفَ، فمنعه الحسين وأمَّنَ الأسودَ والأبيض، وأطفأ اللهُ هذه الفتنة."},{"id":812,"title":"وفاة زيادة الله الثاني بن محمد بن الأغلب أمير أفريقية .","date":["العام الهجري :250","العام الميلادي :864"],"text":"هو أبو محمد زيادةُ الله بن محمد بن الأغلب بن إبراهيم بن الأغلب ولِيَ أفريقيَّة يوم وفاة أخيه أحمد أبو إبراهيم، في ذي القعدة، سنة 249هـ, وكان زيادة الله عاقلًا حليمًا حسَن السيرةِ جميلَ الأفعال، ذا رأيٍ ونجدة وجُودٍ وشجاعةٍ. وهو الثاني ممن اسمه زيادة الله في بني الأغلب، وهو ثامن أمراء الأغالبة بأفريقية، واستمَرَّت إمارته سنة وأيامًا، ثم تولى من بعده ابن أخيه محمد الثاني المعروف بأبي الغرانيق."},{"id":813,"title":"ثورة أهل حمص على عاملهم الفضل بن قارن .","date":["العام الهجري :250","العام الميلادي :864"],"text":"وثب أهلُ حمص وقومٌ من كلب، بعامِلِهم، وهو الفضل بن قارن أخو مازيار بن قارن، فقَتَلوه، فوجَّه المستعين إلى حمص موسى بن بغا الكبير، فلَقِيَه أهلُها فيما بين حمص والرستن، وحاربوه، فهَزَمهم، وافتتح حمص، وقتلَ من أهلها مقتلةً عظيمة، وأحرَقَها وأسر جماعةً من أعيان أهلِها."},{"id":814,"title":"ظهور الحسن بن زيد العلوي بطبرستان .","date":["العام الهجري :250","الشهر القمري : رمضان","العام الميلادي :864"],"text":"خرج الحسَنُ بن زيد بن محمد بن إسماعيل بن الحسَن بن زيد بن الحسن بن علي بن أبي طالب بناحية طبرستان، وكان سبب خُروجِه أنَّه لَمَّا قُتِلَ يحيى بن عمر أقطع المستعينُ لمحمد بن عبد الله بن طاهر طائفةً مِن أرض تلك الناحية، فبعث كاتبًا له يقال له جابر بن هارون، وكان نصرانيًّا، ليتسَلَّم تلك الأراضي، فلما انتهى إليهم كرهوا ذلك جدًّا، وأرسلوا إلى الحسن بن زيد هذا، فجاء إليهم فبايعوه والتَفَّ عليه جملةُ الديلم وجماعةٌ من الأمراء في تلك النواحي فركِبَ فيهم ودخل آمل بطبرستان وأخذها قهرًا، وجبى خراجَها، واستفحل أمرُه جِدًّا، ثم خرج منها طالبًا لقتال سليمان بن عبد الله أمير تلك الناحية، فالتقيا هنالك فكانت بينهما حروبٌ، ثم انهزم سليمان هزيمةً مُنكرة، وترك أهلَه وماله ولم يرجِعْ دون جرجان فدخل الحسنُ بن زيد سارية إحدى مدن طبرستان، فأخذ ما فيها من الأموالِ والحواصل، ثم سيَّرَ أهل سليمان إليه مكَرَّمين على مراكب، واجتمع للحسن بن زيدٍ إمرة طبرستان بكمالِها، ثم بعَثَ إلى الري فأخذها وأخرجَ منها الطاهرية، وصار إلى جند همذان، ولَمَّا بلغ خبَرُه المستعينَ بالله، اغتمَّ لذلك جدًّا، واجتهد في بعض الجيوش والأمداد لقتالِ الحسن بن زيد."},{"id":815,"title":"فتنة إسماعيل بن يوسف الطالبي (السفاك) بمكة .","date":["العام الهجري :251","العام الميلادي :865"],"text":"ظهر إسماعيل بن يوسف بن إبراهيم بن موسى بن عبد الله بن الحسن بن الحسن بن علي بن أبي طالب بمكَّة، فهرب منه نائبُها جعفر بن الفضل بن عيسى بن موسى، فانتَهَبَ مَنزِلَه ومنازلَ أصحابه وقَتَلَ جماعةً من الجند وغيرهم من أهل مكة، وأخَذَ ما في الكعبة من الذَّهَب والفِضَّة والطِّيب وكسوة الكعبة، وأخَذَ من الناس نحوًا من مائتي ألف دينار، ثم خرج إلى المدينةِ النبويَّة فهرب منها نائبُها أيضًا علي بن الحسين بن علي بن إسماعيل، ثم رجع إسماعيل بن يوسف إلى مكَّةَ في رجب فحصر أهلَها حتى هلكوا جوعًا وعَطشًا، فبِيعَ الخُبزُ ثلاثُ أواقٍ بدِرهم، واللَّحمُ الرِّطل بأربعة، وشربة الماء بثلاثة دراهم، ولقي منه أهلُ مكَّة كلَّ بلاء، فترحَّلَ عنهم إلى جُدَّة بعد مُقامِه عليهم سبعة وخمسين يومًا، فانتهب أموال التجَّار هنالك وأخذ المراكِبَ وقطع الميرة عن أهلِ مكَّة، ثم عاد إلى مكَّة لا جزاه الله خيرًا عن المسلمين. فلما كان يومُ عرفة لم يمكِّن النَّاسَ من الوقوف نهارًا ولا ليلًا، وقتَلَ من الحجيج ألفًا ومائة، وسلَبَهم أموالَهم، ولم يقف بعرفةَ عامَئذٍ سواه ومن معه من الحرامية، ثم توفِّي في السنة التالية."},{"id":816,"title":"غزوة عبد الرحمن بن محمد ألبة والقلاع وهزيمة المركويز .","date":["العام الهجري :251","العام الميلادي :865"],"text":"خرج إلى هذه الغزاةِ عبد الرحمن بن محمَّد، وتقدَّمَ حتى حلَّ على نهرِ دوبر وتوالت عليه العساكرُ من كل ناحية، فرتَّبَها ثم تقَدَّم، فاحتل بفج برذنش، وكانت عليه أربعة حصون، فتغلب العسكرُ عليها، وغنم المسلمون جميعَ ما فيها وخربوها، ثم انتقل من موضعٍ إلى موضع، لا يمُرُّ بمسكنٍ إلَّا خرَّبه، ولا موضِعٍ إلا حَرَقه، حتى اتصلَ ذلك في جميع بلادهم، ولم يبقَ لرذريق صاحب القلاع، ولا أردمير صاحب توفة، ولا لعندشلب صاحب برجية، ولا لغومس صاحب مسانقة، حِصنٌ من حصونهِم إلا وعَمَّه الخراب. ثم قصدَ الملاحة، وكانت من أجلِّ أعمال رذريق؛ فحطَّمَ ما حواليها وعفا آثارَها، ثم تقدَّمَ يوم الخروج على فج المركويز؛ فصَدَّ العسكر عنه، وتقدَّم رذريق بحشوده وعسكرِه، فحلَّ على الخندق المجاور للمركويز، وكان رذريق قد عانى توعيرَه أعوامًا، فسخَّرَ فيه أهل مملكتِه، وقطعه من جانب الهضبةِ، فارتفع جرفه، وانقطع مسلكُه، فنزل عبدالرحمن ابن الأمير محمد على وادي إبره بالعسكرِ، وعبَّأ عبد الملك للقتال؛ وعبأ المشركون، وجعلوا الكمائنَ على ميمنة الدرب وميسرته، وناهض المسلمون جموعَ المشركين بصدورهم؛ فوقع بينهم جِلادٌ شديد، وصدق المسلمون اللِّقاء، فانكشف الأعداءُ عن الخندق، وانحازوا إلى هضبةٍ كانت تليه، ثم نزل عبد الرحمن ابن الأمير محمد، ونصب فسطاطَه، وأمر الناس بالنزولِ، وضرب أبنيتهم، ثمَّ نهض المسلمون إليهم فصَدَقوهم القتال، وضرب اللهُ في وجوه المشركين ومنَحَ المسلمين أكتافَهم، فقتلوا أشَدَّ القتل، وأُسِرَ منهم جموعٌ، واستمرُّوا في الهزيمة إلى ناحية الأهزون، واقتحَموا نهر إبره باضطرارٍ في غير مخاضة، فمات منهم خلقٌ كثير غرقًا، وكان القتل والأسر فيهم من ضحى يوم الخميس لاثنتي عشرة ليلة خلت من رجبٍ إلى وقت الظهر، وسلَّمَ الله المسلمين ونصَرَهم على المشركين، وكان قد لجأ منهم إلى الوعر والغياض- عندما أخذتهم السيوفُ- جموعٌ، فتُتُبِّعوا وقُتلوا، ثم هُتِك الخندقُ وسُوِّيَ حتى سَهُل، وسلَكَه المُسلِمونَ غيرَ خائفين ولا مضغطين، وأعظم الله المنة للمسلمين بالصنعِ الجميل، والفتح الجليل، والحمد لله رب العالمين. وكان مبلغُ ما حيز من رؤوس الأعداء في تلك الوقيعة عشرينَ ألف رأس وأربعمائة رأس واثنين وسبعين رأسًا."},{"id":817,"title":"خروج الحسين بن أحمد الكوكبي الطالبي .","date":["العام الهجري :251","العام الميلادي :865"],"text":"خرج الحسين بن أحمد بن محمد بن إسماعيل بن محمد بن الأرقط عبدالله بن زين العابدين علي بن الحسين الكوكبي الطالبي بقزوين، فالتقى موسى بن بغا الكبير هو والحسين بن أحمد الكوكبي على فرسخٍ من قزوين، فاقتتلا قتالًا شديدًا، ولَمَّا التَقَوا صَفَّ أصحاب الكوكبي صفوفًا وأقاموا ترسَتَهم في وجوهِهم يتَّقون بذلك سهامَ أصحاب موسى، فلما رأى موسى أن سهامَ أصحابِه لا تصِلُ إليهم مع ما قد فعلوا، أمَرَ بما معه من النِّفطِ أن يُصَبَّ في الأرض التي التقى هو وهم فيها، ثمَّ أمَرَ أصحابَه بالاستطرادِ لهم وإظهارِ هزيمةٍ منهم، فلما فعل أصحابُه ذلك ظنَّ الكوكبي وأصحابُه أنَّهم انهزموا، فتبعوهم فلمَّا علم موسى أنَّ أصحاب الكوكبي قد توسَّطوا النِّفطَ أمرَ بالنار فأُشعِلَت فيه، فأخذت فيه النارُ وخرجت من تحت أصحابِ الكوكبي فجَعَلَت تحرِقُهم وهرب الآخرون، وكانت هزيمةُ القوم عند ذلك ودخول موسى إلى قزوين, وهرب الكوكبيُّ إلى الديلم."},{"id":818,"title":"تسلط الأتراك على الدولة العباسية .","date":["العام الهجري :252","العام الميلادي :866"],"text":"أوَّلُ من بدأ بجلب الأتراك كان المعتصِم؛ وذلك لأنهم لم يَفسُدوا بعدُ بالترَفُّه، ويمكن تدريبهم عسكريًّا فيصبحوا من الجندِ، وكَثُروا حتى أصبح وجودُهم مُزعِجًا فبُنِيَت من أجلهم سامرَّا، ثم أصبح منهم القادة البارزون كالأفشين وبغا الكبير ووصيف، وأصبح نفوذُهم وتنفُّذُهم كبيرًا بسبب كثرتِهم وبسبب قوَّة إدارتهم، وبسبب تركِ كثيرٍ من الأمور إليهم أصلًا، فتآمروا مع المنتصر لقَتلِ أبيه المتوكِّل، ثم كان لهم التنفذ في تعيين المستعينِ بعد خلع المنتصرِ، ثم قاموا مع المعتز ضد المستعين، فأصبح الخلفاء كالصورة الظاهرة، أو حتى أحيانًا كالأُلعوبة وهم المتنَفِّذونَ الحقيقيُّون، فأصبحت لهم الإقطاعاتُ والأموالُ، وظل أمرهم على ذلك قرابة المائة سنة."},{"id":819,"title":"خلع الخليفة العباسي المستعين بالله ومبايعة المعتز بن المتوكل .","date":["العام الهجري :252","الشهر القمري : محرم","العام الميلادي :866"],"text":"كانت البدايةُ في أنَّ بعض قواد الأتراك من المشغِّبين قد جاؤوا إلى المستعين وسألوه العفوَ والصَّفحَ عنهم ففعل، فطلبوا منه أن يرجِعَ معهم إلى سامرَّا التي خرج منها إلى بغداد؛ بسبب تنكُّرِ بعض هؤلاء القادة الأتراك له، فلم يقبَلْ وبقي في بغداد، وكان محمد بن عبدالله بن طاهر قد أهان أحدَ القادة الأتراك، فزاد غضَبُهم، فلما رجعوا إلى سامرَّا أظهروا الشغب وفتحوا السُّجونَ وأخرجوا من فيها، ومنهم المعتزُّ بن المتوكل وأخوه المؤيَّد الذين كان المستعينُ قد خلعهما من ولاية العهد، فبايعوا المعتز وأخذوا الأموالَ من بيت المال، وقَوِيَ أمرُه، وبايعه أهلُ سامرَّا، والمستعينُ في بغداد حصَّن بغداد خوفًا من المعتز، ثم إن المعتز عقد لأخيه أبي أحمد بن المتوكِّل، وهو الموفَّق، لسبعٍ بَقِين من المحرَّم، على حرب المستعين، ومحمَّد بن عبد الله بن طاهر وجرى القتال بينهم وطالت الحربُ بينهما حتى اضطُرَّ محمد بن عبدالله بن طاهر إلى أن يُقنِعَ المستعين بخلعِ نَفسِه ويشترط شروطًا، فرضي بذلك فاستسلَمَ وكتب شروطَه وبايع للمعتزِّ وبايعت بغداد، وانتقل المستعينُ إلى واسط بعد أن خلعَ نَفسَه، ثم أرسل المعتزُّ إليه من قتَلَه في شوال من نفس العام، فكانت مدَّة خلافته أربع سنين وثلاثةَ أشهر وأيام."},{"id":820,"title":"وفاة إسماعيل بن يوسف الطالبي (السفاك) .","date":["العام الهجري :252","الشهر القمري : ربيع الأول","العام الميلادي :866"],"text":"هو إسماعيل بن يوسف بن إبراهيم بن موسى بن عبد الله بن حسن بن حسن بن علي بن أبي طالب الحسني من بيتٍ خرج منهم جماعةٌ على الخلفاء بالحجاز والعراق والمغرب، عرف بالسَّفَّاك، خرج إسماعيل سنة إحدى وخمسين ومائتين في زمن المستعين بالله بالحجاز وهو شاب له عشرون سنة، وتبعه خلقٌ كثير من المتشيِّعة والديلم, فعاث في الحرمين وقتل من الحُجَّاج بعرفة وسلَبَ ونهب، ولقِيَ النَّاسُ منه عنَتًا إلى أن هلك هو وأصحابُه بالطاعون في السنة التالية من خروجِه."},{"id":821,"title":"فتنة بين الأتراك والمغاربة .","date":["العام الهجري :252","الشهر القمري : رجب","العام الميلادي :866"],"text":"كان سببُها أنَّ الأتراكَ وثَبوا بالوزيرِ عيسى بن فرخان شاه، فضربوه، وأخذوا دابَّته، واجتمَعَت المغاربةُ مع محمد بن راشد، ونصر بن سعد، وغلبوا الأتراكَ على الجوسق، وأخرجوهم منه، وقالوا لهم: كلَّ يومٍ تقتلونَ خليفةً، وتخلعونَ آخر, وتقتلونَ وزيرًا وتُثبِتونَ آخرَ، وصار الجوسق وبيتُ المال في أيدي المغاربة، وأخذوا الدوابَّ التي كان تَرَكها الأتراكُ، فاجتمع الأتراكُ وأرسلوا إلى من بالكرخ والدُّور منهم، فاجتمعوا وتلاقَوا هم والمغاربة، وأعان الغوغاءُ والشاكريَّة المغاربةَ، فضَعُف الأتراكُ وانقادوا، فأصلحَ جعفرُ بن عبد الواحد بينهم، على ألَّا يُحدِثوا شيئًا، ويكون في كلِّ موضعٍ يكونُ فيه رجلٌ من الفريقين يكونُ فيه رجلٌ من الفريقِ الآخر، فمكثوا مدةً مديدةً، ثم اجتمَعَ الأتراك وقالوا: نطلبُ هذين الرأسينِ- يعنون محمد بن راشد ونصر بن سعيد- فإن ظَفِرنا بهما فلا يَنطِق أحدٌ. فبلغَهما خبرُ اجتماع الأتراك عليهما، فخرجا إلى منزل محمد بن عزون؛ ليكونا عنده حتى يسكُنَ الأتراكُ، ثم يرجعا إلى جمعِهما، فغمز ابن عزون بهما إلى الأتراك، فأخذوهما فقَتلوهما فبلغ ذلك المعتَزَّ، فأراد قتل ابن عزون، فكُلِّمَ فيه فنفاه إلى بغداد."},{"id":822,"title":"خلعُ المعتز أخاه المؤيد عن ولاية العهد .","date":["العام الهجري :252","الشهر القمري : رجب","العام الميلادي :866"],"text":"أرسل العلاءُ بن أحمد- عاملُ أرمينية- إلى المؤيَّد بخمسة آلاف دينار ليُصلِحَ بها أمرَه، فبعث عيسى بن فرخانشاه إليها فأخذها, فأغرى المؤيَّد الأتراك بعيسى وخالَفَهم المغاربة، فبعث المعتزُّ إلى المؤيَّد وأبي أحمد، فأخذَهما وحبَسَهما وقيَّدَ المؤيَّد، وأدرَّ العطاء للأتراك والمغاربة. وقيل: إنَّه ضرَبَه أربعينَ مقرعةً، وخلعه بسامرَّاءَ وأخذ خَطَّه بخلعِ نَفسِه."},{"id":823,"title":"وفاة إبراهيم بن المتوكل المعروف بالمؤيد .","date":["العام الهجري :252","الشهر القمري : رجب","العام الميلادي :866"],"text":"هو المؤيَّدُ إبراهيمُ بن جعفر المتوكِّل على الله، أحدُ وُلاةِ العهد الثلاثة بعد الخليفةِ المتوكِّل: وهم المنتصر بالله، والمعتَزُّ بالله، والمؤيَّد، تمَّ خَلْعُه من ولاية العهد مرتين؛ الأولى: في عهد أخيه المنتصِر؛ حيث قام بخلعِه مع المعتز بضَغطٍ من قادة الأتراك, والثانية: على يد أخيه المعتزِّ بالله؛ حيث تمَّ إجبارُه على خَلعِ نَفسِه من ولاية العهدِ، ومن ثمَّ تمَّ قتلُه في ظروف غامضة, وكانت امرأةٌ من نساء الأتراك قد جاءت إلى محمَّد بن راشد المغربي فأخبَرَته أنَّ الأتراك يريدون إخراج إبراهيمَ المؤيَّد من الحبس، وركب محمد بن راشد إلى المعتز فأعلَمَه ذلك، فدعا بموسى بن بغا فسأله فأنكر، وقال: يا أمير المؤمنين إنما أرادوا أن يُخرِجوا أبا أحمد بن المتوكِّل لأُنسِهم به، وأما المؤيَّد فلا، فلما كان يومُ الخميس لثمانٍ بَقِين من رجبٍ دعا المعتزُّ القضاةَ والفقهاء والشهودَ والوجوه، فأُخرِجَ إليهم إبراهيمُ المؤيَّد ميتًا لا أثر به ولا جُرحَ، وحُمِلَ إلى أمه على حمارٍ، وحُمِلَ معه كفَنٌ وحَنوطٌ، وأُمِرَ بدَفنِه، وحول أبو أحمد إلى الحجرة التي كان فيها المؤيَّد، فيقال غُطِّي على أنفِه فمات، وقيل: أُقعِدَ في الثلج ووُضِعَ على رأسه، وقيل في سبب موتِه أشياء أخرى."},{"id":824,"title":"وفاة الخليفة المستعين بالله .","date":["العام الهجري :252","الشهر القمري : رمضان","العام الميلادي :866"],"text":"هو المستعين بالله أبو العباس أحمد بن المعتصم بالله محمد بن الرشيد العباسي، ولد سنةَ إحدى وعشرين ومئتين, وأمُّه أمُّ ولد، اسمها مخارق, وكان رَبعةً، خفيف العارضينِ، وكان مليحًا أبيض، بوجهِه أثَرُ جُدريٍّ، وكان يلثغُ في السين نحو الثاء، بايعَ له الأتراكُ بالخلافة بعد المنتصر، فتسلَّطوا عليه وقهروه، فلم يكن له من الأمرِ شَيءٌ، فانتقل من سامرَّا إلى بغداد مُغضَبًا, جرت عدَّةُ وقائع بينه وبين أخيه المعتز، فلمَّا اشتد البلاءُ على الناس في بغداد  تخلَّى ابن طاهر عن المستعينِ، وكاتب المعتزَّ، ثم سعى في الصلح على خلعِ المستعين، فخلع نفسَه على شروطٍ مؤكَّدة في أول سنة 252ه، ثم أنفذوه إلى واسط، فاعتُقِلَ تسعةَ أشهر، ثمَّ أُحضِرَ إلى سامرَّا، فقتلوه بقادسيَّة سامرا, وكان مُسرِفًا في تبذير الخزائنِ والذَّخائر."},{"id":825,"title":"الفتنة بين جند بغداد ومحمد بن عبدالله بن طاهر .","date":["العام الهجري :252","الشهر القمري : رمضان","العام الميلادي :866"],"text":"اجتمع الشَّاكرية وأصحابُ الفروض إلى دار محمَّد بن عبدالله بن طاهر أميرِ العراق يطلبونَ أرزاقَهم، فكتب إلى أمير المؤمنين بذلك، فكتب الخليفة في الجواب: إن كنتَ تريد الجندَ لنفسِك فأعطِهم أرزاقَهم، وإن كنتَ تريدُهم لنا فلا حاجة لنا فيهم؛ فشَغَّبوا عليه، وأخرجَ لهم ألفي دينارٍ، ففُرِّقَت فيهم فسكتوا، ثم اجتمعوا مرَّةً أخرى بالسِّلاح والأعلام والطبول، وجمع محمَّد أصحابَه في داره, واجتمع إلى أولئك (المشغِّبين) خلقٌ كثير، وكان رئيسَهم أبو القاسم عبدون بن الموفَّق، وكان من نوَّاب عبيدالله بن يحيى بن خاقان، فحثَّهم على طلب أرزاقِهم، فحصل بينهم وبين أصحابِ محمدٍ قتالٌ، وظهروا على أصحابِه، ولَمَّا رأى ابن طاهر أنَّ الجندَ قد ظهروا على أصحابِه أمرَ بالحوانيت التي على باب الجِسرِ أن تُحرَق، فاحترق للتجَّار متاعٌ كثير، فحالت النارُ بين الفريقين، ورجع الجندُ إلى مُعسكرهم, ثم إنَّ ابنَ طاهر أتاه في بعض الأيامِ رجُلان من الجند، فدلَّاه على عورةِ القومِ، فأمر لهما بمئتي دينارٍ، وأمر الشاه بن ميكال وغيرَه من القواد في جماعةٍ بالمسيرِ إليهم، فسار إلى تلك الناحية، وكان أبو القاسم، وابن الخليل- وهما المقَدَّمان على الجند- قد خافا مُضِيَّ ذَينك الرجُلين، وقد تفرق الناسُ عنهما، فسار كلُّ واحد منهما إلى ناحية، وأما ابن الخليل فإنَّه لقي الشاه بن ميكال ومن معه، فصاح بهم، وصاح أصحابُ محمد، وصار في وسَطِهم، فقُتِل، وأما أبو القاسم فإنَّه اختفى فدُلَّ عليه، فأُخذ وحُمل إلى ابن طاهر، وتفَرَّق الجند من باب حرب، ورجَعوا منازِلَهم، وقُيِّدَ أبو القاسِم وضُرِبَ ضربًا مبرِّحًا فمات منه."},{"id":826,"title":"مقتل الخليفة المخلوع المستعين بالله .","date":["العام الهجري :252","الشهر القمري : رمضان","العام الميلادي :866"],"text":"قرر المعتزُّ قتلَ المستعين، فكتب إلى محمد بن عبد الله بن طاهر أن يسلِّمَه إلى سيما الخادمِ، وكتب محمَّد في ذلك إلى الموكَّلين به بواسط فقَتلوه، ثم جاؤوا برأسه والمعتَزُّ يلعب الشطرنجَ، فقيل: هذا رأسُ المخلوعِ، فقال: ضعوه هنالك، ثم فَرَغ من لَعِبِه ودعا به فنظر إليه، ثم أمر بدَفنِه."},{"id":827,"title":"ابتداء دولة يعقوب الصفار وملكه هراة وبوشنج  .","date":["العام الهجري :253","العام الميلادي :867"],"text":"كان يعقوبُ بن الليث وأخوه عمرو يعملانِ الصُّفر بسجستان، ويُظهِران الزهد والتقشُّف، وكان في أيامهما رجلٌ من أهل سجستان يُظهِرُ التطوُّع بقتال الخوارج، يقال له صالح المطوعي، فصَحِبه يعقوب، وقاتلَ معه، فحَظِيَ عنده، فجعله صالحٌ مقامَ الخليفة عنه، ثم هلك صالحٌ، وقام مقامَه إنسانٌ آخر اسمه درهم، فصار يعقوبُ مع درهم كما كان مع صالحٍ قبله. ثم إنَّ صاحبَ خُراسان احتال لدرهم لَمَّا عَظُم شأنُه وكثُر أتباعُه، حتى ظَفِر به وحمَله إلى بغداد، فحبسه بها ثم أطلَقَه، وخدَم الخليفةَ ببغداد. عظُمَ أمرُ يعقوب بعد أخذِ درهم، وصار متولِّيَ أمر المتطوِّعة مكان درهم، وقام بمحاربة الشراة، فظفِرَ بهم، وأكثَرَ القتلَ فيهم، حتى كاد يُفنيهم، وخرَّب قراهم، وأطاعه أصحابُه بمَكرِه، وحُسْنِ حالِه ورأيِه، طاعةً لم يطيعوها أحدًا كان قبله، واشتَدَّت شوكتُه، فغَلَب على سجستان، وأظهر التمسُّكَ بطاعة الخليفة وكاتبه، وصدرَ عن أمره، وأظهَرَ أنَّه هو أمَرَه بقتال أتباعِه، فخرج عن حدِّ طلب الشراة، وصار يتناولُ أصحاب أمير خراسان، ثم سار مِن سجستان إلى هراة من أعمال خُراسان ليملِكَها، وكان أمير خراسان محمد بن طاهر بن عبد الله بن طاهر بن الحسين، وعاملُه على هراة محمد بن أوس الأنباري، فخرج منها لمحاربةِ يعقوب في تعبئة حَسَنة، وبأس شديدٍ، وزيٍّ جميل، فتحاربا واقتتَلا قتالًا شديدًا فانهزم ابن أوس، ومَلَك يعقوبُ هراة وبوشنج، وصارت المدينتانِ في يده، فعَظُم أمره حينئذ، وهابه أميرُ خراسان وغيرُه من أصحاب الأطراف."},{"id":828,"title":"قتال عبدالعزيز بن أبي دلف في همذان .","date":["العام الهجري :253","الشهر القمري : رجب","العام الميلادي :867"],"text":"عقد المعتزُّ لموسى بن بغا الكبير على جيشٍ قريب من أربعةِ آلاف ليذهَبوا إلى قتال عبد العزيز بن أبي دلف بناحيةِ همذان؛ لأنَّه خرج عن الطاعة، وهو في نحوٍ من عشرين ألفًا بناحية همذان، فهَزَموا عبد العزيز في أواخر هذه السَّنة هزيمةً عظيمةً، ثمَّ كانت بينهما وقعةٌ أخرى في رمضانَ عند الكرج، فهُزِم عبد العزيز أيضًا وقُتِلَ من أصحابه بشرٌ كثير، وأَسَروا ذراريَّ كثيرةً حتى أسروا أمَّ عبد العزيز، وبَعَثوا إلى المعتز سبعين حِملًا من الرؤوس، وأعلامًا كثيرة، وأُخِذَ من عبد العزيز ما كان استحوذَ عليه من البلادِ."},{"id":829,"title":"خروج أهل ماردة في الأندلس وقمعهم .","date":["العام الهجري :254","العام الميلادي :867"],"text":"خرج الأميرُ محمد بن عبدالرحمن بن الحكم إلى ماردة بعد أن أظهَروا التمرُّد, وكانوا قد اجتمع أمرُهم في الخروج على أبيه من قبلُ، فأظهرَ أنَّ استعدادَه لطُلَيطِلة، فلما فصَلَ من قرطبةَ، وتقدَّمَ بالمحلاتِ إلى طريق طُليطِلة، نكبَ إلى ماردة، وهم في أمنٍ وغفلة، فتحَصَّنوا في المدينة أيامًا. ثم ناهض القنطرةَ، فوقع القتال، واشتدَّت الحرب حتى غُلِبوا عليها، فأمر الأميرُ بتخريب رِجلٍ من القنطرة، فكان ذلك سببًا في إذعان أهل ماردة، فطاعوا على أن يخرجَ فُرسانُهم، وهم يومئذ عبد الرحمن بن مروان، وابن شاكر، ومكحول، وغير هؤلاء، وكانوا أهلَ بأس ونجدة وبسالةٍ مشهورة. فخرج المذكورونَ ومن هو مثلهم إلى قرطبةَ بعيالهم وذراريِّهم. وولَّى عليها سعيدَ بن عباس القُرَشي، وأمرَ بهدم سورها؛ ولم تبقَ إلَّا قَصَبتُها لِمَن يَرِدُ من العُمَّال."},{"id":830,"title":"قيام الدولة الطولونية بمصر .","date":["العام الهجري :254","العام الميلادي :867"],"text":"كانت ديارُ مصر قد أُقطِعَت لبابكيال، وهو مِن أكابر قوَّاد الأتراك، وكان مُقيمًا بالحَضرة، والتمسَ بابكيال من يستخلِفُه بمصر، فأشيرَ عليه بأحمد بن طولون؛ لِمَا ظهَرَ عنه من حُسنِ السيرة، وكان طولون والدُ أحمد بن طولون أيضًا من الأتراك، وقد نشأ هو بعد والدِه على طريقةٍ مُستقيمة، وسيرةٍ حَسنةٍ، فولَّاه بابكيال وسيَّرَه إليها، وكان بها ابنُ المدبر على الخَراج، وقد تحكَّمَ في البلد، فلمَّا قَدِمَها أحمد كفَّ يد ابن المدبر، واستولى على البلدِ، وكان بابكيال قد استعمَلَ أحمد بن طولون على مصرَ وَحدَها سوى باقي الأعمالِ كالإسكندرية وغيرها، فلما قتَلَ المهتدي بابكيال وصارت مصر لياركوج التركي، وكان بينه وبين أحمد بن طولون مودَّة متأكِّدة، استعمله على ديارِ مِصرَ جَميعِها، فقَوِيَ أمرُه، وعلا شأنُه ودامت أيامه."},{"id":831,"title":"أمير صقلية خفاجة بن سفيان يرسل سراياه إلى سرقوسة ومدينة غيطة .","date":["العام الهجري :254","الشهر القمري : ربيع الأول","العام الميلادي :868"],"text":"سيَّرَ خفاجة ابنَه محمدًا على الحراقات، وسيَّرَ سريَّةً إلى سرقوسة، فغَنِموا وأتاهم الخبَرُ أنَّ بِطريقًا قد سار من القسطنطينية في جمعٍ كثيرٍ، وغَنِم المسلمونَ منهم غنائمَ كثيرة، فرحل خفاجة إلى سرقوسة فأفسَدَ زَرعَها وغَنِم منها وعاد إلى بلرم، وسيَّرَ ابنه محمدًا في البحر، مُستهَلَّ رجَب، إلى مدينة غيطة، فحَصَرها وبثَّ العساكِرَ في نواحيها، فغَنِم وشحَن مراكِبَه بالغنائم، وانصرف إلى بلرم في شوَّال."},{"id":832,"title":"وفاة الجاحظ المتكلم المعتزلي .","date":["العام الهجري :255","العام الميلادي :868"],"text":"هو أبو عثمان عمرُو بنُ بحر بن محبوب الكناني الليثي البصري المتكلِّم المعتزلي، اشتهرَ بالجاحِظِ لجُحوظٍ كان في عينيه، أديبٌ كبيرٌ وُلِدَ في البصرة ونشأ وتعلَّم فيها. قال عنه الذهبي: \"كان واسِعَ النقلِ كثيرَ الاطِّلاع، مِن أذكياءِ بني آدم وأفرادِهم وشياطينِهم\", ليس بثقةٍ ولا مأمونٍ، أخذَ عن الأصمعي وغيرِه, وأخذ عِلمَ الكلام عن أبي إسحاق إبراهيمَ بن سيَّار البلخي المعروف بالنَّظَّام المعتزلي المتكَلِّم المشهور، وقد تتلمذَ على يديه, فتأثر بفِكرِه الاعتزالي فأصبح من رؤسائِهم، بل ظهرت فرقةٌ باسم الجاحظيَّة تُنسَب إليه، وله كتبٌ كثيرة مثل: الحيوان، والبيان والتبيين، والبُخلاء، وله رسائِلُ في الفلسفة والاعتزال، ومن جملةِ أخباره أنَّه قال: ذُكرتُ للمتوكِّل لتأديبِ بعضِ ولده، فلما رآني استبشَعَ منظري فأمَرَ لي بعشرةِ آلاف درهمٍ وصرفني، أصيبَ بالفالجِ في آخِرِ عُمُره، فكان يَطلي نصفَه الأيمن بالصندل والكافور لشِدَّة حرارته، والنِّصفَ الأيسر لو قُرِّض بالمقاريض لما أحسَّ به؛ مِن خَدَره وشِدَّة بَردِه، ومات في البصرة, وقد تجاوز التسعين."},{"id":833,"title":"ظهور ثورة الزنج في البصرة .","date":["العام الهجري :255","العام الميلادي :868"],"text":"ظهر رجلٌ بظاهر البصرة زعمَ أنَّه عليُّ بن محمد بن أحمد بن عيسى بن زيد بن علي بن الحسين بن علي بن أبي طالب، ولم يكنْ صادِقًا، وإنما كان أجيرًا من عبد القيس، واسمُه علي بن محمد بن عبد الرحيم، وأمُّه قرَّة بنت علي بن رحيب بن محمد بن حكيم من بني أسد بن خزيمة، وأصلُه من قرية من قرى الريِّ، والتَفَّ عليه خلقٌ من الزنج الذين يكسحونَ السِّباخ، فعبَرَ بهم دجلةَ فنزل الديناري، وكان يزعُمُ لبعضِ من معه أنَّه يحيى بن عمر أبو الحسين المقتولُ بناحية الكوفة، وكان يدَّعي أنه يحفظُ سورًا من القرآن في ساعةٍ واحدة جرى بها لسانُه لا يحفَظُها غيره في مدَّة دهرٍ طويل، وهنَّ سبحان والكهف وص وعمَّ، وزعم أنَّه فكَّر يومًا وهو في البادية إلى أيِّ بلدٍ يسير فخوطِبَ من سحابة أن يقصِدَ البصرة فقصَدَها، فلمَّا اقترب منها وجد أهلَها متفرِّقينَ على شُعبَتين، سعدية وبلالية، فطَمِعَ أن ينضَمَّ إلى إحداهما فيستعينَ بها على الأخرى فلم يقدِرْ على ذلك، فارتحل إلى بغداد فأقام بها سنةً، وانتسب بها إلى محمد بن أحمد بن عيسى بن زيد، وكان يزعُمُ بها أنَّه يعلم ما في ضمائِرِ أصحابه، وأنَّ الله يُعلِمُه بذلك، فتَبِعَه على ذلك جهلةٌ من الطَّغامِ، وطائفةٌ من الرَّعاعِ العوامِّ, ثم عاد إلى أرض البصرة في رمضان فاجتمع معه بشَرٌ كثيرٌ، ولكِنْ لم يكُنْ معهم عُدَدٌ يُقاتِلونَ بها فأتاهم جيشٌ من ناحية البصرة فاقتَتلوا جميعًا، ولم يكنْ في جيشه هذا الخارجي سوى ثلاثة أسياف، وأولئك الجيشُ معهم عَددٌ وعُدَدٌ ولَبُوسٌ، ومع هذا هزمَ أصحابُ الزنجي ذلك الجيشَ، وكانوا أربعةَ آلاف مقاتل، ثم مضى نحو البصرةِ بمن معه فأهدى له رجلٌ من أهل جبى فرسًا فلم يجِدْ لها سرجًا ولا لجامًا، وإنما ألقى عليها حبلًا وركِبَها، ثم صادرَ رجلًا وتهدَّده بالقتل فأخذ منه مئةً وخمسين دينارا وألف درهم، وكان هذا أوَّلَ مال نهبه من هذه البلاد، وأخَذَ من آخر ثلاثةَ براذين، ومِن موضعٍ آخرَ شيئًا من الأسلحة والأمتعة، ثم سار في جيشٍ قليل السلاح والخيول، ثم جرت بينه وبين نائبِ البصرة وقعاتٍ مُتعددةً يَهزِمُهم فيها، وفي كل مرة يقوى ويعظُم أمرُه ويزداد أصحابُه ويكثُر جيشُه، وهو مع ذلك لا يتعَرَّض لأموال الناس ولا يؤذي أحدًا، وإنما يُريدُ أخْذَ أموال السلطان. وقد انهزم أصحابُه في بعض حروبه هزيمةً عظيمة ثم تراجعوا إليه واجتَمعوا حولَه، ثمَّ كَرُّوا على أهل البصرة فهزموهم وقَتلوا منهم خلقًا وأسَروا آخرين، وكان لا يؤتى بأسيرٍ إلَّا قتله ثم قوِيَ أمرُه وخافه أهلُ البصرة، وبعث الخليفةُ إليها مددًا ليقاتلوا صاحِبَ الزنج قبَّحَه الله، ثم أشار عليه بعضُ أصحابه أن يهجُم بمن معه على البصرةِ فيَدخُلوها عَنوةً فهَجَّن آراءهم وقال: بل نكونُ منها قريبًا حتى يكونوا هم الذين يطلبونَنا إليها ويخطبونَنا عليها."},{"id":834,"title":"فتح جزيرة مالطة .","date":["العام الهجري :255","العام الميلادي :868"],"text":"فتَحَها المسلمونَ في ولاية أبي عبد الله محمد بن أحمد بن محمد بن الأغلب أبو الغرانيق، غزاها خَلفٌ الخادم مولى زيادة الله بن إبراهيم، وخَلفٌ هو المعروفُ ببناء المساجدِ والقناطر، فحاصرها ومات وهو محاصِرٌ لها، فكَتَبوا إلى أبي عبد الله بوفاته، فكتب أبو عبد الله إلى عامِلِه بجزيرة صقليَّة، وهو محمَّد بن خفاجة، أن يبعَثَ إليهم واليًا، فبعث إليهم سوادةَ بن محمد، ففتحوا حصنَ مالطة، وظَفِروا بمَلِكها عمروس أسيرًا، فهَدَّموا حِصنَها وغَنِموا وسَبَوا ما عَجَزوا عن حَملِه، وحُملَ لأحمد بن عمر بن عبد الله بن الأغلب - الذي عَمِلَ من أجل فتح مالطة- من كنائِسِ مالطة ما بنى به قصرَه الذي بسوسةَ داخلًا في البحر، والمَسلَك إليه على قنطرة. وبقيت بعد ذلك جزيرةُ مالطة خَرِبةً غيرَ آهِلةٍ، وإنما كان يدخلُها النشَّاؤون للسُّفُن؛ فإنَّ العودَ فيها أمكَنُ ما يكونُ، والصيادونَ للحوتِ لكَثرتِه في سواحِلِها وطِيبه، والشائرونَ للعَسَلِ؛ فإنه أكثَرُ شَيءٍ هناك."},{"id":835,"title":"استيلاء يعقوب بن الليث الصفار على بلاد فارس .","date":["العام الهجري :255","العام الميلادي :868"],"text":"لَمَّا بلغ عليُّ بن الحسين بن شبل بفارس ما فعَلَه يعقوب بطوقٍ في كرمان أيقَنَ بمجيئِه إليه، وكان عليٌّ بشيراز، فجمع جيشَه وسار إلى مضيقٍ خارج شيراز، من أحدِ جانبيه جبَلٌ لا يُسلَك، ومن الجانب الآخر نهرٌ لا يُخاضُ، فأقام على رأسِ المضيق، وهو ضَيِّقٌ، ممَرُّه لا يسلُكُه إلا واحِدٌ بعد واحد، وهو على طرفِ البَرِّ، وقال: إنَّ يعقوبَ لا يقدِرُ على الجوازِ إلينا، فخاض يعقوبُ وأصحابه النهر وخرجوا من وراء أصحابِ عليٍّ، فلما خرج أوائِلُهم هرب أصحابُ عليٍّ إلى مدينة شيراز وانهزَموا فسقط عليُّ بن الحسين عن دابته، كبا به الفَرَسُ، فأُخِذ أسيرًا وأُتي به إلى يعقوب، فقَيَّده، فلما أصبح نهب أصحابُه دارَ عليٍّ ودُورَ أصحابِه، وأخذ ما في بيوتِ الأموالِ وبيت الخراج ورجَع إلى سجستان."},{"id":836,"title":"استيلاء يعقوب بن الليث الصفار على ولاية كرمان .","date":["العام الهجري :255","العام الميلادي :868"],"text":"كتب المعتزُّ لعلي بن الحسين بن شبل بولاية كرمان، وكتبَ إلى يعقوبَ بن الليث بولايتها أيضًا يلتمِسُ إغراءَ كُلِّ واحدٍ منهما بصاحبه؛ ليُسقِطَ مؤونةَ الهالكِ عنه، وينفرِدَ بالآخر، وكان كلُّ واحد منهما يُظهِرُ طاعةً لا حقيقةَ لها، والمعتز يعلم ذلك منهما. أرسل عليُّ بن الحسين طوقَ بن المغلس إلى كرمان، وسار يعقوبُ إليها فسَبَقه طوقٌ واستولى عليها وأقبل يعقوبُ حتى بقيَ بينه وبين كرمان مرحلةٌ، فأقام بها شهرينِ لا يتقَدَّمُ إلى طوق، ولا طوقٌ يخرج إليه، فلما طال ذلك عليه أظهَرَ الارتحال إلى سجستان، فارتحل مرحلتينِ، وبلغ طوقًا ارتحالُه فظَنَّ أنَّه قد بدا له في حربه، وترك كرمان، فوضع آلةَ الحربِ، وقعد للأكلِ والشُّرب والملاهي، وبلغ يعقوبُ إقبالَ طوقٍ على الشرب، فكرَّ راجعًا فطوى المرحلتينِ في يومٍ واحد، فلم يشعُرْ طوقٌ إلا بغبرةِ عَسكرِ يعقوب، فأحاط به وبأصحابه، فذهب أصحابُه يريدون المناهضةَ والدفعَ عن أنفُسِهم، فقال يعقوبُ لأصحابه: أفرِجوا للقَومِ، فمرُّوا هاربينَ، وخَلَّوا كلَّ ما لهم، وأسَر يعقوبُ طَوقًا، وكان علي بن الحسين قد سَيَّرَ مع طوقٍ في صناديقَ قيودًا ليقَيد بها من يأخُذُه من أصحابِ يعقوب، وفي صناديقَ أطوِقةٌ وأسورة ليعطيَها أهلَ البلاء من أصحابِ نفسِه، فلما غنِمَ يعقوب عسكَرَهم رأى ذلك، فقال: ما هذا يا طوقُ؟ فأخبره، فأخذ الأطوِقةَ والأسورة فأعطاها أصحابَه، وأخذ القيودَ والأغلال فقيَّدَ بها أصحابَ عليٍّ، ثم دخل كرمان وملكَها مع سجستان."},{"id":837,"title":"وفاة محمد بن كرام السجستاني شَيخُ الطائفة الكَرَّاميَّة .","date":["العام الهجري :255","الشهر القمري : صفر","العام الميلادي :869"],"text":"هو المُبتدِع الضّالُّ شَيخُ الكَرَّاميَّة: محمد بن كرَّام بن عراف النيسابوري، الذي إليه تُنسَب الفِرقةُ الكرَّامية, وُلِدَ بقرية من قرى زرنج بسجستان، ثمَّ دخل خراسان, وأكثَرَ الاختلاف إلى أحمد بن حرب الزاهد، كان زاهدًا عابدًا بعيدَ الصِّيتِ, كثيرَ الأصحابِ، ولكِنَّه يروي الواهياتِ, خُذِلَ حتى التقَطَ من المذاهِبِ أرداها، ومن الأحاديثِ أوهاها, ثم جالسَ الجويباري، وابن تميم, ولعلهما قد وضعا مائة ألف حديث، وأخذ التقشُّفَ عن أحمد بن حرب، كان يقولُ بالتجسيمِ والتَّشبيه وأنَّ الله محَلٌّ للحوادثِ، وأنَّ صفاتِه هي عوارِضُ حادثةٌ- تعالى الله عن ذلك- والإيمانُ عنده مجرَّدُ قَولٍ، وكان يجلِسُ للوعظ في بيت المقدِس عند العمود الذي عند مشهَدِ عيسى عليه السلام، واجتمع عليه خلقٌ كثيرٌ، ثمَّ تبين لهم أنه يقولُ: إنَّ الإيمان قولٌ بلا عملٍ، فتركه أهلُها ونفاه متولِّيها إلى غورزغر فمات بها، ونُقِل إلى بيت المقدس. قال فيه الذهبي: \"ونظيرُه في زهده وضلالِه عمرُو بن عُبيد- نسأل اللهَ السلامةَ- وأخبَثُ مقالاتِه أنَّ الإيمانَ قَولٌ بلا معرفةِ قَلبٍ\""},{"id":838,"title":"خلع الأتراك للخليفة العباسي المعتز ثم قتله  .","date":["العام الهجري :255","الشهر القمري : رجب","العام الميلادي :869"],"text":"كان سببَ ذلك أنَّ الأتراك ساروا إلى المعتزِّ يطلبون أرزاقهم، وقالوا: أعطِنا أرزاقَنا حتى نقبَلَ صالح بن وصيف، فلم يكُن عنده ما يعطيهم، فنزلوا معه إلى خمسين ألفَ دينار، فأرسلَ المعتَزُّ إلى أمِّه يسألُها أن تعطيَه مالًا ليعطيَهم، فأرسلت إليه: ما عندي شيءٌ, فلما رأى الأتراكُ أنَّهم لا يحصل لهم من المعتزِّ شَيءٌ، ولا مِن أمِّه، وليس في بيتِ المال شيء، اتَّفَقَت كلمتهم وكلمةُ المغاربة والفراغنة، على خلعِ المعتزِّ، فساروا إليه وصاحوا به فدخل إليه صالح بن وصيف، ومحمَّد بن بغا المعروف بأبي نصر، وبابكيال في السلاح، فجلسوا على بابِه، فدخل إليه جماعةٌ منهم، فجَرُّوه برِجلِه إلى بابِ الحجرة، وضربوه بالدبابيس، وخرَّقوا قميصَه، وكان بعضُهم يلطِمُه وهو يتَّقي بيده، وأدخلوه حُجرةً، وأحضروا ابنَ أبي الشوارب وجماعة أشهدوهم على خَلعِه، ثمَّ سلَّموه إلى من يسومه سوءَ العذاب بأنواعِ المَثُلات، إلى أن مات."},{"id":839,"title":"المهتدي بالله يتولى الخلافة العباسية .","date":["العام الهجري :255","الشهر القمري : رجب","العام الميلادي :869"],"text":"هو أبو محمد عبد الله محمد بن الواثق بن المعتصم بن هارون، كانت بيعتُه بعد خلع المعتزِّ نفسَه بين يديه وإشهادِه عليه، فأوَّلُ من بايعه المعتَزُّ ثمَّ بايعه الخاصَّةُ، ثم كانت بيعةُ العامَّة على المنبر."},{"id":840,"title":"مقتل خفاجة بن سفيان أمير صقلية وتولي ابنه من بعده .","date":["العام الهجري :255","الشهر القمري : رجب","العام الميلادي :869"],"text":"هو خفاجة بن سفيان أمير صقلية، وكان من الشُّجَعان الغُزاة المدَبِّرين، تولَّى إمرة صقلية عام 248هـ وكانت عاصمته بلرم،  اغتاله رجلٌ من عَسكَرِه وهو عائِدٌ مِن غَزوِ سرقوسه قاصدًا بلرم، فطعنه طعنةً فقتله، ثم هرب القاتِلُ إلى سرقوسة، وحُمِل خفاجة إلى بلرم، فدُفِنَ بها وولَّى الناسُ عليهم بعدَه ابنه محمدًا، وكتبوا بذلك إلى الأميرِ محمد بن أحمد، أمير إفريقية، فأقَرَّه على الولاية، وسيَّرَ له العهدَ والخلع."},{"id":841,"title":"شغب العامة ببغداد على ولاية المهتدي .","date":["العام الهجري :255","الشهر القمري : رجب","العام الميلادي :869"],"text":"بعث المهتدي بكتابٍ إلى سليمان بن عبد الله بن طاهر نائبِ الخليفة في بغداد يأمُرُه بأخذ البيعة له، وكان أبو أحمد بن المتوكل ببغداد، وكان المعتزُّ قد سَيَّرَه إليها، فأرسل سليمانَ إليه، فأخذه إلى داره،  فاجتمع العامَّةُ إلى باب دار سليمان، فقاتَلَهم أصحابه، وقيل لهم: ما يَرِدُ علينا من سامرَّاء خبر، فانصَرَفوا ورَجَعوا الغدَ، وهو يوم الجمعة على ذلك، وخطب للمعتز ببغداد، فانصرفوا وبكَّروا يوم السبت، فهجموا على دار سليمان، ونادَوا باسم أبي أحمد، ودَعَوا إلى بيعته، وسألوا سليمانَ أن يُريَهم أبا أحمد، فأظهَرَه لهم، ووعَدَهم أن يصيرَ إلى محبَّتِهم إن تأخَّرَ عنهم ما يحبُّون، فانصرفوا بعد أن أكَّدوا عليه في حفظ أبي أحمد، وذلك قبل أن يعلم أهلُ بغداد بما وقع بسامرَّا من بيعة المهتدي، فقُتِلَ من أهل بغداد وغَرِق منهم خلق كثيرٌ، ثمَّ لَمَّا بلغهم بيعةُ المهتدي سكَنوا, ثم أُرسِل إليهم من سامراء مالٌ ففُرِّق فيهم، فَرَضُوا وبايعوا للمهتدي لسبعٍ خَلَونَ من شعبان، وسكنت الفتنة، فاستقرت الأمور واستقر المهتدي في الخلافةِ."},{"id":842,"title":"وفاة الخليفة العباسي المعتز  .","date":["العام الهجري :255","الشهر القمري : شعبان","العام الميلادي :869"],"text":"هو أبو عبد الله، الزبيرُ بن المتوكل جعفر بن المعتصم محمد بن الرشيد هارون بن المهدي العباسي. ولد سنة 233ه, وأمُّه أم ولد روميَّة تسمَّى قبيحة, وما رُئِيَ في زمانِه أصبحَ وجهًا منه ولا من أمِّه قبيحة، تولَّى الخلافة بعد أن عزَلَ الأتراكُ المستعين بالله وأخذوا البيعة له، ثمَّ دبَّرَ من يقتل المستعينَ بعد عزله من الخلافة، وكان المعتزُ أمرَدَ حين ولِيَ الخلافة, وهو ابنُ عشرين سنة أو دونَها, وجلس جلوسًا عامًّا للناس, فلما كان بعد أشهُرٍ من ولايته، خلعَ أخاه المؤيَّد بالله إبراهيم من العهد، فما بقيَ إبراهيم حتى مات، وخاف المعتَزُّ من أن يتحَدَّثَ الناس أنَّه سَمَّه، فأحضر القضاةَ حتى شاهدوه، وما به أثَرٌ، كانت دولةُ المعتز مُستضعفةً مع الأتراك، اتَّفَق القواد منهم، وقالوا له: أعطِنا أرزاقنا, فطلَبَ مِن أمِّه مالًا ليُنفِقَه فيهم، فشَحَّتْ عليه، فتجَمَّع الأتراك لخلعه، وأتوا الدار, وبعثوا إلى المعتَزِّ ليخرُجَ إليهم, فقال: قد شَرِبتُ دواءً، وأنا ضعيفٌ، فهجم جماعةٌ منهم عليه، فجَرُّوه وضَرَبوه، وأقاموه في الحَرِّ، فبقي يتضوَّرُ وهم يلطِمونَه، ويقولون: اخلَعْ نفسَك, ثم أحضروا القاضيَ والعدول، وخلعوه، وأقدَموا من بغداد إلى سامرَّا محمد بن الواثق، وكان المعتَزُّ قد أبعده، فسَلَّمَ المعتزُّ إليه الخلافة، وبايعوه، ولقِّب بالمهتدي بالله. ثمَّ أخذ الأتراكُ المعتَزَّ بعد خمسة أيام فعذَّبوه ومُنِعَ من الطعام والشراب ثلاثةَ أيامٍ حتى جعل يطلُبَ شَربةً مِن ماء البئر فلم يُسقَ، ثم أدخلوه سردابًا فيه جصُّ جيرٍ فدسوه فيه فأصبح ميتًا، فاستلُّوه من الجصِّ سليمَ الجسَدِ وأشهدوا عليه جماعةً من الأعيان أنَّه مات وليس به أثَرٌ. مات عن عمرِ ثلاث وعشرين سنة, وصلَّى عليه المهتدي بالله، ودُفن مع أخيه المنتصر، فكانت مدَّةُ خلافته أربعَ سنين وستة أشهر وثلاثة وعشرين يومًا، ولَمَّا قُتِلَ المعتزُّ وجدوا عند أمِّه قبيحةَ أموالًا عظيمة، وجواهِرَ نفيسة، كان من جملةِ ذلك ما يقارب ألفي ألف دينار، ومن الزمُرُّد والياقوت الأحمر الذي لم يُرَ مثلُه."},{"id":843,"title":"ثورة الشاكرية والعامة في بغداد على محمد بن أوس  .","date":["العام الهجري :255","الشهر القمري : رمضان","العام الميلادي :869"],"text":"وقعت فتنةٌ ببغداد بين محمَّد بن أوس البلخي ومن تَبِعَه وبين الشاكريَّة والجند وغيرهم من العامَّة والرَّعاع، فوثبت الشاكريَّة ببغداد بمحمد بن أوس، والسببُ في ذلك أنَّ محمَّد بن أوس قَدِمَ بغداد مع سليمانَ بنِ عبد الله بن طاهر، وهو على الجيش القادم من خراسان، ومع سليمان الصعاليكُ الذين تألَّفَهم سليمانُ بالرَّيِّ، ولم تكن أسماؤهم في ديوانِ السُّلطان بالعراق، والجُند والشَّاكرية يصيحون في طلبِ مال البيعة, وكان الحسينُ بن إسماعيل يحرِّضُ العامَّة على محمد بن أوس ومن قدم مع سليمان أنهم يقصِدون أخذَ أموالِهم والفوزَ بها دونهم، حتى امتلأت قلوبُهم غيظًا, فاجتمع من العامَّةِ نحوُ مائة ألف، وكان بين الناس قتالٌ بالنِّبال والرماح والسَّوط، فقُتِلَ خَلقٌ كثير، ثم انهزم محمد بن أوس وأصحابُه، فنَهَبت العامَّةُ ما وجدوا من أموالِه، وهو ما يعادل ألفَي ألف أو نحو ذلك، ثم اتَّفقَ الحالُ على إخراج محمد بن أوس من بغداد إلى أين أراد، فخرجَ منها خائفًا طريدًا؛ وذلك لأنَّه لم يكن عند الناسِ مرضِيَّ السِّيرة."},{"id":844,"title":"استفحال أمر صاحب الزنج في مدن العراق  .","date":["العام الهجري :256","العام الميلادي :869"],"text":"كان أول ظهورٍ لثورة صاحب الزنج  الدعيِّ علي بن محمد عام 255هـ وبدأ يستفحل أمرُه وتوالت الحروب بينه وبين جيوش الخلافة مرَّةً تلو الأخرى، وكل ذلك لم يظفروا به، فدخل البصرةَ والسبخة والأبلة وعبادان والأهواز، حتى خافه كثيرٌ من أهل البصرة وفرُّوا خارج البصرة، فكان هذا بدايةً لدولتهم الجديدة المؤسَّسة أصلًا على الزنج من العبيد الفارِّين والمتمرِّدين على أسيادهم، ومَن أُسِرَ من العبيد في حروبِه."},{"id":845,"title":"ظهور أحمد بن إبراهيم بن طباطبا العلوي في مصر .","date":["العام الهجري :256","العام الميلادي :869"],"text":"ظهر بمصرَ إنسانٌ عَلويٌّ ذُكِرَ أنَّه أحمد بن محمد بن عبد الله بن إبراهيم بن طباطبا، وكان ظهورُه بين الرقة والإسكندرية، وسار إلى الصعيد، وكثُر أتباعه، وادَّعى الخلافة، فسَيَّرَ إليه أحمد بن طولون جيشًا فقاتلوه، وانهزم أصحابُه عنه، وثبت هو فقُتِل، وحُمِلَ رأسُه إلى مصر."},{"id":846,"title":"بناء أحمد بن طولون مدينة القطائع عاصمة الدولة الطولونية .","date":["العام الهجري :256","العام الميلادي :869"],"text":"لَمَّا وليَ أحمد بن طولون مصرَ سكن مدينةَ العسكرِ على عادة أمراء مصرَ من قَبلِه، ثم أحَبَّ أن يبني له قصرًا، فبنى القطائع. والقطائِعُ قد زالت آثارها الآن مِن مصر، ولم يبق لها رَسمٌ يُعرف، وكان موضِعها من قبَّة الهواء، التي صار مكانها الآن قلعةُ الجبل، إلى جامع ابن طولون، وهو طول القطائع، وأمَّا عرضها فإنه كان من أول الرميلة من تحت القلعة إلى الموضع الذي يعرف الآن بالأرضِ الصفراء, وكانت مساحةُ القطائع ميلًا في ميل, وقبة الهواء كانت في السَّطحِ الذي عليه قلعةُ الجبل. وتحت قبة الهواء كان قصرُ ابن طولون. وموضع هذا القصر الميدانُ السلطاني الآن الذي تحت قلعة الجبل بالرميلة, وكان موضع سُوق الخيل والحمير والبغال والجمال بستانًا. يجاورها الميدانُ الذي يُعرَف اليوم بالقبيبات؟ فيصير الميدانُ فيما بين القصر والجامع الذي أنشأه أحمد بن طولون المعروف به. وبجوار الجامع دارُ الإمارة في جهته القبلية، ولها بابٌ من جدار الجامع يخرجُ منه إلى المقصورة المحيطة بمصلَّى الأمير إلى جوار المحراب، وهناك دار الحرم. والقطائع عدَّةُ قِطَع يسكنُ فيها عبيدُ الأمير أحمد بن طولون وعساكِرُه وغِلمانُه. وسبب بناء ابن طولون القصرَ والقطائع كثرةُ مماليكه وعبيدِه، فضاقت دارُ الإمارة عليهم، فركِبَ إلى سفح الجبل وأمرَ بحرث قبور اليهود والنصارى، واختطَّ موضعهما وبنى القصرَ والميدان، ثمَّ أمر أصحابَه وغلمانه أن يختطُّوا لأنفُسِهم حول قصره وميدانِه بيوتًا فاختطوا وبنوا حتى اتَّصل البناءُ بعمارة الفسطاط- مصر القديمة- ثم بُنِيَت القطائع، وسُميت كلُّ قطيعةٍ باسم من سكنها. فكان للنُّوبة قطيعة مفردة تُعرَف بهم، وللرُّوم قطيعة مُفردة تُعرف بهم، وللفرَّاشين قطيعة مفردة تُعرَف بهم، ولكلِّ صِنفٍ من الغِلمانِ قطيعةٌ مفردة تُعرفُ بهم، وبنى القُوَّادُ مَواضِعَ متفَرِّقة، وعُمِرَت القطائعُ عِمارةً حسنةً وتفَرَّقت فيها السِّكَكُ والأزِقَّة، وعُمِرَت فيها المساجد الحِسان والطواحين والحمَّامات، والأفران والحوانيت والشوارع, ولَمَّا بنى ابن طولون القصرَ والميدان، وعَظُمَ أمرُه زادت صدقاتُه ورواتبُه حتى بلغت صدقاتُه المرتَّبة في الشهر ألفي دينار، سوى ما كان يطرأ عليه من مصاريفَ أخرى، وكان يقول: هذه صدقات الشكر على تجديدِ النِّعَم، ثم جعل مطابخَ للفقراء والمساكين في كلِّ يوم، فكان يذبَحُ فيها البقر والغنم ويفرِّقُ للنَّاسِ في القدور الفخَّار والقصع، ولكل قصعةٍ أو قدر أربعةُ أرغفة: في اثنين منها فالوذج، والاثنان الآخران على القِدْر أو القصعة، وكان في الغالب يُعمَلُ سماطٌ عظيم وينادى في مصر: من أحبَّ أن يحضر سماطَ الأميرِ فلْيحضر، ويجلس هو بأعلى القصرِ ينظر ذلك ويأمرُ بفتح جميع أبواب الميدان ينظُرُهم وهم يأكلونَ ويَحمِلون فيسُّرُه ذلك، ويحمد اللهَ على نعمته. وجعل بالقُربِ مِن قَصرِه حُجرةً فيها رجالٌ سمَّاهم بالمكَبِّرين عِدَّتُهم اثنا عشر رجلًا، يبيت في كلِّ ليلةٍ منهم أربعة يتعاقبون بالليلِ نُوبًا، يكَبِّرون ويهَلِّلون ويسبِّحون ويقرؤونَ القرآنَ بطيبِ الألحان ويترسَّلون بقصائدَ زُهديَّة ويؤذنونَ أوقاتَ الأذانِ."},{"id":847,"title":"ظهور ابن الصوفي العلوي بمصر .","date":["العام الهجري :256","العام الميلادي :869"],"text":"ظهر بصعيد مصر إنسانٌ ذكَرَ أنه إبراهيم بن محمد بن يحيى بن عبد الله بن محمد بن أبي طالب العَلَوي، ويُعرَف بابن الصوفي، وملك مدينة أسنا ونهبها وعَمَّ شَرُّه البلاد. فسير إليه أحمد بن طولون جيشًا فهزَمه العَلويُّ، وأسرَ المقَدَّم على الجيش، فقطع يديه ورجليه وصَلَبه؛ فسيَّرَ إليه ابنُ طولون جيشًا آخر فالتقوا بنواحي إخميم، فاقتتلوا قتالًا شديدًا فانهزم العَلَوي، وقُتِل كثيرٌ من رجاله، وسار هو حتى دخل الواحات."},{"id":848,"title":"شغب الترك على المهتدي بسبب صالح بن وصيف .","date":["العام الهجري :256","الشهر القمري : صفر","العام الميلادي :870"],"text":"كان صالح بن وصيف قائدًا من الأتراك صاحِبَ تسلُّطٍ شديد, وهو أحدُ المتآمرين على قتل المتوكِّل، ثم اختفى فطلَبه الأتراك بسببِ أموالٍ بينهم فأتوا المهتدي ليكشِفَ لهم أمرَ صالح. فقدم موسى بن بغا الكبير إلى سامرَّا بطلبٍ من الخليفة, فدخلها في جيشٍ هائل، فأتوا دار الخلافةِ التي فيها المهتدي جالسًا لكشف المظالم فاستأذنوا عليه فأبطأ الإذنَ ساعةً، وتأخَّرَ عنهم فظنُّوا في أنفسهم أنَّ الخليفةَ إنما طلبهم خديعةً منه ليسَلِّطَ عليهم صالحَ بن وصيف، فدخلوا عليه بالقوَّةِ, فأقاموه من مجلسِه وانتهبوا ما كان فيه، ثم أخذوه مهانًا إلى دار أخرى، فجعل يقول لموسى بن بغا: ما لك ويحَك؟ إنِّي إنما أرسلتُ إليك لأتقوَّى بك علي صالح بن وصيف. فقال له موسى: لا بأسَ عليك، احلِفْ لي أنَّك لا تريدُ بي خلاف ما أظهرتَ. فحلف له المهتدي، فطابت الأنفُسُ وبايعوه بيعةً ثانيةً مُشافَهةً، وأخذوا عليه العهود والمواثيق ألَّا يمالئ صالحًا عليهم، واصطلحوا على ذلك. ثم بعثوا إلى صالحِ بن وصيف ليحضُرَ لهم للمناظرة في أمر المعتزِّ، فوعدهم أن يأتيَهم، ثم اجتمع بجماعةٍ من الأمراء من أصحابِه وأخذ يتأهَّبُ لجمعِ الجيوش عليهم، ثم اختفى من ليلتِه لا يَدري أحدٌ أين ذهب في تلك الساعة، فبعثوا المناديةَ تنادي عليه في أرجاء البلد وتهدَّدوا من أخفاه، فلم يزل مختفيًا إلى آخر صفر, ولَمَّا أبطأ خبرُ صالح بن وصيف على موسى بن بغا وأصحابِه، قال بعضهم لبعض: اخلعوا هذا الرجُلَ- يعني الخليفة- فقال بعضهم: أتقتلون رجلًا صوَّامًا قوَّامًا لا يشربُ الخمر ولا يأتي الفواحش؟ واللهِ، إن هذا ليس كغيرِه من الخلفاء، ولا تُطاوِعُكم الناس عليه، وبلغ ذلك الخليفة فخرج إلى الناس وهو متقلِّدٌ سَيفًا، فجلس على السرير واستدعى بموسى بن بغا وأصحابِه، فقال: قد بلغني ما تمالأتُم عليه من أمري، وإني- والله- ما خرجتُ إليكم إلا وأنا متحنِّطٌ وقد أوصيت أخي بولدي، وهذا سيفي، والله لأضربَنَّ به ما استمسكَ قائِمُه بيدي، أمَا تستحيون؟ كم يكون هذا الإقدامُ على الخلفاءِ والجرأةُ على الله عزَّ وجلَّ، وأنتم لا تبصرون؟ سواءٌ عليكم من قصد الإبقاءَ عليكم والسيرةَ الصالحةَ فيكم، ومن كان يدعو بأرطالِ الشَّرابِ المُسكِر فيَشربُها بين أظهُرِكم وأنتم لا تُنكِرونَ ذلك، ثم يستأثِرُ بالأموال عنكم وعن الضُّعفاء! هذا منزلي فاذهبوا فانظروا فيه وفي منازلِ إخوتي ومن يتَّصِلُ بي، هل ترون فيها من آلاتِ الخلافة شيئًا، أو من فُرُشِها أو غير ذلك؟ وإنما في بيوتِنا ما في بيوت آحادِ النَّاسِ، وتقولون إني أعلمُ خبَرَ صالح بن وصيف، وهل هو إلَّا واحد منكم؟ فاذهبوا فاعلموا عِلمَه وأمَّا أنا فلستُ أعلمُ عِلمَه. قالوا: فاحلفْ لنا على ذلك، قال أمَّا اليمين فإنِّي أبذلها لكم، قال: فكأنَّهم لانوا لذلك قليلًا. ثم ظفروا بصالح بن وصيف فقُتِلَ وجيء برأسه إلى المهتدي باللهِ، وقد انفتل من صلاة المغربِ، فلم يزد على أن قال: وارُوه. ثم أخذَ في تسبيحه وذِكرِه. ولَمَّا أصبح الصباح رُفِعَ رأس صالح بن وصيف على رُمحٍ ونودي عليه في أرجاء البلد. هذا جزاء من قتل مولاه. وما زال الأمرُ مضطربًا متفاقمًا، وعظم الخطب حتى أفضى إلى خلعِ الخليفة المهتدي وقتلِه رحمه الله."},{"id":849,"title":"تولي المعتمد على الله الخلافة العباسية .","date":["العام الهجري :256","الشهر القمري : رجب","العام الميلادي :870"],"text":"بويع المعتمِدُ على الله- وهو أحمد بن المتوكِّل على الله- بالخلافةِ في دار الأمير يارجوخ، وذلك قبل خلعِ المهتدي بأيامٍ، ثم كانت بيعةُ العامَّة. وفي صفر من السنة التالية عَقدَ المعتمِدُ لأخيه أبي أحمد على الكوفةِ وطريق مكة والحرمين واليمن، وأضاف إليه في رمضان نيابةَ بغداد والسواد وواسط وكور دجلة والبصرة والأهواز وفارس، وأذِنَ له أن يتصَرَّف في ذلك كلِّه."},{"id":850,"title":"وفاة الخليفة العباسي المهتدي بالله .","date":["العام الهجري :256","الشهر القمري : رجب","العام الميلادي :870"],"text":"هو الخليفة الصالحُ أميرُ المؤمنين أبو إسحاق، وقيل أبو عبدالله محمَّد بن هارون الثاني الواثق بالله بن محمد المعتصم بالله بن هارون الرشيد, وأمُّه أم ولدٍ اسمُها قرب, ولدَ في خلافة جدِّه الواثق سنة 219ه, وبويع بالخلافةِ في رجب سنة 255ه، وما قَبِلَ بيعةَ أحد حتى بايعه المعتز بالله، بعد أن أقرَّ بتنازله عن الخلافة له، وأشهَدَ على نفسِه بعجزه عن تولِّي مهامِّها. كان المهتدي أسمرَ رقيقًا، مليح الوجه، حسَنَ اللِّحية, مِن أحسنِ الخُلَفاء مذهبًا وأجودِهم طريقةً وأكثَرِهم ورَعًا وعبادةً وزَهادةً, وكان عادلًا، قويًّا في أمر الله، شُجاعًا، صوَّامًا قوَّامًا، لم تُعرَف له زلَّةٌ, وكان سهلَ الحِجاب كريمَ الطَّبع يخاطِبُ أصحابَ الحوائجِ بنفسِه ويجلِسُ للمظالم بنفسه, وكان يلبَسُ القميصَ الصُّوفَ الخَشِن تحت ثيابِه على جلدِه, وكان يقول: لو لم يكُن الزهد في الدنيا والإيثارُ لِما عند الله مِن طبعي لتكلَّفتُه وتصنَّعتُه؛ فإنَّ منصبي يقتضيه، فإنِّي خليفةُ الله في أرضِه والقائِمُ مقامَ رَسولِه، النائِبُ عنه في أمته، وكان له سفطٌ فيه جبَّة صوف وكساء كان يلبَسُه بالليل ويصلِّي فيه, وكان قد اطَّرَح الملاهيَ، واعتزل الغِناءَ، ومنع أصحابَ السلطان عن الظُّلم، وكان شديدَ الإشرافِ على أمر الدواوين ومحاسبةِ عُمَّاله. كان يحبُّ الاقتداءَ بما سلكه عمرُ بن عبد العزيز في خلافتِه من الورع والتقشُّف وكثرة العبادة وشدَّة الاحتياط، ولو عاش ووجَد ناصرًا لسار سِيرَتَه ما أمكَنَه، لَمَّا ذُكِّرَ بما حدث للإمامِ أحمد بن حنبل على يدِ أسلافه، قال: رحِمَ الله أحمدَ بن حنبل، واللهِ لو جاز لي أن أتبَرَّأ من أبي لتبَرَّأت منه. كان سفيان الثوريُّ يقول: \"الخلفاء الراشدون خمسةٌ، ويعدُّ فيهم عمر بن عبد العزيز, ثمَّ أجمع الناسُ في أيام المهتدي مِن فَقيهٍ ومُقرئ وزاهد وصاحِبِ حديثٍ أن السادِسَ هو المهتدي باللَّه\". وكان من عَزْمِه أن يُبيد الأتراك الذين أهانوا الخلفاءَ وأذلوهم، وانتهكوا منصِبَ الخلافة. فلما أراد أن يخالِفَ بين كلمة الأتراك ليُضعِفَ تسلُّطَهم على الخلافة، كتب إلى بايكباك أن يتسَلَّم الجيشَ من موسى بن بغا ويكون هو الأميرَ على الناس وأن يُقبِلَ بهم إلى سامرَّا، فلما وصل الكتاب بايكباك أقرأه موسى بن بغا فاشتَدَّ غَضَبُه على المهتدي واتَّفقا عليه وقصدا إليه إلى سامرَّا، وتركا ما كانا فيه، فلمَّا بلغ المهتدي ذلك ركب في جيش ٍكثيفٍ واتَّجه لملاقاتِهما, فلما سمعوا به رجع موسى بن بغا إلى طريقِ خُراسان وأظهر بايكباك السمعَ والطاعة, فأمر المهتدي عند ذلك بضَربِ عُنُق بايكباك، ثم ألقى رأسَه إلى الأتراك، فلما رأوا ذلك أعظَموه وأصبحوا من الغدِ مجتمعين على أخي بايكباك ظغوتيا فخرج إليهم الخليفةُ فيمن معه، فلما التقوا تمالأ الأتراكُ الذين مع الخليفة إلى أصحابِهم وصاروا إلبًا واحدًا على الخليفة، فحمل الخليفةُ عليهم فقتل منهم نحوًا من أربعة آلاف، ثم حملوا عليه فهزموه ومن معه فانهزم الخليفة فعاجله أحمد بن خاقان فرماه بسهمٍ في خاصرتِه، ثم حُمل على دابةٍ وخَلْفَه سائسٌ وعليه قميصٌ وسراويل حتى أدخلوه دار أحمد بن خاقان، فجعل من هناك يصفعونَه ويبزقون في وجهِه، وسلَّموه إلى رجلٍ، فلم يزل يجأُ خصيتيه ويطأُهما حتى مات- رحمه الله- وكانت خلافتُه أقلَّ مِن سنة بخمسة أيام، وصلَّى عليه جعفر بن عبد الواحد، ودُفن بمقبرة المنتصر بن المتوكل رحِمَه الله."},{"id":851,"title":"وفاة الإمام البخاري صاحب الجامع الصحيح .","date":["العام الهجري :256","الشهر القمري : رمضان","العام الميلادي :870"],"text":"هو محمَّد بن إسماعيل بن إبراهيم بن المغيرة، إمامُ أهلِ الحديثِ بلا مُنازِعٍ، صاحِبُ الصَّحيحِ، الذي أجمعت الأمَّةُ على تلِّقيه بالقَبول، وُلِدَ في بخارى، رحل إلى مكَّةَ وبقي فيها فترةً يتلقى العلمَ، طاف البلادَ للحديث يجمَعُ ويحفَظُ، حتى صار إمامَ الحديث وحافِظَه في عصرِه، إمامًا في الجرحِ والتعديلِ، إمامًا في العِلَل. قال ابنُ خُزيمة: \"ما رأيتُ تحت أديمِ السَّماءِ أعلمَ بحديثِ رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم، ولا أحفَظَ له مِن محمد بن إسماعيل البخاري\"، وكان فقيهًا. بل منهم من فضَّلَه بالفقهِ على الإمام أحمدَ، وعلى ابنِ راهَوَيه، قال الدارمي: \"محمَّدُ بن إسماعيل البخاري أفقَهُنا وأعلَمُنا وأغوَصُنا، وأكثَرُنا طلَبًا\"، كان البخاريُّ رحمه الله في غايةِ الحياء والشَّجاعة والسَّخاء والورع والزُّهد في الدنيا دارِ الفناء، والرغبةِ في الآخرة دارِ البقاء، رجع إلى بُخارى فطلبه أميرُها أن يوافيَه ليَسمَعَ أولادَه منه فلم يرضَ، فحقَد عليه ونفاه من بُخارى، فخرج إلى خرتنك قريبة من سمرقند، وفيها توفِّيَ عن عمر 62 سنة، توفِّي ليلة الفطر- رحمه الله تعالى، وجزاه عن الإسلامِ والمسلمينَ خيرًا."},{"id":852,"title":"تغلبُ الحسن بن زيد الطالبي على بلاد الري .","date":["العام الهجري :256","الشهر القمري : شوال","العام الميلادي :870"],"text":"تغلبَ الحسَنُ بن زيد الطالبيِّ على بلاد الريِّ، فتوجه إليه موسى بن بغا في شوال، وخرج الخليفة لتوديعه, فكانت وقعة بين موسى بن بغا وأصحاب الحسن بن زيد، فهزَمَ موسى أصحابَ الحسَنِ وتغَلَّب عليهم."},{"id":853,"title":"خوارج الزنج يحرقون جامع البصرة وقتل الكثير من أهلها .","date":["العام الهجري :257","العام الميلادي :870"],"text":"دخل جيش الخبيثِ الزنجيِّ إلى البصرة قهرًا، فقتل من أهلِها خَلقًا، وهرب نائبُها بغراج ومن معه، وأحرَقَت الزنج جامعَ البصرة ودورًا كثيرة، وانتهبوها، ثم نادى فيهم إبراهيم بن المهلبي أحدُ أصحاب الزنجي الخارجي: من أراد الأمانَ فلْيَحضُر، فاجتمع عنده خلقٌ كثير من أهل البصرة، فرأى أنه قد أصاب فرصةً، فغدر بهم وأمَرَ بقَتلِهم، فلم يُفلِتْ منهم إلَّا الشاذ، كانت الزنجُ تحيط بجماعةٍ من أهل البصرة، ثم يقول بعضهم لبعض: كيلوا- وهي الإشارة بينهم إلى القتل- فيَحمِلون عليهم بالسيوفِ، فلا يُسمَعُ إلَّا قَولُ أشهدُ أنْ لا إله إلا الله، من أولئك المقتولين, وضجيجُهم عند القتل- أي صراخ الزِّنج وضَحِكهم - وهكذا كانوا يفعلونَ في كل محالِّ البصرة في عِدَّة أيام، وهرب الناسُ منهم كلَّ مَهرَبٍ، وحرَقوا الكلأ من الجبَل إلى الجبل، فكانت النارُ تحرِقُ ما وجدت من شيءٍ؛ من إنسانٍ أو بهيمة أو غير ذلك، وأحرقوا المسجِدَ الجامع، وقد قتَل هؤلاء جماعةً كثيرةً من الأعيان والأُدَباء والفُضَلاء والمحَدِّثين والعلماء."},{"id":854,"title":"الاقتتال بين الخوارج بسبب مسألة قبول توبةِ العصاة .","date":["العام الهجري :257","العام الميلادي :870"],"text":"اختلف مساور الخارجي مع رجلٍ من الخوارج- يقال له عُبيدة، من بني زهير العمروي- على توبةِ المخطئ، فقال مساور: نقبلُ توبته؛ وقال عبيدة: لا نقبل، فجمع عبيدةُ جمعًا كثيرًا وسار إلى مساور، وتقدَّمَ إليه مساور من الحديثة، فالتَقَوا بنواحي جهينة، بالقرب من المَوصِل، واقتتلوا أشدَّ قتال، فترجَّل مساور ومن عنده، ومعه جماعةٌ من أصحابه، وعرقبوا دوابَّهم، فقُتِل عبيدة وانهزم جمعه، فقُتِل أكثَرُهم، واستولى مساور على كثير من العراق، ومنع الأموالَ عن الخليفة، فضاقت على الجندِ أرزاقُهم، فاضطَرَّهم ذلك إلى أن سار إليه موسى بن بغا وبابكيال وغيرهما في عسكرٍ عظيم."},{"id":855,"title":"مقتل أمير صقلية محمد بن خفاجة  .","date":["العام الهجري :257","الشهر القمري : رجب","العام الميلادي :871"],"text":"لَمَّا قُتِلَ خفاجة بن سفيان استعمل الناسُ ابنه محمدًا، وأقره محمد بن أحمد بن الأغلب أبو الغرانيق- صاحِبُ القيروان- على ولايته, كان ذلك في عام خمس وخمسين ومائتين، وفي رجب من عام سبع وخمسين ومائتين قُتِلَ الأميرُ محمد، قتله خَدَمُه الخصيان نهارًا وكتموا قَتْلَه، فلم يعرَفْ إلَّا مِن الغد، وكان الخدَمُ الذين قتلوه قد هربوا فطُلِبوا فأُخِذوا وقُتِلَ بعضُهم، ولَمَّا قُتِلَ استعمل محمَّدُ بن أحمد بن الأغلب على صقلية أحمدَ بن يعقوب بن المضاء بن سلمة، فلم تطُلْ أيَّامُه."},{"id":856,"title":"معارك سعيد الحاجب مع خوارج الزنج في البصرة .","date":["العام الهجري :257","الشهر القمري : رجب","العام الميلادي :871"],"text":"أوقع سعيد الحاجب أمير البصرة بجماعةٍ مِن الزنج، فهزمهم واستنقذَ مَن معهم من النساء والذريَّة، واسترجع منهم أموالًا جزيلةً، وأهان الزنجَ غايةَ الإهانة، فكانت المرأةُ من نساء تلك الناحية تأخذ الزنجيَّ فتأتي به عسكرَ سعيدٍ فلا يمتنِعُ عليها، ثم عبَرَ سعيد إلى غرب دجلة فأوقع بصاحِبِ الزنج عدةَ وَقعاتٍ، ثم عاد إلى معسكرِه بهطمة فأقام من ثاني رجب إلى آخر شعبان. ثم أوقع صاحِبُ الزنج بسعيد، وذلك أنَّه سيَّرَ إلى سعيد جيشًا، فأوقعوا به ليلًا وأصابوا مقتلةً من أصحاب سعيد، فقَتلوا خلقًا كثيرًا وأحرقوا عسكرَه، فأمر بالمسير إلى باب الخليفة، وترك بغراج بالبصرة، فسار سعيد من البصرة وأقام بها بغراج يحمي أهلها، فردَّ السلطان أمرَها إلى منصور بن جعفر الخياط بعد سعيد، فجمع منصور الشذا وسار نحو صاحبِ الزنج، فكَمَن له صاحِبُ الزنج كمينًا، فلما أقبل منصورٌ خرج عليه الزنج فقتَلوا في أصحابِه مقتلةً عظيمة، وغرق منهم خلقٌ كثير، فلم يقابِلْهم منصور بعد ذلك."},{"id":857,"title":"الخليفة المعتمد يأمر بحربِ خوارج الزنج في البصرة .","date":["العام الهجري :257","الشهر القمري : ذي القعدة","العام الميلادي :871"],"text":"أمر المعتمد أحمد المولد بالمسير إلى البصرة لحربِ الزنج، فسار حتى نزل الأبلة، ثم نزل البصرة، واجتمع إليه من أهلِها خلقٌ كثير، فسيَّرَ علي بن أبان المهلبي إلى حرب المولد يحيى بن محمد البحراني، فسار إليه فقاتله عشرةَ أيام، ثم وطَّن المولدُ نفسَه على المقام، فكتب العلَويُّ إلى يحيى يأمره بتبييتِ المولد، ووجه إليه الشذا مع أبي الليث الأصفهاني، فبَيَّته، ونهض المولد فقاتلَه تلك الليلة، ومن الغدِ إلى العصر، ثم انهزم عنه، ودخل الزنج عسكَرَه فغَنِموا ما فيه."},{"id":858,"title":"الخليفة المعتمد يأمر أخيه الموفَّق بقتال خوارج الزنج .","date":["العام الهجري :258","الشهر القمري : ربيع الآخر","العام الميلادي :872"],"text":"عقد الخليفةُ المعتمِدُ لأخيه الموفَّق أبي أحمد ومفلح لقتال الزنج، فلما سارا إلى البصرة واجههم علي بن أبان المهلبي فجرى القتالُ بينهما، وكان نتيجته مقتل مفلح وكثيرٍ من أصحابه، ثمَّ إنَّ يحيى بن محمد البحراني- وهو من طرف الزنج- سار نحو نهر العباس فلَقِيَه عسكرُ أصعجور، عامل الأهواز بعد منصور، وقاتلهم، وكان أكثَرَ منهم عددًا، فنال ذلك العسكر من الزنج بالنشاب، وجرحوهم، فعبَرَ يحيى النهرَ إليهم، فانحازوا عنه، وغَنِم سفنًا كانت مع العسكر، فيها الميرةُ، وساروا بها إلى عسكر صاحب الزِّنج على غير الوجه الذي فيه علي بن أبان، لتحاسُدٍ كان بينه وبين يحيى، فلقيهم جيش الموفَّق ورشقوهم بالنشاب، فأصابوا يحيى الذي حاول الهرب، ولكنه قُبِضَ عليه وسُيِّرَ إلى سامرَّا فقُطِعَت يده ورِجلُه من خِلافٍ ثمَّ ذُبِح، ورجع جيشُ الموفَّق لوباءٍ حلَّ بالجند بالإضافة لحريقٍ حصل للجيش."},{"id":859,"title":"غزو الأمير محمد بن عبدالرحمن ثغور الأندلس .","date":["العام الهجري :259","العام الميلادي :872"],"text":"خرج الأمير محمد بن عبدالرحمن بنفسه إلى الثغر، وحلَّ في وجهته بطليطِلة، وأخذ رهائِنَهم، وعقدَ أمانَهم، وقاطَعَهم على قطيعٍ من العُشور يؤدُّونه في كل عام، وهو الأمانُ الثاني. واختلفت أهواؤهم في عُمَّالهم، فطلب قوم منهم توليةَ مطَرِّف بن عبد الرحمن، وطلب آخرونَ تولية طربيشة بن ماسوية، فولَّى كلَّ واحد منهما جانبًا، واقتسما المدينةَ وأقاليمها على حدود مفهومة معلومة؛ ثم تنازعا، وأراد كلُّ واحد منهما الانفرادَ بمُلك طليطلة، ثم غلب الداعون إلى تقديمِ طربيشة، وتأخير مُطَرِّف. وكان الأمير محمد تتلقاه في وجهتِه هذه- في الارتحال والاحتلال- طلائِعُ الظَّفَر، وبوادر النَّجاح والنصر. وتجوَّل في الثغر محاصرًا لبني موسى، ومضيِّقًا عليهم. ثم تقدَّم إلى بنبلونة؛ فوطئ أرضَها، وأذلَّ أهلَها وخَرَّبها ثم قفَل، فحَلَّ بقُرطبة، ومعه جماعةٌ من الثوَّار الناكثين المُفسِدين، فلما أخذ راحتَه أمر بقتل مطرف بن موسى وبنيه."},{"id":860,"title":"عودة ظهور ابن الصوفي العلوي بمصر .","date":["العام الهجري :259","العام الميلادي :872"],"text":"كان إبراهيم بن محمَّد بن يحيى بن عبد الله بن محمد بن أبي طالب المعروف \"بابن الصوفي العَلَوي\" قد ظهر بمصر سنة ست وخمسين، فدعا لنفسه ثم هرب إلى الواحات، ثم عاد هذا العام، فدعا الناسَ إلى نفسه، فتَبِعَه خلق كثير، وسار بهم إلى الأشمونين، فوُجِّه إليه جيش عليهم قائد يعرف بابن أبي الغيث، فوجده قد أصعد إلى لقاء أبي عبد الرحمن العمري، فلما وصل العَلَوي إلى العُمري التقيا، فكان بينهما قتالٌ شديد، أجْلَت الوقعةُ عن انهزام العلوي، فولى منهزمًا إلى أسوان، فعاث فيها وقطع كثيرًا من نَخلِها. فسيَّرَ إليه ابن طولون جيشًا، وأمرهم بطلبه أين كان، فسار الجيش في طلبه، فولى هاربًا إلى عيذاب، وعبَرَ البحر إلى مكَّة، وتفَرَّق أصحابه، فلما وصل إلى مكة بلغ خبَرُه إلى واليها فقبض عليه وحبَسَه، ثم سيَّرَه إلى ابن طولون، فلما وصلَ إلى مصر أمر به فطِيفَ به في البلد، ثم سجَنَه مُدَّة وأطلقه، ثم رجع إلى المدينة فأقام بها إلى أن مات."},{"id":861,"title":"دخول خوارج الزنج إلى بلاد الأهواز .","date":["العام الهجري :259","الشهر القمري : رجب","العام الميلادي :873"],"text":"أنفذ قائدُ الزنجِ عليَّ بن أبان المهلبي، وضمَّ إليه الجيشَ الذي كان مع يحيى بن محمد البحراني، وسليمان بن موسى الشعراني، وسيَّرَه إلى الأهواز, وكان المتولي لها بعد منصور بن جعفر رجلًا يقالُ له أصعجور، فبلغه خبَرُ الزنج، فخرج إليهم، والتقى العسكرانِ بدشت ميسان، فانهزم أصعجور، وقُتِل معه كثيرٌ، وجُرِح خلقٌ كثيرٌ من أصحابه، وغرق أصعجور، وأُسِرَ خَلقٌ كثيرٌ، فيهم الحسن بن هرثمة، والحسن بن جعفر، وحُمِلَت الرؤوسُ والأعلام والأسرى إلى الخبيث، فأمرَ بحَبسِ الأسرى، ودخل الزنجُ الأهواز، فأقاموا يُفسِدون فيها ويَعيثون إلى أن قَدِمَ موسى بن بغا."},{"id":862,"title":"انتهاء الدولة الطاهرية بخراسان على يد الصفارية .","date":["العام الهجري :259","الشهر القمري : شوال","العام الميلادي :873"],"text":"دخل يعقوبُ بن الليث نيسابور، وكان سببَ مَسيرِه إليها أنَّ عبد الله السجزي كان ينازع يعقوب بسجستان، فلما قويَ عليه يعقوبُ هرب منه إلى محمد بن طاهر، فأرسل يعقوبُ يطلب من ابن طاهرٍ أن يسَلِّمَه إليه فلم يفعَلْ، وقيل: كان سببَ مِلك يعقوب نيسابورَ ما بلَغَه من ضَعفِ محمد بن طاهر أميرِ خراسان، فلما تحقَّقَ يعقوبُ ذلك، وأنَّه لا يقدِرُ على الدَّفعِ، وكان بعضُ خاصة محمد بن طاهر، وبعضُ أهلِه لَمَّا رأوا إدبارَ أمرِه، مالوا إلى يعقوبَ فكاتبوه، واستدعَوه وهَوَّنوا على محمد أمرَ يعقوب من نيسابور، فسار نحوَه إلى نيسابور، فلما قرُبَ منها وأراد دخولها، وجَّه محمد بن طاهر يستأذِنُه في تلقِّيه فلم يأذَنْ له، فبعث بعُمومتِه وأهلِ بيته فتلقَّوه, ثم دخل يعقوبُ نيسابور، فركب محمد بن طاهر فدخل إليه في مضربه، فسأله ثم وبَّخَه على تفريطِه في عمَلِه، وقبض على محمد بن طاهر، وأهلِ بيته، وكانوا نحوًا مِن مائة وستين رجلًا، وحملهم إلى سجستان واستولى على خراسان، ورتَّبَ فيها نُوَّابه, ثم أرسل إلى الخليفةِ يذكرُ تفريطَ محمد بن طاهر في عمَلِه، وأنَّ أهلَ خراسان سألوه المسيرَ إليهم، ويذكُر غلبة العَلويِّين على طبرستان، وبالغ في هذا المعنى، فأنكر عليه الخليفةُ ذلك، وأمَرَه بالاقتصارِ على ما أُسنِدَ إليه."},{"id":863,"title":"الخليفة المعتمد يأمر موسى بن بغا لحرب خوارج الزنج .","date":["العام الهجري :259","الشهر القمري : ذي القعدة","العام الميلادي :873"],"text":"أمر المعتمِدُ موسى بن بغا الكبيرَ بالمسير إلى حرب صاحبِ الزنج، فسيَّرَ إلى الأهواز عبد الرحمن بن مفلح، وإلى البصرة إسحاقَ بن كنداجيق، وإلى باذاورد إبراهيمَ بن سيما، وأمرهم بمحاربة صاحب الزنج، فلما وَليَ عبد الرحمن الأهوازَ سار إلى محاربة عليِّ بن أبان المهلبي، فتواقعا فانهزم عبدُالرحمن؛ ثم استعَدَّ وعاد إلى عليٍّ، فأوقع به وقعةً عظيمةً قَتَل فيها من الزنج قتلًا ذريعًا وأسَرَ خلقًا كثيرًا، وانهزم عليُّ بن أبان والزنج، ثم أراد رَدَّهم فلم يرجِعوا من الخوفِ الذي دخلهم من عبد الرحمن، فلمَّا رأى ذلك أذِنَ لهم بالانصرافِ، فانصرَفوا إلى مدينة صاحِبِهم، ووافى عبد الرحمن حِصنَ مهديٍّ ليُعسكِرَ به، فوجَّه إليه صاحِبُ الزنجِ عليَّ بن أبان، فواقعه فلم يقدر عليه، ومضى يُريدُ الموضِعَ المعروف بالدكة، وكان إبراهيمُ بن سيما بالباذاورد، فواقعه عليُّ بن أبان، فهزمه علي بن أبان، ثم واقعه ثانيةً، فهزمه إبراهيمُ، فمضى عليٌّ في الليل ومعه الأدلَّاء في الآجام، حتى انتهى إلى نهر يحيى، وانتهى خبَرُه إلى عبد الرحمن، فوجَّه إليه طاشتمر في جمعٍ من الموالي، فلم يصِلْ إليه؛ لامتناعه بالقصب والحلافي، فأضرمها عليه نارًا فخرجوا منها هاربينَ، فأُسِر منهم أسرى، وانصرف أصحابُ عبد الرحمن بالأسرى والظَّفَر، ثم سار عبد الرحمن نحوَ عليِّ بن أبان بمكانٍ نزل فيه، فكتب علي إلى صاحِبِ الزنج يستمِدُّه، فأمَدَّه بثلاثَ عشرة شذاة، ووافاه عبد الرحمن، فتواقعا يومَهما، فلما كان الليلُ انتخَبَ عليٌّ من أصحابِه جماعةً ممَّن يثِقُ بهم وسار وترك عسكرَه ليُخفِيَ أمرَه، وأتى عبد الرحمن من ورائه فبَيَّتَه، فنال منه شيئًا يسيرًا، وانحاز عبد الرحمن فأخذ عليٌّ منهم أربع شذوات، وأتى عبد الرحمن دولاب فأقام به، وسار طاشتمر إلى عليٍّ فوافاه وقاتله، فانهزم عليٌّ إلى نهر السدرة، وكتب يستمِدُّ عبد الرحمن، فأخبَرَه بانهزام عليٍّ عنه، فأتاه عبد الرحمن وواقع عليًّا عند نهر السدرة وقعةً عظيمةً، فانهزم علي إلى الخبيث، وعسكر عبدُ الرحمن، فكان هو وإبراهيم بن سيما يتناوبان المسيرَ إلى عسكر الخبيث فيُوقعان به، وإسحاق بن كنداجيق بالبصرة، وقد قطَعَ الميرةَ عن الزنج، فكان صاحِبُهم يجمع أصحابَه يوم محاربة عبد الرحمن وإبراهيم، فإذا انقَضَت الحرب سيَّرَ طائفةً منهم إلى البصرة يقاتِلُ بهم إسحاق، فأقاموا كذلك بضعةَ عشر شهرًا إلى أن صرف موسى بن بغا عن حرب الزنج، ووَلِيَها مسرور البلخي."},{"id":864,"title":"الحرب بين يعقوب الصفار والحسن بن زيد العلوي .","date":["العام الهجري :260","العام الميلادي :873"],"text":"كان عبد الله السجزي ينازِعُ يعقوبَ بن الليث الصفَّار الرئاسةَ بسجستان، فقهره يعقوبُ، فهرب منه عبد الله إلى نيسابور، فلما سار يعقوبُ إلى نيسابور، هرب عبد الله إلى الحسن بن زيد العَلَوي بطبرستان، فسار يعقوبُ في أثَرِه، فلقيه الحسنُ بن زيد بقرية سارية، وكان يعقوبُ قد أرسل إلى الحسن يسألُه أن يبعثَ إليه عبد الله ويرجِعَ عنه، فإنَّه إنما جاء لذلك لا لحَربِه، فلم يُسلِّمْه الحسن، فحاربه يعقوبُ، فانهزم الحسَنُ، ومضى نحو السِّرِّ وأرض الديلم، ودخل يعقوب ساريةً، وآمل، وجبى أهلَها خراجَ سَنةٍ، ثم سار في طلَبِ الحسن، فسار إلى بعضِ جبال طبرستان، وتتابعت على يعقوبَ الأمطارُ نحوًا من أربعين يومًا، فلم يتخلَّصْ إلا بمشقَّة شديدة، وهلك عامَّةُ ما معه من الظهر، ثم أراد الدخولَ خلف الحسن، لكنَّه توقَّف على الطريق الذي يريدُ أن يَسلُكَه، وأمر أصحابَه بالوقوف، ثم تقدَّم وحده، وتأمَّل الطريق، ثم رجع إليهم فأمَرَهم بالانصراف، وقال لهم: إنَّه لم يكنْ طريقٌ غيرُ هذا وإلَّا لا طريق إليه، وكان نساءُ أهل تلك الناحية قُلْنَ للرجال: دعوه يدخُل؛ فإنَّه إن دخل كفيناكم أمْرَه، وعلينا أسْرَه لكم. فلمَّا خرج من طبرستان عرضَ رجالَه، ففقد منهم أربعون ألفًا، وذهب أكثَرُ ما كان معه من الخيل والإبل والبغال والأثقال، وكتب إلى الخليفة بما فعله مع الحسَنِ من الهزيمة."},{"id":865,"title":"فتنة الموصل وفساد عاملها ابن أساتكين .","date":["العام الهجري :260","العام الميلادي :873"],"text":"كان المعتمِد قد ولَّى على الموصِل أساتكين من قوَّاد الأتراك، فبعث عليها ابنَه اذكوتكين وسار إليها سنة تسع وخمسين، فأساء السيرةَ وأظهر المُنكَر وعسَفَ بالنَّاسِ في طلب الخَراجِ، وتعرَّضَ أحد الأيام رجلٌ من حاشيته إلى امرأةٍ في الطريقِ، وتخلَّصها من يده بعضُ الصالحين، فأحضره أذكوتكين وضربه ضربًا شديدًا، فاجتمع وجوهُ البلد وتآمروا في رَفعِ أمرهم إلى المعتمِد، فركب إليهم ليوقِعَ بهم فقاتلوه وأخرجوه واجتَمَعوا على يحيى بن سليمان، وولَّوه أمْرَهم، ولَمَّا كانت سنة إحدى وستين ولَّى أستاكين عليها الهيثم بن عبد الله بن العمد الثعلبي العدوي وأمَرَه أن يزحَفَ لِحَربِهم ففعل، وقاتلوه أيامًا وكَثُرت القتلى بينهم، ورجع عنهم الهيثم وولَّى أستاكين مكانه إسحاق بن أيوب الثعلبي، وحاصرها مدَّةً ومرض يحيى بن سليمان الأمير، فطَمِع إسحاقُ في البلد وجدَّ في الحصار، واقتحمها من بعضِ الجهات فأخرجوه، وحملوا يحيى بن سليمان في قبَّة وألقوه أمام الصفِّ، واشتدَّ القتال ولم يزَل إسحاق يراسِلُهم ويَعِدُهم حُسنَ السيرة إلى أن أجابوه على أن يقيمَ بالربض فأقام أسبوعًا، ثم وقع بين بعض أصحابِه وبين قومٍ من أهلِ الموصل شر، فرجعوا إلى الحَرب, وأخرجوه عنها، واستقرَّ يحيى بن سليمان بالموصِل."},{"id":866,"title":"الحرب بين أهل طليطلة وهوارة في الأندلس .","date":["العام الهجري :260","العام الميلادي :873"],"text":"ظهر موسى بن ذي النون الهواري بشنت برية، وأغار على أهل طليطِلة، ودخل حِصنَ وليد من شنت برية، فخرج أهل طليطِلة إليه في نحوِ عشرين ألفًا، فلمَّا التَقَوا بموسى واقتتلوا انهزم محمد بن طريشة في أصحابه، وهو من أهلِ طُليطِلة، فتَبعَه أهلُ طُليطِلة في الهزيمة، وانهزم معهم مُطَرِّف بن عبد الرحمن، فقُتِلَ من أهل طليطِلة خلقٌ كثيرٌ، وقَوِيَ موسى بن ذي النون، وهابه من حاذَرَه."},{"id":867,"title":"ثورة أبى روح على الدولة الطولونية بمصر .","date":["العام الهجري :260","العام الميلادي :873"],"text":"ظهر بمصر إنسانٌ يكنى أبا روحٍ، واسمه سكن، وكان من أصحاب ابن الصوفي، واجتمع له جماعةٌ، فقطع الطريق، وأخاف السبيلَ، فوَجَّه إليه ابن طولون جيشًا, فوقف أبو روحٍ في أرض كثيرةِ الشقوق، وقد كان بها قمحٌ فحُصِد، وبقي مِن تبنه على الأرضِ ما يستُرُ الشقوق، وقد ألِفُوا المشي على مثل هذه الأرضِ، فلما جاءهم الجيش لقوهم، ثم انهزم أصحابُ أبي روح، فتبعهم عسكرُ ابن طولون، فوقعت حوافِرُ خيولهم في تلك الشُّقوق، فسقط كثيرٌ مِن فرسانها عنها، وتراجع أصحابُ أبي روح عليهم، فقتلوهم شرَّ قِتلةٍ، وانهزم الباقون أسوأَ هزيمة، فسيَّرَ ابن طولون جيشًا إلى طريقِهم إلى الواحات، وجيشًا في طلبِ أبي روح، فلقيه الجيشُ الذي في طلبه وقد تحصَّنَ في مثل تلك الأرض، فحَذِرَها عسكرُ ابن طولون، فحين بطَلَت حِيَلُهم انهزموا وتَبِعَهم العسكر، فلما خرجوا إلى طريقِ الواحات رأى أبو روح الطريقَ قد مُلِكَت عليه، فراسل يطلُبُ الأمان، فبُذِلَ له، وبَطَلت الحربُ، وكُفِيَ المسلمونَ شَرَّه."},{"id":868,"title":"وفاة الحسن العسكري .","date":["العام الهجري :260","الشهر القمري : ربيع الأول","العام الميلادي :874"],"text":"هو أبو محمد الحسن العسكري بن علي الهادي بن محمد الجواد بن علي الرضا بن موسى الكاظم بن جعفر الصادق بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، هو الإمامُ الحادي عشر عند الشيعة الذين يدَّعون عِصمَتَهم, كان مولدُه بسامرَّا بلد العسكرِ، ومنها أخذ لقبه، وأمُّه أمُّ ولدٍ. توفِّيَ في سامرا وله تسع وعشرون سنة. ودُفِنَ إلى جانب والده. والحسَنُ العسكري هو والد محمَّد المهدي الذي تزعمُ الرافضة أنَّه الإمام المنتظَر الذي سيخرجُ من السرداب، ولِدَ سنة ثمان وخمسين، وقيل: سنة ست وخمسين. عاش بعد أبيه سنتين، ولم يُعلَم كيف مات. وهم يدَّعون بقاءَه في السرداب منذ عام 262ه، وأنَّه صاحِبُ الزمان، وأنه حيٌّ يعلَمُ عِلمَ الأوَّلينَ والآخرين، ويعتَرِفون أنَّ أحدًا لم يَرَه أبدًا، فنسأل اللهُ أن يثبِّتَ علينا عُقولَنا وإيمانَنا!!"},{"id":869,"title":"حرب أبي الساج للزنج في الأهواز .","date":["العام الهجري :261","العام الميلادي :874"],"text":"ولَّى المعتمِدُ أبا الساج الأهواز بعد مسيرِ عبد الرحمن بن مفلح عنها إلى فارس، وأمَرَه بمحاربة الزنج، فسيَّرَ صهره عبد الرحمن لمحاربة الزنج، فلَقِيه علي بن أبان المهلبي بناحية دولاب، فقُتِلَ عبد الرحمن، وانحاز أبو الساج إلى ناحية عسكر مكرم، ودخل الزِّنج الأهواز، فقتلوا أهلَها وسَبَوا وأحرَقوا، ثم انصرف أبو الساج عمَّا كان إليه من الأهواز، وحربِ الزنج، فوَلِيَها إبراهيم بن سيما فلم يزَلْ بها حتى انصرف عنها مع موسى بن بغا."},{"id":870,"title":"تجهيز مسرور البلخي لقتال خوارج الزنج .","date":["العام الهجري :261","العام الميلادي :874"],"text":"أمر الخليفةُ المعتَمِدُ الموفِّقَ أن يسيرَ إلى حرب الزنج؛ فولَّى الموفِّقُ الأهوازَ والبصرةَ وكور دجلة مسرورًا البلخيَّ، وسيَّرَه في مقدمته، وعزم على المسيرِ بعده، فحدَث من أمرِ يعقوبَ الصَّفَّار ما منعه عن المسيرِ."},{"id":871,"title":"إبراهيم بن أحمد الأغلب يتولى إمرة أفريقية .","date":["العام الهجري :261","العام الميلادي :874"],"text":"لَمَّا مات محمد بن أحمد بن الأغلب أبو الغرانيق، سار أهل القيروان إلى إبراهيم- الذي عينه أخوه أبو الغرانيق وصيًّا على ولده عِقالٍ حتى يكبَرَ- وسألوه أن يتولى أمرَهم؛ لحُسنِ سِيرتِه وعَدْلِه، فلم يفعَلْ، ثم أجاب، وانتقل إلى قصرِ الإمارة، وباشر الأمورَ، وقام بها قيامًا مَرضيًا، وكان عادلًا حازمًا في أموره، أمَّنَ البلاد، وقتل أهلَ البغي والفساد"},{"id":872,"title":"ابتداء أمر السامانيين بحكم بلاد ما وراء النهر .","date":["العام الهجري :261","العام الميلادي :874"],"text":"كان جدُّ السامانيين أسدُ بن سامان من أهل خراسان، وينتسبونَ إلى الفُرس تارة وإلى سامة بن لؤيِّ بن غالب أحيانًا, وكان لأسدِ بن سامان أربعةُ بنين: نوح وأحمد ويحيى وإلياس، وكان في خراسان حين استولى عليها المأمونُ، فأكرمهم المأمونُ أربعَتَهم وقَدَّمَهم واستعملهم، فتولى أحمدُ بن أسد فرغانةَ في سنة أربع ومائتين، ويحيى بن أسد الشاشَ مع أسروشنه، وإلياس بن أسد هراةَ، ونوح بن أسد سمرقندَ، ولَمَّا تولى طاهرُ بن الحسين خراسان أقرَّهم على الأعمال، ثم مات نوح ثم مات إلياس بهراة, وكان لأحمد بن أسدٍ سبعةُ بنين: نصر ويعقوب ويحيى وأسد وإسماعيل وإسحاق وحميد، ثم مات أحمد بن أسد، واستخلف ابنه نصرًا على أعمالِه بسمرقند وما وراءها، فبقي عاملًا عليها إلى آخِرِ أيام الطاهريَّة, وفي هذه السَّنة ولى الخليفةُ المعتمِد نصرَ بن أحمد بلادَ ما وراء النهر، فجعل سمرقند قاعدةَ مُلكِه، وكان إسماعيلُ بن أحمد يخدُم أخاه نصرًا، فولَّاه بُخارى."},{"id":873,"title":"عصيان أهل برقة على ابن طولون .","date":["العام الهجري :261","العام الميلادي :874"],"text":"عصيَ أهلُ بُرقةَ على أحمد بن طولون، وأخرجوا أميرَهم محمد بن الفرج الفرغاني، فبعث ابنُ طولون جيشًا عليه غلامُه لؤلؤ، وأمَرَه بالرِّفقِ بهم، واستعمالِ اللين، فإن انقادوا وإلَّا فالسَّيفُ، فسار العسكرُ حتى نزلوا على بُرقة، وحصروا أهلَها وفعلوا ما أمَرَهم من اللين، فطَمِعَ أهلُ برقة، وخرجوا يومًا على بعضِ العسكرِ، وهم نازلون على باب البلدِ، فأوقعوا بهم وقَتَلوا منهم. فأرسل لؤلؤ إلى صاحِبِه أحمد يعَرِّفُه الخبَرَ، فأمره بالجِدِّ في قتالهم، فنصَبَ عليهم المجانيق، وجَدَّ في قتالهم، وطلبوا الأمانَ فأمَّنَهم، ففتحوا له الباب، فدخل البلد وقبض على جماعةٍ من رؤسائهم، وضَرَبهم بالسياط، وقطعَ أيديَ بَعضِهم، وأخذ معه جماعةً منهم وعاد إلى مصر، واستعمل على برقة عامِلًا، وطِيفَ بالأسرى في البلدِ."},{"id":874,"title":"وفاة محمد بن أحمد الأغلب صاحب إفريقيا  .","date":["العام الهجري :261","الشهر القمري : جمادى الأولى","العام الميلادي :875"],"text":"هو أبو عبدالله محمد بن أحمد بن الأغلب، صاحبُ إفريقيَّة، المعروفُ بأبي الغرانيق؛ بسبب اهتمامه بصيد طيور الغرانيق، وُلد عام 237هـ، وكانت ولايته عشرَ سنين وخمسة أشهر وستة عشر يومًا من 250ه إلى 261هـ، كان عهدُه هادئًا زاهرًا, تمَّ في عهده تشييدُ سلسلةٍ من الحصون والمحارس الساحلية، غيرَ أنَّ الأغالبة مُنُوا بهزائمَ في عهده بجزيرة صقلية, وكانت إفريقيةُ في عهد أبي الغرانيق مزدهرةً تعيش نهضةً كاملة، وكانت خزائنُ الأمير عامرةً، وقد كان أبو الغرانيق عادلًا طيبًا نحو رعاياه, فكان غايةً في الجود، مسرفًا في العطاء، حسَنَ السيرة في الرعيَّة، رفيقًا بهم، غيرَ أنه عاش حياةَ عبث ولهو, ولَمَّا حضره الموت عقدَ لابنِه عِقالٍ العَهدَ، واستخلف أخاه إبراهيم لئلَّا ينازِعَه، وأشهَدَ عليه آل الأغلب ومشايخَ القيروان، وأمره أن يتولى الأمرَ إلى أن يكبَرَ ولَدُه."},{"id":875,"title":"وفاة الإمام مسلم بن الحجاج صاحب الصحيح .","date":["العام الهجري :261","الشهر القمري : رجب","العام الميلادي :875"],"text":"هو مُسلِمُ أبو الحسَنِ القُشيري النيسابوري، أحدُ الأئمَّة من حُفَّاظ الحديثِ، صاحبُ الصحيح الذي يلي صحيحَ البخاري، انتقل إلى العراقِ والحجاز والشَّام ومصر، وسمع من جماعةٍ كثيرين، وقد أثنى عليه جماعةٌ من العلماء من أهل الحديث وغيرهم. قال أحمد بن سلمة: \"رأيت أبا زُرعة وأبا حاتم يُقَدِّمان مسلمَ بن الحجاج في معرفةِ الصَّحيحِ على مشايخ عصرهما\"، وقيل: كان سببُ مَوتِه- رحمه الله- أنَّه عُقِدَ مَجلِسٌ للمذاكرة فسُئلَ يومًا عن حديثٍ فلم يعرِفْه، فانصرف إلى منزلِه، فأوقد السراجَ وقال لأهله: لا يدخُلْ أحدٌ الليلة عليَّ، وقد أُهدِيَت له سلةٌ مِن تمرٍ، فهي عنده يأكلُ تمرةً ويكشِفُ عن حديثٍ ثم يأكُلُ أخرى ويكشِفُ عن آخر، فلم يزَلْ ذلك دأبَه حتى أصبح وقد أكل تلك السلَّة وهو لا يشعُرُ، فحصل له بسبب ذلك ثقلٌ ومرَضٌ من ذلك، حتى كانت وفاته عشيةَ يوم الأحد، ودُفِن يوم الاثنين بنيسابور."},{"id":876,"title":"عودة يعقوب الصفار إلى بلاد فارس  .","date":["العام الهجري :261","الشهر القمري : ذي القعدة","العام الميلادي :875"],"text":"حصَلَت وقعةٌ بين محمد بن واصل بن إبراهيم التميمي- الذي تغلَّبَ على فارس- وعبدالرحمن بن مفلح، فكسره ابنُ واصل وأسَرَه وقتَلَ مُعظَمَ جَيشِه فلم يُفلِتْ منهم إلَّا اليسيرُ، فلما وصل خبَرُهما إلى يعقوب الصفَّار وهو بسجستان، تجدَّدَ طَمَعُه في ملك بلاد فارس، وأخذ الأموالَ والخزائن والسِّلاح التي غَنِمَها من ابن مفلح، فسار مجدًّا, وبلغ ابنُ واصل خبَرَ قُربه منه وأنه نزل البيضاءَ من أرض فارس، وهو بالأهواز، فعاد عنها لا يلوي على شيءٍ، وأرسل خالَه أبا بلال مرداسًا إلى الصفَّار، فوصل إليه، وضَمِنَ له طاعةَ ابن واصل، فأرسل يعقوبُ الصفَّار إلى ابن واصلٍ كُتبًا ورُسلًا، فحبسهم ابنُ واصل، وسار يطلبُ الصَّفَّار والرسُل معه يريدُ أن يُخفي خبَرَه، وأن يصِلَ إلى الصفَّار بغتةً، فينال منه غرَضَه، ويوقِعَ به, فسار في يومٍ شديدِ الحر، في أرضٍ صعبة المسلك، وهو يظُنُّ أن خبَرَه قد خفي عن الصفَّار، فلما كان الظهرُ تَعِبَت دوابُّهم، فنزلوا ليستريحوا، فمات من أصحاب ابن واصل من الرَّجالة كثيرٌ؛ جوعًا وعطشًا، وبلغ خبَرُهم الصفَّار، فجمع أصحابَه وأعلمهم الخبر وسار إلى ابنِ واصل، فلمَّا قاربهم وعلموا به انخذلوا وضَعُفَت نفوسُهم عن مقاومته ومقاتَلتِه، ولم يتقَدَّموا خطوة، فلما صار بين الفريقين رميةُ سهم، انهزم أصحابُ ابن واصل من غير قتالٍ، وتَبِعَهم عسكر الصفَّار، وأخذوا منهم جميعَ ما غَنِموه من ابن مُفلح، واستولى على بلاد فارس، ورتَّبَ بها أصحابَه وأصلح أحوالَها, ومضى ابن واصلٍ مُنهزمًا فأخذ أموالَه من قلعته، وكانت أربعين ألف ألف درهمٍ، وأوقع يعقوبُ بأهل زم؛ لأنهم أعانوا ابن واصلٍ."},{"id":877,"title":"هزيمة أصحاب الزنجي على يد جند الخليفة  .","date":["العام الهجري :262","العام الميلادي :875"],"text":"كانت وقعة للزنوج مع أحمد بن ليثويه، وكان سببَها أنَّ مسرورًا البلخيَّ وجه أحمد بن ليثويه إلى كور الأهواز، فنزل السوس، وكان يعقوبُ الصفَّار قد قلَّدَ محمد بن عبيد الله بن هزارمرد الكردي كورَ الأهواز، فكاتَبَ محمد قائدَ الزنجِ يُطمِعُه في الميلِ إليه، وأوهَمَه أنَّه يتولى له كور الأهواز. وكان محمَّد يكاتِبُه قديمًا، وعزم على مداراة الصفَّار، وقائد الزِّنج، حتى يستقيمَ له الأمرُ فيها، فكاتبه صاحِبُ الزنج يجيبه إلى ما طلبَ، على أن يكون عليُّ بن أبان المتوليَ للبلاد، ومحمد بن عبيد الله يخلُفُه عليها، فقَبِلَ محمد ذلك، فوجه إليه عليُّ بن أبان جيشًا كثيرًا وأمَدَّهم محمد بن عبيد الله، فساروا نحو السوس، فمنعهم أحمدُ بن ليثويه ومن معه من جندِ الخليفة عنها وقاتَلَهم فقَتَل منهم خلقًا كثيرًا وأسَرَ جماعة. وسار أحمد حتى نزل جنديسابور، وسار علي بن أبان من الأهواز ممدًّا محمد بن عبيد الله على أحمد بن ليثويه، فلقِيَه محمد في جيشٍ كثير من الأكراد والصعاليك، ودخل محمَّد تسترَ، فانتهى إلى أحمد بن ليثويه الخبَرُ بتضافُرِهما على قتاله، فخرج عن جنديسابور إلى السوس. ودخل أحمد تستر، وأتت الأخبارُ عليَّ بن أبان بأنَّ أحمد على قَصْدِك، فسار إلى لقائِه ومحاربته، فالتقيا واقتتل العسكران، فاستأمن إلى أحمد جماعةٌ من الأعراب الذين مع علي بن أبان، فانهزم باقي أصحابِ علي، وثبَتَ معه جماعةٌ يسيرة، واشتد القتالُ، وترجَّلَ علي بن أبان وباشر القتالَ راجلًا، فعرفه بعضُ أصحاب أحمد فأنذر النَّاسَ به، فلما عرفوه انصرف هاربًا وألقى نفسَه في نهر المسرقان، فأتاه بعضُ أصحابه بسميرية (سفينة حربيَّة صغيرة) فركِبَ فيها ونجا مجروحًا وقُتِلَ من أبطال أصحابِه جماعةٌ كثيرة."},{"id":878,"title":"الأندلسيون يؤسسون مدينة تنس بساحل أفريقية .","date":["العام الهجري :262","العام الميلادي :875"],"text":"(تنس) مدينةٌ تقع بالقُربِ من مليانة بينهما بحرُ ميلان، أسَّسَها وبناها البحريونَ من أهل الأندلس، وهي مُسَوَّرة حصينة، وبعضُها على جبلٍ وقد أحاط به السُّور، وبعضُها في سهلِ الأرض، وهي قديمةٌ، ويشرب أهلُها من عينٍ عذبة تُعرَفُ بعين عبدالسلام، وبها فواكِهُ وخِصبٌ وإقلاعٌ وانحطاط، ولها أقاليمُ وأعمالٌ ومزارِعُ. أصبحت تنس جمهورية مستقلَّةً مع قدوم قبيلة السَّواد العربية."},{"id":879,"title":"دخول يعقوب الصفار لمدينة واسط وقتاله مع العباسيين .","date":["العام الهجري :262","الشهر القمري : رجب","العام الميلادي :876"],"text":"قدم يعقوبُ بن الليث في جحافِلَ فدخل واسط قهرًا، فخرج الخليفة المعتَمِدُ بنفسه من سامرَّا لقتاله، فتوسط بين بغداد وواسط، فانتدب له أبو أحمد الموفَّق بالله- أخو الخليفة- في جيشٍ عظيم على ميمنتِه موسى بن بغا، وعلى ميسرته مسرورٌ البلخي، فتقاتلوا قتالًا شديدًا، وقد ظهر من أصحابِ يعقوب كراهةٌ للقتال معه؛ إذ رأوا الخليفةَ يُقاتِلُه، فحملوا على يعقوبَ ومَن قد ثبت معه للقتالِ، فانهزم أصحابُ يعقوب، وثبت يعقوبُ في خاصَّةِ أصحابه، حتى مَضَوا وفارقوا موضِعَ الحرب، وتَبِعَهم أصحاب الموفَّق، فغَنِموا ما في عسكرهم، وكان فيه من الدوابِّ والبغال أكثَرُ من عشرة آلاف، ومن الأموالِ ما يُكَلُّ عن حَملِه، ومِن جُرُب المِسك أمرٌ عظيمٌ، وتخلَّصَ محمد بن طاهر من الأسر، وكان مُثقَلًا بالحديد، وخلع عليه الموفَّق، وولَّاه الشرطةَ ببغداد بعد ذلك."},{"id":880,"title":"الخليفة العباسي المعتمد يعهد بالخلافة لابنه جعفر .","date":["العام الهجري :262","الشهر القمري : شوال","العام الميلادي :876"],"text":"ولَّى المعتمِدُ على الله وَلَدَه جعفرًا العهدَ من بعدِه، وسماه المفوِّضَ إلى الله، وولاه المغرِبَ، وضمَّ إليه موسى بن بغا ولايةَ إفريقية ومصر والشام والجزيرة والموصل وأرمينية وطريق خراسان وغير ذلك، وجعل الأمرَ مِن بعد ولَدِه لأبي أحمد المتوكِّل، ولَقَّبَه الموفَّق بالله، وولاه المشرِقَ وضم إليه مسرورًا البلخي وولَّاه بغداد والسواد والكوفة وطريق مكة والمدينة واليمن وكسكر وكور دجلة والأهواز وفارس وأصبهان والكرخ والدينور والري وزنجان والسند، وكتب بذلك مكاتباتٍ وقُرِئَت بالآفاق، وعَلَّقَ منها نُسخةً بالكعبة."},{"id":881,"title":"تسليم أهل أنطاكية حصن لؤلؤة إلى الروم .","date":["العام الهجري :263","العام الميلادي :876"],"text":"كان سببَ ذلك أنَّ أحمد بن طولون قد أدمن الغزوَ بطرسوس قبل أن يليَ مصر، فلمَّا ولِيَ مِصرَ كان يؤثِرُ أن يلي طرسوس ليغزوَ منها أميرًا، فكتب إلى أبي أحمدَ الموفَّق يطلُبُ ولايتَها، فلم يجبه إلى ذلك، واستعمل عليها محمد بن هارون التغلبي، فركب في سفينةٍ في دجلة فألقتها الريحُ إلى الشاطئ، فأخذه أصحابُ مساور الشاري فقتلوه، واستعمَلَ عِوَضَه محمد بن علي الأرمني، وأضيفَ إليه أنطاكية، فوثب به أهلُ طرسوس فقتلوه، فاستعمل عليها أرخوز بن يولغ بن طرخان التركي، فسار إليها وكان غِرًّا جاهلا فأساء السِّيرة، وأخَّرَ عن أهل لؤلؤة أرزاقَهم ومِيرتَهم، فضَجُّوا من ذلك، وكتبوا إلى أهل طرسوس يشكُونَ منه ويقولون: إن لم تُرسلوا إلينا أرزاقَنا ومِيرَتَنا وإلَّا سَلَّمْنا القلعةَ إلى الروم. فأعظم ذلك أهلُ طرسوس وجمعوا من بينهم خمسةَ عشر ألف دينار ليحمِلوها إليهم، فأخذها أرخوز ليحمِلَها إلى أهل لؤلؤة، فأخذها لنَفسِه، فلما أبطأ عليهم المالُ سَلَّموا القلعة إلى الروم، فقامت على أهلِ طرسوس القيامةُ؛ لأنَّها كانت شبحًا في حَلقِ العَدُوِّ، ولم يكن يخرجُ للروم في بَرٍّ أو بحر إلَّا رأوه وأنذروا به؛ واتَّصل الخبَرُ بالمعتمِد، فقَلَّدَها أحمد بن طولون، واستعمل عليها من يقومُ بغزو الروم ويحفَظُ ذلك الثَّغرَ."},{"id":882,"title":"بناء جامع أحمد بن طولون بمصر .","date":["العام الهجري :263","العام الميلادي :876"],"text":"أقام أحمد بن طولون مسجدًا ضخمًا أنفق في بنائه 120 ألف دينار، وقد اهتمَّ بالأمور الهندسية في بنائه، ويُعَدُّ مسجد ابن طولون المسجِدَ الوحيدَ بمصرَ الذي غلَبَ عليه طرازُ سامِرَّاء؛ حيث المئذنةُ الملوية المُدرَّجة. وقام السلطان لاجين بإدخالِ بعض الإصلاحات فيه، وعيَّنَ لذلك مجموعةً من الصناع، كما أمر بصناعةِ ساعة فيه، فجُعِلَت قبةً فيها طيقانٌ صغيرة على عددِ ساعاتِ الليل والنهار وفتحة، فإذا مَرَّت ساعة انغلقت الطاقةُ التي هي لتلك الساعة وهكذا، ثم تعود كلَّ مرة ثانية. وفي عهد الأيوبيين أصبح جامع ابن طولون جامعةً تُدَرَّسُ فيه المذاهِبُ الفقهيَّة الأربعة، وكذلك الحديثُ والطِّبُّ، إلى جانب تعليم الأيتام, وكان أحمد بن طولون قد بنى قصره عند سَفحِ المقَطَّم، وأنشأ الميدانَ أمامه، وبعد أن انتهى من تأسيس مدينة القطائع، شَيَّد جامِعَه على جبل يشكر, وتمَّ بناؤه سنة 265ه، وهذا التاريخُ مُدَوَّن على لوحٍ رُخاميٍّ مُثبت على أحدِ أكتاف رُواق القبلة, والجامِعُ وإن كان ثالِثَ الجوامِعِ التي أُنشِئَت بمصر، يعَدُّ أقدَمَ جامِعٍ احتفظَ بتخطيطِه وكثيرٍ مِن تفاصيلِه المعماريَّة الأصليَّة."},{"id":883,"title":"ذكر الفتنة ببلاد الصين .","date":["العام الهجري :264","العام الميلادي :877"],"text":"ظهرَ ببلادِ الصين إنسانٌ لا يُعرَفُ، فجمع جمعًا كثيرًا من أهل الفَسادِ والعامَّة، فأهمل المَلِكُ أمْرَه؛ استصغارًا لشأنه، فقَوِيَ وظهر حالُه وكَثُف جَمعُه؛ وقَصَده أهلُ الشَّرِّ من كل ناحية، فأغار على البلادِ وأخرَبَها ونزل على مدينةِ خانقوا وحَصَرها، وهي حصينةٌ، ولها نهرٌ عظيم، وبها عالِمٌ كثير من المسلمين، والنصارى، واليهود، والمجوس، وغيرهم من أهل الصينِ، فلما حصَرَ البلدَ اجتمعت عساكرُ المَلِك وقَصَدته، فهزمها وافتتح المدينةَ عَنوةً، وبذل السَّيفَ، فقتل منهم ما لا يُحصى كثرةً، ثم سار إلى المدينة التي فيها المَلِك، وأراد حصارَها فالتقاه مَلِكُ الصين، ودامت الحربُ بينهم نحوَ سنة، ثم انهزم المَلِك، وتَبِعَه الخارجيُّ إلى أن تحصَّنَ منه في مدينة من أطراف بلاده، واستولى الخارجيُّ على أكثَرِ البلاد والخزائن، وعَلِمَ أنَّه لا بقاء له في المُلْك؛ إذ ليس هو من أهلِه، فأخرب البلادَ، ونهب الأموالَ، وسَفَك الدماءَ، فكاتَبَ مَلِكُ الصين ملوكَ الهندِ يستَمِدُّهم، فأمَدُّوه بالعساكرِ، فسار إلى الخارجيِّ، فالتقوا واقتتلوا نحوَ سنة أيضًا، وصبَرَ الفريقان، ثمَّ إنَّ الخارجيَّ عُدِمَ، فقيل: إنَّه قُتِل، وقيل: بل غَرِق، وظفَرَ المَلِكُ بأصحابه وعاد إلى مملكته، ولقب ملوك الصين يعفور، ومعناه ابنُ السماء؛ تعظيمًا لشأنه؛ وتفَرَّق المُلك عليه، وتغَلَّبت كل طائفة على طرفٍ من البلاد، وصار الصينُ على ما كان عليه ملوكُ الطوائف يُظهِرون له الطاعة، وقنع منهم بذلك، وبَقِيَ على ذلك مدةً طويلةً."},{"id":884,"title":"استيلاء ابن طولون على الشام .","date":["العام الهجري :264","العام الميلادي :877"],"text":"توفِّيَ أماجور والي دمشق، فتولى ابنُه مكانَه، فتجهَّزَ ابنُ طولون ليسيرَ إلى الشام فيَملِكَه، فكتب إلى ابن أماجور له أنَّ الخليفة قد أقطعه الشَّامَ والثغور، فأجابه بالسَّمعِ والطاعة، وسار أحمد، واستخلف بمصرَ ابنَه العباس، فلقيه ابن أماجور بالرملة، فأقره عليها وسار إلى دمشق فمَلَكَها وأقرَّ أماجور على أقطاعِهم، وسار إلى حمص فملَكَها وكذلك حماة، وحلب. وراسلَ سيما الطويل بأنطاكية يدعوه إلى طاعتِه ليُقِرَّه على ولايته، فامتنع، فعاوده فلم يُطِعْه، فسار إليه أحمد بن طولون، فحَصَره بأنطاكيَّة، وكان سيئَ السيرة مع أهل البلد، فكاتبوا أحمد بن طولون، ودلُّوه على عورة البلد، فنصَبَ عليه المجانيقَ وقاتَلَه، فمَلَك البلدَ عَنوةً، والحِصنَ الذي له، وركب سيما وقاتلَ قتالًا شديدًا حتى قُتِل ولم يعلَمْ به أحدٌ، فاجتاز به بعضُ قوَّاده، فرآه قتيلًا فحمَلَ رأسَه إلى أحمد، فساءه قَتلُه. ورحل عن أنطاكية إلى طرسوس، فدخلها وعزم على المُقام بها وملازمة الغُزاة، فغلا السِّعرُ بها وضاقت عنه وعن عساكِرِه، فركب أهلُها إليه بالمخيم وقالوا له: قد ضَيَّقْتَ بلَدَنا وأغليتَ أسعارَنا؛ فإمَّا أقمْتَ في عددٍ يَسيرٍ، وإمَّا ارتحلْتَ عنَّا، وأغلظوا له القولَ، وشَغَّبوا عليه، فقال أحمد لأصحابه: لتنهَزِموا من الطرسوسيين، وترحلوا عن البلد، ليظهَرَ للنَّاسِ وخاصةً العدُوَّ أنَّ ابن طولون على بُعدِ صِيتِه وكثرةِ عَساكِرِه لم يقدِرْ على أهل طرسوس؛ وانهزم عنهم ليكونَ أهيبَهم في قلبِ العَدُو، وعاد إلى الشام. فأتاه خبَرُ ولده العباس- وهو الذي استخلفه بمصرَ- أنه قد عصي عليه، وأخذ الأموالَ وسار إلى بُرقة مُشاقًّا لأبيه، فلم يكتَرِثْ لذلك، ولم ينزعِجْ له، وثبتَ وقضى أشغاله، وحَفِظَ أطراف بلاده، وتَركَ بحرَّانَ عسكرًا وبالرِّقَّة عسكرًا مع غلامِه لؤلؤ، وكان حرَّان لمحمد بن أتامش، وكان شجاعًا فأخرجه عنها وهزمه هزيمةً قبيحةً، فلمَّا بلغ خبَرُه أخاه موسى بن أتامش، وكان شُجاعًا بطلًا فجمع عسكرًا كثيرًا وسار نحو حَرَّان، وبها عسكَرُ ابن طولون، ومُقَدَّمُهم أحمد ابن جيعويه، فلما وصله خبَرُ مسيرِ موسى أقلقَه ذلك وأزعجه، ففَطِنَ له رجلٌ مِن الأعرابِ، يقال له أبو الأغر، فقال له: أيُّها الأميرُ، أراك مفكِّرًا منذ أتاك خبَرُ ابن أتامش، وما هذا محلَّه؛ فإنَّه طيَّاشٌ قَلِقٌ، ولو شاء الأميرُ أن آتيَه به أسيرًا لفعلتُ، فغاظه قولُه، وقال: قد شئتُ أن تأتيَ به أسيرًا؛ قال: فاضمُمْ إليَّ عشرينَ رجلًا أختارُهم، قال: افعَلْ، فاختار عشرينَ رجلًا وسار بهم إلى عسكر موسى، فلمَّا قاربَهم كَمَنَ بعضُهم، وجعل بينه وبينهم علامةً إذا سَمِعوها ظهروا. ثم دخل العسكرَ في الباقينَ في زي الأعرابِ، وقارب مُضارَب موسى، وقصد خيلًا مربوطةً فأطلَقَها وصاح هو وأصحابُه فيها فنَفَرت، وصاح هو ومَن معه من الأعراب، وأصحابُ موسى غارُّون، وقد تفَرَّق بعضُهم في حوائجهم، وانزعج العسكَرُ، ورَكِبوا ورَكِبَ موسى، فانهزم أبو الأغَرِّ من بين يديه، فتَبِعَه حتى أخرجه من العسكرِ، وجاز به الكمينَ، فنادى أبو الأغَرِّ بالعلامة التي بينهم، فثاروا من النواحي، وعطفَ أبو الأغرِّ على موسى فأسَروه، فأخذوه وساروا حتى وصلوا إلى ابنِ جيعويه، فعَجِبَ الناس من ذلك، فسيَّرَه ابن جيعويه إلى ابن طولون، فاعتَقَله وعاد إلى مصر."},{"id":885,"title":"أميرَ صقليَّة جعفر بن محمد يغزو مدينة سرقوسة .","date":["العام الهجري :264","الشهر القمري : رمضان","العام الميلادي :878"],"text":"في هذه السنةِ ملَكَ المُسلِمونَ سَرقوسة- وهي من أعظمِ مُدُنِ صَقَليَّة- وكان سببَ مِلكِها أنَّ جعفرَ بنَ محمد أميرَ صقليَّة غزاها فأفسَدَ زَرعَها وزَرْعَ قطانية، وطبرمين، ورمطة، وغيرِها من بلاد صقليَّة التي بيَدِ الروم، ونازل سرقوسة، وحصَرَها برًّا وبحرًا وملَكَ بعضَ أرباضها، ووصَلَت مراكِبُ الرومِ نَجدةً لها، فسيَّرَ إليها أسطولًا فأصابوها وتمكَّنوا حينئذٍ مِن حَصرِها فأقام العسكرُ مُحاصَرًا لها تسعة أشهر، وفُتِحَت، وقُتِلَ من أهلها عِدَّةُ ألوفٍ، وأصيبَ فيها من الغنائِمِ ما لم يُصَبْ بمدينةٍ أخرى، ولم ينجُ مِن رجالِها إلا الشاذَّ الفَذَّ، وأقاموا فيها بعدَ فتحها بشهرين، ثم هَدَموها ثمَّ وصل بعدَ هَدمِها من القسطنطينية أسطولٌ، فالتقَوا بالمسلمين، فظفِرَ بهم المسلمون، وأخذوا منهم أربعَ قِطَع، فقَتَلوا من فيها، ثم انصرف المسلمون إلى بلدِهم آخِرَ ذي القَعدة."},{"id":886,"title":"وفاة المزني صاحب الشافعي .","date":["العام الهجري :264","الشهر القمري : رمضان","العام الميلادي :878"],"text":"هو أبو إبراهيمَ إسماعيلُ بن يحيى بن إسماعيل بن عمرو بن مسلمٍ المُزِني المصري، وُلِدَ بالفُسطاط في مصر في سنة 175ه. صاحِبُ الشافعيِّ، تفَقَّه عليه بمصرَ، ويعَدُّ من أئمَّة الحديث والفقه، كان من المقَدَّمين من أصحاب الشافعي وأعرَفِهم بمذهبه، حتى قال الشافعي: \"المُزنيُّ ناصِرُ مذهبي\"، ألَّفَ كتُبًا تُعتبَرُ مدارَ المذهب الشافعي، منها الجامع الصغير، ومختصر المختصر، والمنثور، والمسائل المعتبَرة، والترغيب في العِلم، وكتاب الوثائق، وغير ذلك، وكان إذا فرغَ مِن مسألة وأودعها مختَصرَه قام إلى المحرابِ وصلَّى ركعتين شكرًا لله تعالى, وقد امتلأت البلادُ بـ (مُختَصَره) في الفقه، وشرَحَه عِدَّةٌ مِن الكبارِ، وبلغ من انتشارِه أنَّ البِكرَ كان يكونُ في جَهازِها نُسخةٌ مِن مُختَصَر المُزنيِّ، كانت له عبادةٌ وفَضلٌ، وهو ثِقةٌ في الحديثِ، لا يُختَلَف فيه, حاذِقٌ من أهل الفقه، كان زاهدًا مجتهدًا، له مناظراتٌ، وكان قويَّ الحُجَّة، توفِّي بمصرَ."},{"id":887,"title":"وفاة أبي زرعة الرازي\n \n  .","date":["العام الهجري :264","الشهر القمري : ذي الحجة","العام الميلادي :878"],"text":"هو أبو زرعة عُبَيد الله بن عبد الكريم الرازي، أحدُ الحُفَّاظ المشهورين. كان مولِدُه في الريِّ بإيران سنة مائتين، وقيل سنة تسعين ومائة, من كبار الحُفَّاظ وسادات أهلِ التقوى. قيل: إنَّه كان يحفَظُ سِتَّمائة ألفِ حديثٍ، وكان فقيهًا وَرِعًا زاهِدًا عابدًا متواضِعًا خاشعًا، أثنى عليه أهلُ زمانه بالحفظِ والدِّيانة، وشَهِدوا له بالتقَدُّم على أقرانه، قال أحمد بن حنبل: \"ما عبَرَ جِسرَ بغداد أحفَظُ من أبي زُرعة\", قال أبو حاتم: \"لم يُخلِّفْ بعده مِثلَه، فِقهًا وعِلمًا وصِيانةً وصِدقًا. وهذا ممَّا لا يُرتابُ فيه, ولا أعلَمُ في المشرِقِ والمغربِ من كان يفهَمُ هذا الشَّأنَ مِثلَه\", وقال إسحاقُ بنُ راهَوَيه: \"كلُّ حديثٍ لا يحفَظُه أبو زُرعةَ، فليس له أصلٌ\"."},{"id":888,"title":"إنهاء ابن طولون تمرد ابنه العباس عليه .","date":["العام الهجري :265","العام الميلادي :878"],"text":"كان ابنُ طولون قد استخلفَ على مصرَ ابنَه العبَّاسَ، وهو متَّجِهٌ إلى الشَّامِ، فخالف العباسُ أباه،  فلما بلغه قدومُ أبيه عليه من الشامِ أخذ ما كان في بيتِ المال من الحواصِلِ ووازره جماعةٌ على ذلك، ثم ساروا إلى بُرقة خارجًا عن طاعة أبيه، فبعث إليه من أخذه ذليلًا حقيرًا، وردُّوه إلى مصر، فحَبَسه وقتَلَ جماعةً مِن أصحابه."},{"id":889,"title":"زعم الشيعة الإمامية اختفاء الإمام الثاني عشر .","date":["العام الهجري :265","العام الميلادي :878"],"text":"هو محمَّد المهدي بن الحسن العسكري بن علي الهادي بن محمد الجواد بن علي الرضا بن موسى الكاظم بن جعفر الصادق بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، ولد بسامرَّا، وهو المهديُّ المنتظَرُ عند الرافضة، يقولون إنَّه دخل في سردابٍ في بيت والده ولم يخرُج منه، وزعموا أنَّه سيخرج في آخر الزمان بنفس العمُرِ الذي دخل فيه السرداب، وهم ينتظرونَه إلى اليومِ عند السرداب المزعوم. قيل: إنه دخل وعمُره تسعُ سنين، وقيل: تسع عشر سنة. وقيل: إنَّ أباه الحسن مات عن غيرِ عَقِبٍ، وقيل: وُلِدَ له ولدٌ بعد موتِه مِن جارية اسمها \"نرجس\" أو \"سوسن\" وقيل: إن اسمَها  \"صقيل\" ادَّعَت الحملَ به بعد وفاةِ سَيِّدها, فزادت فتنةُ الرافضة بصقيل هذه، وبدَعواها، إلى أن حبسها المعتضِدُ بعد نيِّف وعشرين سنة من موت سَيِّدها، وبقيت في قصره إلى أن ماتت في زمن المقتَدِر؛ قال الذهبي: \"نعوذ بالله من زوالِ العَقلِ، فلو فرَضْنا وقوعَ ذلك في سالفِ الدَّهرِ، فمن الذي رآه؟! ومن الذي نعتَمِدُ عليه في إخباره بحياته؟ ومن الذي نصَّ لنا على عصمتِه وأنَّه يعلمُ كلَّ شَيءٍ؟! هذا هَوَسٌ بيِّنٌ، إنْ سَلَّطْناه على العقولِ ضَلَّت وتحيَّرَت، بل جَوَّزَت كلَّ باطلٍ، أعاذنا اللهُ وإياكم من الاحتجاجِ بالمُحالِ والكَذِب، أو رَدِّ الحقِّ الصحيحِ، كما هو ديدَنُ الإماميَّةِ، وممن قال: إنَّ الحسن العسكري لم يُعقِب: محمد بن جرير الطبري، ويحيى بن صاعد، وناهيك بهما معرفةً وثِقةً\".."},{"id":890,"title":"استكمال أحمد بن طولون سيطرته على الشام .","date":["العام الهجري :265","الشهر القمري : محرم","العام الميلادي :878"],"text":"حاصرَ أحمدُ بن طولون نائِبُ الدِّيارِ المصريةِ مدينةَ أنطاكيةَ وفيها سيما الطويلُ، فأخذها منه وجاءته هدايا مَلِكُ الروم، وفي جُملتِها أُسارى من أُسارى المسلمين، ومع كلِّ أسيرٍ مُصحَفٌ، منهم عبد الله بن رشيد بن كاوس، الذي كان عامِلَ الثغورِ، فاجتمع لأحمد بن طولون مُلكُ الشَّامِ بكمالِه مع الدِّيارِ المصريةِ؛ لأنَّه لَمَّا مات نائِبُ دمشق أماخور ركِبَ ابنُ طولون من مصرَ فتلقَّاه ابن أماخور إلى الرملة، فأقَرَّه عليها، وسار إلى دمشق فدخَلَها، ثمَّ إلى حمص فتسَلَّمَها، ثمَّ إلى حلب فأخذها، ثم أكملَ ابنُ طولون استيلاءَه على الشام باستيلائِه على أنطاكية."},{"id":891,"title":"غزو بطارقة الروم مدينة أذنة بالشام .","date":["العام الهجري :265","الشهر القمري : جمادى الأولى","العام الميلادي :879"],"text":"خرج خمسةٌ من بطارقة الروم في ثلاثين ألفًا من الروم إلى أذنة- وهي مدينة بالشامِ بناها الرشيدُ، وأتمها الأمينُ، بين طرسوس والمصيصة- وأهلُ أذنة أخلاطٌ من موالي الخلفاء وغيرِهم، وهي مدينةٌ جليلة عامرة ذاتُ أسواقٍ وصناعاتٍ وصادرٍ ووارد، وهي ثغرُ سيحان، فصاروا إلى المصلَّى وأسَروا أرخوز، كان واليَ الثُّغورِ، ثم عُزِلَ فرابَطَ هناك- فأُسِرَ وأسِرَ معه نحوٌ من أربعمائة رجلٍ، وقَتَلوا ممَّن نفر إليهم نحوًا من ألف وأربعمائة رجلٍ، ثم انصرفوا."},{"id":892,"title":"وفاة يعقوب بن الليث مؤسس الدولة الصفارية .","date":["العام الهجري :265","الشهر القمري : شوال","العام الميلادي :879"],"text":"هو الملك أبو يوسف يعقوب بن الليث الصفَّار الخارجي- خرج على سلطانِ الخلافةِ- التُّركمانيُّ، من سجستان، أصلُه فارسي ينحدِرُ من جبال شرق فارس، أسَّسَ السُّلالةَ الصفَّاريَّة التي حكَمَت فارس وبلاد ما وراء النهر. وقد أكثَرَ أهلُ التاريخ مِن ذِكرِ هذا الرجل وذِكرِ أخيه عمرو وما ملكا من البلادِ وقتلا من العبادِ، وما جرى للخلفاءِ معهما من الوقائع، كان رجلًا عاقلًا حازمًا, وكان أوَّلَ أمْرِه أنه وأخاه عَمرًا صفَّارانِ في حداثتِهما، يعملان في النُّحاس، وكانا يُظهِران الزهد، فجاهدا مع صالح المُطَّوِّعِي المحاربِ للخوارج،  فصَحِبَه إلى أن مات، فتولَّى مكان صالح المطوعي درهمُ بن الحسين المطوعي، فجعل درهمُ يعقوبَ بن الليث قائدًا لعسكره، ثمَّ رأى أصحاب درهم عجْزَه، فملَّكوا يعقوبَ لحُسنِ سياستِه، فأذعَنَ لهم دِرهَم،  واشتَهَرت صولةُ يعقوب، فغَلَب على هراة وبوشنج، وحارب الترك، وظفِرَ بِرُتْبِي، فقتله، وقتل ثلاثةَ ملوك ورجع معه ألوفٌ من الرؤوس، فهابته الملوك, وكان بوجهِه ضربةُ سيف مُخَيَّطَة. أظهر يعقوبُ حرصه على تدعيم مُلكِه؛ حيث اهتمَّ بتدبير أمور مملكتِه وتحصينِها وعمارة أرضه، فكثرت أموالُه وعَمَرت خزائنُه, ثم أعلن نفسَه حاكمًا على موطِنِه في سجستان (بلوشستان). ثم ضمَّ إليه المناطِقَ التي حكمها الطاهريون: هراة، وفارس، وشيراز، وبلخ, ثم طخرستان, حتى انتهى الأمرُ بأن قام بإجلائهم عن خراسان وأفغانستان. فعيَّنَه الخليفةُ المعتزُّ واليًا على المناطق التي سيطر عليها, فأخذ يعقوبُ يبعث هداياه إلى المعتز لمُداراته، ثم صار يرسِلُ للمعتَمِد في العام خمسةَ آلاف ألف درهم، ثمَّ أخذ بلخَ ثم نيسابور، وقصَدَ جرجان، فهزم المُتغلِّبَ عليها الحسن بن زيد العلوي، ثم دخل جرجان، فظَلَم وعَسَف، فاستغاث جماعةٌ جرجانيون ببغداد من يعقوب، فعزم المعتَمِد على حربه، ونفَّذَ كتبًا إلى أعيان خراسان بذمِّ يعقوب، وأن يهتمُّوا لاستئصاله، فكاتبَ يعقوبُ المعتَمِد يخضَعُ ويُراوغ، ويطلُبُ التقليدَ بتوليته المَشرِق، ففعل المعتمِدُ ذاك وأخوه الموفِّقُ؛ لاشتغالهم بحرب الزَّنْج. كان يعقوبُ قد افتتح الرخج، وقتَلَ مَلِكَها وأسلم أهلُها على يده، وافتتح الخلجية وزابل وغيرهما. بعد أن غلب يعقوبُ الصفَّار على سجستان ونيسابور والديلم وفارس، طَمِعَ في بغداد فأقبل عليها غازيًا، فقابلَه جيشُ الموفَّق بدير العاقول، وكشفَ الموفَّق الخوذة وحَمَل، وقال: أنا الغلامُ الهاشميُّ. وكَثُرت القتلى، فانهزم يعقوبُ، وجُرِحَ أمراؤه، وذهبت خزائِنُه، وغَرِق منهم خلقٌ في النهر. مات يعقوبُ بجند يسابور من كور الأهواز، وكانت عِلَّتُه القولنج، فأمره الأطبَّاءُ بالاحتقان بالدواء، فلم يفعل، واختار الموت. وكان المعتمِد قد أنفذ إليه رسولًا وكتابًا يستميلُه ويترضَّاه، ويقَلِّده أعمال فارس، فوصل الرسولُ ويعقوب مريضٌ، فجلس له وجعل عنده سيفًا ورغيفًا من الخبز، ومعه بصَلٌ، وأحضر الرَّسول، فأدَّى الرسالة، فقال له: قُل للخليفة إنَّني عليل، فإن مِتُّ فقد استرحتُ منك واسترحْتَ مني، وإن عوفِيتُ فليس بيني وبينك إلَّا هذا السَّيفُ، حتى آخُذَ بثأري، أو تكسِرَني وتعقِرَني، وأعودَ إلى هذا الخبز والبصل، وأعاد الرسولُ، فلم يلبَثْ يعقوبُ أن هلك. فقام بالأمرِ بعده أخوه عمرو بن الليث، وكتب إلى الخليفةِ بطاعته، فولَّاه الموفَّق خراسان، وفارس، وأصبهان، وسجستان، والسند، وكرمان، والشرطة ببغداد."},{"id":893,"title":"وثوب الأعراب على الحُجَّاج ونهبهم كسوة الكعبة .","date":["العام الهجري :266","العام الميلادي :879"],"text":"وثب جماعةٌ من الأعرابِ- من بني أسد- على عليِّ بن مسرور البلخي قبل وصولِه إلى المغيثة بطريقِ مكَّة، وكان الموفَّق ولَّاه الطريقَ، ووثب الأعرابُ على كسوةِ الكعبةِ فانتهبوها، وصار بعضُها إلى صاحب الزنج، وأصاب الحُجَّاجَ فيها شِدَّةٌ عظيمة."},{"id":894,"title":"أكراد دارنان يهزمون خوارج الزنج .","date":["العام الهجري :266","العام الميلادي :879"],"text":"كانت وَقعةً للزنج انهزموا فيها، وكان سببَها أنَّ محمد بن عبيد الله كتب إلى عليِّ بن أبان بعدَ الصُّلحِ يَسألُه المعونةَ على الأكرادِ الدارنان، على أن يجعلَ له ولأصحابه غنائِمَهم، فكتب عليٌّ إلى صاحبه يستأذِنُه، فكتب إليه أن وجِّهْ إليه جيشًا وأقِمْ أنت، ولا تُنفِذ أحدًا حتى تستوثِقَ منه بالرهائنِ، ولا يأمن غزوه والطلب بثأره. فكتب عليٌّ إلى محمد يطلبُ منه اليمين والرهائن، فبذَلَ له اليمينَ، ومَطَله بالرهائِنِ، ولِحرصِ عليٍّ على الغنائم أنفذ إليه جيشًا، فسيَّرَ محمد معهم طائفةً من أصحابه إلى الأكراد، فخرج إليهم الأكرادُ فقاتلوهم، ونشبت الحرب، فتخلَّى أصحاب محمد عن الزنج، فانهزموا وقَتَلت الأكرادُ منهم خلقًا كثيرًا، وكان محمَّدٌ قد أعدَّ لهم من يتعَرَّضُهم إذا انهزموا، فصادفوهم وأوقعوا بهم، وسَلَبوهم وأخذوا دوابَّهم، ورجعوا بأسوأ حالٍ، فأظهر الخبيثُ الغضَبَ على ابنِ أبان، فأرسل محمَّد إلى بهبود، ومحمد بن يحيى الكرماني، وكانا أقربَ الناسِ إلى علي، فضَمِنَ لهما مالًا إن أصلحا له عليًّا وصاحِبَه، ففعلا ذلك، فأجابهما الخبيثُ إلى الرضا عن محمد على أن يخطُبَ له على منابِرِ بلاده، وأعلما محمدًا بذلك، فأجابهما إلى كلِّ ما طلبا، وجعل يراوِغُ في الدعاءِ له على المنابر، ثم إنَّ عليًّا استعدَّ لمتوث- وهي بلدة بين قرقوب وكور الاهواز- فسار إليها فلم يظفَرْ بها فرَجَع، وعمِلَ السلاليم والآلات التي يصعَدُ بها إلى السور، واستعَدَّ لقَصدِها، فعرف ذلك مسرور البلخي، وهو يومئذٍ بكور الأهواز، فلما سار عليٌّ إليها سار إليه مسرورٌ، فوافاه قبل المغربِ وهو نازلٌ عليها، فلما عاين الزنج أوائِلَ خيل مسرور انهزموا أقبحَ هزيمة، وترَكوا جميعَ ما كانوا أعدُّوه، وقُتِلَ منهم خلقٌ كثيرٌ، وانصرف عليٌّ مهزومًا، فلم يلبثْ إلا يسيرًا حتى أتته الأخبارُ بإقبال الموفق، ولم يكن لعليٍّ بعد متوث وقعة، فكتب إليه صاحِبُه يأمره بالعودِ إليه، ويستحِثُّه حثًّا شديدًا."},{"id":895,"title":"خروج عمر بن حفصون بالأندلس .","date":["العام الهجري :267","العام الميلادي :880"],"text":"ابتدأ شَرُّ عمر بن حفصون، الذي أعيا الخلفاءَ أمرُه، وطالت في الدنيا فتنتُه، وعَظُم شَرُّه، فقام في هذه السنة على الأميرِ محمد بناحية رية. فتقدَّم إليه عامر بن عامر، فانهزم عامرٌ وأسلَمَ قُبَّته؛ فأخذها ابن حفصون، وهو أوَّل رُواقٍ ضَرَبه؛ فاستكنَّ إليه أهلُ الشر. وعزل الأميرُ محمد عامرًا عن كورة رية، وولَّاها عبد العزيز بن عباس، فهادنه ابن حفصون، وسكَنَت الحالُ بينهما. ثم عُزِل عبد العزيز، وتحرَّك ابن حفصون، وعاد إلى ما كان عليه من الشَّرِّ، وخرج هاشم بن عبد العزيز إلى كورة رية يطلُبُ كُلَّ من كشَفَ وَجهَه في الفتنةِ وأظهرَ الخلاف، وأخذ رهائِنَ أهل تاكرنا على إعطاءِ الطاعة."},{"id":896,"title":"محاولة العباس بن أحمد بن طولون غزو المغرب .","date":["العام الهجري :267","العام الميلادي :880"],"text":"عندما وصل العباسُ بن أحمد بن طولون الغربَ هربًا من والده، راسل إبراهيمَ الثاني الأغلبي، وادَّعى أنَّ الخليفةَ قد قلَّده أمر المغرب، فسار العباسُ حتى وصل إلى مدينةِ لبدة فاستقبله أهلُها فاستباحها، وغَرَّته نفسُه فتابع السيرَ نحو الغَربِ، فقاتله إبراهيمُ الثاني وهزمه واضطَرَّه إلى العودة إلى برقة، ثمَّ إن ابن طولون أرسل جيشًا خلف ابنه ليُعيدَه فأخذوه ومَن معه وأعادوهم إلى مصرَ، فسُجِنَ العبَّاسُ حتى مات، وقُتِلَ كثيرٌ من أعوانه بسبب هذا الفعلِ."},{"id":897,"title":"بناء مدينة الموفقية .","date":["العام الهجري :267","العام الميلادي :880"],"text":"ابتنى أبو أحمد الموفَّق بن المتوكِّل مدينةً تجاه مدينة صاحب الزنج  المختارة, وسمَّاها الموفَّقيَّة، وعظُمَ شأنُها، بناها أبو أحمد ليستعينَ بها على قتال صاحب الزنج، فأرسل إلى من يأتيه بآلاتِ الماء, ويبني فيها السفنَ والشذاءات, ويجلِبُ متاع البحر. وكان قد انقطع جلَبُ البحر منذ أكثَرَ من عشر سنين لإخافةِ الخبيث السُّبُلَ، وكتب بإثبات كلِّ من يصلُحُ للجنديَّةِ إلى عمَّاله في الأمصار، ورغَّب في ذلك، والمدينةُ الموفَّقيَّة تُبنى والكتُبُ تُنفَذ بما يَعمُرُها والتجَّار يجهِّزون إليها والأسواقُ تكثر وأقبلت إليها مراكِبُ البحر، وبنى أبو أحمد المسجدَ الجامع، فصارت مدينةً كبيرةً، وحُمِلَت إليها الأموالُ والعطاء في أوقاتِه، ورغب الناسُ في حلولها والمصيرِ إليها من كلِّ أَوْب, والخبيثُ يرصُدُ غِرَّةً يصيب فيها فرصَتَه من أبى أحمد، فلا يجدُ لِتَيقُّظِ النَّاسِ وتحارُسِهم، ولحفظ الموكَّلين بالمواضِعِ الضعيفةِ فيها."},{"id":898,"title":"الموفَّق بالله يأمر ولَدَه أبا العباس لقتال خوارج الزنج .","date":["العام الهجري :267","الشهر القمري : صفر","العام الميلادي :880"],"text":"وجَّه أبو أحمد الموفَّق ولَدَه أبا العباسِ في نحوٍ مِن عشرة آلافِ فارس وراجلٍ، في أحسَنِ هيئةٍ وأكملِ تجَمُّل لقتال الزنج، فساروا نحوَهم فكان بينه وبينهم من القتالِ والنِّزال في أوقاتٍ متعدِّدة ووقعاتٍ مشهورةٍ، استحوذ أبو العباس بن الموفِّق فيها على ما كان استولى عليه الزنجُ ببلاد واسط وأراضي دجلة، هذا وهو شابٌّ حَدَثٌ لا خبرةَ له بالحرب، ولكِنْ سَلَّمَه الله وأعلى كلمَتَه وسَدَّد رَميَتَه وأجاب دعوتَه، وفتح على يديه وأسبَغَ نِعَمَه عليه، وهذا الشابُّ هو الذي وليَ الخلافةَ بعد عمه المعتمد، ثم ركب أبو أحمد الموفَّق ناصر دين الله في بغداد في صفر منها في جيوشٍ كثيفة، فدخل واسط في ربيع الأوَّل منها، ثم سار بجميعِ الجيوش إلى صاحب الزنج وهو بالمدينة التي أنشأها وسمَّاها المنيعة، فقاتل الزنجُ دونها قتالًا شديدًا فقهرهم ودخلها عَنوةً وهربوا منها، فبعث في آثارِهم جيشًا، فلَحِقوهم إلى البطائح يقتُلون ويأسرون، وغَنِمَ أبو أحمد من المنيعة شيئًا كثيرًا، واستنقذ من النساء المُسلمات خمسةَ آلافِ امرأة، وأمر بإرسالهنَّ إلى أهاليهن بواسط، وأمر بهدمِ سُورِ البلد وبطَمِّ خندقها وجعلها بلقعًا بعد ما كان للشَّرِّ مَجمعًا، ثم سار الموفَّق إلى المدينة التي لصاحب الزنج التي يقال لها المنصورة، وبها سليمان بن جامع، فحاصروها وقاتلوه دونها فقُتِلَ خَلقٌ كثيرٌ من الفريقين، ورَمى أبو العباس بن الموفَّق بسهمٍ أحمدَ بن هندي أحدَ أمراء صاحب الزنج فأصابه في دماغِه فقَتَله، فشَقَّ ذلك على الزنجِ جِدًّا، وأصبح الناسُ محاصِرينَ مدينة الزنج يومَ السبت لثلاث بقين من ربيع الآخر والجيوشُ المُوَفَّقية مُرتَّبة أحسنَ ترتيب، فتقدم الموفَّق واجتهد في حصارِها، فهزم الله مقاتِلَتَها وانتهى إلى خَندقِها، فإذا هو قد حُصِّنَ غايةَ التحصين، وإذا هم قد جعلوا حول البلدِ خمسةَ خنادقَ وخمسة أسوار، فجعل كلمَّا جاوز سورًا قاتلوه دون الآخَرِ، فيَقهَرُهم ويجوز إلى الذي يليه، حتى انتهى إلى البلد فقتل منهم خلقًا كثيرًا وهرب بقيَّتُهم، وأسَرَ مِن نساءِ الزِّنج من حلائل سليمان بن جامع وذويه نساءً كثيرةً وصِبيانًا، واستنقذ من أيديهم النساءَ المُسلِمات والصبيانَ مِن أهل البصرة والكوفة نحوًا من عشرة آلاف نسمةٍ فسَيَّرَهم إلى أهليهم، ثمَّ أمر بهدم أسوارِها ورَدْم خنادِقِها وأنهارِها، وأقام بها سبعةَ عشر يومًا، بعث في آثارِ مَن انهزم منهم، فكان لا يأتونَ بأحدٍ منهم إلَّا استماله إلى الحقِّ برِفقٍ ولِينٍ وصَفحٍ، فمن أجابه أضافه إلى بعض الأمراءِ - وكان مقصودُه رجوعَهم إلى الدينِ والحَقِّ- ومن لم يُجِبْه قتله أو حبَسَه، ثم ركب إلى الأهواز فأجلاهم عنها وطرَدَهم منها وقتلَ خلقًا كثيرًا من أشرافهم؛ منهم أبو عيسى محمد بن إبراهيم البصري، وكان رئيسًا فيهم مُطاعًا، وغَنِم شيئًا كثيرًا من أموالهم، وكتب الموفَّق إلى صاحب الزنج- قبَّحَه الله- كتابًا يدعوه فيه إلى التوبةِ والرجوع عمَّا ارتكبه من المآثِمِ والمظالمِ والمحارمِ، ودعوى النبوَّةِ والرِّسالة، وخرابِ البُلدانِ واستحلالِ الفُروج الحرام، ونبَذَ له الأمانَ إن هو رجَعَ إلى الحق، فلم يَرُدَّ عليه صاحِبُ الزنج جوابًا، فسار أبو أحمد الموفَّق إلى مدينةِ صاحب الزنج وحصار المختارة، فلمَّا انتهى إليها وجدَها في غاية الإحكام، وقد حَوَّط عليها من آلات الحصار شيئًا كثيرًا، وقد التفَّ على صاحب الزنج نحوٌ من ثلثمائة ألفِ مقاتلٍ بسيفٍ ورُمحٍ ومِقلاعٍ، ومن يكثر سوادهم، فقَدَّم الموفَّق ولدَه أبا العباس بين يديه فتقَدَّم حتى وقف تحت قصرِ الملك فحاصَره محاصرةً شديدةً، وتعجَّبَ الزنج من إقدامِه وجرأتِه، ثم تراكمتِ الزِّنجُ عليه من كلِّ مكان فهزمهم وأثبتَ بهبوذ بن عبدالوهاب أكبَر أمراءِ صاحبِ الزنجِ بالسِّهام والحجارةِ، ثم خامر جماعةٌ من أصحاب أمراءِ صاحِب الزنج إلى الموفَّق فأكَرَمهم وأعطاهم خِلَعًا سَنِيَّة، ثم رَغِبَ إلى ذلك جماعةٌ كثيرون فصاروا إلى الموفَّق، ثم ركب أبو أحمد الموفَّق في يوم النصف من شعبان ونادى في الناسِ كلِّهم بالأمان إلى صاحبِ الزنج، فتحول خلقٌ كثيرٌ من جيش صاحب الزنج إلى الموفَّق، وابتنى الموفَّق مدينةً تجاه مدينة صاحب الزنج سمَّاها الموفَّقيَّة، ليستعينَ بها على قتال صاحب الزنج، ثم جرت بينهم حروبٌ عظيمة، وما زالت الحربُ ناشبةً حتى انسلخت هذه السنةُ وهم محاصِرونَ للخبيثِ صاحِبِ الزنج، وقد تحوَّل منهم خلقٌ كثيرٌ، فصاروا على صاحِبِ الزنج بعد ما كانوا معه، وبلغ عددُ من تحول قريبًا مِن خمسين ألفًا من الأمراءِ الخواصِّ والأجناد، والموفَّق وأصحابُه في زيادةٍ وقوَّة ونصرٍ وظفَرٍ."},{"id":899,"title":"غزو محمد بن الفضل الروم في جزيرة صقلية .","date":["العام الهجري :268","العام الميلادي :881"],"text":"سارت سريَّةٌ من المسلمين في صقليَّة مُقَدَّمُها رجلٌ يُعرَفُ بأبي الثور، فلقيهم جيشٌ من الروم، فأصيب المسلمون كلُّهم غيرَ سبعة نفر، وعُزِل الحسَنُ بن العباس عن صقلية، ووَلِيَها محمد بن الفضل، فبثَّ السرايا في كل ناحية من صقليَّة، وخرج هو في حشدٍ وجمعٍ عظيم، فسار إلى مدينة قطانية، فأهلك زرعَها، ثم رحل إلى أصحابِ الشلندية فقاتَلَهم، فأصاب فيهم فأكثَرَ القتلَ، ثم رحل إلى طبرمين فأفسَدَ زَرعَها، ثم رحل فلقيَ عساكر الروم، فاقتتلوا فانهزم الرومُ وقُتِلَ أكثَرُهم، فكانت عِدَّةُ القتلى ثلاثةَ آلاف قتيل، ووصلت رؤوسُهم إلى بلرم، ثم سار المسلمونَ إلى قلعة كان الروم بنوها عن قريبٍ، وسمَّوها مدينة الملك، فملكها المسلمونَ عَنوةً، وقَتَلوا مقاتليها وسَبَوا من فيها."},{"id":900,"title":"حملة المنذر بن محمد لتأديب المخالفين في الأندلس .","date":["العام الهجري :268","العام الميلادي :881"],"text":"في هذه السنة سيَّرَ محمد بن عبد الرحمن- صاحِبُ الأندلس- جيشًا مع ابنه المنذِر إلى المخالفينَ عليه، فقصَدَ مدينة سرقسطة، فأهلك زَرعَها وخَرَّب بلَدَها وافتتح حِصنَ روطة، فأسَرَ منه عبد الواحد الروطي، وهو من أشجَعِ أهل زمانه، وتقَدَّم إلى دير تروجة، وبلد محمَّد بن مركب بن موسى، فهتكَهما بالغارة، وقصد مدينةَ لاردة وقرطاجنة، فكان فيها إسماعيل بن موسى فحاربه، فأذعن إسماعيلُ بالطاعة، وترك الخلافَ وأعطى رهائنَه على ذلك، وقصَدَ مدينة أنقرة وهي للمُشركين، فافتتح حصونًا ثم عاد."},{"id":901,"title":"أمين أسرار صاحب الزنج يطلب الأمان من الموفق بالله .","date":["العام الهجري :268","الشهر القمري : محرم","العام الميلادي :881"],"text":"طلب جعفرُ بن إبراهيم السَّجَّان الأمانَ من الموفَّق، وكان أمينَ أسرار الخبيثِ صاحب الزنجِ، وأحدَ خواصِّه، فخلع عليه الموفَّقُ وأعطاه مالًا كثيرًا، وأمر بحَملِه إلى قريبِ مدينة الخبيث. فلمَّا حاذى قصر الخبيث صاح: وَيحَكُم إلى متى تصبِرونَ على هذا الخبيثِ الكذَّابِ؟ وحدَّثهم بما اطَّلع عليه مِن كَذِبه وفُجوره، فاستأمَنَ في ذلك اليومِ خلقٌ كثيرٌ منهم. وتتابع النَّاسُ في الخروجِ مِن عند الخبيثِ."},{"id":902,"title":"الموفق بالله يشدد الحصار على مدينة صاحب الزنج .","date":["العام الهجري :268","الشهر القمري : ربيع الآخر","العام الميلادي :881"],"text":"عبَرَ أبو أحمد الموفَّق إلى مدينة الفاجر بعد أن أوهى قُوَّتَه في مُقامِه بمدينة الموفَّقيَّة بحصاره والتضييقِ عليه، فلما أراد العبورَ إليها أمَرَ ابنه أبا العبَّاس بالقصد للموضِعِ الذي كان قصَدَه مِن رُكنِ مدينة الخبيث الذي يحوطُه بابنه وجِلَّةِ أصحابه وقوَّاده، وقصد أبو أحمد موضِعًا من السور- فيما بين النَّهرِ المعروف بمنكى، والنهر المعروف بابن سمعان- وأمر صاعدا وزيرَه بالقصد لفُوَّهة النهر المعروف بجري كور، وتقدَّمَ إلى زيرك في مناكفتِه وأمرَ مسرورًا البلخيَّ بالقصدِ لنهرِ ما يليهم من السورِ، وطلب منهم الموفَّق ألا يزيدوا على هدمِ السُّورِ، وألا يدخلوا مدينةَ الخبيث، ووكل بكل ناحيةٍ من النواحي التي وجَّه إليها القوَّاد شذوات فيها الرُّماة، وأمرهم أن يحمُوا بالسهامِ من يهدِمُ السورَ مِن الفَعَلة والرَّجَّالة الذين يخرجون للمدافعةِ عنهم، فثَلَم في السورِ ثُلَمًا كثيرة، ودخل أصحابُ أبي أحمد مدينةَ الفاجر من جميع تلك الثُّلَم، وجاء أصحاب الخبيث يحاربونَهم فهزمهم أصحابُ أبي أحمد وأتبعوهم حتى وغَلوا في طلَبِهم، إلَّا أن أصحاب الخبيث تراجعوا فشَدُّوا على أصحاب أبي أحمد وقتلوا منهم جماعةً، وأصاب أصحابُ الخبيثِ أسلحةً وأسلابًا، وثبت جماعةٌ من غلمان أبي أحمد فدافعوا عن أنفُسِهم وأصحابِهم، حتى وصلوا إلى الشذا، وانصرف أبو أحمد بمن معه إلى مدينة الموفَّقيَّة وأمر بجَمعِهم وعَذلِهم على ما كان منهم من مخالفةِ أمْرِه والافتياتِ عليه في رأيه وتدبيرِه، وتوعَّدَهم بأغلظِ العُقوبة إن عادوا لخلافِ أمْرِه بعد ذلك، وأمر بإحصاءِ المفقودين من أصحابِه فأُحصوا له، وأقَرَّ ما كان جاريًا لهم على أولادِهم وأهاليهم، فحَسُنَ مَوقِعُ ذلك منهم، وزاد في صِحَّة نيَّاتهم لِمَا رأَوا من حياطتِه خَلْفَ من أصيبَ في طاعتِه."},{"id":903,"title":"وفاة ابن المواز المالكي .","date":["العام الهجري :269","العام الميلادي :882"],"text":"هو أبو عبد الله محمد بن إبراهيم بن زياد الإسكندراني المالكي صاحبُ التصانيف المشهورة، المعروف بابن الموَّاز، فقيهٌ مالكي، تفقَّه على أصبغ بن الفرج المصري، وعلى ابن الماجِشون، انتهت إليه رياسةُ المذهب المالكي في عصره، فكان المنتهى في تفريعِ المسائل، وكتابه المشهورُ بالموازية يعتبَرُ من الكتب المعتَمَدة في الفقه المالكي، بل قيل: هو أصحُّ كتاب في الفقه المالكي، وعليه العُمدةُ، قَدِمَ دمشقَ في صحبة أحمد بن طولون, وقيل: إنه تزهَّد، وانزوى ببعض الحصونِ الشاميَّة في أواخر عمره، حتى أدركه أجَلُه- رحمه الله تعالى- توفي في دمشق عن 99 عامًا."},{"id":904,"title":"محاولة الخليفة العباسي المعتمد التآمر مع ابن طولون على أخيه الموفق .","date":["العام الهجري :269","الشهر القمري : جمادى الأولى","العام الميلادي :882"],"text":"لَمَّا رأى الخليفةُ المعتَمِد أن أخاه أبا أحمد قد استحوذ على أمورِ الخلافة، وصار هو الحاكِمَ الآمِرَ الناهي، وإليه تُجلَبُ التقادم وتُحمَل الأموال والخَراج، وهو الذي يُوَلِّي ويعزل، كتب إلى أحمد بن طولون يشكو إليه ذلك، فكتب إليه ابن طولون أن يتحَوَّل إليه في مصرَ، ووعده النصرَ والقيامَ معه، فاستغلَّ غَيبةَ أخيه الموفَّق، وركب في جمادى الأولى ومعه جماعةٌ من القواد، وقد أرصد له ابن طولون جيشًا بالرقة يتلقَّونه، فلما اجتاز الخليفةُ بإسحاق بن كنداج نائب الموصل وعامة الجزيرة، اعتقله عنده عن المسيرِ إلى ابن طولون، وفنَّدَ أعيانَ الأمراء الذين معه، وعاتب الخليفةَ ولامَه على هذا الصنع أشَدَّ اللوم، ثم ألزمه العودَ إلى سامرَّا ومن معه من الأمراء، فرجعوا إليها في غاية الذلِّ والإهانة، ولَمَّا بلغ الموفَّقَ ذلك شكَرَ سعيَ إسحاق وولَّاه جميع أعمال أحمد بن طولون إلى أقصى بلاد إفريقيَّة، وكتب إلى أخيه أن يأمنَ ابن طولون في دار العامة، فلم يمكِنْ المعتَمِد إلَّا إجابتُه إلى ذلك، وهو كارِهٌ، وكان ابن طولون قد قطع ذِكرَ الموفَّق في الخُطَب وأسقط اسمَه عن الطرازات."},{"id":905,"title":"كاتب صاحب الزنج يطلب الأمان من الموفق .","date":["العام الهجري :269","الشهر القمري : شعبان","العام الميلادي :883"],"text":"طلب محمدُ بن سمعان- كاتِبُ الخبيث، وأوثَقُ أصحابِه في نفسِه- الأمانَ من الموفَّقِ، وكان سببَ استئمانِه أنَّ الخبيث أطلَعَه على أنه عازمٌ على الخلاصِ وَحدَه بغير أهلٍ ولا مالٍ، فلمَّا رأى ذلك من عزْمِه، أرسل يطلبُ الأمان، فأمَّنَه الموفَّقُ وأحسن إليه، وقيل: كان سبَبَ خُروجِه أنه كان كارهًا لصُحبة الخبيث، مُطَّلعًا على كُفرِه وسوءِ باطِنِه، ولم يمكِنْه التخلصُ منه ففارقه."},{"id":906,"title":"الحرب بين عسكر ابن طولون وعسكر الموفق بمكة .","date":["العام الهجري :269","الشهر القمري : ذي الحجة","العام الميلادي :883"],"text":"سبَبُها أنَّ أحمد بن طولون سيَّرَ جيشًا مع قائدينِ إلى مكَّةَ، فوصلا إليها وجمَعا الحنَّاطين، والجزارين، وفَرَّقا فيهم مالًا؛ وكان عامِلُ مكة هارون بن محمد إذ ذاك ببستانِ ابن عامر قد فارقها خوفًا منهما، فقَدِمَ مكة جعفر الباغمردي في عسكرٍ، وتلقاه هارون بن محمد في جماعةٍ، فقَوِيَ بهم جعفر، والتَقَوا هم وأصحاب ابن طولون فاقتتلوا وأعان أهلُ خراسان جعفرًا، فقتل من أصحابِ ابن طولون مائتي رجلٍ، وانهزم الباقونُ وسُلِبوا وأُخِذَت أموالهم، وأخذ جعفرٌ من القائدينِ نحوَ مائتي ألف دينار، وأمَّن المصريِّين، والجزَّارين، والحنَّاطين، وقُرِئَ كتابٌ في المسجد الجامع، ولُعِن ابن طولون، وسَلِم الناسُ وأموال التجار."},{"id":907,"title":"خروج محمد بن الفضل أمير صقلية إلى ناحية رمطة .","date":["العام الهجري :269","الشهر القمري : ذي الحجة","العام الميلادي :883"],"text":"خرج محمد بن الفضل أميرُ صقليَّة في عسكرٍ إلى ناحية رمطة، وبلغ العَسكرُ إلى قطانية، فقتل كثيرًا من الرومِ، وسبى وغَنِم، ثم انصرف إلى بلرم."},{"id":908,"title":"وفاة محمد بن نُصَير رأس النصيرية .","date":["العام الهجري :270","العام الميلادي :883"],"text":"هو أبو شُعَيب- وقيل: أبو جعفر- محمد بن نُصَير بن بكر النميري البصري، أحد نوَّاب الإمام المنتظَر عند الرافضة في فترة الغَيبة الصغرى. إليه تُنسَبُ الفرقةُ النصيرية، وهي من الفِرَق الباطنيةِ من غُلاة الشيعة، زعم ابنُ نصير هذا أنَّه الباب إلى الإمامِ الحسن العسكري، أي: أنَّه الإمام والمَرجِعُ من بعده، ثم ادَّعى ألوهيَّةَ علي بن أبي طالب، وأنه هو الذي أرسلَه للنَّاسِ رسولًا، قال بالتناسُخِ وأنَّ المؤمِنَ يتحَوَّلُ إلى سَبعِ مراحِلَ قبل أن يأخُذَ مكانه بين النجوم، وأما الشِّريرُ فيُنسَخ إلى نصراني أو يهودي أو مُسلم حتى يتخَلَّصَ من الكفرِ أو يتحَوَّلَ إلى كِلابٍ وبغال وحمير، وقيل: بل هؤلاء الذين لا يعبدون عليًّا، وإباحة المحارم، والخَمر، والنُّصيرية اليوم قبائِلُ موزعة غالِبُها في جبال العلويين في أطرافِ الساحل الغربي لسوريا، ولواء إسكندرون بتركيا وكردستان وإيران."},{"id":909,"title":"هزيمة الروم على يد نائب طرسوس بازمان .","date":["العام الهجري :270","العام الميلادي :883"],"text":"خرجت الرومُ في مائة ألف، فنزلوا على قلمية، وهي على ستَّة أميال من طرسوس، فخرج إليهم الخادمُ نائب طرسوس بازمان ليلًا فبَيَّتَهم في ربيع الأول، فقتَلَ منهم- فيما يقال- سبعين ألفًا، وقتل مُقَدَّمَهم، وهو بطريق البطارقة، وقتل أيضًا بِطريقَ الفنَّادين، وبِطريقَ الباطليق، وأفلت بطريقِ قرة وبه عدَّة جراحات، وأخذ لهم سبعةَ صُلبان من ذهب وفضة؛ وصَليبُهم الأعظمُ من ذهب مكَلَّل بالجوهر، وأخذ خمسة عشر ألف دابَّة، ومن السُّروجِ وغير ذلك، وسُيوفًا محلاة، وأربعَ كراسيَّ من ذهب، ومائتي كرسيٍّ من فضة، وآنيةً كثيرة، ونحوًا من عشرة آلاف علَم ديباج، وديباجًا كثيرًا وبزيون وغير ذلك."},{"id":910,"title":"وفاة الحسن بن زيد مؤسس الدولة العلوية .","date":["العام الهجري :270","العام الميلادي :883"],"text":"هو الحسَنُ بن زيد بن محمد بن إسماعيل بن الحسن بن زيد بن الحسن بن علي بن أبي طالب، صاحبُ طبرستان ومؤسِّس الدولةِ العَلَوية فيها، كان في الريِّ، فلما حَدَثت الفتنةُ بين بني طاهر أصحابِ خراسان وبين أهل طبرستان سنة 250هـ كتبوا إليه يستدعونَه، فبايعوه والتفَّ عليه الديلم وأمراءُ النواحي، فمَلَك طبرستان وجرجان والريَّ، فدامت دولتُه عشرين سنة، وخَلَفه بعده أخوه محمد، والحسنُ كان أحد العُلَماء الزيدية، له كتاب (الجامع في الفقه) و كتاب (الحجَّة في الإمامة)."},{"id":911,"title":"وفاة داود الظاهري .","date":["العام الهجري :270","العام الميلادي :883"],"text":"هو الحافِظُ العلَّامة داود بن علي بن خلَف، أبو سليمان الظاهريُّ الأصبهاني، صاحِبُ مذهب الظاهريَّة، المعروف بداود الظاهريِّ، وهو أصبهانيُّ الأصل، من أهل قاشان (بلدة قريبة من أصبهان) وُلِدَ سنة 200ه في الكوفة. سكن بغداد، وهو أوَّلُ من نفى القياسَ في الأحكامِ الشرعيَّة، تُنسَب إليه طائفةُ الظاهريَّة، وسُمِّيَت بذلك لتمسُّكِها بظواهرِ النصوصِ وإعراضِها عن التأويلِ والرأيِ والقياسِ. وكان داودُ أوَّلَ مَن جهر بهذا القول. سَمِعَ الكثيرَ ولقِيَ الشيوخَ وتَبِعَه خلقٌ كثيرٌ، وقَدِمَ بغدادَ وصَنَّف بها الكتُبَ، وإليه انتهت رياسةُ العلم ببغداد، وتوفي بها في رمضان، وقيل: في ذي القعدة، عن عمر 70 عامًا."},{"id":912,"title":"قتل صاحب الزنج المدعي أنه علي بن محمد وإنهاء فتنته .","date":["العام الهجري :270","الشهر القمري : صفر","العام الميلادي :883"],"text":"لَمَّا قُتِلَ الذين كانوا يمُدُّون الزنجَ بالميرة، وقُطِعَت تلك الإمدادات واشتَدَّ الحصار على الزنج، ولَمَّا فرغ الموفَّقُ من شأن مدينة صاحبِ الزنج، وهي المختارة، واحتاز ما كان بها من الأموالِ وقَتَل من كان بها من الرجال، وسَبى من وجد فيها من النِّساء والأطفال، وهرب صاحِبُ الزنج عن حومةِ الحرب والجِلاد، وسار إلى بعضِ البلاد طريدًا شريدًا بشَرِّ حال؛ عاد الموفَّق إلى مدينتِه المُوفَّقيَّة مُؤيَّدًا منصورًا، وقَدِمَ عليه لؤلؤة غلام أحمد بن طولون مُنابذًا لسيِّده سميعًا مطيعًا للمُوَفِّق، وكان ورودُه عليه في ثالث المحرم من هذه السنة، فأكرمه وعَظَّمه وأعطاه وخَلَع عليه وأحسَنَ إليه، وبعثه طليعةً بين يديه لقتالِ صاحب الزنج، وركِبَ الموفَّق في الجيوش الكثيفة الهائلة وراءه، فقصدوا الخبيث وقد تحصَّنَ ببلدة أخرى، فلم يزل به محاصِرًا له حتى أخرجه منها ذليلًا، واستحوذ على ما كان بها من الأموالِ والمغانم، ثمَّ بعث السرايا والجيوشَ وراء حاجِبِ صاحب الزنج، فأسروا عامَّة من كان معه من خاصَّته وجماعتِه، منهم سليمان بن جامع، فاستبشر الناسُ بأسره وكبَّرُوا الله وحَمِدوه؛ فرحًا بالنصر والفتح، وحمل الموفَّقُ بمن معه حملةً واحدة على أصحابِ الخبيث فاستحَرَّ فيهم القتل، وما انجلت الحربُ حتى جاء البشيرُ بقتل صاحب الزنج في المعركةِ، وأُتي برأسِه مع غلامِ لؤلؤة الطولوني، فلما تحقَّق الموفَّق أنَّه رأسُه بعد شهادة الأمراء الذين كانوا معه من أصحابِه بذلك، خَرَّ ساجدًا لله، ثم انكفأ راجعًا إلى الموفَّقيَّة، ورأسُ الخبيثِ يُحمَلُ بين يديه، وسليمانُ معه أسير، فدخل البلدَ وهو كذلك، وكان يومًا مشهودًا، وفرح المسلمون بذلك في المغارب والمشارق، ثم جيء بأنكلاني ولد صاحب الزنج، وأبان بن علي المهلبي مُسَعِّر حربِهم مأسورينِ، ومعهم قريبٌ من خمسة آلاف أسير، فتم السرورُ وهرب قرطاس الذي رمى الموفَّق بصدره بذلك السَّهم إلى رامهرمز، فأُخِذَ وبُعِثَ به إلى الموفَّق فقتله أبو العباس أحمد بن الموفَّق، واستتاب مَن بقي من أصحابِ صاحب الزنج وأمَّنَهم الموفَّق، ونادى في الناس بالأمان، وأن يرجِعَ كُلُّ من كان أُخرِجَ من دياره بسبَبِ الزنج إلى أوطانِهم وبلدانهم، ثم سار إلى بغداد وقَدَّمَ ولده أبا العباس بين يديه، ومعه رأسُ الخبيث يُحمَلُ لِيَراه الناس، فدخلها لثنتي عشرة ليلةً بقيت من جمادي الأولى من هذه السنة، وكان يومًا مشهودًا، وانتهت أيامُ صاحب الزنج المُدَّعي الكذَّاب- قبَّحه الله- واسمُه محمد بن علي، وقد كان ظهورُه في يوم الأربعاء لأربعٍ بَقِين من رمضان سنة خمس وخمسين ومائتين، وكان هلاكُه يوم السبت لليلتين خلتا من صفر سنة سبعين ومائتين، وكانت دولته أربع عشرة سنة وأربعة أشهر وستة أيام، ولله الحمدُ والمنَّة، وقد قيل في انقضاء دولة الزنجِ وما كان من النصرِ عليهم أشعارٌ كثيرة."},{"id":913,"title":"مسير إسحاق بن كنداجيق إلى الشام .","date":["العام الهجري :270","الشهر القمري : شعبان","العام الميلادي :884"],"text":"لَمَّا توفِّيَ أحمدُ بن طولون كان إسحاقُ بن كنداجيق على الموصل والجزيرة، فطَمِعَ هو وابن أبي الساج- وهما من كبار قادة الترك عند المعتَمِد- في الشام، واستصغرا أولادَ أحمد، وكاتَبا الموفَّقَ بالله في ذلك، واستمَدَّاه، فأمرهما بقصدِ البلاد، ووعدهما إنفاذَ الجيوش، فجمَعَا وقصدَا ما يجاوِرُهما من البلاد، فاستولَيَا عليه وأعانهما النائبُ بدمشق لأحمد بن طولون، ووعدَهما الانحيازَ إليهما فتراجع مَن بالشامِ مِن نواب أحمد بأنطاكية، وحلب وحمص، وعصى متولِّي دمشق، واستولى إسحاقُ عليها، وبلغ الخبَرُ إلى أبي الجيش خمارَوَيه بن أحمد بن طولون، فسيَّرَ الجيوش إلى الشام فمَلَكوا دمشق، وهرب النائبُ الذي كان بها من قِبَل إسحاق؛ وسار عسكرُ خمارويه من دِمشقَ إلى شيزر لقتال إسحاق بن كنداجيق وابن أبي الساج، فطاولهم إسحاقُ ينتظِرُ المدد من العراق، وهجم الشتاءُ على الطائفتَينِ، وأضرَّ بأصحاب ابن طولون، فتفَرَّقوا في المنازل بشيزر، ووصل العسكرُ العراقي إلى كنداجيق، وعليهم أبو العباس أحمد بن الموفَّق وهو المعتضِدُ بالله، فلما وصل سار مُجِدًّا إلى عسكر خمارويه بشيزر، فلم يَشعُروا حتى كبَسَهم في المساكن، ووضع السيفَ فيهم، فقتل منهم مقتلةً عظيمةً، وسار من سَلِمَ إلى دمشق على أقبَحِ صُورةٍ، فسار المعتَضِد إليهم، فجُلُوا عن دمشقَ إلى الرملة، ومَلَك هو دمشق، ودخلَها في شعبان سنة إحدى وسبعين ومائتين، وأقام عسكرُ ابن طولون بالرملة، فأرسلوا إلى خِمارَوَيه يُعَرِّفونه بالحال، فخرج من مصرَ في عساكره قاصدًا إلى الشَّامِ."},{"id":914,"title":"وفاة الربيع بن سليمان صاحب الشافعي .","date":["العام الهجري :270","الشهر القمري : شوال","العام الميلادي :884"],"text":"هو الربيعُ بن سليمان بن عبد الجبار بن كامل أبو محمد المراثي الفقيهُ، صاحِبُ الشافعيِّ، نقل عنه مُعظَمَ أقاويلِه، وكان فقيهًا فاضلًا ثقةً دَيِّنًا، وهو أوَّلُ من أملى الحديثَ بجامع ابن طولون، مات بمصر عن عمر 96 عامًا، وصلى عليه صاحِبُ مصر خِمارَوَيه بن أحمد بن طولون."},{"id":915,"title":"وفاة أحمد بن طولون مؤسس الدولة الطولونية بمصر .","date":["العام الهجري :270","الشهر القمري : ذي القعدة","العام الميلادي :884"],"text":"هو أحمد بن طولون أبو العبَّاسِ، تركي الأصل، ولِدَ بسامرَّاء، عام 220ه كانت أمُّه جاريةً اسمُها هاشم, أميرُ الديار المصرية، وباني الجامع المنسوب إليه، نشأ ابنُ طولون في صيانةٍ وعفافٍ ورياسةٍ وطلَبٍ للعلمِ ودِراسةٍ للقرآن العظيم، مع حُسنِ الصَّوتِ به. تنقَّلَت به الأحوال؛ تأمَّرَ فولِيَ ثُغورَ الشامِ، ثمَّ إمرةَ دمشق، ثم ولِيَ الديار المصريةَ في سنة أربع وخمسين، وله إذ ذاك أربعونَ سنة, وكانت له أطماعٌ توسُّعِيَّة على حسابِ الخلافة العباسيَّة, والخليفةُ كان مشغولًا عنه بحرب الزنج. وكان بطلًا شُجاعًا، مِقدامًا مَهِيبًا، سائِسًا جَوادًا، مُمَدَّحًا باذِلًا، مِن دُهاة الملوك. لكنَّه كان جبارًا سفَّاكًا للدماء، أُحصِيَ من قتَلَهم صبرًا، أو مات في سِجنِه، فبلغوا ثمانية عشر ألفًا. كان يعيب على أولاد التُّرك ما يرتكبونَه من المحرَّمات والمُنكَرات. بنى المارستان وأنفقَ عليه ستين ألف دينار، وعلى الميدانِ مائةً وخمسين ألفًا، وكانت له صدقات كثيرة جدًّا، وإحسانٌ زائد. ملك دمشقَ بعد أميرها ماخور، توفِّي بمصر من علةٍ أصابته من أكلِ لَبَن الجواميسِ فأُصيبَ بسَبَبِه فكواه الأطباءُ وأمروه أن يحتمِيَ منه، فلم يقبَلْ منهم، فكان يأكُلُ منه خُفيةً، فمات رحمه الله، وقد تركَ من الأموال والأثاث والدوابِّ شَيئًا كثيرًا جدًّا، من ذلك عشرةُ آلافِ ألفِ دينار، ومن الفضَّة شيئًا كثيرًا، وكان له ثلاثةٌ وثلاثون ولدًا، منهم سبعة عشر ذكرًا. قام بالأمر من بعده وَلَدُه خِمارَوَيه."},{"id":916,"title":"وقعة الطواحين بين المعتضِدِ بالله وبين خِمارَوَيه بن طولون .","date":["العام الهجري :271","العام الميلادي :884"],"text":"كانت بين أبي العباس المعتضِدِ بن الموفَّق وبين خِمارَوَيه بن أحمد بن طولون، وذلك أن المعتَضِد سار من دمشق- بعد أن ملَكَها- نحوَ الرملة إلى عساكرِ خمارويه، فأتاه الخبَرُ بوصول خمارويه إلى عساكرِه، وكثرةِ مَن معه من الجموع، فهَمَّ بالعود، فلم يُمكِنْه من معه من أصحاب خمارويه الذين صاروا معه؛ وكان المعتضد قد أوحش ابن كنداجيق، وابن أبي الساج، ونسبهما إلى الجبن، حيث انتظراه ليصل إليهما ففسدت نياتهما معه، ولما وصل خمارويه إلى الرملة نزل على الماء الذي عليه الطواحين، فملكه، فنسبت الوقعة إليه؛ ووصل المعتضد وقد عبأ أصحابه، وكذلك أيضًا فعل خمارويه، وجعل له كمينًا عليهم سعيدًا الأيسر، وحملت ميسرة المعتضد على ميمنة خمارويه، فانهزمت، فلما رأى ذلك خمارويه، ولم يكن رأى مصافًا قبله، ولى منهزمًا في نفر من الأحداث الذين لا علم لهم بالحرب، ولم يقف دون مصر، ونزل المعتضد إلى خيام خمارويه، وهو لا يشك في تمام النصر، فخرج الذين عليهم سعيد الأيسر، وانضاف إليه من بقي من جيش خمارويه، ونادوا بشعارهم، وحملوا على عسكر المعتضد وهم مشغولون بنهب السواد، ووضع المصريون السيف فيهم، وظن المعتضد أن خمارويه قد عاد، فركب فانهزم ولم يلو على شيء، فوصل إلى دمشق، ولم يفتح له أهلها بابها فمضى منهزمًا حتى بلغ طرسوس، وبقي العسكران يضطربان بالسيوف، وليس لواحد منهما أمير، وطلب سعيد الأيسر خمارويه فلم يجده، فأقام أخاه أبا العشائر، وتمت الهزيمة على العراقيين، وقتل منهم خلق كثير وأسر كثير، وقال سعيد للعساكر: إن هذا – يعني أبا العشائر- أخو صاحبكم، وهذه الأموال تنفق فيكم؛ ووضع العطاء، فاشتغل الجند عن الشغب بالأموال، وسيرت البشارة إلى مصر، ففرح خمارويه بالظفر، وخجل للهزيمة، غير أنه أكثر الصدقة، وفعل مع الأسرى فعلة لم يسبق إلى مثلها أحد قبله، فقال لأصحابه: إن هؤلاء أضيافكم فأكرموهم؛ ثم أحضرهم بعد ذلك وقال لهم: من اختار المقام عندي فله الإكرام والمواساة، ومن أراد الرجوع جهزناه وسيرناه؛ فمنهم من قام ومنهم من سار مكرمًا؛ وعادت عساكر خمارويه إلى الشام أجمع، فاستقر ملك خمارويه له."},{"id":917,"title":"دخول محمد وعلي ابنا الحسين بن جعفر المدينة النبوية .","date":["العام الهجري :271","العام الميلادي :884"],"text":"دخل محمدٌ وعليٌّ ابنا الحُسَين بن جعفر بن موسى بن جعفر بن محمد بن علي بن الحسين بن علي بن أبي طالب المدينة، وقتلا جماعةً مِن أهلها وأخذا من القومِ مالًا، ولم يُصَلِّ أهلُ المدينة في مسجدِ رسولِ اللهِ- صلَّى اللهُ عليه وسلم- لا جمعةً ولا جماعةً، شَهرًا."},{"id":918,"title":"وقوع حرب بين عسكر الخليفة وعمرو الصفار .","date":["العام الهجري :271","الشهر القمري : ربيع الأول","العام الميلادي :884"],"text":"وقَعَت الحربُ بين عساكر الخليفة وفيها أحمد بن عبدالعزيز بن أبي دلف، وبين عمرو بن الليث الصَّفَّار، ودامت الحربُ من أوَّلِ النهار إلى الظهر، فانهزم عمرٌو وعساكِرُه، وكانوا خمسةَ عشَرَ ألفًا بين فارسٍ وراجلٍ، وجُرِحَ الدرهميُّ مُقَدَّمُ جيشِ عَمرِو بن الليث، وقُتِلَ مائة رجل من حُماتِهم، وأُسِرَ ثلاثةُ آلاف، واستأمنَ منهم ألفَ رجل، وغَنِموا من معسكرِ عَمرٍو من الدوابِّ والبقَرِ والحميرِ ثلاثينَ ألفَ رأسٍ، وما سوى ذلك فخارِجٌ عن الحَدِّ والحصرِ."},{"id":919,"title":"تحرك بقية خوارج الزنج في أرض البصرة .","date":["العام الهجري :272","العام الميلادي :885"],"text":"تحرَّكَت بقيَّةُ الزنج في أرض البصرة ونادَوا: يا انكلاي يا منصور، وانكلاي هو ابنُ صاحب الزنج، وسليمانُ بن جامع وأبان بن علي المهلبي، وجماعةٌ من وجوههم كانوا في جيش الموفَّق, فبعث إليهم الموفَّق فقُتِلوا وحُمِلَت رؤوسُهم إليه، وصُلِبَت أبدانُهم ببغداد، وسَكَنَت شرورُهم."},{"id":920,"title":"نشوب حرب بين اذكوتكين ومحمد بن زيد العلوي .","date":["العام الهجري :272","الشهر القمري : جمادى الأولى","العام الميلادي :885"],"text":"وقَعَت حربٌ شديدة بين أذكوتكين بن أساتكين أحدِ قوَّاد التُّرك وبين محمَّد بن زيد العلوي، صاحِبِ طبرستان، ثم سار أذكوتكين من قزوين إلى الريِّ ومعه أربعةُ آلاف فارس، وكان مع محمد بن زيد من الديلم والطبريَّة والخراسانية عالَمٌ كبير، فاقتتلوا فانهزم عسكرُ محمد بن زيد وتفَرَّقوا، وقُتِل منهم ستةُ آلافٍ وأُسِرَ ألفانِ، وغَنِمَ أذكوتكين وعسكَرُه من أثقالِهم وأموالِهم ودوابِّهم شيئًا لم يَرَوا مِثلَه، ودخل أذكوتكين الريَّ فأقام بها وأخذ من أهلِها مائةَ ألفِ ألف دينار، وفرَّقَ عمالَه في أعمالِ الريِّ."},{"id":921,"title":"خمارويه يعيد توحيد مصر والشام .","date":["العام الهجري :273","العام الميلادي :886"],"text":"في هذه السَّنَة فسَدَ الحالُ بين محمد بن أبي الساج وإسحاق بن كنداج- من كبار قادةِ الأتراك في عهد المُعتَمِد- وكانا متَّفِقَين في الجزيرة، وسببُ ذلك أنَّ ابن أبي الساج نافَرَ إسحاق في الأعمالِ، وأراد التقدُّمَ، وامتنع عليه إسحاقُ، فأرسل ابن أبي الساج إلى خِمارَوَيه بن أحمد بن طولون، صاحِبِ مصر، وأطاعه وصار معه وخطَبَ له بأعمالِه، وهي قِنَّسرين، وسيَّرَ ولده ديوداد إلى خِمارَوَيه رهينةً، فأرسل إليه خمارويه مالًا جزيلًا له ولِقُوَّاده، وسار خمارَوَيه إلى الشام، فاجتمع هو وابنُ أبي الساج ببالس، وعبَرَ ابن أبي الساج الفراتَ إلى الرقَّة، فلقيه ابن كنداج، وجرت بينهما حربٌ انهزم فيها ابن كنداج، واستولى ابن أبي الساج على ما كان لابنِ كنداج، وعبَرَ خمارويه الفراتَ ونزل الرافقة، ومضى إسحاقُ مُنهزِمًا إلى قلعة ماردين، فحصره ابنُ أبي الساج، وسار عنها إلى سنجار، فأوقع بقومٍ من الأعراب، وسار ابن كنداج من ماردين نحو الموصِل، فلقيه ابنُ أبي الساج ببرقعيد، فكَمَن كمينًا فخرجوا على ابن كنداج وقتَ القتال، فانهزم عنها وعاد إلى ماردين فكان فيها، وقَوِيَ ابنُ أبي الساج وظهر أمرُه، واستولى على الجزيرةِ والموصل، وخطَبَ لخِمارَوَيه فيها ثمَّ لنَفسِه بعدَه."},{"id":922,"title":"ثورة العبيد السودان في مصر .","date":["العام الهجري :273","العام الميلادي :886"],"text":"ثار السودانُ بمصر وحصروا صاحِبَ الشُّرطة، فسَمِعَ خِمارَوَيه بن أحمد بن طولون الخبَرَ، فركب، وفي يده سيفٌ مسلولٌ، وقصد دارَ صاحِبِ الشرطة، وقتل كلَّ مَن لَقِيَه من السودان، فانهزموا منه، وأكثَرَ القتلَ فيهم، وسكنت مصرُ وأمِنَ النَّاسُ"},{"id":923,"title":"وفاة محمد بن عبدالرحمن صاحب الأندلس .","date":["العام الهجري :273","الشهر القمري : صفر","العام الميلادي :886"],"text":"هو محمَّد بن عبد الرحمن بن الحَكَم بن هشام الأموي، صاحِبُ الأندلُس، كانت ولايتُه أربعًا وثلاثين سنةً وأحد عشر شهرًا، كان أيمَنَ أمراءِ الأندلُس مُلكًا، وأكرَمُهم تثبُّتًا وأناةً، يجمَعُ إلى هذه الخِلالِ البلاغةَ والأدبَ، وكان ذكيًّا فَطِنًا بالأمور المُشتَبِهة، خلف نيفًا وخمسين ولدًا، منهم ثلاثةٌ وثلاثون ذكرًا، ولَمَّا مات كان عمرُه نحوًا مِن خمس وستين سنةً. وَلِيَ بعده ابنُه المنذر بن محمد، بويِعَ له بعد موتِ أبيه لثلاث ليال، وأطاعه النَّاسُ، وأحسَنَ إليهم."},{"id":924,"title":"وفاة ابن ماجه صاحب السنن .","date":["العام الهجري :273","الشهر القمري : رمضان","العام الميلادي :887"],"text":"هو أبو عبد الله محمَّد بن يزيد بن ماجه، صاحِبُ كتابِ السُّنَن المشهورِ، وهي دالَّةٌ على عَمَلِه وعِلمِه وتبحُّرِه واطلاعِه واتِّباعِه للسُّنَّة في الأصول والفروع، حُكِيَ عن أبي زُرعةَ الرازي أنه انتقَدَ منها بضعة عشر حديثًا، كان عالِمًا بهذا الشأن، صاحِبَ تصانيف، منها (التاريخ والسُّنَن)، ارتحل إلى العراقَينِ- الكوفة والبصرة- ومصر والشام، مات وعمره أربعٌ وستون سنة، وصلَّى عليه أخوه أبو بكر، تولى دفنه مع أخيه الآخَرِ أبي عبد الله وابنه عبد الله بن محمد بن يزيد رحمه الله."},{"id":925,"title":"حروب أهلية في الأندلس .","date":["العام الهجري :275","العام الميلادي :888"],"text":"بعد وفاة الأمير المنذر بويعَ بالإمارة بعده لأخيه عبد الله بن محمَّد بن عبد الرحمن بن الحكم، وأفضَتِ الإمارةُ إليه، وقد مَزَّقَها الشِّقاقُ، ونَقْض العهود, وحلَّ عُراها النِّفاق؛ والفِتنةُ مُستولِية، والقلوبُ مُختَلِفة، والباطِلُ قد أُعلِن، والشَّرُّ قد اشتَهَر؛ وقد تمالأ على أهلِ الإيمان حِزبُ الشيطان؛ وتألَّبَ على أهلِ الإسلامِ أهلُ الشِّركِ ومن ضاهاهم من أهلِ الفتنةِ، الذين جرَّدوا سيوفَهم على أهل الإسلام، فصار أهلُ الإسلامِ بين قتيلٍ ومَحروب ومحصورٍ، انقطَعَ الحرث، وكاد أن ينقَطِعَ النَّسلُ. فناضل الأميرُ بجُهده، وحمى بجِدِّه، وجاهد عدُوَّ اللهِ وعَدُوَّه. وانقطع الجهادُ إلى دار الحرب، وصارت بلادُ الإسلام بالأندلس هي الثَّغرَ المَخُوف؛ فكان قتالُ المنافقين وأشباهِهم أوكَدَ بالسُّنَّة، وألزمَ بالضَّرورة."},{"id":926,"title":"قتال بين خمارويه وابن أبي الساج .","date":["العام الهجري :275","الشهر القمري : محرم","العام الميلادي :888"],"text":"كان بين ابن أبي الساج- أحد كبارِ قادةِ الأتراك في عهد المعتَمِد- وخِمارَوَيه بن طولون اتِّفاقٌ، وكان ابنُ أبي الساج يطيع خِمارَوَيه ويسمَعُ له، إلَّا أنَّ ابنَ أبي الساج خالف على خمارَوَيه، فلما سمع خمارويه الخبَرَ، سار عن مصر في عساكِرِه نحو الشام، فقَدِمَ إليه آخِرَ سنة أربع وسبعين، فسار ابنُ أبي الساج إليه، فالتَقَوا عند ثنية العقاب بقُرب دمشق، وكان القتالُ بينهما فانهزمت ميمنةُ خمارَوَيه وأحاط باقي عسكرِه بابن أبي الساج ِومن معه، فمضى منهزمًا واستبيح مُعسكَرُه، وأُخِذَت الأثقال والدوابُّ وجميعُ ما فيه، وكان قد خلَّفَ بحمص شيئًا كثيرًا فسَيَّرَ إليه خمارويه قائدًا في طائفةٍ من العسكرِ جريدة، فسبقوا ابنَ أبي الساج إليها ومنعوه من دخولِها والاعتصام بها، واستولوا على ما لَه فيها، فمضى ابن أبي الساج منهزمًا إلى حلَب، ثم منها إلى الرقَّة، فتبعه خمارَوَيه، ففارق الرقَّة، فعبر خمارويه الفراتَ، وسار في أثرِ ابنِ أبي الساج، فوصل خمارويه إلى مدينةِ بلد، وكان قد سبقه ابنُ أبي الساج إلى الموصل. فلما سمع ابنُ أبي الساج بوصولِه إلى بلد سارَ عن الموصِلِ إلى الحديثة، وأقام خمارَوَيه ببلد."},{"id":927,"title":"وفاة أمير الأندلس المنذر بن محمد بن عبدالرحمن .","date":["العام الهجري :275","الشهر القمري : صفر","العام الميلادي :888"],"text":"هو المُنذِر بن محمد بن عبد الرحمن بن الحكم أبو الحكم المرواني. تملَّك بعد والِدِه. لَقِيَ مصرَعَه وهو أمام قلعةِ بربشتر محاصِرًا لعمر بن حفصون رأس الخارجينَ على سُلطانِ الدولة الأمويَّة بالأندلس، كانت ولايتُه سنةً واحدة وأحدَ عشَرَ شهرًا وعشرة أيَّام."},{"id":928,"title":"وفاة أبي داود صاحب السنن .","date":["العام الهجري :275","الشهر القمري : شوال","العام الميلادي :889"],"text":"هو سُليمان بن الأشعث بن إسحاق بن بشير بن شداد السِّجستاني، إمامٌ في الحديث، وُلِدَ بسجستان عام 202ه، رحل إلى بغداد وتفَقَّه فيها على الإمامِ أحمد وغيرِه، ورحل إلى الحجاز والشام ومصر، قال أبو بكر الخَلَّال: \"أبو داود سليمانُ بن الأشعث السجستاني الإمامُ المقدَّم في زمانِه، رجلٌ لم يَسبِقْه إلى معرفةِ تخريجِ العلومِ وبَصرِه بمواضِعِها أحَدٌ مِن أهلِ زمانه، رجلٌ وَرِعٌ مُقَدَّم\"، وقال إبراهيم الحربي: \"أُلِينَ لأبي داودَ الحديثُ، كما أُلينَ لداودَ الحديدُ\"، كان أحدَ حُفَّاظ الإسلام للحديثِ وعِلَلِه وسَنَدِه، وكان في أعلى درجةِ النُّسُك والعَفافِ والصَّلاحِ والوَرَع، من فُرسان الحديثِ، استقَرَّ بالبصرة بناءً على رغبة الموفَّق الخليفةِ العباسي، ودرَّس فيها إلى أن توفِّيَ فيها- رحمه الله تعالى- عن عمر 73 سنة."},{"id":929,"title":"وفاة بقي بن مخلد الأندلسي صاحب المسند .","date":["العام الهجري :276","الشهر القمري : جمادى الآخرة","العام الميلادي :889"],"text":"هو أبو عبدالرحمن بقِيُّ بن مَخلَد بن يزيد أبو عبد الرحمن الأندلسي الحافِظُ الكبير، له المُسنَد المبَوَّب على الفِقهِ، روى فيه عن ألفٍ وستمائة صحابي، وقد فضَّلَه ابنُ حزم على مسند الإمامِ أحمد بن حنبل، وقد رحل بقيٌّ إلى العراقِ، فسَمِعَ من الإمام أحمد وغيرِه من أئمَّة الحديث بالعراق وغيرها، يزيدون على المائتين بأربعة وثلاثين شيخًا، وله تصانيفُ أخرى، وكان رجلًا صالحًا عابدًا زاهدًا مُجابَ الدَّعوة، ومُسنَدُه المذكور مفقودٌ، ليس منه إلَّا جزءٌ يسير."},{"id":930,"title":"وفاة ابن قتيبة الدينوري .","date":["العام الهجري :276","الشهر القمري : رجب","العام الميلادي :889"],"text":"هو أبو محمَّد عبدالله بن مسلم بن قُتَيبة الدِّينَوَري وقيل المروزي، ولد سنة 213ه, خطيبُ أهل السنة، عالمٌ في التفسيرِ واللُّغة، والنحو والأدب، والتاريخ والحديث، تولَّى القضاءَ في دِينَوَر فنُسِبَ إليها، كان شديدًا على المعتَزِلة، عاد إلى بغداد ودرَّسَ فيها، ومن مؤلَّفاتِه غريبُ الحديث، ومُشكِل القرآنِ، وأدب الكاتبِ، وجامِعُ النَّحوِ، وغيرُها، توفي عن 63 سنة."},{"id":931,"title":"ظهور حركة القرامطة في العراق .","date":["العام الهجري :277","العام الميلادي :890"],"text":"بعد أن تمَّ القضاءُ على ثورةِ الزنج، بدأ بالظهورِ دَعوةٌ جديدة كان رائِدَها حمدانُ بن الأشعث المعروف بقَرمَط، جاء من خوزستان إلى الكوفةِ واستقَرَّ بمكانٍ يُسمَّى (النهرين)، وكان يُظهِرُ الزهدَ والتقشُّفَ ويسفُ الخُوصَ ويأكُلُ مِن كَسْبِ يَدِه، ويُكثِرُ الصلاة، فأقام على ذلك مدَّةً، فكان إذا قعد إليه رجلٌ ذاكَرَه في أمر الدينِ وزَهَّدَه في الدنيا وأعلَمَه أنَّ الصلاة المفروضةَ على الناسِ خمسونَ صلاةً في كلِّ يومٍ وليلة، حتى فشا ذلك عنه بموضِعِه، ثمَّ أعلَمَهم أنَّه يدعو إلى إمامٍ مِن آل بيتِ الرَّسولِ، فلم يزَلْ على ذلك حتى استجاب له جمعٌ كثيرٌ، وكان تأثَّرَ أصلًا بالحسين الأهوازي صاحب الإسماعيليِّين، واستلمَ الزَّعامة حمدانُ بعد موت الحسين، فابتنى دارًا لأتباعِه بالكوفة، وفرَضَ على أتباعه مبلغًا يدفعونَه ويَصرِفُه هو في الدَّعوة، كما جعل من أصحابِه اثني عشر نقيبًا، واشترى السلاحَ وأخافَ النَّاسَ فلَحِقَ به بعضُهم خوفًا، وكان القرامِطةُ دُعاةً للإسماعيليَّة في البداية، ثم انحرفوا عنهم بعد أن انحرَفَت الدعوة في السلميَّة- مقر الدَّعوة الإسماعيلية- ولم تعد لأولاد محمَّد بن إسماعيل بل لأولاد عبدالله بن ميمون القدَّاح- ابن مؤسِّس الدعوة- فبدأ بالدعوة بطريقٍ آخَرَ مخالِفًا عن الإسماعيليين؛ مما ولَّد الشقاق بينهم، وأصبحت كلُّ دعوةٍ مُستقلَّةً بنَفسِها، ومن المعروفِ أن هذه الدعوةَ فيها إسقاطٌ للفروضِ مِن الصلاةِ والصَّومِ والحَجِّ وغيرها من التعاليم."},{"id":932,"title":"جفاف ماء النيل وشدة في غلاء الأسعار .","date":["العام الهجري :278","العام الميلادي :891"],"text":"في هذه السَّنةِ غار نَهرُ النِّيلِ، حتى قيل: لم يبق فيه ماءٌ، وهذا ما لم يحصُلْ من قبلُ أبدًا، فكانت شِدَّةٌ وغلاءٌ بالأسعارِ عظيمٌ، ومجاعةٌ وقَحطٌ."},{"id":933,"title":"القرامطة يؤسسون دولتهم في القطيف والأحساء  .","date":["العام الهجري :278","العام الميلادي :891"],"text":"في هذا العام- وقيل عام 281هـ- جاء إلى القطيفِ رجلٌ كذَّابٌ اسمُه يحيى، يدَّعي أنَّه رسولٌ من الإمام المهدي، ويستغِلُّ رغبة المؤمنين بظهور المهديِّ؛ لتحقيقِ مطامِعِه، وأعانه على ذلك رجلٌ ثري اسمه أبو سعيد الجنابي. لكنهما كُشِفا عام 283هـ، وقُبِضَ على يحيى، أمَّا الجنابي فقد هرب، وبعد إطلاق سَراحِه ذهب يحيى للبادية، فاستمال إليه البدوَ وأعانه الجنابيُّ بأموالِه، فكوَّنوا جيشًا قويًّا من عدَّةِ قبائلَ بدَويَّة، وهاجموا القطيفَ واحتلُّوها، وكوَّنوا دولة القَرامِطة، وهرب كثيرٌ مِن الأهالي وانضموا للجيشِ العباسيِّ الذي أرسله الخليفةُ المُعتَضِد، ولكِن قوَّاتُ القرامطة هَزَمت العباسيِّينَ. وفي نفس السنة هاجموا الأحساءَ واحتلُّوها. وفي عام 301هـ اغتِيلَ الجنابيُّ قائدُ القرامطةِ، فتولى الحكمَ مَجلِسٌ عسكريٌّ سُمِّيَ بالعقدانيَّة مُهمَّتُه الوصاية على العرشِ، حتى بلوغ الابن الأكبر سعيد. ولكنَّ الابنَ الأصغرَ سليمان تمكَّنَ من إقصاءِ أخيه وتولَّى الحكم. واعترف به مجلسُ الوصاية، كما اعترف به الفاطميُّونَ حُكَّام مصر (المُعادُونَ للدولة العباسية في العراق) وفي عام 314هـ قام أبو طاهر سُليمان الحاكم القرمطي بنقل العاصمةِ إلى الأحساءِ."},{"id":934,"title":"ذكر قتال ابن حفصون بالأندلس .","date":["العام الهجري :278","الشهر القمري : صفر","العام الميلادي :891"],"text":"خرج الأميرُ عبد الله إلى بلاي مِن عَمَل قبرة، وبها عدوُّ اللهِ ابنُ حفصون مع جماعةٍ كبيرةٍ مِن أصحابِه أهلِ الفسادِ والارتداد. وكانوا قد أضَرُّوا بأقاليمِ قرطبة، وضَيَّقوا عليهم حتى أغاروا على أغنامِ قُرطبة. فخرج إليهم الأميرُ، فناهضه وصادقه القتال، فانهزم ابنُ حَفصون ومن معه، ولجأ إلى حِصنِه مع ملأٍ من أصحابِه، وعُوجِلَ خواصُّه عن الدخول معه، فلم يخلُصْ منهم أحدٌ. فبات الأميرُ قريرَ عَينٍ، والمسلمون كذلك، وقد أخذوا عليه تلك الليلةَ البابَ؛ رجاءَ أن يأتي الصباحُ، فيُؤخَذَ داخِلَ الحِصنِ، لكنه خرج منه مع بعضِ أصحابه، ونجا ونجَوْا. ولَمَّا أصبحَ أُعلِمَ السُّلطانُ بخَبَرِه، فأرسل الخيلَ في أثَرِه، فلم يُعلَمْ له خَبَرٌ. ودخل الأميرُ الحصن فوجده مُترعًا بالذَّخائر، ملآنَ من العُدَد، وكان عددُ عسكرِ الأمير ثمانيةَ عشر ألف فارس. وقيل: إن ابن حفصون ألَّبَ أهل حصون الأندلس كلِّها، وأقبل إليه في ثلاثين ألفًا، ووقعت الحرب بينهم، فانهزم عدوُّ الله، وقُتِلَ أكثَرُ من كان معه، ودخَلَت جملةٌ منهم في مَحلَّة الأمير، فأمر بالتقاطِهم، فأُتي بألف رجُلٍ منهم فقُتِلوا صبرًا بين يديه، ثمَّ قصَدَ الأميرُ إستجة فنازلهم وحاربهم، وقتَلَ منهم عددًا كثيرًا. فلما أخذهم الجَهدُ رفعوا الأطفالَ على الأيدي في الأسوارِ، مُستصرِخينَ ضارِعينَ راغبينَ في العَفوِ، فعفا عنهم"},{"id":935,"title":"وفاة الموفق أخو الخليفة المعتمد على الله  .","date":["العام الهجري :278","الشهر القمري : جمادى الآخرة","العام الميلادي :891"],"text":"هو الموفَّقُ بالله أبو أحمد محمد بن جعفر المتوكِّل على الله بن محمد المعتصم بن هارون الرشيد, وقيل: إن اسمه طلحة، الأميرُ العباسي وقائِدُ جيش الخليفة المعتَمِد على الله. ولِدَ في بغداد عام 227ه من أمِّ ولَدٍ للخليفة المتوكِّل على الله، وتربَّى تربيةً عِلميَّةً، وكان عالِمًا بالأدب والنَّسَب، والفِقه والقضاءِ، غزيرَ العَقلِ، حسَنَ التدبيرِ، كريمًا حازمًا، ذا مَقدِرةٍ في سياسةِ المُلْك، اعتبَرَه البعضُ بأنَّه المنصورُ الثاني. كان الموفَّقُ وليَّ عَهدِ المعتَمِد على الله، إلَّا أنه كان الخليفةَ الفعليَّ. كان الموفَّقُ عادِلًا حسَنَ السِّيرةِ، يَجلِسُ للمظالمِ وعنده القُضاة وغيرُهم، فينتصِفُ النَّاسُ بعضُهم من بعض. كما يعتبَر الموفَّقُ أبا الخلفاء الثاني بعد المنصورِ؛ إذ إنَّ الخلافةَ العباسية استمَرَّت في عَقِبِه حتى سقوطِها على يد هولاكو خان عام 656ه. كما أنَّه بعث الحياةَ في الخلافة العباسية بعد أن أشرَفَت على السقوطِ بسبب حالةِ الفوضى التي سادت على يدِ الأتراك بين عامي 247 - 256 بعد مقتل الخليفةِ المتوكِّل واستبداد الأتراكِ وقادتِهم بالأمرِ وقَتْلِهم للخُلَفاء: المنتصِر، والمُستعين، والمعتَزِّ، والمهتدي، واستقلال أمراء الأطراف بولاياتهم كالصَّفَّاريين في المشرق، والطولونيين في مصر. فقد تحمَّلَ الموفَّقُ بالله أعباءً كبيرةً في سبيل تثبيت الخلافة؛ إذ تمكَّنَ من القضاءِ على ثورةِ الزِّنجِ كما تمكَّنَ من إيقاعِ الهزيمةِ بجُموعِ الصَّفَّاريين وزعيمِهم يعقوبَ بنِ الليث، الذي كان قد اقتَرَب من بغداد في محاولةٍ لإرغام الخليفة على الاعترافِ بسُلطانه على المَشرِق، كما تمكَّنَ أيضًا من الحَدِّ من توسع الطولونيِّين غربًا. أُصيبَ الموفَّقُ بمرض النقرِس في بلاد الجبل، فانصرف وقد اشتَدَّ به وجع النقرس، فلم يقدِرْ على الركوب، فعُمِل له سريرٌ عليه قُبَّة، فكان يقعد عليه، وخادِمٌ له يُبَرِّد رجلَه بالأشياء الباردة، حتى إنَّه يضعُ عليها الثلج، ثم صارت عِلَّة داء الفيل برِجلِه، وهو ورَمٌ عظيمٌ يكون في السَّاق، يسيل منه ماء، ثم بقِيَ في داره مريضًا عِدَّةَ أيام حتى توفي. لَمَّا مات الموفَّقُ اجتمع القواد وبايعوا ابنه أبا العباس بولايةِ العَهدِ، بعد المفَوِّض بن المعتَمِد، ولُقِّبَ المُعتَضِدَ بالله."},{"id":936,"title":"وفاة بازمان نائب مدينة طرسوس .","date":["العام الهجري :278","الشهر القمري : رجب","العام الميلادي :891"],"text":"دخل أحمدُ العجيفي طرسوسَ، وغزا مع بازمان الصائفةَ، فبلغوا شكند، فأصابت بازمان شظيةٌ من حجرِ مَنجَنيقٍ في أضلاعه، فارتحَلَ عن شكند بعد أن أشرَفَ على أخذها, فتوفِّيَ في الطريق، وحُمِلَ إلى طرسوس فدُفِنَ بها. وكان بازمان قد أطاع خِمارَوَيه بن أحمد بن طولون، فلما توفِّيَ خَلَفَه ابنُ عجيف، وكتب إلى خمارَوَيه يُخبِرُه بمَوتِه، فأقَرَّه على ولاية طرسوس، وأمَدَّه بالخيل والسِّلاحِ والذخائر وغيرِها، ثم عزله خمارَوَيه، واستعمَلَ عليها ابنَ عَمِّه محمَّدَ بن موسى بن طولون."},{"id":937,"title":"ثورة أهل طرطوس على خمارَوَيه .","date":["العام الهجري :278","الشهر القمري : شعبان","العام الميلادي :891"],"text":"سببُ ذلك أنَّ الموفَّقَ لَمَّا توفِّيَ كان له خادمٌ من خواصِّه يقال له: راغب، فاختار الجِهادَ، فسار إلى طرسوس على عَزمِ المُقام بها، فلما وصل إلى الشام سيَّرَ ما معه من دوابَّ وآلاتٍ وخيامٍ وغير ذلك إلى طرسوس، وسار هو إلى خمارَوَيه ليزورَه، ويُعَرِّفَه عزمَه، فلما لَقِيَه بدمشق أكرَمَه خمارَوَيه وأحَبَّه وأَنِسَ به، واستحيا راغِبٌ أن يطلُبَ منه المسيرَ إلى طرسوس، فطال مُقامُه عنده، فظنَّ أصحابُه أنَّ خمارَوَيه قبَضَ عليه، فأذاعوا ذلك، فاستعظَمَه الناسُ، وقالوا: يَعمِدُ إلى رجلٍ قصَدَ الجهادَ في سبيل الله فيَقبِضُ عليه! ثم شَغَّبوا على أميرهم محمد ابن عم خمارَوَيه، وقبضوا عليه، وقالوا: لا تزالُ في الحبسِ إلى أن يُطلِقَ ابنُ عَمِّك راغبًا، ونَهَبوا دارَه وهَتَكوا حَرَمَه، وبلغ الخبَرُ إلى خمارَوَيه، فأطْلَعَ راغبًا عليه، وأذِنَ له في المسيرِ إلى طرسوس، فلمَّا بلغ إليها أطلَقَ أهلُها أميرَهم، فلما أطلقوه قال لهم: قبَّحَ اللهُ جِوارَكم، وسار عنها إلى بيت المقدس فأقام به، ولَمَّا سار عن طرسوس عاد العجيفي إلى ولايتِها."},{"id":938,"title":"الخليفة العباسي المعتمد على الله يخلع ابنه من ولاية العهد .","date":["العام الهجري :279","الشهر القمري : محرم","العام الميلادي :892"],"text":"خرج المعتَمِدُ على الله، وجلس للقُوَّادِ والقُضاةِ ووجوهِ النَّاس، وأعلَمَهم أنَّه خلع ابنَه المفَوِّضَ إلى الله جعفرًا من ولايةِ العهد، وجعل ولايةَ العَهدِ للمُعتَضِد بالله أبي العباسِ أحمدَ بنِ الموفَّق، وشَهِدوا على المفَوِّض أنه قد تبرَّأ من العهد، وأسقط اسمَه من السِّكَّة، والخِطبة، والطراز، وغير ذلك، وخُطِبَ للمُعتَضِد، وكان يومًا مشهودًا."},{"id":939,"title":"وفاة الخليفة المعتمد على الله وتولي المعتضد بالله الخلافة .","date":["العام الهجري :279","الشهر القمري : رجب","العام الميلادي :892"],"text":"هو أبو العبَّاس- وقيل أبو جعفر- أحمد المعتَمِدُ على الله بن جعفر المتوكل بن محمد المعتصم بن هارون الرشيد. ولِدَ سنة تسع وعشرين ومائتين بسُرَّ من رأى، وأمُّه روميَّة اسمها فتيان. كان أسمرَ رقيق اللون، خفيفًا، لطيف اللِّحية، أعْيَنَ جميلًا, كان مربوعًا نحيفًا, فلما استُخلِفَ سَمِنَ وأسرع إليه الشَّيبُ، استُخلِفَ بعد قتل المهتدي بالله في سادس عشر رجب سنة 256ه. مكث في الخلافة ثلاثًا وعشرين سنة وستة أيام، كان المعتَمِد أوَّلَ خليفةٍ انتقل من سامرَّا إلى بغداد، ثمَّ لم يعُدْ إليها أحَدٌ من الخلفاء، بل جعلوا إقامتَهم ببغداد، كان سبَبَ هلاكِه- فيما ذكره ابن الأثيرِ- أنَّه شَرِبَ في تلك الليلةِ شَرابًا كثيرًا وتعشَّى عشاءً كثيرًا، وكان وقتُ وفاته في القصر الحُسَيني من بغداد، وحين مات أحضَرَ المعتضِدُ القضاةَ والأعيانَ وأشهَدَهم أنَّه مات حتْفَ أنفِه، ثمَّ غُسِّلَ وكُفِّنَ وصُلِّيَ عليه، ثم حُمِلَ فدُفِنَ بسامِرَّاء،  ثم كانت خلافةُ المُعتَضِد أبي العباس أحمدَ بن أبي أحمد الموفَّق بن جعفر المتوكل، كان من خيارِ خُلَفاء بني العباس ورجالِهم، بويعَ له بالخلافةِ صبيحةَ مَوتِ المُعتَمِد لعشرٍ بَقِين من رجبٍ منها، وقد كان أمرُ الخلافةِ داثرًا فأحياه الله على يديه بعَدْلِه وشهامَتِه وجُرأتِه."},{"id":940,"title":"وفاة الترمذي صاحب السنن .","date":["العام الهجري :279","الشهر القمري : رجب","العام الميلادي :892"],"text":"هو الحافِظُ محمَّدُ بنُ عيسى بن سورة بنِ موسى بن الضحَّاك السلمي التِّرمذي، الضريرُ، قيل: ولِدَ أعمى، والصحيحُ أنه كُفَّ بَصرُه في كِبَرِه، بعد رحلتِه وكتابتِه العِلمَ. وهو أحدُ أئمَّة الحديث في زمانه، وله المصَنَّفات المشهورة؛ منها: الجامِعُ المعروف بالسُّنَن، والشَّمائل، وأسماءُ الصحابة، وغير ذلك، تتلمذَ على البخاريِّ، رحل إلى خُراسان والعراق والحجاز، ورُويَ عنه أنَّه قال: \"صنَّفتُ هذا المُسندَ الصَّحيحَ، وعرضتُه على علماءِ الحجاز فَرَضُوا به، وعرَضتُه على عُلماءِ العِراقِ فَرَضُوا به، وعرضتُه على علماء خُراسان فَرَضُوا به، ومن كان في بيتِه هذا الكتابُ، فكأنَّما في بيتِه نبيٌّ يَنطِقُ، وفي رواية يتكَلَّم\"، أصيبَ بالعمى في آخِرِ حياتِه، وتوفِّي في ترمذَ، مكانِ ولادتِه."},{"id":941,"title":"بناء دار الخلافة في بغداد .","date":["العام الهجري :280","العام الميلادي :893"],"text":"أوَّلُ مَن بناها المعتضدُ بالله في هذه السَّنة، وهو أوَّلُ مَن سكَنَها من الخلفاءِ إلى آخرِ دولتِهم، وكانت أولًّا دارًا للحسَنِ بنِ سَهلٍ تُعرَفُ بالقصرِ الحَسَني، ثم صارت بعد ذلك لابنتِه بُوران زوجةِ المأمون، ثم أَصلحَت ما وَهَى منها ورَمَّمَت ما كان قد تشعَّثَ فيها، وفرَشَتْها بأنواعِ الفُرشِ في كُلِّ مَوضعٍ منها ما يليقُ به من المفارشِ، وأسكَنَتْه ما يليقُ به من الجواري والخَدَمِ، وأعدَّت بها المآكلَ الشَّهيَّة وما يَحسُن ادِّخاره في ذلك الزمان، ثم أرسَلَت مفاتيحَها إلى المعتَضِد، فلمَّا دخلها هالَه ما رأى من الخيراتِ، ثمَّ وسَّعَها وزاد فيها وجعل لها سورًا حَولَها، وكانت قدرَ مدينة شيراز، فبنى المعتضِدُ فيها الميدانَ، ثم بنى فيها قصرًا مُشرِفًا على دجلةَ، ثمَّ بنى فيها المُكتفي التَّاجَ، فلما كان أيَّام المقتدر زاد فيها زياداتٍ أخرى كبيرةً وكثيرةً جِدًّا، ثم بعد هذا كُلِّه خَربَت حتى كأنْ لم يكُنْ مَوضِعَها عمارةٌ، وتأخَّرَت آثارُها إلى أيام التتار الذين خَرَّبوها وخَرَّبوا بغداد، وقال الخطيبُ البغدادي: والذي يُشبِهُ أنَّ بُورانَ وهبت دارها للمعتَمِد لا للمعتَضِد؛ فإنَّها لم تعِشْ إلى أيَّامه, وقد تقَدَّمَت وفاتُها\"."},{"id":942,"title":"المعتضد بالله يقضي على فتنة بني شيبان في الموصل .","date":["العام الهجري :280","الشهر القمري : صفر","العام الميلادي :893"],"text":"كان بنو شَيبانَ قد أفسدوا في الأرضِ وأخذوا يُغِيرونَ على المَوصِل وينهبون ويَسلبونَ، فتصدَّى لهم الخوارجُ وأهلُ الموصِلِ إلَّا أنهم هزموهم, فسار إليهم المعتَضِد، وقصدَ الموضِعَ الذي يجتمعونَ به من أرضِ الجزيرة، فلمَّا بلَغَهم قَصدُه جمعوا إليهم أموالَهم، فأغار عليهم وأوقعَ بهم، فقتَلَ منهم مقتلةً عظيمةً وغَرِقَ منهم خلقٌ كثيرٌ في الزابين – فروع أنهارٍ حَولَ الفُرات- وأخذ النِّساءَ والذراريَّ وغَنِم أهلُ العَسكرِ مِن أموالِهم ما أعجَزَهم حَملُه، وأخذَ مِن غَنَمِهم وإبلِهم ما كثُرَ في أيدي الناس حتى بِيعَت الشاةُ بدِرهَم والجَمَلُ بخَمسةِ دراهِمَ، وأَمَرَ بالنساءِ والذراريِّ أن يُحفَظوا حتى يحدروا إلى بغداد، ثم مضى المعتضِدُ إلى الموصِل، ثم إلى بلدٍ، ثم رجع إلى بغدادَ فلَقِيَه بنو شيبان يسألونَه الصَّفحَ عنهم وبذلوا له الرهائِنَ، فأخذ منهم خمسَمائة رجلٍ فيما قيل، ورجع المعتضِدُ يريد مدينة السَّلام."},{"id":943,"title":"نشوء الدولة الزيدية في مدينة صعدة باليمن .","date":["العام الهجري :280","الشهر القمري : صفر","العام الميلادي :893"],"text":"كان يَحيى بنُ الحُسَين بن القاسم بن إبراهيم بن إسماعيلَ بنِ إبراهيم بن الحسن بن الحسَن بن علي بن أبي طالب، يقيمُ بالمدينة المنوَّرة، فجاءه وفٌد مِن اليمَنِ يدعوه للمُقامِ في بلادهم وأن يقومَ لهم بأمرِهم، فسافر إليهم في هذا العامِ، غيرَ أنَّه لم يجد ما كان يتوقَّعُه، فعاد للمدينةِ، فجاءه وفدٌ آخَرُ فاعتذر إليه ممَّا كان ووعدوه بالنَّصرِ فرجع إليهم، وأقام في صعدة، ثمَّ بدأت الدولةُ تتأسَّسُ وتَقوى، وكانت بينهم وبين بني يعفر حروبٌ على مدى السَّنَواتِ."},{"id":944,"title":"ظهور القرامطة في البحرين .","date":["العام الهجري :281","العام الميلادي :894"],"text":"كان ابتداءُ القرامِطةِ بناحية البحرين أنَّ رجُلًا يُعرفُ بيحيى بن المهدي قصدَ القَطيفَ فنزل على رجلٍ يُعرَفُ بعليِّ بن المعلي بن حمدان، مولى الزياديِّين، وكان مُغاليًا في التشيُّع، فأظهَرَ له يحيى أنَّه رسولُ المهدي، وكان ذلك سنة 281، وذكَرَ أنه خرج إلى شيعتِه في البلاد يدعوهم إلى أمرِه، وأنَّ ظهورَه قد قَرُب، فوجه عليُّ بن المعلي إلى الشيعةِ مِن أهل القطيف فجمَعَهم، وأقرأهم الكتابَ الذي مع يحيى بن المهدي إليهم من المهديِّ، فأجابوه، وأنهم خارجونَ معه إذا أظهر أمرَه، ووجَّه إلى سائر قرى البحرين بمثلِ ذلك فأجابوه، وكان فيمن أجابه أبو سعيدٍ الجنابي. كان يبيعُ للنَّاسِ الطَّعام، ويَحسِبُ لهم بيعَهم، ثم غاب عنهم يحيى بن المهديِّ مُدَّة، ثم رجع ومعه كتابٌ يزعُمُ أنَّه من المهدي إلى شيعته، فيه: قد عرَّفَني رسولي يحيى بن المهدي مسارعتَكم إلى أمري، فليدفَعْ إليه كل رجل منكم ستةَ دنانيرَ وثُلُثَين، ففعلوا ذلك. ثم غاب عنهم، وعاد ومعه كتابٌ فيه أنِ ادفَعوا إلى يحيى خُمسَ أموالِكم، فدفعوا إليه الخُمُس. وكان يحيى يتردَّدُ في قبائل قيس، ويوردُ إليهم كتبًا يزعُمُ أنَّها مِن المهدي، وأنَّه ظاهِرٌ، فكُونوا على أُهبَةٍ. وحكى إنسانٌ منهم يقالُ له إبراهيم الصائغ أنَّه كان عند أبي سعيدٍ الجنابي، وأتاه يحيى، فأكلوا طعامًا، فلما فرغوا خرج أبو سعيدٍ مِن بيتِه، وأمر امرأتَه أن تدخُلَ إلى يحيى، وألَّا تمنَعَه إن أرادها، فانتهى هذا الخبَرُ إلى الوالي، فأخذ يحيى فضرَبَه، وحلق رأسَه ولحيَتَه، وهرب أبو سعيدٍ الجنابي إلى جنابا، وسار يحيى بن المهدي إلى بني كلابٍ، وعَقيل، والخريس، فاجتمعوا معه ومع أبي سعيدٍ، فعَظُمَ أمرُ أبي سعيد."},{"id":945,"title":"خِمارَوَيه أميرُ مِصرَ يغزوِ بلاد الرومِ .","date":["العام الهجري :281","العام الميلادي :894"],"text":"أرسل خِمارَوَيه أميرُ مِصرَ طغج بن جف إلى غزوِ الرومِ، فتوجَّهَ مِن طرسوس حتى بلغ طرابزون، وفتح ملورية في جُمادى الآخرة، ودامت الحربُ بين المسلمين والروم اثني عشر يومًا، فظَفِرَ المسلمونَ وغَنِموا غنائمَ كثيرةً ثمَّ عادوا."},{"id":946,"title":"هدم دار الندوة بمكة وبناء مسجد مكانها .","date":["العام الهجري :281","العام الميلادي :894"],"text":"كانت دارُ النَّدوةِ عامرةً بالحَرَمِ تجاهَ الكعبةِ في مكَّةَ المُكرَّمة مِن الجِهةِ الشَّماليَّة الغربيَّة، وكان ينزِلُ بها الخُلَفاءُ والأُمَراءُ في حجِّهم في صدرِ الإسلام، ولكنَّها أُهمِلَ أمرُها في مُنتصَفِ القَرنِ الثالثِ الهجريِّ فأخذ يتهَدَّمُ بناؤُها. فكتب في ذلك إلى الخليفةِ المُعتَضِد العباسيِّ، فأمر بها فهُدِمَت في هذا العامِ وجُعِلَت مسجِدًا وفيها قبلةٌ إلى الكعبةِ، ثم بُني له قُبَّةٌ عاليةٌ."},{"id":947,"title":"مسير المعتضِد بالله إلى المَوصِل لقتال الخوارج .","date":["العام الهجري :281","الشهر القمري : ذي القعدة","العام الميلادي :895"],"text":"خرج المعتضِدُ إلى المَوصِل، قاصدًا حَمدانَ بنَ حمدون التغلبيَّ؛ لأنَّه بلغه أنَّ حَمدانَ التَّغلِبيَّ مال إلى هارون الشاري الخارجي، ودعا له، فلمَّا بلغ الأعرابَ والأكرادَ مَسيرُ المعتَضِد تحالَفوا أنَّهم يُقاتِلونَ على دمٍ واحد، واجتمعوا وعَبَّوا عسكرَهم، وسار المعتضِدُ إليهم في خَيلِه، فأوقع بهم، وقتل منهم، وغرِقَ منهم في الزابِ خَلقٌ كثير. ثم تابع المعتَضِدُ سَيرَه إلى الموصل يريد قلعةَ ماردين، وكانت لحمدانَ بنِ حمدون، فهرب حمدانُ منها وخَلَّفَ ابنَه بها فنازلها المعتَضِد، وقاتل مَن فيها يومَه ذلك، فلما كان من الغدِ ركبَ المعتَضِدُ فصَعِد إلى باب القلعة، وصاح: يا ابنَ حَمدانَ, فأجابه، فقال له: افتَحِ الباب، ففَتَحه، فقعد المعتَضِدُ في الباب، وأمر بنقلِ ما في القلعةِ وهَدمِها، ثم وجه خلفَ ابنِ حمدون، وطُلِبَ أشدَّ الطَّلَبِ، وأُخِذَت أموالٌ له، ثم ظفرَ به المعتَضِد بعد عودتِه إلى بغدادَ."},{"id":948,"title":"اغتيال خمارويه حاكم الدولة الطولونية .","date":["العام الهجري :282","العام الميلادي :895"],"text":"كان خِمارَوَيه في دمشقَ في قاسيون، وكان قد بلغه أنَّ جاريةً له قد اتَّخَذت خَصِيًّا له كالزَّوجِ لها، فلمَّا عَلِمَ بذلك وأراد أن يقتُلَه تمالأ الخدَمُ على قتلِه فقَتَلوه وهو في فراشِه ذبحًا، ثم أُخِذَ الخدَمُ وقُتِلوا وكانوا أكثَرَ مِن عشرين، وقيل غيرُ ذلك في سبب قتلِه، ثم حُمِلَ في تابوتٍ إلى مصرَ ودُفِنَ فيها، وتوَّلى الحكم بعده ابنَه جيشَ بنَ خِمارَوَيه"},{"id":949,"title":"المعتضِد بالله يقضي على فتنة الخارجي هارون الشاري .","date":["العام الهجري :282","العام الميلادي :895"],"text":"خلَّفَ المعتَضِدُ بالموصِلِ نصرًا القشوريَّ يَجبي الأموالَ ويُعينُ العُمَّال على جبايتها، فخرج عامل معلثايا - معلثايا قريةٌ غَربَ مدينة دهوك- إليها ومعه جماعةٌ مِن أصحاب نصرٍ، فوقع عليهم طائفةٌ مِن الخوارجِ، فاقتتلوا إلى أن أدرَكَهم الليلُ وفَرَّقَ بينهم، وقُتِلَ من الخوارج إنسان اسمُه جعفر، وهو من أعيان أصحابِ هارون، فعَظُم عليه قتلُه، وأمر أصحابَه بالإفسادِ في البلادِ، فكتب نصرٌ القشوري إلى هارونَ الخارجيِّ كتابًا يتهدَّدُه بقُرب الخليفة، فلما قَدِمَ المعتَضِد، جَدَّ في قَصدِه، وولَّى الحسَنَ بن عليٍّ كورةَ المَوصِل، وأمره بقصدِ الخوارج، وأمرَ مُقدَّمِي الولاياتِ والأعمالِ كافةً بطاعتِه، فجَمَعَهم، وسار إلى أعمال المَوصِل، وخندقَ على نفسِه، وأقام إلى أن رفعَ النَّاسُ غُلاتَهم، ثم سار إلى الخوارج، وعبَرَ الزابَ إليهم، فلَقِيَهم قريبًا من المغلَّة، وتصافُّوا للحرب، فاقتتلوا قتالًا شديدًا، وانكشف الخوارجُ عنه ليفَرِّقوا جمعيَّتَه ثم يَعطِفوا عليه، فأمر الحسَنُ أصحابَه بلزومِ مواقِفِهم، ففعلوا فرجعَ الخوارِجُ وحَمَلوا عليهم سبعَ عشرةَ حملةً، فانكشفت ميمنةُ الحسَنِ، وقُتِلَ من أصحابه، وثبت هو، فحمَلَ الخوارجُ عليه حملةَ رجلٍ واحدٍ، فثبت لهم وضُرِبَ على رأسِه عِدَّةُ ضربات فلم تؤثِّرْ فيه. فلما رأى أصحابُه ثباتَه تراجعوا إليه وصبَرُوا، فانهزم الخوارجُ أقبَحَ هزيمةٍ، وقُتِلَ منهم خلقٌ كثيرٌ، وفارقوا موضِعَ المعركة، ودخلوا أذربيجان. وأمَّا هارون فإنَّه تحيَّرَ في أمره، وقصَدَ البرِّية، ونزل عند بني تغلِب، ثم عاد إلى معلثايا ثم عاد إلى البرِّية، ثم رجع عبْرَ دجلة إلى حزةَ، وعاد إلى البرية. وأمَّا وجوهُ أصحابه، فإنَّهم لَمَّا رأوا إقبالَ دولة المعتَضِد وقوَّتَه، وما لَحِقَهم في هذه الوقعةِ، راسلوا المعتضِدَ يطلُبون الأمانَ فأمَّنَهم، فأتاه كثيرٌ منهم، يبلُغون ثلاثَمائة وستينَ رجُلًا، وبقي معه بعضُهم يجولُ بهم في البلادِ، إلى أن قُتِلَ سنة 383هـ، حيث لاحَقَه الحسينُ بنُ عبدانَ التغلِبيُّ حتى قبَضَ عليه وأرسلَه للمعتَضِد الذي قتله وصَلَبه."},{"id":950,"title":"ملك الروم يستعين بأسارى المسلمين في قتال نصارى الصقالبة .","date":["العام الهجري :283","العام الميلادي :896"],"text":"في هذه السَّنة سارت الصَّقالِبة (البلغار) إلى الرُّوم، فحصروا القُسطنطينية، وقتلوا من أهلِها خَلقًا كثيرًا وخَرَّبوا البلادَ، فلما لم يَجِدْ ملِكُ الرومِ منهم خلاصًا، جمع مَن عنده مِن أُسارى المُسلمين، وأعطاهم السِّلاحَ، وسألهم مَعونتَه على الصَّقالبة، ففعلوا وكَشَفوا الصَّقالبة وأزاحوهم عن القُسطنطينية، ولَمَّا رأى ملِكُ الروم ذلك خاف المسلمينَ على نفسِه، فردَّهم وأخذ السلاحَ منهم، وفرَّقَهم في البلاد؛ حذرًا من جنايتِهم عليه."},{"id":951,"title":"عصيان رافع بن هرثمة على الخليفة المُعتَضِد .","date":["العام الهجري :283","العام الميلادي :896"],"text":"كان الخليفةُ المُعتَضِد قد عزل رافِعَ بنَ هرثمةَ مِن ولاية خُراسان وأعطاها لعمرِو بنِ الليث، وذلك عام 279هـ، فأعلن رافِعٌ العصيانَ، وانضم إلى محمَّدِ بنِ زيد العلوي بطبرستان، فجهَّز جيشًا وتوجَّه إلى خراسان لاستردادِها، فخرج إليه عمرُو بنُ الليث بجيشٍ واقتتل الطرفان في معركةٍ قرب طوس، فهرب رافِعٌ إلى خوارزم فتعَقَّبَه عمرو إلى أن قبضَ عليه وقتَلَه، وأرسل رأسَه إلى المعتَضِد."},{"id":952,"title":"وفاة الشاعر ابن الرومي .","date":["العام الهجري :283","العام الميلادي :896"],"text":"هو أبو الحسَنُ عليُّ بنُ العبَّاسِ بن جريج، مولى آل المنصورِ, أصلُه روميٌّ يُوناني، شاعِرُ زمانِه مع البحتريِّ، وُلد سنة 221. كان من كُتَّاب الدواوين، غلب عليه الشِّعرُ فلم يُعرَفْ إلَّا به، كان مُرَّ الهِجاءِ، قيل توفِّيَ مسمومًا بأمر القاسم بن عبيدالله وزيرِ المعتَضِد؛ لأنه أكثَرَ مِن هجائِه وأفحشَ، توفِّي في بغداد عن 62 عامًا. وقيل: مات سنة 284."},{"id":953,"title":"اغتيال أبي العساكر بن خمارويه حاكم الدولة الطولونية .","date":["العام الهجري :283","العام الميلادي :896"],"text":"خرج جماعةٌ مِن قُوَّاد حاكِمِ مِصرَ جيشِ بنِ خِمارَوَيه، وجاهروا بالمُخالفة، وقالوا: لا نرضى بك أميرًا فاعتَزِلْنا حتى نولِّي عَمَّك الإمارةَ. وكان سببُ ذلك أنَّه لَمَّا وَلِيَ وكان صبيًّا قَرَّبَ الأحداثَ والسفلَ، وأخلد إلى استماعِ أقوالهم، فغَيَّروا نيَّته على قوَّادِه وأصحابه، وصار يقعُ فيهم ويذُمُّهم، ويُظهِرُ العزمَ على الاستبدالِ بهم، وأخذَ نَعَمَهم وأموالَهم، فاتَّفَقوا عليه ليقتلوه ويقيموا عمَّه، فبلغه ذلك فلم يكتُمْه بل أطلق لسانَه فيهم، ففارَقَه بعضُهم، وخلعه طغج بن جف أميرُ دمشق. وسار القوَّادُ الذين فارقوه إلى بغداد، وهم محمَّد بن إسحاق بن كنداجيق، وخاقان المفلحي وبدر بن جف، أخو طغج، وغيرُهم من قوَّاد مصر، وقَدِموا على المعتَضِد، وبقِيَ سائرُ الجنود بمصر على خِلافِهم ابنَ خِمارَوَيه، فسألهم كاتبُه عليُّ بن أحمد الماذرائي أن ينصرفوا يومَهم ذلك، فرجعوا فقتَلَ جيشُ بنُ خِمارَوَيه عمَّينِ له، وبكَّر الجندُ إليه، فرمى بالرأسينِ إليهم، فهجَمَ الجندُ على جيشِ بنِ خِمارَوَيه فقتلوه ونهبُوا داره، ونهبوا مصرَ وأحرَقوها، وأقعدوا أخاه هارونَ بنَ خِمارَوَيه في الإمرةِ بعدَه، فكانت ولايتُه تسعةَ أشهرٍ."},{"id":954,"title":"وفاة البحتري الشاعر المشهور .","date":["العام الهجري :284","العام الميلادي :897"],"text":"هو أبو عُبادةَ الوليدُ بنُ عبيدِ بنِ يحيى الطائي البُحتري المنبجي القحطاني، صاحِبُ الديوان المعروف، شاعرٌ كبيرٌ يقال لِشعِرِه سلاسِلُ الذَّهَبِ، كان أحدَ أشعَرِ أهلِ عَصرِه، وُلِدَ بمَنبج إحدى قرى حلب عام 206ه وهو أحدُ الثلاثة الذين كانوا أشعَرَ أبناءِ عَصرِهم: هو، والمتنَبِّي، وأبو تمَّام، قيل إنَّ أبا تمام لَمَّا سمع شِعرَه قال: نُعِيَت إليَّ نَفسي، رحلَ البُحتري إلى العراق متكسِّبًا بشِعرِه، فكان يمدحُ ويهجو على حسَبِ ذلك، اتُّهِم بالبخلِ وقِلَّة الوفاء؛ بسبب ذلك التقلُّبِ بالمديح والهجاء، أمَّا شِعرُه فغلب عليه الوصفُ وسُهولةُ التراكيبِ، مع براعةٍ في الوصف والخيال، اعتزل في آخِرِ أيامِه في مدينة مولده منبج، حتى مات فيها عن 78 عامًا."},{"id":955,"title":"فتنة في مدينة طرسوس بين أتباع الدولة العباسية والطولونية .","date":["العام الهجري :284","العام الميلادي :897"],"text":"كان سبَبُ الفِتنةِ أنَّ راغِبًا مولى المُوَفَّق ترك الدُّعاءَ لهارون بن خِمارَوَيه بن أحمد بن طولون، ودعا لبدر مولى المعتَضِد، واختلف هو وأحمدُ بن طوغان، فلمَّا انصرف أحمدُ بنُ طوغان من الفداء سنة 283 ركب البحرَ ومضى، ولم يدخُلْ طرسوس، وخلَّفَ دِميانةَ غلامَ بازمان بها للقيامِ بأمرها، وأمَدَّه ابن طوغان، فقَوِيَ بذلك، وأنكر ما كان يفعَلُه راغب، فوقعت الفتنةُ، فظَفِرَ بهم راغب، فحمل دميانةَ إلى بغداد، ثمَّ في هذه السنة قَدِمَ قَومٌ من أهل طرسوس على المعتَضِد يسألونه أن يولِّيَ عليهم واليًا، وكانوا قد أخرجوا عامِلَ ابنِ طولون، فسيَّرَ إليهم المعتضدُ ابنَ الإخشيدِ أميرًا."},{"id":956,"title":"بداية لعن معاوية بن أبي سفيان على المنابر  .","date":["العام الهجري :284","العام الميلادي :897"],"text":"عزَمَ المُعتَضِد على لعْنِ مُعاويةَ بنِ أبي سفيانَ- رضيَ اللهُ عنه- على المنابرِ، فحَذَّره وزيرُه عبدُ الله بن وهب، وقال له: إنَّ العامَّةَ تُنكِرُ قُلوبُهم ذلك، وهم يترحَّمونَ عليه ويترَضَّونَ عنه في أسواقِهم وجوامِعِهم، فلم يلتَفِتْ إليه، بل أمر بذلك وأمضاه، وكتب به نُسخًا إلى الخُطَباءِ بلَعنِ مُعاويةَ، وذكَرَ فيها ذمَّه وذَمَّ ابنِه يزيدَ بنِ معاوية وجماعةٍ مِن بني أمية، وأورد فيها أحاديثَ باطلةً في ذمِّ مُعاويةَ وقُرِئَت في الجانبينِ مِن بغداد، ونُهِيَت العامةُ عن الترحم على معاويةَ والتَّرضِّي عنه، فلم يزَلْ به الوزير حتى قال له فيما قال: يا أميرَ المؤمنينَ، إنَّ هذا الصنيعَ لم يسبِقْك أحَدٌ من الخلفاء إليه، وهو ممَّا يُرَغِّبُ العامَّةَ في الطالبيِّينَ وقَبولِ الدعوةِ إليهم، فوَجَم المعتَضِدُ عند ذلك؛ تخوفًا على المُلْك."},{"id":957,"title":"اضطرابات في مصر على هارون بن خمارويه .","date":["العام الهجري :284","العام الميلادي :897"],"text":"ظهر اختلالُ حالِ هارونَ بنِ خِمارَوَيه بنِ أحمد بن طولون بمصر، واختلَفَت القوَّاد، وطَمِعوا فانحَلَّ النظام، وتفَرَّقَت الكلمة، فأقاموا له أحدَ أمراءِ أبيه يديرُ الأمورَ ويُصلِحُ الأحوال، وهو أبو جعفرِ بن أبان، وكان عند والدِه وجَدِّه مُقَدَّمًا كبيرَ القَدرِ، فأصلحَ مِن الأحوالِ ما استطاع، وكان مَن بدمشق من الجُندِ قد خالفوا على أخيه جيشِ بنِ خِمارَوَيه، فلما تولى أبو جعفرٍ الأمورَ سَيَّرَ جيشًا إلى دمشق عليهم بدرُ الحمامي، والحسينُ بن أحمد الماذرائي، فأصلحا حالَها وقرَّرا أمور الشامِ، واستعملا على دمشقَ طغج بن جف واستعملا على سائر الأعمال، ورجعا إلى مصرَ والأمور فيها اختلالٌ، والقُوَّاد قد استولى كلُّ واحدٍ منهم على طائفةٍ مِن الجند وأخذَهم إليه، وهكذا يكون انتقاضُ الدُّوَل، وإذا أراد الله أمرًا فلا مَرَدَّ لحُكمِه، وهو سريعُ الحِسابِ."},{"id":958,"title":"راغِبٌ الخادِمُ مَولى المُوفَّقُ يغزو بلادَ الرومِ .","date":["العام الهجري :285","العام الميلادي :898"],"text":"غزا راغِبٌ الخادِمُ مَولى المُوفَّقُ بلادَ الرومِ ففتح حصونًا كثيرةً، وأسَرَ ذراريَّ كثيرةً جِدًّا، وقتَلَ مِن أُسارى الرجالِ الذين معه ثلاثةَ آلاف أسير، ثم عاد سالِمًا مُؤَيَّدًا منصورًا."},{"id":959,"title":"ابنُ الإخشيد نائب مدينة طرسوس يغزو بلادَ الرومِ .","date":["العام الهجري :285","العام الميلادي :898"],"text":"غزا ابنُ الإخشيد بأهلِ طرسوس بلادَ الرومِ، ففتح اللهُ على يديه حصونًا كثيرةً، ولله الحمدُ."},{"id":960,"title":"وفاة أبي العباس محمد بن يزيد المعروف بالمبرد .","date":["العام الهجري :285","الشهر القمري : ذي الحجة","العام الميلادي :899"],"text":"هو إمامُ النحو أبو العبَّاس محمَّدُ بنُ يزيدَ بنِ عبد الأكبر الأزديُّ الثمالي المعروف بالمُبَرِّد، النحويُّ البصري. ولِدَ بالبصرة عام 210 إمامٌ في اللغة العربية، أخذ ذلك عن المازنيِّ وأبي حاتم السِّجستاني، وكان إمامًا علَّامةً، جميلًا وسيمًا، فَصيحًا مُفَوَّهًا، ثقةً ثَبتًا فيما ينقُلُه, كان المبَرِّدُ مناوِئًا وزميلًا لأبي العبَّاسِ أحمد بن يحيى المشهور بثَعلب. والمبرد يحِبُّ مناظرتَه والاستكثارَ منها، بينما ثعلب كان يكرهُ ذلك ويمتَنِعُ عنه لتفَوُّقِه عليه, وله كتابُ \"الكامِلُ في الأدَب\"."},{"id":961,"title":"المعتضد بالله يحاصر مدينة آمد ويأخذها بالأمان .","date":["العام الهجري :285","الشهر القمري : ذي الحجة","العام الميلادي :899"],"text":"لَمَّا توفِّيَ أحمدُ بنُ عيسى بن الشيخ الشَّيباني صاحِبُ ديار بكر، قام بعده ابنُه محمد بآمد وما يليها على سبيل التغَلُّب، فسار المعتَضِدُ إلى آمد بالعساكر، ومعه ابنُه أبو محمد علي المُكتَفي، وجعل طريقَه على الموصِل، فوصل آمدَ، وحصرها إلى ربيع الآخر من سنة 286، ونصب عليها المجانيقَ، فأرسل محمَّد بن أحمد بن عيسى يطلبُ الأمانَ لنفسه، ولِمَن معه، ولأهل البلد، فأمَّنَهم المعتضد، فخرج إليه وسلَّم البلد، فخلع عليه المُعتَضِد وأكرَمَه، وهدم سورَها. ثم بلغه أنَّ محمَّدَ بن أحمد يريد الهربَ، فقبض عليه وعلى أهلِه."},{"id":962,"title":"قتال بين إسماعيلَ الساماني وعمرو بن الليث الصَّفار .","date":["العام الهجري :286","العام الميلادي :899"],"text":"قامت الحربُ بين إسماعيلَ بنِ أحمدَ الساماني وعمرو بن الليث بنِ يعقوبَ الصَّفار؛ وذلك أنَّ عمرَو بنَ الليث لَمَّا قَتلَ رافِعَ بن هرثمة وبعث برأسِه إلى الخليفةِ، سأل منه أن يُعطِيَه ما وراء النهرِ مضافًا إلى ما بيده من ولاية خُراسان، فأجابه إلى ذلك فانزعج لذلك إسماعيلُ بنُ أحمد الساماني نائبُ ما وراء النهر، وكتب إليه: إنَّك قد وُلِّيتَ دنيا عريضةً فاقتَنِعْ بها عمَّا في يديَّ مِن هذه البلاد، فلم يقبَلْ، فأقبل إليه إسماعيلُ في جيوشٍ عظيمةٍ جدًّا، فالتقيا عند بلخ فهُزِمَ أصحابُ عمرو، وأُسِرَ عمرٌو، فلما جيء به إلى إسماعيلَ بنِ أحمد قام إليه وقبَّلَ بين عينيه وغسَلَ وجهَه وخلع عليه وأمَّنَه وكتب إلى الخليفةِ في أمره، ويُذكَرُ أنَّ أهلَ تلك البلاد قد مَلُّوا وضَجِروا من ولايته عليهم، فجاء كتابُ الخليفة بأن يتسَلَّمَ حواصِلَه وأموالَه فسَلَبَه إيَّاها، فآل به الحالُ بعد أن كان مطبخُه يُحمَلُ على ستِّمائةِ جمل إلى القيدِ والسَّجنِ، ومن العجائب أنَّ عَمرًا كان معه خمسونَ ألف مقاتل لم يُصَب أحدٌ منهم ولا أُسِر سواه وحده، وهذا جزاءُ مِن غلب عليه الطَّمعُ، وقاده الحِرصُ حتى أوقعه في ذُلِّ الفَقرِ، وهذه سنَّةُ الله في كل طامعٍ فيما ليس له، وفي كلِّ طالبٍ للزيادةِ في الدُّنيا."},{"id":963,"title":"ظهور أبي سعيد الجنابي القرمطي في البحرين .","date":["العام الهجري :286","العام الميلادي :899"],"text":"ظهر أمرُ رجلٍ مِن القرامطة يُعرَفُ بأبي سعيد الجنابي بالبحرين، كان أوَّلَ أمرِه يبيعُ للنَّاسِ الطعامَ ويحسِبُ لهم بيعَهم، ثم أصبح أبو سعيدٍ مِن أبرز أتباعِ يحيى بن المهديِّ رسولِ المهديِّ المُنتظَر- على زعمِهم- فاجتمع إليه جماعةٌ مِن الأعراب والقرامطة، وقَوِيَ أمرُه، فقتَلَ مَن حولَه من أهلِ القُرى، ثمَّ سار إلى القطيف فقتَلَ ممَّن بها وأظهر أنَّه يريد البصرةَ، فكتب أحمدُ بنُ محمد بن يحيى الواثقي- وكان متولِّيَ البصرةِ- إلى المعتضِد بذلك، فأمره بعمَلِ سورٍ على البصرةِ."},{"id":964,"title":"إظهار عمر بن حفصون النصرانية بالأندلس .","date":["العام الهجري :286","العام الميلادي :899"],"text":"أظهر عُمَرُ بنُ حفصون النصرانيَّة، وكان قد خرج في الأندلسِ على أميرها وحصَلَت بينهم عدَّةُ وقائِعَ، وكان قبل ذلك يُسِرُّها، وانعقد مع أهلِ الشِّركِ وباطَنَهم، ونفر عن أهلِ الإسلام ونابَذَهم، فتبرأ منه خلقٌ كثير، ونابذه عوسجة بن الخليع، وبنى حصِنَ قنبط، وصار فيه مواليًا للأمير عبد الله، محاربًا لابنِ حفصون, فرأى جميعُ المسلمينَ أنَّ حَربَه جهادٌ، فتتابعت عليه الغزواتُ بالصوائفِ والشَّواتي من ذلك الوقتِ."},{"id":965,"title":"قتل محمد بن زيد العلوي صاحب طبرستان .","date":["العام الهجري :287","العام الميلادي :900"],"text":"كان سببُ قَتلِ محمَّدِ بنِ زيد العَلويِّ أنَّه لَمَّا عَلِمَ بأسر عمرِو بن الليث الصَّفَّار، خرج من طبرستان نحو خراسان ظنًّا منه أنَّ إسماعيل الساماني لا يتجاوزُ عَمَلَه، ولا يقصِدُ خُراسان، وأنه لا دافِعَ له عنها، فلما سار إلى جُرجان أرسل إليه إسماعيل، وقد استولى على خُراسان، يقول له: الزَمْ عمَلَك، ولا تقصِدْ خُراسان؛ وتَرك جُرجان له، فأبى ذلك محمد، فندب إليه إسماعيلُ بنُ أحمد، محمَّدَ بنَ هارون، ومحمَّدٌ هذا كان يخلُفُ رافِعَ بنَ هرثمة أيَّامَ ولايتِه خراسان، فجمع محمَّدٌ جمعًا كثيرًا من فارسٍ وراجلٍ، وسار نحوَ محمَّد بن زيد، فالتَقَوا على باب جرجان، فاقتتلوا قتالًا شديدًا، فانهزم محمد بن هارون أوَّلًا ثم رجع وقد تفَرَّقُ أصحاب محمد بن زيد في الطلبِ، فلما رأوه قد رجع إليهم ولَّوا هاربينَ، وقُتِلَ منهم بشَرٌ كثيرٌ، وأصابت ابنَ زيدٍ ضَرَباتٌ، وأُسِرَ ابنُه زيد، وغَنِمَ ابنُ هارون عسكَرَه وما فيه، ثم مات محمَّد بن زيد بعد أيَّامٍ مِن جراحاته التي أصابته، فدُفِنَ على باب جرجان, وحُمِلَ ابنُه زيد بن محمد إلى إسماعيل بن أحمد، فأكرمه ووسَّعَ في الإنزال عليه، وأنزله بُخارى، وسار محمَّدُ بن هارون إلى طبرستان."},{"id":966,"title":"الروم يغيرون على طرسوس ويأسرون أميرها .","date":["العام الهجري :287","العام الميلادي :900"],"text":"اجتمَعَت الروم وتحشَّدَت، ووافت بابَ قلميَّة من طرسوس، فنفر أبو ثابتٍ أميرُ طرسوس بعد كوت بن الإخشيد، وكان استخلَفَه عند موته، فبلغ أبو ثابتٍ في نفيرِه إلى نهر الرجان في طلَبِهم، فأُسِرَ أبو ثابت، وأصيبَ النَّاسُ معه، وكان ابن كلوب غازيًا في دربِ السَّلامة – موقِعٌ كان يسمَّى بدرب الحدث، لكنَّ بني أمية سمَّوه بدرب السلامة- فلمَّا عاد ابنُ كلوب جمعَ مشايخَ الثغرِ لِيَتراضَوا بأميرٍ، فأجمعوا رأيَهم على ابنِ الأعرابيِّ، فولَّوه أمرَهم."},{"id":967,"title":"واقعة ركب الحاج العراقي بأرض المعادن .","date":["العام الهجري :287","الشهر القمري : محرم","العام الميلادي :900"],"text":"هاجمت طيِّئٌ ركْبَ الحاجِّ العراقي بأرض المعدن. وكانت الأعرابُ في ثلاثة آلافٍ ما بين فارس وراجل، وكان أميرَ الحاجِّ أبو الأغَرِّ، فأقاموا يقاتِلونَهم يومًا وليلة. واشتد القتالُ، ثمَّ إنَّ الله أيَّدَ الرَّكبَ وهزموهم، وقُتِلَ صالحُ بنُ مدرك الذي نهب الحاجَّ فيما مضى، وقُتِلَ معه أعيانُ طيئٍ، ودخل الركبُ بغدادَ بالرؤوس على الرِّماحِ وبالأسرى."},{"id":968,"title":"ولاية أبي العباس بن الأغلب جزيرة صقلية .","date":["العام الهجري :287","الشهر القمري : شعبان","العام الميلادي :900"],"text":"كان إبراهيمُ بنُ الأمير أحمدَ أمير إفريقيَّة قد استَعمَلَ على صقليَّةَ أبا مالكٍ أحمدَ بنَ عمر بن عبدالله، فاستضعفه، فولَّى بعده ابنَه أبا العباسِ بنَ إبراهيمَ بنِ أحمد بن الأغلب، فوصل إليها في مائةٍ وعشرين مركبًا وأربعينَ حربيًّا."},{"id":969,"title":"المعتضد بالله يأمر بقتال القرامطة .","date":["العام الهجري :287","الشهر القمري : شعبان","العام الميلادي :900"],"text":"عظُمَ أمرُ القرامطةِ بالبحرين، وأغاروا على نواحي هجَر، وقَرُب بعضُهم من نواحي البصرةِ، فكتب أحمدُ الواثقيُّ يسألُ المدَدَ، فأمر المعتَضِدُ باختيار رجلٍ يُنفِذُه إلى البصرة، وعزَلَ العبَّاسَ بنَ عمرو عن بلاد فارس، وأقطعه اليمامةَ والبحرين، وأمَرَه بمحاربة القرامطة وضَمَّ إليه زُهاءَ ألفَي رجل، فسار إلى البصرةِ، واجتمع إليه جمعٌ كثيرٌ من المتطوِّعة والجُند والخَدَم، ثم سار إلى أبي سعيدٍ الجَنابي، فلَقُوه مساءً، وتناوشوا القتال، وحجز بينهم الليلُ، فلما كان الليلُ انصرف عن العبَّاسِ مَن كان معه من أعرابِ بني ضَبَّة، وكانوا ثلاثَمائة إلى البصرةِ، وتبعهم مطَوِّعةُ البصرة، فلما أصبح العبَّاسُ باكَرَ الحربَ، فاقتتلوا قتالًا شديدًا، ثم حمل نجاحٌ غلامُ أحمد بن عيسى بن الشيخ من ميسرةِ العبَّاسِ في مائة رجل على ميمنةِ أبي سعيدٍ، فتوغَّلوا فيهم، فقُتِلوا عن آخِرِهم، وحمل الجنابيُّ ومن معه على أصحابِ العبَّاس، فانهزموا وأُسِرَ العبَّاس، واحتوى الجنابيُّ على ما كان في عسكَرِه، فلما كان من الغدِ أحضر الجنابيُّ الأسرى فقَتَلهم جميعًا وحَرَقَهم، ثم سار الجنابيُّ إلى هجر بعد الوقعة، فدخلها وأمَّنَ أهلَها وانصرف مَن سَلِمَ من المنهزمين، وهم قليلٌ، نحو البصرة بغير زادٍ، فخرج إليهم من البصرة نحوُ أربعمائة رجلٍ على الرواحل، ومعهم الطعامُ والكسوة والماء، فلَقُوا بها المنهزمين، فخرج عليهم بنو أسَدٍ وأخذوا الرواحِلَ وما عليها وقَتَلوا من سَلِمَ من المعركة، فاضطربت البصرةُ لذلك، وعزم أهلُها على الانتقالِ منها فمَنَعَهم الواثقي، وبقيَ العبَّاسُ عند الجنابي أيامًا ثم أطلَقَه، وقال له: امضِ إلى صاحِبِك وعرِّفْه ما رأيت؛ وحَمَله على رواحِلَ، فوصل إلى بعضِ السواحل وركب البحرَ فوافى الأبُلَّة، ثم سار منها إلى بغدادٍ فوصَلَها في رمضان، فدخل على المعتَضِدِ فخلع عليه."},{"id":970,"title":"دخول الروم إلى بلادَ الرقَّة .","date":["العام الهجري :288","العام الميلادي :900"],"text":"قصد الرومُ في هذه السنة بلادَ الرقَّة في جحافِلَ عظيمةٍ وعساكِرَ من البحر والبر، فقتلوا خلقًا وأسَروا نحوًا من خمسةَ عشر ألفًا من الذريَّة."},{"id":971,"title":"وفاة أبي الحسن ثابت بن قرة الصابئي .","date":["العام الهجري :288","العام الميلادي :900"],"text":"هو الحاسِبُ الحكيمُ أبو الحسن ثابت بن قُرَّة بن مروان بن ثابت الحَرَّاني الصابئي, وُلد في مدينة حرَّان الشامية سنة 221. كانت أسرتُه تدرِّسُ قديمًا الديانةَ الصابئيَّةَ، ثم أسلمت. كان صيرفيًّا بحرَّان، ثم انتقل إلى بغداد واشتغل بعلوم الأوائل فمهر فيها وبرعَ في الطبِّ، وكان الغالبُ عليه الفلسفةَ، وكان ثابتٌ يجيدُ عِدَّةَ لغات، منها: السريانية والعربية واليونانية، وترجم عدَّةَ مؤلَّفات من اليونانية للعربية، كأعمال أبي لونيوس وأرخميدس وإقليدس وبطليموس, وكان ثابت صابئيًّا من أعيان عصره ومن حذَّاق الأطباء، عالج مَرَّة السريَّ الرَّفَّاء الشاعر، فأصاب العافية وحصل على مال كثير. جرى بينه وبين أهل مذهبِه أشياء أنكروها عليه في المذهب فرفعوه إلى رئيسهم، فأنكر عليه مقالتَه ومنعه من دخول الهيكل، فتاب ورجع عن ذلك، ثم عاد مدَّةً إلى تلك المقالة فمنعوه من الدخول إلى المجمعِ، فخرج من حرَّان، فلما قدِمَ محمد بن موسى من بلاد الروم راجعًا إلى بغداد اجتمع به، فرآه فاضلًا فصيحًا، فاستصحبه إلى بغداد. توفي ثابت عن تسع وخمسين سنة."},{"id":972,"title":"تأسيس أشهر دول الزيدية باليمن .","date":["العام الهجري :288","العام الميلادي :900"],"text":"مؤسِّسُها يحيى بن الحسَن الطالبيُّ الذي كان يعيشُ بالمدينة المنورة، ولكِنَّه وبطلَبٍ مِن أهل اليمَنِ سافر إليهم فالتَفُّوا حوله واستقَرَّ في صعدةَ عام 284 فأراد التوسُّعَ، فاصطدم بمقاومةِ حُكَّامِ اليمَنِ، وكان أشدَّهم عليه بنو يعفرَ في صنعاء، فاصطدم معهم عام 285 غيرَ أنَّه عجزَ عن دخولها، لكنَّه دخلها عام 288ه بمساعدة الأئمَّة الزُّيود الذين استولَوا على الحُكمِ فيما بعدُ، وهم بنو الرسِّ في صعدة، ثم حكَمَهم الإمام المنصور يحيى الذي دام حكمُه من عام 325ه حتى عام 366ه ومِن بعده جاء يوسُفُ الداعي الذي امتَدَّ حكمُه من 366 إلى 430. ثم ضَعُفَ أمر بني رسٍّ بعد موت الداعي يوسُفَ وموت المهديِّ الحسين بن القاسم في العام نفسِه، وقد كانا إمامينِ في وقتٍ واحد. وانقطعت دولتُهم حتى عام 426 ثمَّ قام الحسن بن عبد الرحمن (أبو هاشم) واستمَرَّ أمره حتى عام 431، ثم انقطعت الدولة الثانيةُ مُدَّةَ سِتِّ سنواتٍ أخرى، حيث قام أبو الفتح الديلمي عام 437 ثم قُتِلَ عام 444 في معركةِ فيد أثناء حروبِه مع علي الصليحي، وتوقف أمرُ الأئمة حوالي مائة سنةٍ بعد ذلك، ثمَّ برز إمامُ بني الرس أحمد بن سليمان، وبقي حتى عام 566 ولم يكُنْ وضعُه مستقرًّا."},{"id":973,"title":"السامانيون في بلاد ما وراء النهر يقوضون على دولة الصفارية .","date":["العام الهجري :288","العام الميلادي :900"],"text":"كان يعقوبُ بنُ اللَّيثِ الصَّفَّار قد قضى على الدَّولةِ الطاهريَّة، وأقام دولتَه على أنقاضِها، فأمر الخليفةُ أن يجهِّزَ جيشًا بقيادةِ أخيه الموفَّقِ؛ لِمُواجهة يعقوب، وذلك في عام 262هـ / 876م، ويشاءُ اللهُ أن تدور الدائرةُ على يعقوبَ فيُهزَم، ولكِنَّ المُعتَمِد يرى الاحتفاظَ بولائه للخلافةِ، فمِثلُه يمكِنُ الاعتماد عليه في مواجهةِ الثَّوراتِ والانتفاضات، فبعث إليه يستميلُه ويتَرضَّاه، ويقَلِّدُه أعمال فارس وغيرِها ممَّا هو تحت يديه، ويصِل رسولُ الخليفة إليه، وهو في مرَضِ الموت، ولكِنْ بعد أن كَوَّنَ دولةً، وبسط سلطانَه عليها. ويُظهِرُ أخوه (عمرو) من بعدِه ولاءَه للخليفة، فيولِّيه الخليفةُ خُراسان، وفارِسَ، وأصبهان، وسجستان، والسِّند، وكرمان، والشرطة ببغداد، وكان عمرٌو كأخيه ذا أطماعٍ واسعةٍ، فانتهز فرصةَ تحسُّن العلاقة بينه وبين الخليفةِ وراح يتَمِّمُ رسالة أخيه. فاتَّجَه بنظره إلى إقليم ما وراءَ النهر الذي كان يحكُمُه السامانيون، ولكِنَّ قُوَّتَهم لا يستهان بها، فكتب إلى الخليفة المعتَضِد ليساعِدَه على تملُّكِ هذا الإقليم، فهُزِمَ عمرُو بن الليث الصفار هزيمةً ساحقةً، ووقع أسيرًا في أيدي السامانيِّين، وأُرسل إلى بغداد ليُقضى عليه، فيقتل سنة 289هـ / 902م. ولم تكَدْ تمرُّ ثماني سنوات حتى كان السامانيُّون قد قَضَوا نهائيًّا على الصفاريِّين، واستولَوا على أملاكِهم"},{"id":974,"title":"بدء الدولة العبيدية (الفاطمية) في أفريقيا .","date":["العام الهجري :288","العام الميلادي :900"],"text":"لم تنقَطِعْ حركاتُ التشَيُّع ولم تتوقَّف، فقد كانوا متعصِّبين لآرائهم، مؤمنينَ بفِكرتِهم، يزعمونَ أنَّ أحَقَّ النَّاسِ بالخلافةِ أبناءُ عليِّ بنِ أبي طالبٍ مِن نسلِ السَّيِّدةِ فاطمةَ الزَّهراءِ، فإن نالَها غيرُهم فما ذاك إلَّا أمرٌ باطِلٌ يجب أن يُمحى، ونَشِطَ دُعاةُ الشيعةِ في الدعوةِ إلى مذهبهم، وبخاصةٍ في الجهاتِ البعيدةِ عن مركز الخلافةِ، مثل أطراف فارِسَ واليمَنِ وبلاد المغرب. وكان من هؤلاء الدُّعاةِ أبو عبدالله الشِّيعي وهو رجُلٌ مِن صنعاء اتَّجه إلى المغرب بعد أن رأى دويلاتِ الأغالبةِ والأدارسةِ وغَيرِهما تنشأُ وتُقام بعيدًا عن يدِ الدَّولةِ العباسيَّة وسُلطانها، وركَّزَ أبو عبد الله دعايتَه بين البربرِ، وسُرعانَ ما انضَمُّوا إليه في آلافٍ عديدة، فأرسل إلى زعيمِه الفاطميِّ عُبَيدِ الله بن محمَّد. وقال لهم إنَّ عُبَيد الله شريف علوي فاطميٌّ. ولَمَّا عَلِمَ الخليفة العباسي بالأمرِ أمر بمطاردةِ عُبيد الله، والقبضِ عليه، فاضطُرَّ حين وصل مصرَ إلى أن يتنكَّرَ في زيِّ التجَّار، ثم حاول أن يُفلِتَ مِن دويلات شمال إفريقيا، ولكنَّه سقط أخيرًا في يد أميرِ سجلماسة. فاعتَقَله، وكان معه ابنُه محمد وسجَنَهما."},{"id":975,"title":"خروج طاهر بن الليث الصفار إلى فارس .","date":["العام الهجري :288","الشهر القمري : صفر","العام الميلادي :901"],"text":"دخل طاهِرُ بنُ محمَّد بنِ عمرِو بنِ الليث بلادَ فارس في عسكَرِه وأخرجوا عنها عامِلَ الخليفة، فكتب الأميرُ إسماعيلُ بنُ أحمد الساماني إلى طاهر يذكُرُ له أنَّ الخليفةَ المعتضِدَ قد ولَّاه سجستان، وأنَّه سائر إليها فعاد طاهِرٌ لذلك، فولَّى المعتضِدُ مولاه بدرًا فارِسَ، وأمره بالشُّخوصِ إليها لَمَّا بلغه أنَّ طاهرًا تغلب عليها، فسار إليها في جيشٍ عظيمٍ في جمادى الآخرة، فلما قَرُب من فارس تنحَّى عنها مَن كان بها من أصحابِ طاهرٍ، فدخَلَها بدر، وجَبى خراجَها وعاد طاهرٌ إلى سجستان."},{"id":976,"title":"أخبار القرامطة في العراق .","date":["العام الهجري :289","العام الميلادي :901"],"text":"انتشر القرامطةُ بسَوادِ الكوفة، فوجَّه المعتَضِدُ شِبلًا غلامَ أحمد بن محمد الطائي، وظفِرَ بهم، وأخذ رئيسًا لهم يُعرَف بأبي الفوارس، فسيَّرَه إلى المعتضد، فأحضره بين يديه، وقال له: أخبرني، هل تزعمون أنَّ رُوحَ الله تعالى ورُوحَ أنبيائه تحُلُّ في أجسادِكم فتعصِمُكم من الزلل وتوفِّقُكم لصالح العمل؟ فقال له: يا هذا، إن حَلَّت رُوحُ الله فينا فما يضُرُّك؟ وإن حلَّت روحُ إبليسَ فما ينفَعُك؟ فلا تسألْ عمَّا لا يعنيك وسَلْ عمَّا يخُصُّك، فقال: ما تقولُ فيما يخصُّني؟ قال: أقولُ: إنَّ رسولَ اللهِ- صلَّى الله عليه وسلم- مات وأبوكم العبَّاسُ حَيٌّ، فهل طالبَ بالخلافةِ أم هل بايَعَه أحدٌ من الصحابةِ على ذلك؟ ثم مات أبو بكرٍ فاستخلف عُمَرَ، وهو يرى موضِعَ العبَّاسِ، ولم يوصِ إليه، ثم مات عمَرُ وجَعَلَها شورى في ستَّةِ أنفُس، ولم يوصِ إليه، ولا أدخَلَه فيهم، فبماذا تستحِقُّونَ أنتم الخلافة؟ وقد اتَّفَق الصحابةُ على دفع جَدِّك عنها. فأمر به المعتَضِدُ فعُذِّبَ، وخُلِعَت عظامه، ثم قُطِعَت يداه ورجلاه، ثم قُتِل."},{"id":977,"title":"أخبار القرامطة في الشام .","date":["العام الهجري :289","العام الميلادي :901"],"text":"ظهر بالشامِ رجلٌ مِن القرامطة، وجمع جموعًا من الأعرابِ، وأتى دمشق، وأميرها طغج بن جف من قِبَل هارون بن خِمارَوَيه بن أحمد بن طولون، وكانت بينهما وقَعاتٌ، وكان ابتداءُ حال هذا القرمطيِّ أنَّ زكرَوَيه بن مهرَوَيه الداعية القرمطي الذي بدأ أمرُه في العراق هذا لَمَّا رأى أنَّ الجيوشَ مِن المعتَضِد متتابِعةٌ إلى مَن بسواد الكوفةِ مِن القرامطة، فإنَّ القتلَ قد أبادهم، سعى باستغواءِ مَن قَرُب من الكوفة من الأعرابِ: أسَد وطيئ وغيرهم، فلم يجِبْه منهم أحد، فأرسل أولادَه إلى كلب بن وبرة فاستغوَوهم، فلم يجِبْهم منهم إلَّا الفَخذُ المعروف ببني العليص بن ضمضَم بن عدِيِّ بن خباب ومواليهم خاصةً، فبايعوا في هذه السَّنة، بناحية السماوة، ابنَ زكرَوَيه، المسمَّى بيحيى، المُكنَّى أبا القاسم، فلقبوه الشيخ، وزعم أنَّه محمَّد بن عبد الله بن محمد بن إسماعيل بن جعفر بن محمد بن علي بن الحسين بن علي بن أبي طالب، وقيل: لم يكن لمحمَّد بنِ إسماعيل ولدٌ اسمه عبد الله، وزعم أنَّ له بالبلاد مائة ألفِ تابعٍ، وأنَّ ناقتَه التي يركَبُها مأمورةٌ، فإذا تبعوها في مسيرِها نُصِروا، وأظهَرَ عَضُدًا له ناقصة، وذكَرَ أنَّها آيتُه، وأتاه جماعةٌ من بني الأصبع، أخلصوا له وتَسَمَّوا بالفاطميين، ودانُوا بدينه، فقصدهم شبلٌ غلامُ المعتَضِد من ناحية الرصافة فاغتَرُّوه فقتلوه، وأحرقوا مسجِدَ الرصافة، واعتَرَضوا كلَّ قرية اجتازوا بها حتى بلغوا هارونَ بنَ خمارَوَيه التي قوطِعَ عليها طغج بن جف، فأكثَروا القتلَ بها والغارة، فقاتَلَهم طغج، فهزموه غيرَ مَرَّة."},{"id":978,"title":"وفاة الخليفة العباسي المعتضد بالله وتولي ابنه المكتفي بالله الخلافة .","date":["العام الهجري :289","الشهر القمري : ربيع الأول","العام الميلادي :902"],"text":"هو أميرُ المؤمنينَ أبو العَبَّاس أحمدُ بنُ طلحة الموفَّق بالله بن المتوكل على الله جَعْفَر بن المُعْتَصم بن الرشيد الهاشمي العباسي. ولد في ذي القَعدة سنة 242 في دولةِ جَدِّه، استخلف بعد عَمِّه المعتَمِد في رجبٍ سنة تسع وسبعين. وكان ملكًا شجاعًا مهيبًا، أسمرَ نحيفًا، معتدِلَ الخَلقِ، ظاهِرَ الجبروت، وافِرَ العقل، شديدَ الوطأة، من أفراد خلفاءِ بني العَبَّاس. وكان ذا سياسةٍ عظيمة. وكان المُعْتَضِدُ يبخل ويجمَعُ المال، وقد وليَ حَربَ الزِّنجِ وظَفِرَ بهم، وفي أيَّامِه سكنت الفتَنُ لفَرطِ هيبتِه. وكان غلامُه بدرٌ على شرطتِه، وعبيد الله بن سُلَيْمَان على وزارته، ومحمَّد بن سِياه على حرسه، وكانت أيامُه أيامًا طيبة كثيرةَ الأمن والرخاء. وكان قد أسقط المُكوسَ، ونشَرَ العدل، ورفع الظُّلمَ عن الرعية. وكان يُسمَّى السفاحَ الثانيَ؛ لأنَّه جدَّد مُلكَ بني العباس، وكان مُلْكُهم قد خلقَ وضعُف وكاد يزولُ. أصيب المعتَضِد في آخر أيامه بمرضٍ واشتدَّ به المرض حتى توفِّيَ، فتولى غَسلَه محمَّدُ بن يوسف، وصلَّى عليه الوزيرُ عبيد الله بن سُلَيمان، ودُفِنَ ليلًا في دار محمَّد بن طاهر، وجلس الوزيرُ في دار الخلافة للعزاء، وجدَّد البيعة للمُكتفي, وكانت مُدَّةُ خلافة المعتَضِد سبعَ سنين وتسعة أشهر وثلاثة عشر يومًا. لَمَّا توفِّيَ المعتَضِد كتب الوزيرُ إلى أبي محمد علي بن المُعتَضِد، وهو المكتفي باللهِ، يعَرِّفُه بذلك وبأخذِ البيعة له، وكان بالرقَّة، فلما وصله الخبَرُ أخذ البيعةَ على مَن عِندَه من الأجناد، ووضع لهم العطاءَ وسار إلى بغداد، ووجَّه إلى النواحي من ديارِ ربيعةَ ومُضَرَ ونواحي العرَبِ مَن يحفظُها ودخل بغدادَ لثمانٍ خَلَونَ مِن جمادى الأولى."},{"id":979,"title":"استيلاء محمد بن هارون على بلاد الري .","date":["العام الهجري :289","الشهر القمري : رجب","العام الميلادي :902"],"text":"كاتب أهلُ الريِّ محمَّدَ بنَ هارون الذي حارب محمَّدَ بن زيد العلوي، وتولى طبرستان لإسماعيلَ بنِ أحمد الساماني، فلما خلع محمَّدُ بن هارون طاعةَ إسماعيل، سأله أهلُ الرَّيِّ المسيرَ إليهم ليُسَلِّموها إليه، وكان سببُ ذلك أنَّ الواليَ عليهم كان قد أساء السيرةَ فيهم، فسار محمَّدُ بن هارون إليهم فحاربه واليها وهو الدتمش التركي، فقتله محمَّد وقتَلَ ابنينِ له وأخا كيغلغ، وهو من قوَّاد الخليفة، ودخل محمَّدُ بن هارون الريَّ، واستولى عليها، وفي هذه السنة كانت وقعةٌ بين إسماعيل بن أحمد وبين محمَّد بن هارون بالري، فانهزم محمَّد، ولحق بالديلم مُستجيرًا بهم، ودخل إسماعيلُ الرَّيَّ."},{"id":980,"title":"الحروب مع القرامطة في الشام .","date":["العام الهجري :290","العام الميلادي :902"],"text":"أقبل يحيى بن زكرَوَيه بن مهرويه أبو قاسم القرمطي المعروفُ بالشيخ في جحافلِه، فعاث بناحية الرقَّة فسادًا، فجهز إليه الخليفةُ جيشًا نحو عشرة آلاف فارس، وكان قد سار يحيى بن زكرويه إلى دمشق وحاصرها، فقُتِلَ على باب دمشق، زرَقَه رجلٌ من المغاربةِ بِمزراقِ نارٍ- المزراقُ رُمحٌ قصير أو خفيفٌ يُقْذَف باليد- فقَتَله، ففَرِحَ الناس بقتله، وكان هذا المغربيُّ من جملة جيش المصريين، فقام بأمرِ القرامطةِ مِن بعده أخوه الحُسَين وتسمَّى بأحمد وتكنَّى بأبي العباس وتلقَّب بأمير المؤمنين، وأطاعه القرامطة، فحاصر دمشقَ فصالحه أهلُها على مال، ثم سار إلى حمصَ فافتتحها وخُطِبَ له على منابِرِها، ثمَّ سار إلى حماة ومعرَّة النعمان فقهر أهلَ تلك النواحي واستباح أموالَهم وحريمَهم، وكان يقتُلُ الدوابَّ والصِّبيانَ في المكاتب، ويُبيحُ لِمَن معه وطء النِّساء، فربما وطئَ الواحدةَ الجماعةُ الكثيرةُ مِن الرجال، فإذا ولَدَت ولدًا هنأَ به كلُّ واحدٍ منهم الآخَرَ، فكتب أهل الشامِ إلى الخليفة ما يلقَونَ مِن هذا اللعين، فجهَّز إليهم جيوشًا كثيفة، وأنفق فيهم أموالًا جزيلة، وركب في رمضان فنزل الرقَّةَ وبَثَّ الجيوشَ في كلِّ جانبٍ لقتال القرامطة، وكان القرمطي هذا يكتُبُ إلى أصحابه: \"مِن عبد الله المهديِّ أحمد بن عبد الله المهدي المنصور الناصر لدين الله القائم بأمر الله الحاكم بحكم الله، الداعي إلى كتاب الله، الذابِّ عن حريم الله، المختار من ولد رسول الله\" وكان يدَّعي أنَّه من سلالة علي بن أبي طالب من فاطمة، وهو كاذِبٌ أفاكٌ أثيمٌ- قبَّحه الله- فإنَّه كان من أشدِّ الناس عداوةً لقريش، ثم لبني هاشم، دخل سلميةَ فلم يدَعْ بها أحدًا من بني هاشم حتى قتَلَهم، وقتل أولادَهم، واستباح حريمَهم."},{"id":981,"title":"مقتل عبدالله بن الأغلب وتولي ابنه زيادة الله الإمارة من بعده .","date":["العام الهجري :290","العام الميلادي :902"],"text":"هو أبو العبَّاس عبدالله بنُ إبراهيمَ بنِ أحمد بن الأغلب، الأميرُ الأغلبيُّ أميرُ تونُسَ والقيروان الحادي عشر من أمراء الدولةِ الأغلبيَّة، كان عاقلًا حكيمًا شجاعًا، قَرَّب إليه العلماءَ واستعان بهم على تطبيق العدلِ بين الناس، وسار بهم سيرةً حَسنةً، ولكِنَّ أمرَ الحُكمِ بدأ يضطرِبُ ويضعُفُ في أيَّامِه، وكان قد سجَنَ ابنًا له هو زيادة الله، سجنَه بسبب انحرافِه في الشهواتِ، وقيل: بل لأنَّه كان يتآمَرُ على والده، ثم وهو في السجنِ تآمر مع بعضِ الخدَمِ لقَتلِ أبيه، فقتل هؤلاءِ الخدَمُ الأميرَ عبدَالله وهو على سريرِه، فكانت مدة إمارته سنة وخمسون يومًا، فتولى ابنُه زيادةُ الله الإمارةَ من بعده."},{"id":982,"title":"الأندلسيون يؤسسون مدينة وهران بالساحل الجزائري .","date":["العام الهجري :290","العام الميلادي :902"],"text":"تقع على الساحلِ الغربيِّ على البحر الأبيض المتوسط، عاصمةُ غرب البلاد وثاني أكبَر مدينةٍ بعد الجزائر العاصمة. تعدُّ المدينةُ مركزًا اقتصاديًّا وميناءً بحريًّا مهمًّا. قام البحَّارة الأندلسيُّون بإنشاءِ هذه المدينة في هذا العام. حتى أصبَحَت مدينةُ وهران محطَّ نزاعٍ بين الأمويِّين في الأندلس والفاطميِّين. دُمِّرَت مدينة وهران عدةَ مرَّات أثناء تلك الحِقبة. وأصبحت المدينةُ تحت الحكم الأموي عام 407، ثم أصبَحت تحت حُكم المرابطين عام 474، وكانت المدينةُ تمثِّلُ أهمَّ ميناء تجاري للدولة الزيانيَّة ومَنفذًا لها على البحر المتوسِّط."},{"id":983,"title":"وفاة عبدالله بن الإمام أحمد بن حنبل .","date":["العام الهجري :290","الشهر القمري : جمادى الآخرة","العام الميلادي :903"],"text":"هو أبو عبدِ الرَّحمنِ عبدُ الله بنُ أحمدَ بنِ محمد بن حنبل الشيباني البغدادي، الحافظ، مِن أهل بغداد، والده هو الإمامُ أحمد بن حنبل، ولد سنة 213 وأمُّه اسمها ريحانة، تزوجَّها الإمام أحمد بعد وفاةِ زوجته الأولى عبَّاسة أم ابنِه صالحٍ، وأنجبت له ريحانةُ ابنَه عبد الله. تعلَّمَ على يدِ أبيه فسَمِعَ منه المُسنَد، فكان مُكثِرًا في الروايةِ عن أبيه وعن غيره, وكان إمامًا ثِقةً حافِظًا ثَبتًا، قال ابن المنادي: لم يكُنْ أحدٌ أروى عن أبيه منه، روى عنه المسندَ ثلاثينَ ألفًا، والتفسير مائة ألفِ حديث وعشرون ألفًا، من ذلك سماعٌ، ومن ذلك إجازة، ومن ذلك الناسِخُ والمنسوخ، والمقَدَّم والمؤخَّر، والمناسِك الكبير والصغير، وغير ذلك من التصانيف، وحديث الشيوخِ، وقال- أي ابن المنادي: وما زِلْنا نرى أكابِرَ شيوخِنا يشهدون له بمعرفةِ الرِّجالِ وعِلَل الحديث، والأسماءِ والكُنى، والمواظبة على طلَبِ الحديث في العراق وغيرها، ويذكُرونَ مِن أسلافهم الإقرارَ له بذلك، حتى إنَّ بعضَهم أسرفَ في تقريظه له بالمعرفة وزيادةِ السَّماعِ للحديث عن أبيه\"، ولَمَّا مَرِضَ قيل له أين تُدفَنُ ؟ فقال: صحَّ عندي أنَّ بالقطعيَّة نبيًّا مدفونًا، ولَأن أكونَ بجوارِ نبيٍّ أحَبُّ إليَّ مِن أن أكونَ في جوار أبي، مات عن سبع وسبعين سنة، كما مات لها أبوه، واجتمع في جنازته خلقٌ كثيرٌ من الناس، وصلَّى عليه زهير ابن أخيه، ودُفِنَ في مقابِرِ باب التين- رحمَه الله تعالى."},{"id":984,"title":"المكتفي بالله يقضي على فتنة القرامطة ويأسر زعيمهم .","date":["العام الهجري :291","العام الميلادي :903"],"text":"أمرَ محمَّدُ بنُ سليمان- الذي ولَّاه المكتفي قتالَ القرامطةِ- بمناهضةِ صاحِبِ الشامة القرمطيِّ الحسين بن زكرويه - المُدَّعي أنَّه أحمد بن عبد الله- فسار إليه في عساكِرِ الخليفة، حتى لَقُوه وأصحابَه بمكان بينهم وبين حماة اثنا عشرَ ميلًا، فقَدَّمَ القرمطيُّ أصحابَه إليهم، وبقِيَ في جماعةٍ مِن أصحابه، معه مالٌ كان جمعه، وسوادُ عَسكرِه، والتحمت الحربُ بين أصحاب الخليفةِ والقرامطة، واشتَدَّت وانهزمت القرامطةُ وقُتِلوا كلَّ قِتلةٍ، وأُسِرَ مِن رجالهم بشَرٌ كثير، وتفَرَّق الباقون في البوادي، وتَبِعَهم أصحابُ الخليفة،فلما رأى صاحِبُ الشامة ما نزل بأصحابِه، حمَّلَ أخًا له يكنَّى أبا الفضلِ مالًا، وأمره أن يلحَقَ بالبوادي إلى أن يظهَرَ بمكانٍ فيسيرَ إليه، ورَكِبَ هو وابنُ عمه المسمى بالمَدَّثر، والمطوق صاحبه، وغلام له رومي، وأخذ دليلًا وسار يريدُ الكوفة عرضًا في البريَّة، فانتهى إلى الداليَّة مِن أعمالِ الفُرات، وقد نفِدَ ما معهم من الزادِ والعَلَف، فوجَّه بعضَ أصحابه إلى الداليَّة المعروفة بدالية ابن طوق ليشتريَ لهم ما يحتاجونَ إليه، فدخلها فأنكروا زيَّه، فسألوه عن حالِه فكتَمَه، فرفعوه إلى متولِّي تلك الناحية الذي يُعرفُ بأبي خبزة خليفةِ أحمد بن محمد بن كشمرد، فسأله عن خبَرِه، فأعلمه أنَّ صاحِبَ الشامة خلْفَ رابيةٍ هناك مع ثلاثةِ نفَرٍ، فمضى إليهم وأخَذَهم، وأحضرهم عند ابنِ كشمرد، فوجَّهَ بهم إلى المكتفي بالرقَّةِ، ورجعت الجيوشُ مِن الطلب، وفي يوم الاثنين لأربعٍ بَقِينَ من المحرم أُدخِلَ صاحِبُ الشامة الرقَّة ظاهرًا على فالجٍ- وهو الجملُ ذو السَّنامينِ- وبين يديه المدَّثِّر والمطوق؛ وسار المكتفي إلى بغدادَ ومعه صاحبُ الشامة وأصحابُه، وخلَّفَ العساكِرَ مع محمد بن سليمان، وأُدخل القرمطيُّ بغدادَ على فيلٍ، وأصحابُه على الجمل، ثم أمرَ المكتفي بحَبسِهم إلى أن يَقدَمَ محمَّد بن سليمان، فقَدِمَ بغداد، وقد استقصى في طلَبِ القرامطة، فظَفِرَ بجماعةٍ من أعيانهم ورؤوسِهم، فأمر المكتفي بقَطعِ أيديهم وأرجُلِهم، وضَرْبِ أعناقهم بعد ذلك، وأُخرِجوا من الحبس، وفُعِلَ بهم ذلك، وضُرِبَ صاحب الشامة مائتي سوطٍ، وقُطِعَت يداه، وكُوِيَ فغُشِيَ عليه، وأخذوا خشبًا وجعلوا فيه نارًا ووضعوه على خواصِرِه، فجعل يفتَحُ عينه ويُغمِضُها، فلما خافوا موتَه ضربوا عنُقَه، ورفعوا رأسَه على خشبة، فكبَّرَ الناس لذلك، ونُصِبَ على الجِسرِ."},{"id":985,"title":"انتصار المسلمين على الترك في بلاد ما وراء النهر .","date":["العام الهجري :291","العام الميلادي :903"],"text":"خرجت التُّركُ في خلقٍ كثيرٍ لا يُحصَون إلى ما وراءَ النَّهر، وكان في عسكرِهم سبعُمائة قُبَّة تركية، ولا يكونُ إلَّا للرؤساء منهم، فوجَّه إليهم إسماعيلُ بنُ أحمد الساماني جيشًا كثيرًا، وتَبِعَهم من المتطَوِّعة خلقٌ كثيرٌ، فساروا نحو التُّركِ، فوصلوا إليهم وهم غارُّونَ، فكَبَسَهم المسلمون مع الصبحِ، فقَتَلوا منهم خلقًا عظيمًا لا يُحصَون، وانهزم الباقون، واستُبيحَ عَسكرُهم، وعاد المسلمونَ سالِميَن غانِمينَ."},{"id":986,"title":"فتح المسلمين مدينة أنطاكية .","date":["العام الهجري :291","العام الميلادي :903"],"text":"في هذه السنة سار المعروفُ بغلام زرافة من طرسوس نحو بلادِ الروم، ففتح مدينةَ أنطاكية، وهي تعادِلُ القُسطنطينية، فتَحَها بالسَّيفِ عَنوةً، فقتل خمسةَ آلاف رجلٍ، وأسَرَ مِثلَهم، واستنقذَ مِن الأُسارى خمسةَ آلاف، وأخذ لهم ستينَ مَركبًا فحمَلَ فيها ما غَنِمَ من الأموال والمتاع والرَّقيق، وقُدِّرَ نصيبُ كلِّ رجلٍ ألف دينار، وهذه المدينة على ساحل البحر، فاستبشر المسلمونَ بذلك."},{"id":987,"title":"الروم يقتحمون ثغور المسلمين بجيش عظيم .","date":["العام الهجري :291","الشهر القمري : شعبان","العام الميلادي :904"],"text":"خرج من الروم عشرةُ صُلبان مع كلِّ صليبٍ عَشرةُ آلافٍ إلى الثغور، فغاروا على أطرافِ بلاد المسلمينَ، فأحرقوا, وقَتَلوا خلقًا وسَبَوا نساءً وذرِّيةً."},{"id":988,"title":"القضاء على دولة بن طولون في مصر .","date":["العام الهجري :292","الشهر القمري : صفر","العام الميلادي :905"],"text":"سار محمَّدُ بن سليمان إلى حدودِ مِصرَ لحرب هارونَ بنِ خمارَوَيه بن أحمد بن طولون، وسببُ ذلك أنَّ محمَّدَ بنَ سُلَيمان لَمَّا تخلَّفَ عن المكتفي، وعاد عن محاربةِ القرامطة، واستقصى محمَّد في طلَبِهم، فلما بلغ ما أراد عزمَ على العودِ إلى العراق، أتاه كتابُ بدرٍ الحمامي غلامِ ابن طولون، وكتابُ فائق، وهما بدمشق، يدعوانِه إلى قصد البلاد بالعساكِرَ يُساعدانه على أخذها، فلما عاد إلى بغداد أنهى ذلك إلى المُكتفي، فأمره بالعَودِ، وسيَّرَ معه الجنود والأموال، ووجَّه المكتفي دميانة غلامَ بازمار، وأمره بركوبِ البحر إلى مصر، ودخول النيل، وقطْع الموادِّ عن مصر، ففعل وضَيَّق عليهم، وزحف إليهم محمَّدُ بنُ سليمان في الجيوش في البَرِّ، حتى دنا من مصرَ وكاتَبَ مَن بها من القوَّاد، وكان أوَّلَ من خرج إليه بدرٌ الحمامي، وكان رئيسَهم، فكَسَرهم ذلك، وتتابعه المُستأمَنة من قوَّاد المصريين، وفي بعض الأيام ثارت عصبيَّةٌ، فاقتتلوا فخرج هارون يسَكِّنُهم، فرماه بعضُ المغاربة بمزراق معه فقَتَله، فلما قُتِلَ قام عمُّه شيبان بالأمر من بعده، وبذلَ المالَ للجُند، فأطاعوه وقاتلوا معه، فأتَتهم كتُبُ بدرٍ يدعوهم إلى الأمانِ، فأجابوه إلى ذلك، فلما عَلِمَ محمد بن سليمان الخبَرَ سار إلى مصر، فأرسل إليه شيبانُ يطلُبُ الأمان، فأجابه، فخرج إليه ليلًا، ولم يعلَمْ به أحد من الجند، فلما أصبحوا قصَدوا داره ولم يجدوه، فبَقُوا حيارى، ولما وصل محمَّد مصرَ دخلها واستولى على دورِ طولونَ وأموالهم، وأخذَهم جميعًا وهم بضعةَ عشرَ رجُلًا فقيَّدَهم، وحبسهم واستقصى أموالَهم، وكتب بالفتحِ إلى المكتفي، فأمره بإشخاصِ آلِ طولون وترحيلِهم من مصر والشام إلى بغداد، ولا يَترُك منهم أحدًا ففعل ذلك، وعاد إلى بغداد، وولَّى معونةَ مصرَ عيسى النوشري، فكانت مدَّةُ الدولة الطولونية 38 عامًا مِن حكم أحمد بن طولون."},{"id":989,"title":"ذكر أخبار القرامطة بالشام والعراق .","date":["العام الهجري :293","العام الميلادي :905"],"text":"أنفذ زكرَوَيه بن مهرويه، بعد قَتلِ صاحب الشامة الحُسَينِ بنِ زكرويه، رجلًا كان يعَلِّمُ الصبيانَ بالرافوفة من الفلوجة يسمَّى عبد الله بن سعيد، ويكنَّى أبا غانم، فسُمِّي نصرًا, وقيل كان المنفذ ابن زكرويه، فدار على أحياءِ العرَبِ مِن كَلبٍ وغيرهم يدعوهم إلى رأيِه، فلم يقبَلْه منهم أحد، إلَّا رجلًا من بني زياد يسمَّى مقدام بن الكيال، واستقوى بطوائِفَ من الأصبغيين المنتمينَ إلى الفواطم، وغيرِهم من العليصيين، وصعاليكَ مِن سائر بطونِ كَلبٍ، وقصد ناحيةَ الشام، والعامِلُ بدمشق والأردن أحمدُ بن كيغلغ، وهو بمصرَ يُحارِبُ الخلنجي، فاغتنم ذلك عبدُ الله بن سعيد، وسار إلى بُصرى وأذرِعاتٍ والبثينة، فحارب أهلَها ثم أمَّنَهم، فلما استسلموا إليه قتَلَ مُقاتِليهم، وسبى ذراريَّهم وأخذ أموالَهم، ثمَّ قصَدَ دِمشقَ، فخرج إليهم نائِبُ ابن كيغلغ، وهو صالِحُ بنُ الفضل، فهزمه القرامِطةُ، وأثخَنوا فيهم، ثم أمَّنوهم وغَدرُوهم بالأمان، وقتلوا صالحًا وفضُّوا عسكره، وساروا إلى دمشق، فمنعهم أهلُها فقصدوا طبرية، وانضاف إليه جماعةٌ من جند دمشق افتُتِنوا به، فواقعهم يوسفُ بنُ إبراهيم بن بغامردي، وهو خليفةُ أحمد بن كيغلغ بالأردن، فهزموه، وبذلوا له الأمانَ، وغَدَروا به، وقتلوه، ونهَبوا طبرية، وقتلوا خلقًا كثيرًا من أهلِها وسَبَوا النساء، فأنفذ الخليفةُ الحسينَ بن حمدان وجماعةً مِن القواد في طلبهم، فوردوا دمشقَ، فلما عَلِمَ بهم القرامطة رجعوا نحو السَّماوة، وتبعهم الحُسَينُ في السماوة، وبلغ الخبَرُ إلى المكتفي فسيَّرَ محمد بن إسحاق بن كنداج، فلم يقيموا لمحمَّد. وكتب إلى ابنِ حمدان بالمسير إليهم من جهةِ الرحبة ليجتمعَ هو ومحمد على الإيقاعِ بهم، ففعل ذلك، فلما أحسَّ الكلبيُّونَ بإقبالِ الجيش إليهم وثَبُوا بنصر عبدِ الله بن سعيد فقتلوه، قتلَه رجلٌ منهم يقال له الذئبُ بن القائم، وسار برأسِه إلى المكتفي متقربًا بذلك، مستأمِنًا، فأجيب إلى ذلك، واقتَتَلت القرامطة بعد نصرٍ حتى صارت بينهم الدِّماءُ، فكتب الخليفةُ إلى ابن حمدان يأمُرُه بمعاودتهم، واجتثاثِ أصلِهم، فأرسل إليهم زكرَوَيه بن مهرويه داعيةً له يسمَّى القاسِمَ بن أحمد، ويعرف بأبي محمد، وأعلَمَهم أنَّ فِعلَ الذِّئبِ قد نفَّرَه منهم، وأنهم قد ارتدُّوا عن الدين وأنَّ وقتَ ظُهورِهم قد حضر، وقد بايع له من أهلِ الكوفة أربعون ألفًا، وأن يومَ موعِدِهم الذي ذكره اللهُ في شأن موسى صلَّى الله عليه وسلَّم، وعَدُوِّه فرعونَ؛ إذ {قَالَ مَوْعِدُكُمْ يَوْمُ الزِّينَةِ وَأَنْ يُحْشَرَ النَّاسُ ضُحًى} ويأمُرُهم أن يُخفُوا أمرَهم، وأن يَسيروا حتى يُصَبِّحوا الكوفةَ يوم النحر سنة 293، فإنَّهم لا يمنعون منها وأنَّه يظهر لهم، وينجزُ لهم وعْدَه الذي يعِدُهم إياه، وأن يحملوا إليه القاسِمَ بن أحمد، فامتثلوا رأيَه، ووافَوا باب الكوفة وقد انصرف النَّاسُ عن مصلاهم، وعامِلُهم إسحاق بن عمران، ووصلوها في ثمانمائة فارس عليهم الدروع، والجواشن، والآلات الحسنة، وقد ضربوا على القاسِمِ بن أحمد قبة، وقالوا هذا أثَرُ رسول الله. ونادَوا \"يا لَثاراتِ الحُسَين\"، يعنون الحُسَين بن زكرويه المصلوبَ ببغداد، وشعارهم \"يا أحمد، يا محمد\"، يعنون ابنَي زكرَوَيه المقتولين، فأظهروا الأعلامَ البيضَ، وأرادوا استمالةَ رَعاعِ الناس بالكوفة بذلك، فلم يَمِلْ إليهم أحد، فأوقع القرامطةُ بمن لحقوه من أهل الكوفةِ، وقتلوا نحوًا من عشرينَ نفسًا، وبادر الناسُ الكوفة، وأخذوا السلاحَ، ونهض بهم إسحاق، ودخل مدينةَ الكوفة من القرامطة مائة فارس، فقُتِلَ منهم عشرون نفسًا وأُخرِجوا عنها، وظهر إسحاق وحاربهم إلى العصر، ثم انصرفوا نحو القادسيَّة، وكتب إسحاق إلى الخليفة يستَمِدُّه، فأمَدَّه بجماعةٍ مِن قواده، فساروا منتصفَ ذي الحجة حتى قاربوا القادسيَّةَ فنزلوا بالصوان، فلَقِيَهم زكرويه، وأما القرامطةُ فإنهم أنفذوا واستخرجوا زكرَوَيه من جُبٍّ في الأرض كان منقطعًا فيه سنينَ كثيرة، بقريةِ الدرية، وكان على الجُبِّ بابٌ حديدٌ مُحكَم العمل، فلما استخرجوه حملوه على أيديهم، وسَمَّوه وليَّ الله، ولَمَّا رأوه سجدوا له، وحضر معه جماعةٌ من دُعاته وخاصته، وأعلمهم أنَّ القاسِمَ بنَ أحمد من أعظمِ الناس عليهم ذِمَّةً ومِنَّةً، وأنَّه ردهم إلى الدِّينِ بعد خروجهم عنه، وأنَّهم إن امتثلوا أوامِرَه أنجز موعِدَهم وبلغوا آمالَهم، ورمَزَ لهم رموزًا ذكَرَ فيها آياتٍ مِن القرآن، نقلها عن الوجه الذي أُنزِلَت فيه، فاعتَرَف له من رسخَ حُبُّ الكُفرِ في قلبه أنَّه رئيسُهم وكهفُهم، وأيقنوا بالنصرِ وبلوغ الأمل، وسار بهم وهو محجوبٌ يَدعونَه ولا يُبرِزونَه، والقاسمُ يتولى الأمور، وأعلَمَهم أن أهل السواد قاطبةً خارجون إليه، فأقام بسَقيِ الفرات عدةَ أيام، فلم يَصِلْ إليه منهم إلَّا خمسمائة رجل، ثم وافته الجنودُ المذكورة من عند الخليفة، فلَقِيَهم زكرويه بالصوان، وقاتَلَهم واشتدت الحرب بينهم، وكانت الهزيمةُ أوَّل النهار على القرامطة، وكان زكرَوَيه قد كمَنَ لهم كمينًا من خَلْفِهم، فلم يشعُرْ أصحاب الخليفةِ إلَّا والسَّيفُ فيهم من ورائهم، فانهزموا أقبحَ هزيمةٍ، ووضع القرامطةُ السيف فيهم، فقتلوهم كيف شاؤوا وغَنِموا سوادهم، ولم يَسلَمْ من أصحاب الخليفةِ إلَّا مَن دابَّتُه قوية، أو من أُثخِنَ بالجراح، فوضع نفسَه بين القتلى، فتحاملوا بعد ذلك، وقوِيَ القرامطةُ بما غَنِموا، ولَمَّا ورد خبَرُ هذه الوقعة إلى بغداد أعظَمَها الخليفةُ والنَّاسُ، وندب إلى القرامطةِ محمَّد بن إسحاق بن كنداج، وضَمَّ إليه من الأعراب بني شيبانَ وغيرَهم أكثَرَ مِن ألفي رجل، وأعطاهم الأرزاقَ، ورحلَ زكرويه من مكانِه إلى نهرِ المثنية لنَتْنِ القَتلى."},{"id":990,"title":"ظهور الخلنجي في مصر ومحاولة القضاء عليه .","date":["العام الهجري :293","العام الميلادي :905"],"text":"ظهر بمصر رجلٌ يُعرَفُ بالخلنجي، من القادةِ, وهو أبو عبدِ اللهِ محمَّدُ بن علي الخلنجي المصري الطولوني، كان قد تخلَّفَ عن محمد بن سليمان، فاستمال جماعةً، وخالف على السُّلطانِ، فتمَلَّك الديارَ المصريَّةَ بالسَّيفِ، واستولى عليها عَنوةً مِن عيسى بن محمد النوشري. فلما مَلَك الخلنجي الديارَ المصرية ومَهَّدَ البلادَ ووطَّنَ الناسَ ووضعَ العطاءَ وفَرَض الفروضَ. كتب النوشري إلى المُكتفي بالخبر، فجَهَّز الخليفةُ جيشًا لقتاله وعليهم أبو الأغر، وفي الجيش الأميرُ أحمد بن كيغلغ وغيرُه، فخرج إليهم الخلنجي وقاتَلَهم فهزمهم أقبحَ هزيمةٍ وأسَرَ مِن جماعةِ أبي الأغر خلقًا كثيرًا، وعاد أبو الأغَرِّ حتى وصل إلى العراقِ."},{"id":991,"title":"أخبار القرامطة في اليمن .","date":["العام الهجري :293","العام الميلادي :905"],"text":"وفي اليمَنِ نبغ رجلٌ يدعو إلى القرامطة يُدعى بالداعية الذي سار إلى مدينةِ صنعاء، فحاربه أهلُها فظَفِرَ بهم وقتَلَهم، فلم يُفلِتْ إلَّا اليسير، وتغلَّب على سائرِ مُدُنِ اليمن، ثم اجتمَعَ أهل صنعاء وغيرُها فحاربوا الداعيةَ فهزموه، فانحاز إلى موضعٍ من نواحي اليمن، وبلغ الخبَرُ الخليفة، فخلع على المظفَّر بن حاج في شوال، وسيَّرَه إلى عمله باليمَنِ، وأقام بها إلى أن مات."},{"id":992,"title":"القضاء على الخلنجي في مصر  .","date":["العام الهجري :293","العام الميلادي :905"],"text":"عَظُمَ على الخليفةِ المكتفي ما أصاب جيشَه بقيادة أبي الأغَرِّ في مصر على يدِ الخلنجي، فجهَّزَ إليه العساكِرَ ثانيًا بصحبة فاتك مولى المعتَضِد في البَرِّ، وجهَّزَ دميانة غلامَ بازمان في البحر، فقَدِمَ فاتك بجيوشِه حتى نزل بالنويرة, وقد عَظُم أمر الخلنجي وأخرج عيسى النوشري عن مصرَ وأعمالِها, ولَمَّا بلغ الخلنجيَّ مجيءُ عسكر العراق بصُحبة فاتك، جمعَ عَسكرَه وخرج إلى بابِ المدينة وعسكَرَ به، وقام بالليل بأربعةِ آلاف من أصحابِه ليُبيِّتَ فاتكًا وأصحابه، فضلَّ الخلنجيُّ وجيشُه الطريقَ وأصبحوا قبل أن يَصِلوا إلى النويرة، فعَلِمَ بهم فاتِكٌ فنهض بأصحابِه والتقى مع الخلنجي قبل أن يَصِلوا إلى النويرة، فتقاتلا قتالًا شديدًا, فانهزم الخلنجيُّ بعد أن ثبت ساعةً بعد فرار أصحابِه عنه، ودخل إلى مصر واستتر بها لثلاثٍ خَلَونَ من شهر رجب، ثم قُبِضَ عليه وحُبِسَ, فكتب المكتفي إلى فاتكٍ في حملِ الخلنجي ومَن معه إلى بغداد، فوجه فاتكٌ مولى المعتَضِد الخلنجيَّ إلى بغداد، فدخلها هو ومن معه في شهر رمضان، فأمر المكتفي بحَبسِهم."},{"id":993,"title":"دخول الروم إلى قورس .","date":["العام الهجري :293","العام الميلادي :905"],"text":"أغارت الرومُ على قورس، من أعمالِ حلَبٍ، فقاتلهم أهلُها قتالًا شديدًا، ثم انهزموا وقُتِلَ أكثَرُهم، وقَتَلوا رؤساء بني تميم، ودخل الرومُ قورس فأحرقوا جامِعَها وساقُوا مَن بَقِيَ مِن أهلِها."},{"id":994,"title":"انتصارات أبي عبدالله الشيعي بأفريقيا ونهاية دولة الأغالبة .","date":["العام الهجري :293","العام الميلادي :905"],"text":"عمِلَ أبو عبد الله الشيعيُّ على تنظيم جماعتِه، حتى التزموا طاعتَه، ثم بدأ في سنة (289هـ - 901م) في مهاجمةِ دولة الأغالبة، التي دَبَّ فيها الضَّعفُ؛ بسبب سوء وضعِ آخِرِ حكامِها زيادةِ الله الثالثِ الذي قَتَل والِدَه وقرابته، مع انهماكه في اللَّهوِ، ودخل معها في عِدَّة معارِكَ وتوالت انتصاراتُ أبي عبدالله الشيعيُّ على دولة الأغالبة خاصةً بعد هرب زيادةِ الله إلى مصر، فسَقَطَت في يد أبي عبدالله الشيعيِّ قرطاجنَّة، وقسنطينة، وقفصة، ودخل رقادة عاصمة الأغالبة عام 296هـ - 26 من مارس 909م). وبذلك انتهت دولة الأغالبةِ بشَمالِ أفريقيا وتهيَّئَت البلادُ لقيامِ دولة الفاطميِّينَ."},{"id":995,"title":"تعرض القرامطة للحجيج وقتلهم وسلبهم .","date":["العام الهجري :294","العام الميلادي :906"],"text":"ارتحل زكرَوَيه من نهر المثنية يريد الحاجَّ، فبلغ السَّلمان، وأقام ينتَظِرُهم، فبلغت القافلةُ الأولى واقصةَ سابِعَ المحرَّم، فأنذرهم أهلُها وأخبَروهم بقرب القرامطة، فارتحلوا لساعتِهم، وسار القرامطةُ إلى واقصة، فسألوا أهلَها عن الحاجِّ، فأخبَروهم أنَّهم ساروا فاتَّهَمهم زكرويه، فقتل العلافةَ، وأحرق العلَف، وتحصَّن أهل واقصة في حِصنِهم، فحصرهم أيامًا ثم ارتحل عنهم نحو زبالة، ولقيَ زكرَوَيه القرمطيُّ قافلةَ الخراسانية بعُقبة الشيطان راجعينَ مِن مكة، فحاربهم حربًا شديدةً، فلما رأى شدةَ حَربِهم سألهم: هل فيكم نائبُ للسلطان؟ فقالوا: ما معنا أحَدٌ. قال: فلستُ أريدكم؛ فاطمأنُّوا وساروا، فلما ساروا أوقع بهم، وقتَلَهم عن آخِرِهم، ولم ينجُ إلَّا الشريد، وسَبَوا من النَّاسِ ما أرادوا وقَتَلوا منهم، وكتب من نجا من الحُجَّاج من هذه القافلةِ الثانية إلى رؤساءِ القافلة الثالثة من الحُجَّاج يُعلِمونهم ما جرى من القرامطة، ويأمرونَهم بالتحَذُّر، والعدولِ عن الجادَّة نحو واسط والبصرة، والرجوعِ إلى فيد والمدينةِ إلى أن تأتيَهم جيوش السلطان، فلم يسمعوا ولم يُقيموا، وسارت القرامطةُ مِن العَقَبة بعد أخذِ الحاجِّ، وقد طموا الآبار والبِرَك بالجِيَف، والأراب، والحجارة، بواقصة، والثعلبية، والعقبة، وغيرها من المناهِل في جميع طريقِهم، وأقام بالهيبر ينتظر القافلةَ الثالثة، فساروا فصادفوه هناك، فقاتَلَهم زكرويه ثلاثة أيام، وهم على غيرِ ماء، فاستسلموا لشدةِ العطش، فوضع فيهم السَّيفَ وقتلهم عن آخرهم، وجمع القتلى كالتَلِّ، وأرسل خلف المنهزمينَ مَن يبذلُ لهم الأمان، فلما رجعوا قتَلَهم، وكان نساء القرامطة يَطُفنَ بالماء بين القتلى يَعرِضْنَ عليهم الماء، فمن كلَّمَهنَّ قَتَلْنَه، فقيلَ إنَّ عدة القتلى بلغت عشرين ألفًا ولم ينجُ إلَّا من كان بين القتلى فلم يُفطَنْ له فنجا بعد ذلك، ومن هرب عند اشتغالِ القرامطة بالقتل والنهب، فكان من مات من هؤلاء أكثَرُ ممَّن سلم ومن استعبدوه، وكان مبلغُ ما أخذوه من هذه القافلة ألفي ألف دينارٍ."},{"id":996,"title":"ذكر بعض الحوادث مع الروم .","date":["العام الهجري :294","العام الميلادي :906"],"text":"غزا ابنُ كيغلغ الرومَ مِن طرسوس، فأصاب من الرومِ أربعةَ آلافِ رأسٍ سبيًا ودوابَّ ومتاعًا، ودخل بِطْرِيقٌ من بطارقةِ الروم في الأمانِ وأسلم، كما غزا ابنُ كيغلغ شكند، وافتتح اللهُ عليه، وسار إلى الليس، فغنموا نحوًا من خمسينَ ألفَ رأسٍ، وقتلوا مقتلةً عظيمة من الروم، وانصرفوا سالِمينَ، وكاتَبَ أندرونقس البطريقُ المكتفيَ بالله يطلُبُ منه الأمان، وكان على حربِ أهلِ الثغور من قِبَل ملك الروم، فأعطاه المكتفي ما طلَب، فخرج ومعه مائتا أسيرٍ مِن المسلمين كانوا في حِصنِه، وكان ملكُ الرومِ قد أرسل للقَبضِ عليه، فأعطى المسلمينَ سلاحًا وخرجوا معه، فقَبَضوا على الذي أرسَلَه مَلِكُ الروم ليقبضَ عليه ليلًا، فقتلوا ممن معه خلقًا كثيرًا، وغَنِموا ما في عسكَرِهم، فاجتمعت الرومُ على أندرونقس ليحاربوه، فسار إليهم جمعٌ من المسلمين ليخَلِّصوه ومن معه من أسرى المسلمين، فبلغوا قونية، فبلغ الخبَرُ إلى الروم، فانصرفوا عنه، وسار جماعةٌ من ذلك العسكر إلى أندرونقس، وهو بحِصنِه، فخرج ومعه أهلُه إليهم، وسار معهم إلى بغداد، وأخرب المسلمونَ قونيةَ."},{"id":997,"title":"وفاة محمَّد بنُ نَصرِ المَروزي .","date":["العام الهجري :294","العام الميلادي :906"],"text":"هو الإمامُ أبو عبد الله محمَّد بنُ نَصرِ المَروزي، إمامُ أهل الحديثِ في عصره، وأحدُ الأعلامِ في العلومِ والأعمالِ. ولِدَ سنة 202 ببغداد، ونشأ بنيسابورَ، سكن سمرقندَ وغيرَها. وكان أبوه مروزيًّا. قال الحاكمُ فيه: \"إمامُ الحديثِ في عصرِه بلا مُدافعةٍ\". كان من أعلمِ النَّاسِ باختلافِ الصَّحابةِ والتابعينَ ومَن بعدهم، كان مولِدُه ببغداد ثم رحل إلى نيسابورَ ونشأ بها، ثم رحل إلى مصر، وكان من أحسَنِ النَّاسِ صلاةً وأكثَرِهم خُشوعًا فيها، وقد صنف كتابًا عظيمًا في الصلاةِ هو تعظيمُ قَدرِ الصَّلاةِ، وله كِتابُ القَسامة والمُسند في الحديث وغيرها، عاد إلى سمرقند وتوفِّي فيها عن 92 عامًا رحمَه الله تعالى."},{"id":998,"title":"مقتل زكرويه بن مهرويه القرمطي .","date":["العام الهجري :294","الشهر القمري : ربيع الأول","العام الميلادي :907"],"text":"لَمَّا فعل زكرَوَيه بالحجاج ما فعل، عَظُمَ ذلك على الخليفة خاصَّةً، وعلى جميع المسلمين عامَّةً، فجهَّزَ المكتفي الجيوشَ، فلما كان أوَّل ربيع الأول سيَّرَ وصيف بن صوارتكين مع جماعةٍ من القوَّاد والعساكر إلى القرامطة، فساروا على طريقِ حفان فلَقِيَهم زكرَوَيه، ومن معه من القرامطةِ، فاقتتلوا يومهم، ثم حجزَ الليل، وباتوا يتحارَسون، ثمَّ بكَّروا إلى القتال، فاقتتلوا قتالًا شديدًا فقُتِلَ من القرامطة مقتلةٌ عظيمة، ووصل عسكَرُ الخليفة إلى عدُوِّ الله زكرَوَيه، فضربه بعضُ الجند بالسَّيفِ على رأسه، فبلغت الضربةُ دماغه، وأخذه أسيرًا وأخذ خليفتَه وجماعةً مِن خواصِّه وأقربائه، وفيهم ابنُه وكاتبه، وزوجتُه، واحتوى الجندُ على ما في العسكرِ، وعاش زكرَوَيه خمسةَ أيام ومات، فسُيِّرَت جيفتُه والأسرى إلى بغداد، وانهزم جماعةٌ من أصحابه إلى الشام، فأوقع بهم الحُسَين بن حمدان، فقتلوهم جميعًا، وأخذوا جماعةً مِن النساء والصبيان، وحُمِلَ رأس زكرويه- لعنه الله- إلى خُراسان، لئلَّا ينقَطِعَ الحُجَّاج، وأخذ الأعرابُ رَجُلين من أصحابِ زكرَوَيه يُعرَف أحدهما بالحداد، والآخر بالمُنتَقِم، وهو أخو امرأةِ زكرويه، كانا قد سارا إليهم يدعوانِهم إلى الخروجِ معهم، فلما أخذوهما سيَّرُوهما إلى بغداد، وتتَبَّع الخليفةُ القرامطة بالعراق، فقتل بعضَهم، وحبس بعضَهم، ومات بعضُهم في الحبس."},{"id":999,"title":"وفاة أمير خراسان إسماعيل بن أحمد الساماني .","date":["العام الهجري :295","الشهر القمري : صفر","العام الميلادي :907"],"text":"هو أبو إبراهيمَ إسماعيلُ بنُ أحمدَ الساماني أميرُ خراسان وما وراء النَّهرِ، شَهِدَ عَهدُه ظهورَ السَّامانيين كقوَّةٍ في المنطقة. وهو ابنُ أحمدَ بنِ أسد، ويرجع نسَبُه إلى سامان خدا الذي أسَّس سلالةَ السَّامانيين والذي ترك المجوسيَّة واعتنقَ الإسلامَ، ويُعتبَرُ إسماعيل أبًا روحيًّا للقوميَّة الطاجيكية، كان عاقلًا عادلًا، حسَنَ السِّيرةِ في رعيَّتِه، حليمًا كريمًا، يلقب بعد موته بالماضي، وهو الذي كان يُحسِنُ إلى إمامِ أهلِ الحديث في عصرِه محمَّد بن نصر المروزي ويعَظِّمُه ويُكرِمُه ويَحتَرِمُه ويقوم له في مجلسِ مُلكِه، فلما مات تولَّى بعده ولدُه أحمدُ بنُ إسماعيل بن أحمد الساماني, وأرسلَ إليه المكتفي باللهِ عهْدَه بالولاية وعقَدَ لواءَه بيَدِه‏.‏"},{"id":1000,"title":"مفاداة الأسرى بين الروم والمسلمين .","date":["العام الهجري :295","الشهر القمري : ذي القعدة","العام الميلادي :908"],"text":"تمَّ الفِداءُ بين المسلمين والروم، وكان عِدَّةُ من فودِيَ به من الرجال والنساء ثلاثةَ آلافِ نفسٍ."},{"id":1001,"title":"وفاة الخليفة العباسي المكتفي بالله وتولي أخيه المقتدر بالله الخلافة .","date":["العام الهجري :295","الشهر القمري : ذي القعدة","العام الميلادي :908"],"text":"هو أميرُ المؤمنينَ أبو محمَّد علي المكتفي باللهِ بنُ الخليفة المعتَضِد بن الأمير أبي أحمد الموفَّق بن المتوكل على الله جعفر بن المعتصم بن الرشيد العباسي، وليس من الخلفاءِ مَن اسمُه عليٌّ سواه بعد عليِّ بنِ أبي طالبٍ، وليس من الخُلَفاء مَن يُكنَّى بأبي محمَّد سوى الحسَنِ بن علي بن أبي طالب وهو، ولِدَ سنة 264، وكان يُضرَبُ المثَلُ بحُسنِه في زمانه. كان معتَدِلَ القامةِ، أسودَ الشَّعرِ، حسَنَ اللِّحيةِ، جميلَ الصورة. بويع بالخلافةِ عند موت والده في جمادى الأولى سنة 289، وفي أيَّامِه فُتِحَت أنطاكية وكان فيها من أُسارى المسلمين بشَرٌ كثيرٌ وجَمٌّ غفير، ولَمَّا حضرته الوفاةُ سأل عن أخيه أبي الفضلِ جعفرِ بنِ المعتضد، فأحضره في يوم الجمعة لإحدى عشرةَ ليلةً خلت من ذي القعدة منها، وأحضَرَ القضاةَ وأشهدهم على نفسِه بأنَّه قد فوَّضَ أمرَ الخلافة إليه مِن بَعدِه، ولقبه بالمُقتَدِر بالله، ثم مات بعد عِدَّة أيام، وكانت خلافته سِتَّ سنين وستة أشهر وتسعة عشر يومًا. مات شابًّا في الثلاثين من عمُرِه، ثم تولى الخلافةَ المقتَدِرُ باللهِ أبو الفَضلِ جعفرُ بن المعتضد، فجُدِّدَت له البيعةُ بعد موت أخيه وقتَ السَّحَر لأربعَ عشرةَ ليلةً خلت من ذي القَعدةِ مِن هذه السنة، وعمُرُه إذ ذاك ثلاثَ عشرةَ سنةً وشهرٌ واحد وإحدى وعشرون يومًا، ولم يل الخلافةَ أحَدٌ قبله أصغَرُ منه."},{"id":1002,"title":"خلع الخليفة العباسي المقتدر وإعلان الخلافة لعبدالله بن المعتز .","date":["العام الهجري :296","العام الميلادي :908"],"text":"اجتمع جماعةٌ مِن القوَّادِ والجُند والأُمَراء على خَلعِ المُقتَدِر وتوليةِ عبدِ الله بن المعتَزِّ الخلافةَ، فأجابهم ابنُ المعتَزِّ على ألَّا يُسفَكَ بسَبَبِه دَمٌ، وكان المقتَدِرُ قد خرج يلعَبُ بالصولجان، فقصد إليه الحُسَينُ بن حمدان يريد أن يفتِكَ به، فلما سمع المقتَدِرُ الصَّيحةَ بادر إلى دارِ الخلافةِ فأغلقها دونَ الجيشِ، واجتمع الأمراءُ والأعيانُ والقُضاة في دارِ المخرمي فبايعوا عبدَ الله بن المعتَزِّ، وخوطب بالخلافة، ولُقِّبَ بالمرتضي بالله، واستوزر أبا عُبَيد الله محمَّد بن داود وبعث إلى المقتَدِر يأمُرُه بالتحَوُّلِ من دار الخلافةِ إلى دار ابنِ طاهرٍ لينتَقِلَ إليها، فأجابه بالسَّمعِ والطاعة، فركِبَ الحُسَين بن حمدان من الغَدِ إلى دار الخلافةِ ليتسَلَّمَها فقاتله الخدَمُ ومَن فيها، ولم يُسَلِّموها إليه، وهَزَموه فلم يقدِرْ على تخليصِ أهلِه ومالِه إلَّا بالجَهدِ، ثم ارتحلَ مِن فَورِه إلى الموصِل وتفَرَّقَ نظامُ ابنِ المعتَزِّ وجماعتِه، فأراد ابنُ المعتز أن يتحوَّلَ إلى سامرَّا لينزِلَها، فلم يتْبَعْه أحدٌ من الأمراء، فدخل دارَ ابنِ الجصَّاص فاستجار به فأجاره، ووقع النَّهبُ في البلد واختبط النَّاسُ، وبعث المقتَدِرُ إلى أصحابِ ابنِ المعتَزِّ فقُبِض عليهم وقُتِلَ أكثرُهم، وأعاد ابنَ الفرات إلى الوزارةِ، فجَدَّد البيعةَ إلى المقتَدِر، وأرسل إلى دار ابنِ الجصَّاص فتسَلَّمَها، وأحضر ابنَ المعتَزِّ وابنَ الجصاص فصادر ابنَ الجصَّاص بمالٍ جزيلٍ جِدًّا، نحوُ ستة عشر ألفَ ألف درهم، ثم أطلَقَه واعتقل ابن المعتَزِّ، فلما دخل في ربيع الآخر ليلتان ظهَرَ للنَّاسِ مَوتُه وأُخرِجَت جُثَّتُه، فسُلِّمَت إلى أهله فدُفِن، وصَفَحَ المُقتَدِر عن بقيَّةِ مَن سعى في هذه الفتنةِ حتى لا تفسُدَ نيَّاتُ الناس، قال ابن الجوزي: \"ولا يُعرَفُ خليفةٌ خُلِعَ ثم أعيدَ إلَّا الأمينُ والمُقتَدِر\"."},{"id":1003,"title":"الغزو الإسماعيلي العبيدي الفاطمي لأفريقيا .","date":["العام الهجري :296","العام الميلادي :908"],"text":"لَمَّا كان مِن أمْرِ انتهاءِ دَولةِ الأغالِبةِ واستحواذِ أبي عبدالله الشيعيِّ على البلادِ، واستقَرَّت له القيروانُ ورقادة، سار إلى سجلماسة، وكان المهديُّ وابنه أبو القاسم محبوسينِ عند اليسَع بن المدرار أميرِ سجلماسة، فلاطفه أبو عبدِالله ليُخَلِّصَ المهديَّ منه دون أذًى، وكان المهدي قد حاول الحضورَ إلى المغربِ بعد أن راسله أبو عبدالله بما فتح من البلادِ وغلبَ، وأن الأمرَ قد استتَبَّ له فلْيَحضُرْ، ولكنَّه قُبِضَ عليه في الطريقِ وأُسِرَ حتى صار أمرُه عند اليسَع بن مدرار أميرِ الخوارج الصفريَّة، لكنَّ اليسع لم يتلطَّفْ له بل حاربه، ثمَّ لَمَّا أحس بقوة أبي عبدالله الشيعي هرب من الحِصنِ فدخله أبو عبدالله وأخرج المهديَّ منه واستخرجَ ولَدَه، فأركَبَهما، ومشى هو ورؤساءُ القبائِلِ بين أيديهما، وأبو عبد الله يقول للنَّاسِ: هذا مولاكم، (وهو يبكي) من شِدَّةِ الفَرَح، حتى وصل إلى فسطاطٍ قد ضُرِبَ له فنزل فيه، وأمر بطَلَبِ اليسع (فطُلِبَ)، فأُدرِكَ، فأُخِذَ وضُرِبَ بالسِّياطِ ثمَّ قُتِل."},{"id":1004,"title":"زوال دولة الأغالبة بالمغرب .","date":["العام الهجري :296","العام الميلادي :908"],"text":"كان آخِرَ مَن تولَّى من أمراء الأغالبةِ زيادةُ الله الثالثُ الذي قتل أباه وتولى بعده عام 290، لكنَّه كان منصرفًا إلى اللَّهوِ والمُجون، فقويَ أمرُ أبي عبدالله الشيعي الحُسَين بن أحمد بن زكريَّا الصنعاني الذي رحل إلى المغربِ بعد أن مهَّدَ له الطريقَ والدَّعوةَ فيها رجلانِ قبله، وكان بينه وبين بني الأغلَبِ حروبٌ، وكان الأحولُ بنُ إبراهيم الثاني الأغلبي- عمُّ زيادةِ الله- لأبي عبدالله الشيعي بالمرصاد, ولكِنَّ زيادةَ اللهِ قتَلَ عَمَّه الأحول، فقَوِيَ أمرُ أبي عبدالله الشيعي أكثَرَ، وجهرَ بالدَّعوةِ إلى المهدي، فلما أحس زيادةُ الله بالضَّعفِ آثَرَ الهروبَ، فجمع الأموالَ وهرب إلى مصرَ، ثم حاول دخولَ بغداد فلم يُؤذَنْ له، فرجع إلى مصر ووعدوه بأن يجمَعوا له الرجالَ والمالَ ليعودَ فيأخُذَ بثأره، فلما طال انتظارُه رحل إلى بيت المقدِسِ وسكن الرملة وتوفِّيَ فيها، فكانت مدَّةُ دولةِ الأغالبة مائةً واثنتي عشرة سنة."},{"id":1005,"title":"زوال دولة الخوارج الصفرية في تاهرت .","date":["العام الهجري :296","العام الميلادي :908"],"text":"بعد أن دخل أبو عبدالله الشيعيِّ رقادةَ واستولى عليها وقضى على الأغالبةِ، اتَّجَه إلى سجلماسة قاعدةِ الخوارِجِ الصفريَّة، لكنَّه مَرَّ بطريقه على تاهرت، وكانت الدولةُ الصَّفريةُ في مرحلةِ ضَعفٍ وتنازُعٍ على السلطة، فقَتَلَ يقظان بن أبي اليقظان وبَنيه، وسار إلى العاصمة الرستمية وقتل فيها، وهرَبَ مَن هربَ، واستباح المدينةَ وحَرَقها، فقضى على الدَّولةِ الرُّستمية الصفريَّة الخارجية، لكِنَّ المذهبَ الإباضيَّ الذي هو أصلُ هذه الدولةِ لم ينتهِ؛ لأنَّ من استطاع الهربَ تحصَّنَ في ورغلة واحةٍ في الصحراءِ التي بقيت مدَّةً لا يستطيعُ العُبيديون دخولَها والقضاءَ عليها."},{"id":1006,"title":"وفاة أبي بكر الأثرم .","date":["العام الهجري :296","الشهر القمري : شوال","العام الميلادي :909"],"text":"هو الإمامُ الحافِظُ العلَّامة: أبو بكرٍ أحمدُ بنُ محمد بن هاني الإسكافي الأثرَم الطَّائي، وقيل: الكلبيُّ. أحدُ الأعلامِ، ومُصَنِّفُ (السُّنَن)، تلميذُ الإمام أحمد. ولد في دولة الرشيد. روى عنه كثيرًا مِن المسائِلِ، سَمِعَ مِن عفان، وأبي الوليد، والقعنبي، وأبي نُعيم، وابنِ أبي شيبة, وخلقٍ كثيرٍ، وحَدَّث عنه: النَّسائي في (سُنَنه)، وموسى بن هارون، ويحيى بن صاعد، وعليُّ بن أبي طاهر القزويني، وغيرهم. وكان حافظًا صادقًا قويَّ الذاكرة، كان ابنُ مَعينٍ يقول عنه: \"كان أحدُ أبويه جِنِّيًّا\"؛ لسُرعةِ فَهمِه وحِفظِه، وكان عالِمًا بكُتُبِ ابنِ أبي شيبة، وله كتبٌ مُصَنَّفةٌ في العِلَل والناسخ والمنسوخ، وكان من بحورِ العِلمِ، وله مُسنَدٌ مُصنَّفٌ كذلك."},{"id":1007,"title":"عدوان ابن حفصون .","date":["العام الهجري :297","العام الميلادي :909"],"text":"اجتمع عُمَرُ بنُ حفصون، وسعيدُ بن مستنة، وسعيدُ بن هذيل، وضَمَّهم عسكرٌ واحدٌ، فضَرَبوا بناحيةِ جيان جنوب إسبانيا وأغاروا، فأصابوا وغَنِموا، وانصَرَفوا إلى حِصنِ جُريشة؛ فاتَّبَعَهم القائدُ أحمدُ بن محمد بن أبي عبدة فلَحِقَهم وهَزَمهم، وقتل جماعةً منهم، فيهم تسريل العجمي من قُوَّاد ابنِ حفصون."},{"id":1008,"title":"غزو المتمردين في الأندلس .","date":["العام الهجري :297","العام الميلادي :909"],"text":"افتتح القائدُ أحمدُ بنُ محمد بن أبي عبدة حصنَ الزبيب، وابتنى حصنَ ترضيض؛ تضييقًا على ابن هُذَيل، وحَصَّن قلعة الأشعث، ووضَعَ فيه ندبًا من الرجال. وشتَّى هذه السنة بجبل أرنيش من كورة قبرة. وكانت له في هذه الشتوة حركات بالغت في نكايةِ أهلِ النفاق."},{"id":1009,"title":"هزيمة نصارى الأندلس على يد محمَّد بن عبد الملك الطويل .","date":["العام الهجري :297","العام الميلادي :909"],"text":"خرج محمَّدُ بنُ عبد الملك الطويل إلى بار بليارش؛ فافتتح حصنَ أوربوالة، وأصاب من المُشرِكينَ ثلاثمائة سبية، وقتل كثيرًا منهم، وهدَمَ الحِصنَ وحَرَّقه. وتقَدَّمَ إلى حصني علتير والغبران فهَدَمهما. وكان مبلغُ الفَيءِ في هذه الغزاة ثلاثةَ عشرَ ألفًا."},{"id":1010,"title":"تأسيس دولة العبيديين الفاطميين في أفريقيا .","date":["العام الهجري :297","الشهر القمري : ربيع الآخر","العام الميلادي :910"],"text":"لَمَّا ظهر المهدِيُّ مِن سِجنِه أقام بسِجِلماسة أربعين يومًا، ثم سار إلى أفريقيَّة، وأحضر الأموالَ من إنكجان، فجعَلَها أحمالًا وأخذها معه، وقد عمِلَ أبو عبدالله الشيعي على زوالِ مُلك بني الأغلب، ومُلك بني مدرار الذين منهم اليسَع، وكان لهم ثلاثون ومائة سنةً منفردين بسجلماسة، وزوالِ مُلكِ بني رستم من تاهرَت، ولهم ستون ومائة سنةٍ تفرَّدوا بتاهَرت، ومَلَك المهديُّ جميع ذلك، فلمَّا قَرُب من رقادة تلقَّاه أهلها، وأهلُ القَيروان، وأبو عبدالله، ورؤساءُ كُتامة مشاةً بين يديه، وولَدُه خَلْفَه، فسلَّموا عليه، فردَّ جميلًا، وأمَرَهم بالانصراف، ونزل بقصرٍ من قصور رقادة، وأمر يومَ الجُمُعة بذِكرِ اسمِه في الخطبة في البلاد، وتلقَّب بالمهديِّ أميرِ المؤمنين، وجلس بعد الجمعةِ رجلٌ يُعرَف بالشَّريف، ومعه الدُّعاةُ، وأحضروا النَّاسَ بالعنف والشدّة، ودَعَوهم إلى مذهبِهم، فمن أجاب أُحسِنَ إليه، ومَن أبى حُبِسَ، فلم يدخُلْ في مذهبِهم إلَّا بعضُ الناس، وهم قليلٌ، وقُتِلَ كثيرٌ ممَّن لم يوافِقْهم على قولهم، فكان أوَّل من حَكَم هو هذا الملَقَّب بالمهدي واسمُه عبيدالله بن عبدالله بن ميمون، وقد اختُلِفَ كثيرًا في نَسَبِه وصِحَّتِه، فمنهم من يقولُ: نسبُه صحيحٌ إلى علي بن أبي طالب، ومنهم من يقولُ: بل هو راجِعٌ إلى ميمون القدَّاح، ومنهم من يقولُ: بل أصلُه يهودي ربيبُ الحسين بن علي بن محمد بن علي بن موسى بن جعفر بن محمد بن علي بن الحسين بن علي بن أبي طالب، بل قيل: إنَّ اليسَع قد قَتَل عُبيدَ الله، وجعل مكانه رجلًا يهوديًّا في السجن، وهو الذي أخرجه أبو عبدالله الشيعي، عِلمًا أنَّ أبا عبدالله الشيعي لم يَسبِقْ له أن رأى المهديَّ أصلًا؛ ولذلك حصل الشِّقاقُ بينهم فيما بعدُ, وعلى أيِّ حالٍ كان ومِن أيِّ نسَبٍ كان، فإنَّ دولَتَهم وما كانوا يَدْعونَ إليه كفيلةٌ ببيان ما كانوا عليه من الكُفرِ والنِّفاقِ والشِّقاقِ لأهلِ الحقِّ والإسلامِ."},{"id":1011,"title":"إعلان قيام الدولة الفاطمية برقادة .","date":["العام الهجري :297","الشهر القمري : ربيع الآخر","العام الميلادي :910"],"text":"نجح أبو عبد الله الشيعيُّ داعيةُ الإسماعيليَّةُ في إعلانِ قيامِ الدَّولةِ الفاطميَّةِ في \"رقادة\" عاصمةِ دولةِ الأغالبةِ، ومُبايعةِ عُبيدِ الله المَهديِّ بالخلافة، وجاء هذا النَّجاحُ بعد محاولاتٍ فاشلةٍ قام بها الشِّيعةُ منذ قيامِ الدولة الأمويَّة للظَّفَرِ بالخلافةِ."},{"id":1012,"title":"شن حرب على ابن حفصون .","date":["العام الهجري :297","الشهر القمري : شعبان","العام الميلادي :910"],"text":"كان غزوُ العاصِ بنِ الإمام عبدِ الله الغَزاةَ المعروفةَ بغَزوةِ رية وفريرة. قاد الخيلَ أحمدُ بنُ محمد بن أبي عبدة. وفصَلَ يوم الخميس لتسعٍ بَقِينَ مِن شعبان؛ فتقدَّمَ إلى بلدة فحاربَها. ثم احتلَّ على نهر طلجيرة، فدارت بينه وبين أصحاب ابن حفصون حربٌ، عُقِرَت فيها خيلُ السُّلطان، وقُتِلَ عددٌ مِن أصحابِ ابنِ حفصون. ثمَّ تقدَّمَ إلى حصون إلبيرة؛ فنزل على حصنِ شبيلش، فكانت هنالك حربٌ شديدةٌ، ونالت بعضَ حُماةِ العَسكرِ جِراحٌ. وتجوَّلَ في كورة إلبيرة، وحلَّ بمحلة بجانة، ثمَّ قفل على كورة جيان، فنازل حِصنَ المنتلون يوم الأربعاء للَيلتين بَقِيتا من ذي القَعدة، فأقام عليه محاصِرًا أيامًا ثمَّ ضحَّى فيه يومَ الأحد، وقفل يومَ الاثنين لإحدى عشرة ليلة خلَت من ذي الحِجة، ودخل قُرطبةَ يومَ الأربعاء، لأربعَ عَشرةَ ليلةً خَلَت من ذي الحِجَّة."},{"id":1013,"title":"وفاة محمد بن داود الظاهري .","date":["العام الهجري :297","الشهر القمري : رمضان","العام الميلادي :910"],"text":"هو أبو بكرٍ محمَّدُ بنُ داود بن عليِّ بن خلف الأصبهانيُّ المعروفُ بالظاهريِّ. ابنُ الإمامِ داودَ بنِ عليٍّ الظاهري, كان عالِمًا بارعًا, إمامًا في الحديث, أديبًا شاعِرًا ظريفًا، فقيهًا ماهرًا، اشتغل على أبيه وتَبِعَه في مذهبه ومَسلَكِه وما اختاره من الطرائِقِ وارتضاه، وكان أبوه يحبُّه ويقَرِّبُه ويُدنيه. كان أحدَ من يُضرَبُ المثَلُ بذكائه. تصَدَّرَ للفُتيا بعد والده، لَمَّا جلس للفتوى بعد والِدِه استصغروه، فدَسُّوا عليه من سأله عن حَدِّ السُّكرِ، ومتى يعَدُّ الإنسانُ سَكرانَ؟ فقال: إذا عَزَبَت- يعني: بعُدت وغابت- عنه الهُمومُ، وباح بسِرِّه المكتومِ، فاستُحسِنَ ذلك منه. كان مِن أجمل النَّاسِ وأكرَمِهم خلقًا، وأبلَغِهم لسانًا، وأنظَفِهم هيئةً، مع الدِّينِ والورَع، وكلِّ خَلَّةٍ محمودةٍ، مُحَبَّبًا إلى الناس. حَفِظَ القرآنَ وله سبعُ سنين، وذاكَرَ الرِّجالَ بالآدابِ والشِّعرِ وله عشرُ سنين، وكان يُشاهَدُ في مَجلِسِه أربعُمئة صاحبِ مِحبَرةٍ، وله من التآليفِ: كتابُ الزهرة، صنَّفه في عنفوان شبابِه، وهو مجموعٌ في الأدبِ، جمعَ فيه غرائبَ ونوادِرَ وشِعرٍ رائق، كتابُ (الإنذار والإعذار)، وكتاب (التقصِّي) في الفقه، وكتاب (الإيجاز) ولم يَتِمَّ، وكتاب (الانتصارُ من محمَّد بن جريرٍ الطَّبَري)، وكتاب (الوصولُ إلى معرفة الأصول)، وكتاب (اختلافُ مصاحف الصحابة)، وكتاب (الفرائض) وكتاب (المناسِك)."},{"id":1014,"title":"اغتيال أبي عبدالله الشيعي من قبل عبيد الله المهدي .","date":["العام الهجري :298","العام الميلادي :910"],"text":"سببُ ذلك أنَّ المهديَّ لَمّا استقامت له البلادُ، ودان له العباد، وباشر الأمورَ بنَفسِه، وكفَّ يدَ أبي عبد الله، ويدَ أخيه أبي العبَّاس - وهما أكبَرُ دعاته- داخَلَ أبا العبَّاسِ الحسَدُ، وعظُمَ عليه الفطامُ عن الأمر والنهي، والأخذِ والعطاء، فأقبل يُزري على المهديِّ في مجلسِ أخيه، ويتكلَّمُ فيه، وأخوه ينهاه، ولا يرضى فِعلَه، فلا يزيدُه ذلك إلَّا لجاجًا، ولم يزَلْ حتى أثَّر في قلب أخيه، فقال أبو عبدِ الله يومًا للمهديِّ: \"لو كنتَ تجلِسُ في قصرِك، وتتركُني مع كُتامةَ آمُرُهم وأنهاهم؛ لأنِّي عارِفٌ بعاداتهم، لكان أهيبَ لك في أعيُنِ النَّاسِ\". وكان المهديُّ سمِعَ شيئًا ممَّا يجري بين أبي عبد الله وأخيه، فتحقَّقَ ذلك، ثم صار أبو العبَّاسِ يقول: \"إنَّ هذا ليس الذي كنَّا نعتقد طاعته، وندعو إليه؛ لأنَّ المهديَّ يختم بالحجَّة، ويأتي بالآياتِ الباهرة\"، فأخذ قولُه بقلوبِ كثيرٍ مِن الناس، فاتَّفقَ هو وأخوه ومَن معهما على الاجتماعِ، وعَزَموا على قتل المهديِّ، واجتمع معهم قبائِلُ كُتامةَ إلَّا قليلًا منهم، وكان معهم رجل يُظهِرُ أنَّه منهم، وينقُل ما يجري إلى المهديِّ، ودخلوا عليه مِرارًا فلم يجسِروا على قتلِه، فأمر المهديُّ عروبةَ ورجالًا معه أن يرصُدوا أبا عبدالله وأخاه أبا العبَّاس، ويقتُلوهما، فلمَّا وصلا إلى قرب القصرِ حمل عروبة على أبي عبدالله، فقال: لا تفعَلْ يا بُنيَّ، فقال: الذي أمَرتَنا بطاعتِه أمَرَنا بقَتلِك؛ فقُتِلَ هو وأخوه، فقيل: إنَّ المهديَّ صلَّى على أبي عبدالله، وقال: رحمك اللهُ أبا عبدالله، وجزاك خيرًا بجميلِ سَعيِك. وثارت فتنةٌ بسبَبِ قَتلِهما، وجرَّدَ أصحابُهما السيوف، فركب المهديُّ وأمَّن النَّاسَ، فسَكَنوا، ثمّ تَتَّبَعهم حتى قتَلَهم. وثارت فتنة ثانية بين كُتامة وأهل القَيروان قُتِلَ فيها خلقٌ كثيرٌ، فخرج المهديُّ وسكَّن الفتنةَ، وكفَّ الدُّعاةَ عن طلَبِ التشيُّعِ من العامَّة، ولَمَّا استقامت الدولة للمهديِّ عَهِدَ إلى ولده أبي القاسم نِزار بالخلافةِ."},{"id":1015,"title":"وفاة أبي عبدالله الشيعي داعية عبيد الله المهدي العبيدي\n  .","date":["العام الهجري :298","العام الميلادي :910"],"text":"هو الحُسينُ بنُ أحمد بن محمد بن زكريا أبو عبد الله الشيعي المعروف بالقائم؛ فهو الذي قام بالدعوة لعُبيد الله المهدي جَدِّ ملوك مصر, ويُعرَفُ كذلك بالمعلِّم؛ لأنه يعلِّمُ الناسَ عقائِدَ الباطنية, وأصلُه من اليمن من صنعاء، وقيل: كان من أهل الكوفة، سار من سلمية من عند عُبيد الله المهدي داعيًا له في البلاد، وتنقَّلت به الأحوال إلى أن دخل المغرِبَ, وكان من دُهاة العالم، وأفرادِ بني آدم دَهاءً ومَكرًا ورأيًا. دخل إفريقيةَ وحيدًا بلا مال ولا رجال، فلم يزَلْ يسعى ويتحَيَّل ويستحوذ على النُّفوسِ بإظهار الزهادة والقيامِ لله، حتى تَبِعَه خلقٌ وبايعوه، وحاربوا صاحِبَ إفريقية مرَّات. وآل أمرُه إلى أن تمَلَّك القيروان، وهرب صاحِبُها أبو مضر زيادة الله الأغلبي آخِرُ ملوك بني الأغلب منه إلى بلادِ الشرق. كما قضى على دولتَي بني مدرار والرستمية في أفريقيةَ، حتى مهَّد القواعِدَ للمهديِّ ووطَّدَ البلاد, فأقبل المهديُّ من الشرق وسَلَّمَه الأمر، ثمَّ كفَّ المهديُّ يَدَه ويدَ أخيه أبي العباس، فندم أبو عبد الله على ما صنع وأضمَرَ الغَدرَ هو وأخوه بعُبيد الله، فاستشعر منهما المهديُّ الغدرَ, فدَسَّ إليهما من قتَلَهما في ساعةٍ واحدةٍ، وذلك بمدينة رقادة, فتوطَّدَ المُلكُ لعُبيد الله."},{"id":1016,"title":"وفاة الراوندي الفيلسوف الملحد .","date":["العام الهجري :298","العام الميلادي :910"],"text":"هو أحمدُ بنُ يحيى بن إسحاق الراوندي نسبةً إلى راوند بلدةٍ مِن أصبهان، ولد عام 210, فيلسوف مجاهرٌ بالإلحاد، له مناظراتٌ ومجالسُ مع علماء الكلام، انفرد بمذاهِبَ نُقِلَت عنه في كتبه، كالقول بالحُلوليَّة، وتناسُخ رُوح الإله في الأئمَّة، وكان يلازِمُ الرافضةَ والملاحِدةَ، فإذا عوتِبَ قال: \"أنا أريدُ أن أعرِفَ مذاهبَهم\"، ثم كاشَفَ وناظَرَ، وصنَّف في الزندقة- لعنه اللهُ- قيل: إنَّ أباه كان يهوديًّا فأظهَرَ الإسلامَ، قال ابن حجر: \"كان أوَّلًا مِن متكَلِّمي المعتَزِلة، ثم تزندقَ واشتَهَر بالإلحادِ\" وقيل: إنه كان لا يستقِرُّ على مذهبٍ ولا يَثبُتُ على شيءٍ، ويقال: كان غايةً في الذكاءِ، قال الإمام أبو الفرج بن الجوزي: \"كنتُ أسمع عنه بالعظائمِ، حتى رأيتُ له ما لم يَخطُرْ مِثلُه على قلبٍ\" وهو أحدُ مشاهير الزنادقة، طلبه السلطانُ فهرب إلى ابن لاوي اليهودي بالأهواز، وصَنَّفَ عنده مصنَّفات، منها كتاب \"الدامغ للقرآن\" وضعه ليطعنَ به في القرآنِ، وفي النبيِّ صلَّى الله عليه وسلم. ثمَّ لم يلبث إلَّا أيامًا حتى مرِضَ ومات, وكتابٌ في الرَّدِّ على الشريعةِ سمَّاه \"الزمردة\"، قال ابن عقيل: \"عجبي كيف لم يُقتَلْ وقد صنَّف «الدامغ»\" قال بعضُ اليهودِ للمُسلمينَ: لا يُفسِدَنَّ عليكم هذا كتابَكم، كما أفسَدَ أبوه علينا التوراةَ\". واختُلِفَ في موته، فقيل: مات وهو عند اليهوديِّ، وقيل: بل صُلِبَ، عاش أكثَرَ مِن ثمانين سنة، فلا رَحِمَه الله. وجازاه بما يستحِقُّه."},{"id":1017,"title":"قيام الدولة السامانية وزوال الدولة الصفارية .","date":["العام الهجري :298","الشهر القمري : رجب","العام الميلادي :911"],"text":"استولى أبو نصر أحمدُ بن إسماعيل السامانيُّ على سِجِستان، وسببُ ذلك أنَّه لَمَّا استقرَّ أمرُه، وثبت ملكُه في بلادِ ما وراءَ النهر، خرج في سنة 297 إلى الرَّيِّ، وكان يسكُنُ بُخارى، ثمَّ سار إلى هراة، فسيَّرَ منها جيشًا في المحرَّم سنة ثمان وتسعين إلى سِجِستان، وسيَّرَ جماعةً من أعيان قوَّاده وأمرائه، منهم أحمد بن سهل، ومحمَّد بن المظفَّر، وسيمجور الدواتي، وهو والدُ آل سيمجور ولاة خُراسان للسامانيَّة، واستعمَلَ أحمدُ على هذا الجيشِ الحسينَ بن علي المَروَروذيَّ، فساروا حتى أتوا سجستان، وبها المعدَّلُ بن علي بن الليث الصَّفَّار، وهو صاحبها، فلمَّا بلغ المعدَّلَ خَبَرُهم سيَّرَ أخاه أبا عليٍّ محمَّد بن عليِّ بن الليث إلى بُست والرخج؛ ليحمي أموالها، ويرسِل منها الميرةَ إلى سجستان، فسار الأميرُ أحمد بن إسماعيل إلى أبي عليٍّ ببُست، وجاذبه وأخذه أسيرًا، وعاد به إلى هَراة، وأمَّا الجيشُ الذي بسجستان فإنَّهم حصروا المُعدَّلَ وضايقوه، فلمَّا بلغه أنَّ أخاه أبا عليٍّ محمَّدًا قد أُخذَ أسيرًا، صالَحَ الحسينَ بنَ عليٍّ، واستأمن إليه، فاستولى الحسينُ على سجستان، فاستعمل عليها الأميرُ أحمدُ أبا صالحٍ منصورَ بن إسحاق، وهو ابنُ عمِّه، وانصرف الحسينُ عنها ومعه المعدَّلُ إلى بُخارى."},{"id":1018,"title":"وفاة الجنيد بن محمد الصوفي .","date":["العام الهجري :298","الشهر القمري : شوال","العام الميلادي :911"],"text":"هو أبو القاسِمُ الجُنَيدُ بنُ محمَّد البغدادي النهاوندي الخزَّاز- لأنه كان يعمَلُ في الخَزِّ- أصلُه من نهاوند، ولد ببغداد قيل بعد 220، ونشأ فيها، كان شيخَ العارفينَ وقُدوةَ السَّائرينَ وعَلَمَ الأولياءِ في زمانه، تفَقَّه على أبي ثورٍ, وسمِعَ من الحسن بن عرفة وغيرِه, واختصَّ بصحبةِ السَّرِيِّ السَّقَطيِّ. أتقن العِلمَ، ثم أقبَلَ على شبابه، واشتغل بما خُلِقَ له، سمع الكثيرَ، وشاهَدَ الصالحينَ وأهلَ المعرفة، ورُزِقَ من الذَّكاءِ وصوابِ الإجاباتِ في فُنونِ العلم ما لم يُرَ في زمانِه مِثلُه عند أحدٍ مِن أقرانه، ولا ممَّن أرفعُ سنًّا منه ممَّن كان منهم يُنسَبُ إلى العِلمِ الباطِنِ والعلمِ الظَّاهِرِ في عفافٍ وعُزوفٍ عن الدنيا وأبنائِها. كان يُفتي في حلقةِ أبي ثَورٍ الكَلبيِّ وله عِشرونَ سنة. يقالُ: إنَّه أوَّلُ مَن تكلَّمَ في علم التوحيدِ ببغداد، عَدَّه العلماءُ شَيخَ الصوفيَّةِ؛ لِضَبطِ مَذهَبِه بقواعِدِ الكتابِ والسُّنَّة، ولِكَونِه لم يتلبَّسْ بعقائِدَ فاسدةٍ، وكان يُقالُ له طاووس العُلَماءِ، أخذ الطريقةَ عن خالِه سَرِيٍّ السَّقَطي، كان الجُنيدُ يقولُ: \"مَذهَبُنا مُقيَّدٌ بالكتابِ والسُّنَّة، فمن لم يقرأ القُرآنَ ويكتُبِ الحديثَ لا يُقتدى به\" يعني: في مذهبِه وطريقتِه، أثنى عليه وعلى كَلِماتِه الوعظيَّةِ كثيرٌ مِن العلماء، توفِّيَ في بغدادَ ودُفِنَ عند قبر خالِه."},{"id":1019,"title":"المقتدر بالله يقبض على وزيره ابن الفرات .","date":["العام الهجري :299","الشهر القمري : ذي الحجة","العام الميلادي :912"],"text":"قبَضَ المقتَدِرُ على الوزير أبي الحَسَنِ بنِ الفُرات، ووكَّلَ بدارِه، وهتَكَ حَرَمه، ونهب مالَه، ونُهِبَت دور أصحابِه ومَن يتعلَّقُ به، وافتتنت بغدادُ لِقَبضِه، ولقِيَ الناسُ شِدَّةً لِمُدة ثلاثة أيَّامٍ، ثمّ سكنوا. وكانت مدُّةُ وزارتِه- وهي الوزارة الأولى- ثلاثَ سنين وثمانية أشهر وثلاثة عشر يومًا؛ لكونه أخَّرَ أرزاقَ الجُندِ، واعتَلَّ بضيقِ الأموال، فقال المقتَدِر: أين ما ضَمِنْتَ مِن القيامِ بأمرِ الجُند؟ ثم عزَلَه, واستوزر مِن بعدِه أبا علي محمد بن عبيدالله بن يحيى بن خاقان."},{"id":1020,"title":"وزارة الخاقاني وانحلال أمور الدولة العباسية .","date":["العام الهجري :299","الشهر القمري : ذي الحجة","العام الميلادي :912"],"text":"لَمَّا عزَلَ المُقتَدِرُ ابنَ الفرات قلَّدَ أبا علي محمد بن يحيى بن عبيد الله بن يحيى بن خاقان، وكان قليلَ الخبرةِ في تدبير أمور الوزارة, فانحَلَّت أمور الدولة؛ لأنَّه كان ضجورًا، ضَيِّقَ الصَّدرِ، مُهمِلًا لقِراءةِ كتُبِ العُمَّال، وجِبايةِ الأموال، وكان يتقَرَّبُ إلى الخاصة والعامة، فمنَعَ خَدَمَ السُّلطانِ وخَواصَّه أن يخاطِبوه بالعبدِ، وكان إذا سأله أحدٌ حاجةً دقَّ صَدرَه، وقال: نعمْ وكرامةً، فسُمِّي \"دق صَدرَه\"، إلَّا أنَّه قَصَّرَ في إطلاقِ الأموال للفرسان والقُوَّاد، فنفروا عنه واتَّضَعت الوَزارةُ بفِعلِه. وكان أولادُه قد تحَكَّموا فيه، وكان يولِّي في الأيام القليلة عِدَّةً من العُمَّال، حتى إنَّه ولَّى بالكوفةِ في مدةِ عشرينَ يومًا، سبعةً مِن العمال، فاجتمعوا في الطريقِ، فعَرَضوا توقيعاتِهم، فسار الأخيرُ منهم، وعاد الباقونَ يطلُبونَ ما خَدَموا به أولادَه، ثم زاد الأمرُ حتى تحكَّمَ أصحابُه، فكانوا يُطلِقونَ الأموالَ ويُفسِدونَ الأحوال، فانحَلَّت القواعِدُ، وخَبُثَت النيَّات، واشتغل الخليفةُ بعَزلِ وُزرائِه والقَبضِ عليهم، والرُّجوعِ إلى قَولِ النِّساءِ والخَدَم، والتصَرُّف على مقتضى آرائِهم، فخرجت الممالِكُ، وطَمِعَ العُمَّالُ في الأطراف."},{"id":1021,"title":"فتنة أهل صقلّية بين طاعة المقتدر بالله وطاعة المهديّ العلويّ .","date":["العام الهجري :300","العام الميلادي :912"],"text":"في سنة 297 استعمل عُبيدُ الله المهديُّ عليَّ بنَ عُمَرَ على صقلِّية، فلمَّا وَلِيَها كان شيخًا ليِّنًا، فلم يرضَ أهلُ صقلِّيَّة بسيرته، فعزلوه عنهم، وولَّوا على أنفسهم أحمدَ بنَ قرهب، ودعا أحمدُ بن قرهب النَّاسَ إلى طاعة المقتَدِر، فأجابوه إلى ذلك، فخَطب له بصقلِّيَّة، وقَطع خُطبةَ المهديِّ، وأخرج ابنُ قرهب جيشًا في البحرِ إلى ساحل أفريقيَّة، فلَقُوا هناك أسطولَ المهديِّ ومُقَدَّمه الحَسَن بن أبي خنزير، فأحرقوا الأسطولَ، وقَتَلوا الحسن، وحملوا رأسَه إلى ابن قرهب، وسار الأسطولُ الصقلِّيُّ إلى مدينة سفاقس، فخرَّبوها، وساروا إلى طرابلس، فوجدوا فيها القائِمَ بنَ المهديِّ، فعادوا، ووصَلَت الخِلَع السُّود والألوية إلى ابن قرهب من المقتَدِر، ثمَّ أخرج مراكِبَ فيها جيشٌ إلى قلوريةَ، فغَنِمَ جيشُه، وخَرَّبوا وعادوا، وسيَّرَ أيضًا أسطولًا إلى إفريقيَّة، فخرج عليه أسطولُ المهديِّ، فظَفِروا بالذي لابن قرهب وأخذوه، ولم يستَقِمْ بعد ذلك لابن قرهب حالٌ، وأدبَرَ أمرُه، وطَمِعَ فيه الناس، وكانوا يخافونَه، وخاف منه أهلُ جرجنت –مدينة في صقلية-، وعَصَوا أمره، وكاتبوا المهديَّ، فلمَّا رأى ذلك أهلُ البلاد كاتبوا المهديَّ أيضًا، وكرهوا الفتنةَ، وثاروا بابن قرهب، وأخذوه أسيرًا سنة 300 وحبسوه، وأرسلوه إلى المهديِّ مع جماعة من خاصَّتِه، فأمر بقَتلِهم على قبرِ ابن أبي خنزير، فقُتِلوا، واستعمل على صقلِّية أبا سعيد موسى بن أحمد، وسيَّرَ معه جماعةً كثيرة من شيوخِ كتامة."},{"id":1022,"title":"ولاية عبدالرحمن بن محمد إمارة الأندلس .","date":["العام الهجري :300","العام الميلادي :912"],"text":"كان والِدُ عبدِ الرحمنِ النَّاصر- محمَّدُ بنُ عبدِ الله- قد قتله أخوه المُطَرِّفُ فِي صدر دولةِ أبيهما. وخلَّفَ محمَّدٌ ابنَه عبدَ الرحمنِ، وهو ابنُ عشرين يومًا. ولَمَّا توفِّيَ الأميرُ عبدُ اللَّهِ جَدُّ عبدِ الرحمنِ سنة ثلاثمئة، وليَ عبدُ الرحمنِ الأمرَ بعده. وكان ذلك مِن غرائبِ الأمورِ؛ لأنَّه كَانَ شابًّا مع وجودِ أكابِرَ مِن أعمامِه وأعمامِ أبيه، وتقدَّم هُوَ- وهو ابن اثنتين وعشرين سنة- فوَلِيَ الإمارةَ، والبلادُ كُلُّها في حالةِ اضطراب؛ قد امتَنَعَت على الدولةِ حصونُ بكورة رَيَّة وحصن ببشتر، فحاربها الناصر، حتّى استَرَدَّها، وكان طُليطُلة قد خالف أهلَ الدولة، فقاتلهم حتَّى عادُوا إلى الطاعة، ولم يزَلْ يقاتل المخالفين حتَّى أذعنوا له، وأطاعوه نيِّفًا وعشرين سنة، فاستقامت البلادُ، وأَمِنَت دولته، واستقام لَهُ الأمرُ، وقد حكم خمسين سنة من 300عام إلى 350."},{"id":1023,"title":"خلاف سجستان وعودها إلى طاعة أحمد بن إسماعيل الساماني .","date":["العام الهجري :300","العام الميلادي :912"],"text":"سببُ ذلك أنَّ محمَد بن هُرمُز، المعروفُ بالمولى الصندليِّ، كان خارجيَّ المذهب، وكان قد أقام ببُخارى وهو من أهلِ سِجِستان جنوب غرب أفغانستان، وكان شيخًا كبيرًا، فجاء يومًا إلى الحُسين بن عليِّ بنِ محمَّد العارض يَطلُبُ رِزقَه، فقال له: إنَّ الأصلحَ لِمِثلِك من الشيوخِ أن يلزمَ رباطًا يَعبُدُ الله فيه، حتّى يوافيَه أجلُه، فغاظه ذلك، فانصرف إلى سِجِستان والوالي عليها منصورُ بنُ إسحاق، فاستمال جماعةً من الخوارج، ودعا إلى الصَّفَّار، وبايع في السرِّ لِعَمرو بن يعقوب بن محمَّد بن عمرو بن الليث، وكان رئيسُهم محمَّد بن العبّاس، المعروف بابن الحَفَّار، وكان شديدَ القوَّة، فخرجوا، وقبضوا على منصورِ بن إسحاقَ أميرِهم وحبَسَوه في سجن أرك، وخطبوا لعمرو بن يعقوب، وسلَّموا إليه سجستان، فلمَّا بلغ الخبر إلى الأمير أحمد بن إسماعيل سيَّرَ الجيوشَ مع الحسين بن عليٍّ، مرّةً ثانية إلى زرنج، فحصرها تسعةَ أشهر، فصعد يومًا محمَّدُ بن هُرمُز الصندليُّ إلى السور، وقال: ما حاجتُكم إلى أذى شيخٍ لا يصلُحُ إلَّا لِلُزومِ رِباطٍ؟ يُذَكِّرُهم بما قاله العارضُ ببخارى؛ واتَّفق أنَّ الصندليَّ مات، فاستأمن عمرُو بن يعقوب الصَّفَّار وابن الحفَّار إلى الحسين بن عليٍّ، وأطلقوا منصور بن إسحاق، وكان الحسينُ بن عليٍّ يُكرِمُ ابن الحفَّار ويقرِّبُه، فواطأ ابن الحفَّار جماعة على الفتك بالحسين، فعَلِمَ الحسين بذلك، وكان ابنُ الحفَّارِ يدخُلُ على الحسين، لا يُحجَبُ عنه، فدخل إليه يومًا وهو مُشتَمِلٌ على سيف، فأمر الحُسَينُ بالقبض عليه، وأخذه معه إلى بُخارى، ولَمَّا انتهى خبر فتح سِجِستان إلى الأمير أحمد استعمل عليها سيمجورَ الدواتيَّ، وأمر الحسينَ بالرجوعِ إليها فرجع ومعه عمرُو بن يعقوب وابن الحفّار وغيرهما، وكان عَودُه في ذي الحجَّة سنة ثلاثمائة، واستعمل الأمير أحمدُ منصورًا ابنَ عمِّه إسحاق على نَيسابور وأنفَذَه إليها، وتوفِّي ابنُ الحفّار."},{"id":1024,"title":"اعتقال سبكري غلام عمرو بن الليث الصفاري .","date":["العام الهجري :300","العام الميلادي :912"],"text":"لَمَّا استولى السامانيُّونَ على سجستان، بلغهم خبَرُ مسيرِ سُبكرى في المفازة من فارسَ إلى سجستانَ، فسيَّروا إليه جيشًا، فلَقُوه وهو وعسكره قد أهلكَهم التَّعبُ، فأخذوه أسيرًا، واستولَوا على عسكرِه، وكتب الأميرُ أحمدُ إلى المقتَدِر بذلك، وبالفتح، فكتب إليه يشكُرُه على ذلك، ويأمُرُه بحمل سُبكرى، ومحمَّد بن عليِّ بن الليث إلى بغداد، فسيَّرَهما، وأُدخِلا بغداد مشهورَينِ على فيلَينِ، وأعاد المقتدر رسلَ أحمد، صاحِب خُراسان، ومعهم الهدايا والخِلَع."},{"id":1025,"title":"وفاة عبدالله بن محمد صاحب الأندلس .","date":["العام الهجري :300","الشهر القمري : ربيع الأول","العام الميلادي :912"],"text":"هو عبدُ اللهِ بنُ محمَّدِ بنِ عبد الرحمن بن الحاكم بن هشام بن عبد الرحمن بن معاوية الداخِل، صاحِبُ الأندلس، وليَ الأمرَ بعد أخيه المُنذِر بن محمد في صفر سنة 275، وطالت أيامُه، وبقي في المُلكِ خمسًا وعشرين سنةً وأحد عشر شهرًا، وكان من الأمراءِ العادلين الذين يَعِزُّ وجودُ مثلهم. كان صالحًا تقيًّا، كثيرَ العبادةِ والتلاوة، رافعًا لِعَلمِ الجِهادِ، مُلتَزِمًا للصَّلواتِ في الجامعِ، وله غَزواتٌ مَشهورةٌ، منها غزوةُ \"بلي\" التي يُضرَبُ بها المثل. وذلك أنَّ ابنَ حفصونَ حاصرَ حِصنَ بلي في ثلاثين ألفًا. فخرج الأميرُ عبد الله من قُرطُبةَ في أربعة عشر ألف مقاتل، فهَزَم ابنَ حَفصونَ، وتبعه قتلًا وأسرًا، حتى قيل: إنَّه لم ينجُ مِن الثّلاثين ألفًا إلَّا النَّادُّ, وكان عبد الله أديبًا عالِمًا. مات وكان عمُرُه اثنتين وأربعين سنة، وخلَّف أحدَ عشَرَ ولدًا ذكرًا، أحدُهم محمَّد المقتول, وهو والدُ عبد الرحمن الناصر، قتله أخوه المطرف فِي صدرِ دولة أبيهما، ولَمَّا توفِّيَ عبدالله تولى بعده ابنُ ابنِه عبد الرحمن بن محمَّد لمدة خمسينَ سنةً."}]
